UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', curriculum_id = 'as', topic_code = '1.1', syllabus_cite = '9702 1.1 Speed', problem_number = 2, "order" = 2, question_text = 'A car travels 90 km in 1.5 h at a constant speed. Calculate its speed, in km/h.', question_image_url = 'diagram:kin-1.1-q2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '60', answer_unit = 'km/h', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'speed = distance ÷ time = 90 ÷ 1.5 = 60.0 km/h. Common mistake: dividing time by distance instead of distance by time.', points = 1 WHERE id = '96b9e4f8-19d7-450e-bfb3-ee379048ac84';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', curriculum_id = 'as', topic_code = '1.1', syllabus_cite = '9702 1.1 Speed', problem_number = 3, "order" = 3, question_text = 'A runner completes a 400 m race in 50 s at a constant pace. Calculate the runner''s average speed, in m/s.', question_image_url = 'diagram:kin-1.1-q3', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '8', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'speed = distance ÷ time = 400 ÷ 50 = 8.00 m/s. Common mistake: thinking you need the pace at one instant — the AVERAGE speed over the whole race only needs the total distance and total time.', points = 1 WHERE id = '096b0bdb-29e9-49dd-acd3-04ec2f5b09ec';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', curriculum_id = 'as', topic_code = '1.1', syllabus_cite = '9702 1.1 Speed', problem_number = 4, "order" = 4, question_text = 'Convert a speed of 20 m/s into km/h.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '72', answer_unit = 'km/h', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = '1 m/s = 3.6 km/h, since 1000 m = 1 km and 1 h = 3600 s. 20 × 3.6 = 72.0 km/h. Common mistake: multiplying by 3.6 when converting the other way (km/h → m/s), where you should divide.', points = 1 WHERE id = '0b0c50b0-9ee8-4c2e-a6b5-ebca5181b301';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', curriculum_id = 'as', topic_code = '1.1', syllabus_cite = '9702 1.1 Speed', problem_number = 5, "order" = 5, question_text = 'Convert a speed of 108 km/h into m/s.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '30', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'To convert km/h to m/s, divide by 3.6: 108 ÷ 3.6 = 30.0 m/s. Common mistake: dividing by 3.6 the wrong way round, or using 1000/60 instead of 1000/3600.', points = 1 WHERE id = 'ebf14862-2157-469f-b710-21777f89bce6';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', curriculum_id = 'as', topic_code = '1.1', syllabus_cite = '9702 1.1 Speed', problem_number = 6, "order" = 6, question_text = 'Light travels at 3.0 × 10⁸ m/s in a vacuum. Calculate the time taken for light to travel 1.00 km.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '3.333e-6', answer_unit = 's', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 't = distance ÷ speed = 1000 ÷ (3.0 × 10⁸) = 3.33 × 10⁻⁶ s. Common mistake: forgetting to convert 1.00 km to 1000 m before dividing by a speed given in m/s.', points = 1 WHERE id = '80cc4e13-8ffd-41e5-bc3d-e686bc1afee7';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', curriculum_id = 'as', topic_code = '1.1', syllabus_cite = '9702 1.1 Speed', problem_number = 7, "order" = 7, question_text = 'A cyclist rides 12 km in 40 minutes, then a further 8 km in 20 minutes, both in the same direction. Calculate the average speed for the whole 20 km journey, in km/h.', question_image_url = 'diagram:kin-1.1-q7', difficulty_level = 2, answer_type = 'numeric'::answer_type, answer_correct = '20', answer_unit = 'km/h', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Total distance = 12 + 8 = 20 km. Total time = 40 + 20 = 60 min = 1.00 h. Average speed = 20 ÷ 1.00 = 20.0 km/h. Common mistake: averaging the two leg speeds (18 km/h and 24 km/h gives 21 km/h) instead of using total distance ÷ total time — these only agree when both legs take equal time.', points = 2 WHERE id = '93b11de5-504f-4283-bc88-960b902715c0';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', curriculum_id = 'as', topic_code = '1.1', syllabus_cite = '9702 1.1 Speed', problem_number = 8, "order" = 8, question_text = 'A car''s speedometer reads 54 km/h as it passes a checkpoint, but police radar measures its average speed over the previous 10 km at only 40 km/h. Which statement best explains this?', question_image_url = NULL, difficulty_level = 2, answer_type = 'multiple_choice'::answer_type, answer_correct = 'The speedometer gives the instantaneous speed at that moment, which can be higher than the average speed over a slower stretch of road', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = ('Instantaneous speed (what a speedometer shows) is the speed at one moment' || chr(59) || ' average speed is total distance ÷ total time over a stretch of road, which is pulled down by any slower sections (traffic, bends, hills). The two need not match. Common mistake: assuming a single instantaneous reading must equal a calculated average.'), points = 2 WHERE id = 'f09947d7-e8b1-4ef0-a212-5e45e4f55459';
UPDATE problem_options SET problem_id = 'f09947d7-e8b1-4ef0-a212-5e45e4f55459', option_text = 'The speedometer gives the instantaneous speed at that moment, which can be higher than the average speed over a slower stretch of road', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = 'c520f420-3560-4b32-b92f-66c3c52a44b1';
UPDATE problem_options SET problem_id = 'f09947d7-e8b1-4ef0-a212-5e45e4f55459', option_text = 'The speedometer must be faulty', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = '712b9554-881b-43c3-b2a2-5639d19c3a70';
UPDATE problem_options SET problem_id = 'f09947d7-e8b1-4ef0-a212-5e45e4f55459', option_text = 'Average speed is always higher than instantaneous speed', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '72ad9d89-2096-4fb2-ae58-00ed1f29d453';
UPDATE problem_options SET problem_id = 'f09947d7-e8b1-4ef0-a212-5e45e4f55459', option_text = 'Speed and distance cannot be compared this way', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = 'acb51aa8-71d2-4ea1-9628-b5a299fa8a6f';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', curriculum_id = 'as', topic_code = '1.1', syllabus_cite = '9702 1.1 Speed', problem_number = 9, "order" = 9, question_text = 'A train''s speed increases steadily from 20 m/s to 50 m/s over 30 s. Using the fact that for a steady increase the average speed equals the mean of the initial and final speeds, calculate the distance travelled.', question_image_url = 'diagram:kin-1.1-q9', difficulty_level = 2, answer_type = 'numeric'::answer_type, answer_correct = '1050', answer_unit = 'm', answer_unit_required = false, answer_tolerance = 0.05, answer_sign_sensitive = false, explanation = 'Because the speed increases steadily, the average speed is the mean of the two values: (20 + 50) ÷ 2 = 35.0 m/s. Distance = average speed × time = 35.0 × 30 = 1050 m. Common mistake: using only the final speed (giving 1500 m, too high) or only the initial speed (giving 600 m, too low).', points = 2 WHERE id = 'a04446d3-c7a6-4727-ac00-63371ba5cbb5';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', curriculum_id = 'as', topic_code = '1.2', syllabus_cite = '9702 1.2 Distance and displacement, scalar and vector', problem_number = 1, "order" = 1, question_text = 'Which pair correctly classifies distance and displacement?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = ('Distance is a scalar' || chr(59) || ' displacement is a vector'), answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Distance is a scalar (size only, no direction). Displacement is a vector (size AND direction, measured in a straight line from start to finish). Common mistake: assuming both are vectors because both are "lengths".', points = 1 WHERE id = '0bad663b-8bfe-41d3-ac46-902e868a3e04';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', curriculum_id = 'as', topic_code = '1.2', syllabus_cite = '9702 1.2 Distance and displacement, scalar and vector', problem_number = 2, "order" = 2, question_text = 'A person walks 300 m east, then walks 300 m back west to their starting point. Calculate the magnitude of their displacement.', question_image_url = 'diagram:kin-1.2-q2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '0', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Displacement is measured from the start to the final position in a straight line. The walker ends up exactly where they started, so the displacement is 0 m, even though the total distance walked is 300 + 300 = 600 m. Common mistake: giving the distance (600 m) instead of the displacement.', points = 1 WHERE id = '19707446-ea1f-426a-964c-20f24a3ae129';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', curriculum_id = 'as', topic_code = '1.2', syllabus_cite = '9702 1.2 Distance and displacement, scalar and vector', problem_number = 3, "order" = 3, question_text = 'A cyclist rides 500 m along a straight road without changing direction. State the magnitude of the displacement.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '500', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'When the whole journey is in a straight line with no reversal, distance and displacement have the same magnitude: 500 m. Common mistake: thinking displacement must always be smaller than distance — they are equal whenever the path never turns back on itself.', points = 1 WHERE id = '52a2889b-299d-4034-9f0c-dd8327a46795';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', curriculum_id = 'as', topic_code = '1.2', syllabus_cite = '9702 1.2 Distance and displacement, scalar and vector', problem_number = 4, "order" = 4, question_text = 'Which of the following is a vector quantity?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'displacement', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = ('A vector needs both a size AND a direction. Displacement has both' || chr(59) || ' mass, distance and time are scalars — each is fully described by a single number with a unit. Common mistake: calling distance a vector because it has units of length, like displacement.'), points = 1 WHERE id = 'b121e968-668b-498f-897e-c5bc05905a21';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', curriculum_id = 'as', topic_code = '1.2', syllabus_cite = '9702 1.2 Distance and displacement, scalar and vector', problem_number = 5, "order" = 5, question_text = 'An object moves 8 m east, then a further 6 m east. Calculate the magnitude of its total displacement.', question_image_url = 'diagram:kin-1.2-q5', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '14', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Both legs are in the same direction, so they add directly: 8 + 6 = 14 m east. Common mistake: treating this like a right-angle problem and using Pythagoras, when the two legs are actually parallel.', points = 1 WHERE id = 'f608eb49-1c9c-46f8-bf91-ea41a89c5ec3';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', curriculum_id = 'as', topic_code = '1.2', syllabus_cite = '9702 1.2 Distance and displacement, scalar and vector', problem_number = 6, "order" = 6, question_text = 'A hiker walks 4.0 m north, then 3.0 m further north, then 2.0 m south. Calculate the total distance walked.', question_image_url = 'diagram:kin-1.2-q6', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '9', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Distance just adds up every length covered, regardless of direction: 4.0 + 3.0 + 2.0 = 9.00 m. (The displacement is smaller, 5.0 m north, since the final 2.0 m southward partly cancels the earlier northward motion — but distance does not care about direction.) Common mistake: subtracting the southward leg to get 5.0 m, which is the displacement, not the distance.', points = 1 WHERE id = '5012e8ca-61df-417b-aefd-e0c355cbc33b';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', curriculum_id = 'as', topic_code = '1.2', syllabus_cite = '9702 1.2 Distance and displacement, scalar and vector', problem_number = 7, "order" = 7, question_text = 'A delivery drone flies 300 m east, then 400 m north. Calculate the magnitude of its total displacement.', question_image_url = 'diagram:kin-1.2-q7', difficulty_level = 2, answer_type = 'numeric'::answer_type, answer_correct = '500', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The two legs are perpendicular, so the resultant displacement is the hypotenuse of a right triangle: magnitude = √(300² + 400²) = √(90000 + 160000) = √250000 = 500 m. Common mistake: adding the two distances directly (300 + 400 = 700 m) instead of combining them as vectors at right angles.', points = 2 WHERE id = '47e16443-5af2-4bf1-b87b-6acba1315509';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', curriculum_id = 'as', topic_code = '1.2', syllabus_cite = '9702 1.2 Distance and displacement, scalar and vector', problem_number = 8, "order" = 8, question_text = 'A runner completes one full lap of a 400 m circular track, finishing at the exact point where they started. Which statement is correct?', question_image_url = NULL, difficulty_level = 2, answer_type = 'multiple_choice'::answer_type, answer_correct = 'Distance = 400 m, displacement = 0 m', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Distance is the total length of the path actually covered: 400 m, the full circumference. Displacement is the straight-line separation between start and finish, which is 0 m because the runner returns to the starting point. Common mistake: assuming the distance must also be 0 because the runner "didn’t go anywhere" overall.', points = 2 WHERE id = 'ecd9f02b-8df7-4055-9a81-e31596066086';
UPDATE problem_options SET problem_id = 'ecd9f02b-8df7-4055-9a81-e31596066086', option_text = 'Distance = 400 m, displacement = 0 m', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = '91b5f2cd-c96a-4bc0-9335-922c1dcf0591';
UPDATE problem_options SET problem_id = 'ecd9f02b-8df7-4055-9a81-e31596066086', option_text = 'Distance = 0 m, displacement = 400 m', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = '1df3737a-63eb-45fb-81b0-e75001ebe3d0';
UPDATE problem_options SET problem_id = 'ecd9f02b-8df7-4055-9a81-e31596066086', option_text = 'Both distance and displacement are 400 m', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '10bae015-e689-4b7e-9074-63f05cd92f05';
UPDATE problem_options SET problem_id = 'ecd9f02b-8df7-4055-9a81-e31596066086', option_text = 'Both distance and displacement are 0 m', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = 'd8e17bc6-fd4b-430e-9e7e-36e0435c06c9';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'd47d25c0-5538-419d-9d8f-026400e11f72', curriculum_id = 'as', topic_code = '1.3', syllabus_cite = '9702 1.3 Speed and velocity', problem_number = 1, "order" = 1, question_text = 'Which statement correctly distinguishes velocity from speed?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = ('Velocity has a direction and is the rate of change of displacement' || chr(59) || ' speed has no direction and is the rate of change of distance'), answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Velocity is the rate of change of DISPLACEMENT — a vector, with a direction as well as a size. Speed is the rate of change of DISTANCE — a scalar, size only. Common mistake: using the two words interchangeably, which is fine in everyday speech but not in physics.', points = 1 WHERE id = 'a16bb09d-949b-440e-ac9a-60d02379101b';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'd47d25c0-5538-419d-9d8f-026400e11f72', curriculum_id = 'as', topic_code = '1.3', syllabus_cite = '9702 1.3 Speed and velocity', problem_number = 2, "order" = 2, question_text = 'An object moves 20 m in a straight line, without reversing, in 4.0 s. Calculate its velocity.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '5', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Since the motion is in a straight line with no reversal, velocity = displacement ÷ time = 20 ÷ 4.0 = 5.0 m/s, in the direction of travel. Common mistake: forgetting that a velocity answer should (in principle) carry a direction, even though here there is only one direction available.', points = 1 WHERE id = 'd06dc42c-9233-4003-8009-c48ae5b58a8f';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'd47d25c0-5538-419d-9d8f-026400e11f72', curriculum_id = 'as', topic_code = '1.3', syllabus_cite = '9702 1.3 Speed and velocity', problem_number = 3, "order" = 3, question_text = 'Taking rightward as positive, a particle moves at a constant −3.0 m/s (i.e. to the left) for 5.0 s. Calculate its displacement.', question_image_url = 'diagram:kin-1.3-q3', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '-15', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Displacement = velocity × time = (−3.0) × 5.0 = −15 m — the negative sign shows the particle ends up 15 m to the LEFT of where it started. Common mistake: dropping the negative sign and giving +15 m, which would describe motion to the right instead.', points = 1 WHERE id = '9f5f5e0a-4b13-4e10-a4ba-c3ceafeb81c5';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'd47d25c0-5538-419d-9d8f-026400e11f72', curriculum_id = 'as', topic_code = '1.3', syllabus_cite = '9702 1.3 Speed and velocity', problem_number = 4, "order" = 4, question_text = 'A car''s velocity changes from +20 m/s to −5 m/s. What has happened to the car''s direction of travel?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'The car has reversed direction', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The sign of a 1-D velocity shows its direction relative to the chosen positive direction. Going from +20 m/s to −5 m/s means the car has reversed direction — it is now travelling the opposite way, and more slowly than before. Common mistake: thinking the car has simply slowed down without changing direction, ignoring what the sign change means.', points = 1 WHERE id = 'f0a139c9-9c17-4865-bbfd-1b50b116a00f';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'd47d25c0-5538-419d-9d8f-026400e11f72', curriculum_id = 'as', topic_code = '1.3', syllabus_cite = '9702 1.3 Speed and velocity', problem_number = 5, "order" = 5, question_text = 'A parked car is stationary. State its velocity.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '0', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'A stationary object has zero rate of change of displacement, so its velocity is 0 m/s. (Its speed is also 0 m/s — when an object is at rest, speed and velocity agree, since there is no direction to specify.) Common mistake: leaving the answer blank because "nothing is happening" — zero is a perfectly valid, specific value.', points = 1 WHERE id = '6e954f1e-4c35-41d9-90f2-b398963c0184';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'd47d25c0-5538-419d-9d8f-026400e11f72', curriculum_id = 'as', topic_code = '1.3', syllabus_cite = '9702 1.3 Speed and velocity', problem_number = 6, "order" = 6, question_text = 'Taking rightward as positive, a particle''s displacement changes by −40 m over 8.0 s at a constant rate. Calculate its velocity.', question_image_url = 'diagram:kin-1.3-q6', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '-5', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'velocity = displacement ÷ time = (−40) ÷ 8.0 = −5.0 m/s — negative, so the motion is to the left. Common mistake: reporting the magnitude only (5.0 m/s) and losing the direction information the negative sign carries.', points = 1 WHERE id = '75c561eb-e32f-4395-aeb6-431072fcce15';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'd47d25c0-5538-419d-9d8f-026400e11f72', curriculum_id = 'as', topic_code = '1.3', syllabus_cite = '9702 1.3 Speed and velocity', problem_number = 7, "order" = 7, question_text = 'Taking rightward as positive, a particle moves at +4.0 m/s for 10 s, then reverses to −2.0 m/s for a further 5.0 s. Calculate its average velocity for the whole 15 s.', question_image_url = 'diagram:kin-1.3-q7', difficulty_level = 2, answer_type = 'numeric'::answer_type, answer_correct = '2', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Displacement in phase 1: 4.0 × 10 = 40.0 m. Displacement in phase 2: (−2.0) × 5.0 = −10.0 m. Total displacement = 40.0 + (−10.0) = 30.0 m over 15 s, so average velocity = 30.0 ÷ 15 = 2.00 m/s. Common mistake: averaging the two velocities, (4.0 + (−2.0))/2 = 1.0 m/s, instead of using total displacement ÷ total time (they only agree when both phases last equally long).', points = 2 WHERE id = '7787dd19-8911-43ba-9df6-4cdd0c12d5be';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'd47d25c0-5538-419d-9d8f-026400e11f72', curriculum_id = 'as', topic_code = '1.3', syllabus_cite = '9702 1.3 Speed and velocity', problem_number = 8, "order" = 8, question_text = 'A car''s speedometer reads 60 km/h as it drives around a bend at a steady speed. Is the car''s velocity also constant?', question_image_url = NULL, difficulty_level = 2, answer_type = 'multiple_choice'::answer_type, answer_correct = 'No, because velocity also depends on direction, which is changing around the bend', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'No — even though the SPEED is constant (the speedometer reading never changes), the car''s direction is continuously changing as it goes round the bend, so its velocity (which depends on direction too) is constantly changing. Common mistake: assuming constant speed automatically means constant velocity — it only does for motion in a straight line.', points = 2 WHERE id = 'ac611434-c011-4db1-a6d2-ef2c7325a274';
UPDATE problem_options SET problem_id = 'ac611434-c011-4db1-a6d2-ef2c7325a274', option_text = 'No, because velocity also depends on direction, which is changing around the bend', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = '66bad937-1b70-4752-b3bb-1f17e3d4fdec';
UPDATE problem_options SET problem_id = 'ac611434-c011-4db1-a6d2-ef2c7325a274', option_text = 'Yes, because speed and velocity are always equal in magnitude', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = '180ec140-b07d-41f3-8b03-46b4eccf6e5c';
UPDATE problem_options SET problem_id = 'ac611434-c011-4db1-a6d2-ef2c7325a274', option_text = 'Yes, because the speedometer measures velocity directly', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = 'c266818f-ecb7-463a-8859-bb20e39a1124';
UPDATE problem_options SET problem_id = 'ac611434-c011-4db1-a6d2-ef2c7325a274', option_text = 'No, because the car must be accelerating its speed as well', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '4e78a4e7-0153-4c9c-8248-edd818105b18';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', curriculum_id = 'as', topic_code = '1.6', syllabus_cite = '9702 1.6 Combining velocities', problem_number = 1, "order" = 1, question_text = 'A boat moves relative to the water, and the water itself flows relative to the ground. How is the boat’s resultant velocity relative to the ground found?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'They are added as vectors (tip-to-tail, or by components)', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Velocities combine as vectors, exactly like displacements: the boat''s velocity relative to the water and the water''s velocity relative to the ground are added tip-to-tail (or by components) to give the boat''s resultant velocity relative to the ground. Common mistake: trying to average the two velocities instead of adding them as vectors.', points = 1 WHERE id = 'd5d14e0a-5072-45b7-bec8-2e24ba2ee0b8';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', curriculum_id = 'as', topic_code = '1.6', syllabus_cite = '9702 1.6 Combining velocities', problem_number = 2, "order" = 2, question_text = 'A swimmer swims at 5.0 m/s relative to the water, in the same direction as a current flowing at 2.0 m/s. Calculate the swimmer''s resultant velocity relative to the ground.', question_image_url = 'diagram:kin-1.6-q2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '7', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Both velocities act in the same direction, so they add directly: 5.0 + 2.0 = 7.0 m/s. Common mistake: using Pythagoras here, which is only needed when the two velocities are NOT in the same direction.', points = 1 WHERE id = '6ee075a1-2ce1-46c1-bed6-40f15c80f2f8';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', curriculum_id = 'as', topic_code = '1.6', syllabus_cite = '9702 1.6 Combining velocities', problem_number = 3, "order" = 3, question_text = 'Taking the swimmer’s intended direction as positive, a swimmer swims at +2.0 m/s relative to the water, directly against a current flowing at −3.0 m/s. Calculate the swimmer’s resultant velocity relative to the ground.', question_image_url = 'diagram:kin-1.6-q3', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '-1', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The two velocities are in opposite directions, so they are added with their signs: 2.0 + (−3.0) = −1.0 m/s. The negative sign shows the swimmer is actually being swept backwards overall, despite swimming forwards relative to the water. Common mistake: giving +1.0 m/s, which would mean the swimmer is making forward progress — the opposite of what is actually happening.', points = 1 WHERE id = 'b7212974-93a1-49a0-a9c1-733e0e49199b';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', curriculum_id = 'as', topic_code = '1.6', syllabus_cite = '9702 1.6 Combining velocities', problem_number = 4, "order" = 4, question_text = 'A boat heads straight across a river at 3.0 m/s relative to the water, while the current flows at 4.0 m/s along the river. Calculate the magnitude of the boat’s resultant velocity relative to the ground.', question_image_url = 'diagram:kin-1.6-q4', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '5', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'These two velocities are perpendicular, so Pythagoras applies: magnitude = √(3.0² + 4.0²) = √(9+16) = √25 = 5.00 m/s (a 3-4-5 triangle). Common mistake: adding 3.0 + 4.0 = 7.0 m/s directly, ignoring that the two velocities act at right angles.', points = 1 WHERE id = '32fa0c94-ecd1-4e25-bba7-d24b669d9848';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', curriculum_id = 'as', topic_code = '1.6', syllabus_cite = '9702 1.6 Combining velocities', problem_number = 5, "order" = 5, question_text = 'A headwind of 20 m/s blows at 30° to a plane’s direction of travel. Calculate the component of the wind acting directly against the plane’s motion.', question_image_url = 'diagram:kin-1.6-q5', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '17.32', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = 0.05, answer_sign_sensitive = false, explanation = 'Component along the direction of travel = 20 × cos30° = 20 × 0.866 = 17.3 m/s. Common mistake: using the full 20 m/s as the headwind component, ignoring that only part of an angled wind acts directly against the direction of travel.', points = 1 WHERE id = '613d4b09-8c8f-4d71-9645-03b28750fd34';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', curriculum_id = 'as', topic_code = '1.6', syllabus_cite = '9702 1.6 Combining velocities', problem_number = 6, "order" = 6, question_text = 'A plane''s airspeed (velocity relative to the air) is 200 m/s, and the air itself is perfectly still (zero wind). State the plane''s ground speed.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '200', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'With no wind, the air''s velocity relative to the ground is zero, so the plane''s velocity relative to the ground equals its velocity relative to the air: 200 m/s. Common mistake: assuming ground speed and airspeed must always differ — they are only different when there is wind to add or subtract.', points = 1 WHERE id = 'd7522506-ff07-44f1-b8c2-713646cc6c8c';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', curriculum_id = 'as', topic_code = '1.6', syllabus_cite = '9702 1.6 Combining velocities', problem_number = 7, "order" = 7, question_text = 'A boat is steered straight across a river at 2.0 m/s relative to the water, while the current flows along the river at 1.5 m/s. Calculate the magnitude of the boat’s resultant velocity over the ground.', question_image_url = 'diagram:kin-1.6-q7', difficulty_level = 2, answer_type = 'numeric'::answer_type, answer_correct = '2.5', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'magnitude = √(2.0² + 1.5²) = √(4.0+2.25) = √6.25 = 2.50 m/s. Common mistake: forgetting that "steered straight across" describes the boat’s velocity relative to the WATER, not its actual path over the ground, which is diverted downstream by the current.', points = 2 WHERE id = 'c62ad9dc-448f-4bda-bfd4-450534ef1732';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', curriculum_id = 'as', topic_code = '1.6', syllabus_cite = '9702 1.6 Combining velocities', problem_number = 8, "order" = 8, question_text = 'To cross a river by the shortest possible path (travelling straight across, perpendicular to the banks), in which direction should a boat be steered relative to the water, if the current flows along the river?', question_image_url = NULL, difficulty_level = 2, answer_type = 'multiple_choice'::answer_type, answer_correct = 'Angled upstream, so the current’s effect is exactly cancelled', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The boat must be steered at an angle upstream (angled against the current), so that the upstream component of the boat''s own velocity exactly cancels the current''s downstream push, leaving only a resultant velocity straight across. Common mistake: steering straight across relative to the WATER, which actually results in a path that drifts downstream, not a straight-across path over the ground.', points = 2 WHERE id = '965f82a8-04d8-4fd7-9e49-c4dac520563a';
UPDATE problem_options SET problem_id = '965f82a8-04d8-4fd7-9e49-c4dac520563a', option_text = 'Angled upstream, so the current’s effect is exactly cancelled', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = '86975e57-b83b-4130-a102-425cd5db7b8c';
UPDATE problem_options SET problem_id = '965f82a8-04d8-4fd7-9e49-c4dac520563a', option_text = 'Straight across, relative to the water', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = '378ab526-fa80-465d-bf6c-b3af3a0c0d96';
UPDATE problem_options SET problem_id = '965f82a8-04d8-4fd7-9e49-c4dac520563a', option_text = 'Angled downstream, to arrive sooner', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '58f09e31-49ef-499e-be01-b230b2702925';
UPDATE problem_options SET problem_id = '965f82a8-04d8-4fd7-9e49-c4dac520563a', option_text = 'Directly against the current, facing fully upstream', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = 'b9ed4e46-b2ff-4747-9271-fc36cc223f1f';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '19109221-dd23-4986-8f92-84b0ea2c6033', curriculum_id = 'as', topic_code = '1.7', syllabus_cite = '9702 1.7 Subtracting vectors', problem_number = 1, "order" = 1, question_text = 'How is the vector subtraction A − B carried out?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'Reverse the direction of B, then add A + (−B)', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'A − B is found by reversing the direction of B (keeping its magnitude the same) to get −B, and then adding A + (−B) using the usual tip-to-tail (or component) method for vector addition. Common mistake: subtracting the magnitudes of A and B as if they were ordinary numbers, ignoring their directions.', points = 1 WHERE id = 'cf6799e2-92a1-4300-971c-f530be613238';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '19109221-dd23-4986-8f92-84b0ea2c6033', curriculum_id = 'as', topic_code = '1.7', syllabus_cite = '9702 1.7 Subtracting vectors', problem_number = 2, "order" = 2, question_text = 'Taking the direction of travel as positive, a car’s velocity changes from +10 m/s to +4 m/s. Calculate the change in velocity, Δv.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '-6', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Δv = final velocity − initial velocity = 4 − 10 = −6.00 m/s. The negative sign shows the velocity has decreased (the car has decelerated), even though it never changes direction. Common mistake: computing initial − final (10−4=+6 m/s) instead of final − initial — Δ always means "final minus initial".', points = 1 WHERE id = '2e86500c-6b0b-4485-aa25-13fb5b882462';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '19109221-dd23-4986-8f92-84b0ea2c6033', curriculum_id = 'as', topic_code = '1.7', syllabus_cite = '9702 1.7 Subtracting vectors', problem_number = 3, "order" = 3, question_text = 'Taking rightward as positive, an object’s velocity changes from +5.0 m/s to −3.0 m/s. Calculate Δv.', question_image_url = 'diagram:kin-1.7-q3', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '-8', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Δv = final − initial = (−3.0) − (+5.0) = −8.00 m/s. Common mistake: adding the two velocities (5.0 + (−3.0) = 2.0 m/s) instead of subtracting — a CHANGE is always found by subtraction, not addition.', points = 1 WHERE id = '8416b418-4edc-4855-951a-3c73c6cec67f';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '19109221-dd23-4986-8f92-84b0ea2c6033', curriculum_id = 'as', topic_code = '1.7', syllabus_cite = '9702 1.7 Subtracting vectors', problem_number = 4, "order" = 4, question_text = 'Given a vector B, how do you find −B?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = ('Keep the magnitude the same' || chr(59) || ' reverse the direction'), answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Keep the same magnitude, but reverse the direction by 180°. Common mistake: making the magnitude negative instead (which is meaningless for a vector’s size) rather than reversing the direction.', points = 1 WHERE id = '56866bb7-6c85-47b5-b325-81e7ca763d27';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '19109221-dd23-4986-8f92-84b0ea2c6033', curriculum_id = 'as', topic_code = '1.7', syllabus_cite = '9702 1.7 Subtracting vectors', problem_number = 5, "order" = 5, question_text = 'Vector A is 10 m east and vector B is 6 m east. Calculate A − B.', question_image_url = 'diagram:kin-1.7-q5', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '4', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Since A and B point in the same direction, A − B = A + (−B) simplifies to 10 − 6 = 4 m east. Common mistake: treating this like a right-angle subtraction and reaching for Pythagoras, when the two vectors are actually parallel.', points = 1 WHERE id = 'f311c11d-5161-4fbf-a878-0a555c17150d';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '19109221-dd23-4986-8f92-84b0ea2c6033', curriculum_id = 'as', topic_code = '1.7', syllabus_cite = '9702 1.7 Subtracting vectors', problem_number = 6, "order" = 6, question_text = 'Vector A is 10 m north and vector B is 10 m north (equal to A). State the magnitude of A − B.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '0', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Subtracting an equal vector from itself always gives zero: A − B = 0 m. Common mistake: thinking a subtraction of two nonzero vectors must itself be nonzero — it is exactly zero whenever the two vectors are identical.', points = 1 WHERE id = '15e0d773-e032-4817-a439-7bd061fbc150';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '19109221-dd23-4986-8f92-84b0ea2c6033', curriculum_id = 'as', topic_code = '1.7', syllabus_cite = '9702 1.7 Subtracting vectors', problem_number = 7, "order" = 7, question_text = 'An object''s velocity changes from (6.0, 0) m/s to (0, 6.0) m/s (components in m/s). Calculate the magnitude of the change in velocity, Δv.', question_image_url = 'diagram:kin-1.7-q7', difficulty_level = 2, answer_type = 'numeric'::answer_type, answer_correct = '8.485', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Δv = v₂ − v₁ = (0−6.0, 6.0−0) = (−6.00, 6.00) m/s. Magnitude = √(6.00² + 6.00²) = 8.49 m/s. Common mistake: computing |v₂| − |v₁| = 6.0 − 6.0 = 0, which compares only the SIZES of the two velocities and completely ignores that their directions are different.', points = 2 WHERE id = '9d557398-1985-42fa-a525-b78ee61c97a5';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = '19109221-dd23-4986-8f92-84b0ea2c6033', curriculum_id = 'as', topic_code = '1.7', syllabus_cite = '9702 1.7 Subtracting vectors', problem_number = 8, "order" = 8, question_text = 'An object moves in a circle at a perfectly constant SPEED. Does its velocity change?', question_image_url = NULL, difficulty_level = 2, answer_type = 'multiple_choice'::answer_type, answer_correct = 'Yes — its direction keeps changing, so velocity (a vector) keeps changing even though speed does not', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Yes — velocity is a vector, and even though the speed (magnitude) never changes, the DIRECTION is continuously changing as the object goes around the circle. Since velocity depends on both size and direction, a changing direction means a changing velocity, so Δv is nonzero at every instant, even though |v| stays exactly the same throughout. Common mistake: concluding there is no change in velocity because the speedometer reading (speed) never changes.', points = 2 WHERE id = '11c27aaf-f7d7-46f5-9b3e-ab97a3c16e0a';
UPDATE problem_options SET problem_id = '11c27aaf-f7d7-46f5-9b3e-ab97a3c16e0a', option_text = 'Yes — its direction keeps changing, so velocity (a vector) keeps changing even though speed does not', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = 'a21e8d66-55d1-442f-a2dd-f81073f08b86';
UPDATE problem_options SET problem_id = '11c27aaf-f7d7-46f5-9b3e-ab97a3c16e0a', option_text = 'No — constant speed always means constant velocity', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = 'c0ea8d28-944e-4cae-9079-390955d1cf31';
UPDATE problem_options SET problem_id = '11c27aaf-f7d7-46f5-9b3e-ab97a3c16e0a', option_text = 'No — velocity only changes if the speed changes', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '7fd5c1c7-51e0-4ceb-b7f2-56c2c3c7d0eb';
UPDATE problem_options SET problem_id = '11c27aaf-f7d7-46f5-9b3e-ab97a3c16e0a', option_text = 'Yes, but only because the object is also slowing down', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '217b2695-b59f-40da-857c-6abeebae996c';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', curriculum_id = 'as', topic_code = '1.8', syllabus_cite = '9702 1.8 Other examples of scalar and vector quantities', problem_number = 1, "order" = 1, question_text = 'Which of these is a SCALAR quantity?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'energy', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = ('Energy has a size (measured in joules) but no direction associated with it, so it is a scalar. Common mistake: assuming any quantity that can be positive or negative (like some energies) must be a vector — sign alone does not make something a vector' || chr(59) || ' it needs a direction in space.'), points = 1 WHERE id = 'e7daa557-8b25-4817-8007-11f650dba4da';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', curriculum_id = 'as', topic_code = '1.8', syllabus_cite = '9702 1.8 Other examples of scalar and vector quantities', problem_number = 2, "order" = 2, question_text = 'Which of these is a VECTOR quantity?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'force', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Force has both a size (magnitude) and a direction in which it acts, so it is a vector. Common mistake: thinking of force only as "how hard something pushes" (a number) without considering that the direction of the push is just as physically important.', points = 1 WHERE id = '48f2ce96-6097-4bac-8deb-55aea9a22e59';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', curriculum_id = 'as', topic_code = '1.8', syllabus_cite = '9702 1.8 Other examples of scalar and vector quantities', problem_number = 3, "order" = 3, question_text = 'Which of the following is a VECTOR quantity?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'momentum', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Momentum (mass × velocity) has a direction, inherited from the velocity''s direction, so it is a vector. Common mistake: confusing momentum with kinetic energy (½mv²), which uses velocity SQUARED and so loses the direction information, making it a scalar.', points = 1 WHERE id = '21af327e-b762-4ad1-b298-e2c7bbd8dc5f';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', curriculum_id = 'as', topic_code = '1.8', syllabus_cite = '9702 1.8 Other examples of scalar and vector quantities', problem_number = 4, "order" = 4, question_text = 'Which of the following is a SCALAR quantity?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'temperature', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Temperature is fully described by a single number (with a unit) and has no associated direction, so it is a scalar. Common mistake: confusing temperature with heat flow, which does have a direction (from hot to cold) and would need vector treatment if direction mattered for a calculation.', points = 1 WHERE id = '747aff67-16c5-49af-8a41-23db12e65a2b';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', curriculum_id = 'as', topic_code = '1.8', syllabus_cite = '9702 1.8 Other examples of scalar and vector quantities', problem_number = 5, "order" = 5, question_text = 'Weight is a vector quantity, always directed vertically downward (towards the centre of the Earth). Calculate the magnitude of the weight of a 5.0 kg object, taking g = 9.81 N/kg.', question_image_url = 'diagram:kin-1.8-q5', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '49.05', answer_unit = 'N', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'weight = mass × g = 5.0 × 9.81 = 49.1 N, directed vertically downward. Common mistake: forgetting that weight (a force) is distinct from mass (a scalar) — mass alone, 5.0 kg, has no direction and is not itself a weight.', points = 1 WHERE id = '5441a1c1-10e5-48e8-bbae-21fe7a0aa959';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', curriculum_id = 'as', topic_code = '1.8', syllabus_cite = '9702 1.8 Other examples of scalar and vector quantities', problem_number = 6, "order" = 6, question_text = 'Which pair of quantities are BOTH vectors?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'force and velocity', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Force and velocity both have a size and a direction, so both are vectors. Common mistake: pairing a vector with a scalar (for example force and energy) and assuming both are the same type just because they are both common physics quantities.', points = 1 WHERE id = 'dfccd990-1442-4bc7-bc2f-6bf2a775af02';
UPDATE problem_options SET problem_id = 'dfccd990-1442-4bc7-bc2f-6bf2a775af02', option_text = 'force and velocity', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = '6da6a088-800d-4345-b71c-44f1740e35cf';
UPDATE problem_options SET problem_id = 'dfccd990-1442-4bc7-bc2f-6bf2a775af02', option_text = 'energy and power', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = '60b370ad-e371-4369-b5df-8b3a274c25a2';
UPDATE problem_options SET problem_id = 'dfccd990-1442-4bc7-bc2f-6bf2a775af02', option_text = 'mass and time', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '291acecd-92f6-4abb-a78b-2081ae85877d';
UPDATE problem_options SET problem_id = 'dfccd990-1442-4bc7-bc2f-6bf2a775af02', option_text = 'distance and speed', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '9984bc58-3d19-47b5-9fda-5a192d109336';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', curriculum_id = 'as', topic_code = '1.8', syllabus_cite = '9702 1.8 Other examples of scalar and vector quantities', problem_number = 7, "order" = 7, question_text = 'A force of 50 N acts at 40° above the horizontal. Calculate the horizontal component of this force.', question_image_url = 'diagram:kin-1.8-q7', difficulty_level = 2, answer_type = 'numeric'::answer_type, answer_correct = '38.3', answer_unit = 'N', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Like any vector, a force resolves using horizontal = magnitude × cos(angle from horizontal): 50 × cos40° = 50 × 0.766 = 38.3 N. This is exactly the same technique used for resolving a displacement or velocity — the method for resolving any vector is identical, whatever physical quantity it represents. Common mistake: thinking force needs a different resolving technique from displacement or velocity, when the underlying vector mathematics is identical.', points = 2 WHERE id = '6f8e256f-793f-432e-91c8-623c1e1169bd';
UPDATE problems SET chapter_id = '4653a171-76f9-4b44-bc1d-19802787195f', topic_id = 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', curriculum_id = 'as', topic_code = '1.8', syllabus_cite = '9702 1.8 Other examples of scalar and vector quantities', problem_number = 8, "order" = 8, question_text = 'Identify the SCALAR quantity in this list.', question_image_url = NULL, difficulty_level = 2, answer_type = 'multiple_choice'::answer_type, answer_correct = 'power', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Power (the rate of transfer of energy) is a single number with no direction, so it is a scalar. Common mistake: assuming power must be a vector because it is closely related to force and velocity (both vectors) in the formula P = Fv — a product of two vectors used this way (through the dot product) can still give a scalar result.', points = 2 WHERE id = '74dc244f-4167-48e0-ba50-87be28baefb7';
UPDATE problem_options SET problem_id = '74dc244f-4167-48e0-ba50-87be28baefb7', option_text = 'power', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = '4d2e5054-e66d-433e-be5b-82f6ff86d71c';
UPDATE problem_options SET problem_id = '74dc244f-4167-48e0-ba50-87be28baefb7', option_text = 'momentum', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = 'cbfb15f5-3fd6-47b7-ab71-b560add9b566';
UPDATE problem_options SET problem_id = '74dc244f-4167-48e0-ba50-87be28baefb7', option_text = 'force', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '63c250df-498c-4773-9f5d-47aa2dcc8e68';
UPDATE problem_options SET problem_id = '74dc244f-4167-48e0-ba50-87be28baefb7', option_text = 'acceleration', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '0b4fbbc8-0d55-4520-9600-757f76e96b13';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '8ba3439e-0247-4a40-8f47-a5945e5c2968', curriculum_id = 'as', topic_code = '2.1', syllabus_cite = '9702 2.1 The meaning of acceleration', problem_number = 1, "order" = 1, question_text = 'Which statement correctly defines acceleration?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'Acceleration is the rate of change of velocity', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Acceleration is the rate of change of velocity: a = Δv ÷ Δt. Like velocity, it is a vector, with a direction as well as a size. Common mistake: defining acceleration as "speeding up", which misses that acceleration also describes slowing down, and any change of direction.', points = 1 WHERE id = 'f8bf04cc-1ab1-4e5e-9aac-9f3c04cf62db';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '8ba3439e-0247-4a40-8f47-a5945e5c2968', curriculum_id = 'as', topic_code = '2.1', syllabus_cite = '9702 2.1 The meaning of acceleration', problem_number = 2, "order" = 2, question_text = 'A ball moving forward is slowing down. In which direction does its acceleration point, relative to its direction of motion?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'Opposite to the direction of motion', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'When an object slows down, its velocity is decreasing, so Δv (and hence the acceleration) points OPPOSITE to the direction of motion — this is what ''deceleration'' means in vector terms. Common mistake: assuming acceleration must always point in the same direction as the velocity, which is only true while an object is speeding up.', points = 1 WHERE id = '02e05a08-eaad-4e54-9837-81441faebbfc';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '8ba3439e-0247-4a40-8f47-a5945e5c2968', curriculum_id = 'as', topic_code = '2.1', syllabus_cite = '9702 2.1 The meaning of acceleration', problem_number = 3, "order" = 3, question_text = 'A car''s velocity increases from 10 m/s to 16 m/s in 3.0 s. Calculate its acceleration.', question_image_url = 'diagram:kin-2.1-q3', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '2', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'acceleration = Δv ÷ Δt = (16−10) ÷ 3.0 = 2.00 m/s². Common mistake: dividing the FINAL velocity (16 m/s) by the time instead of the CHANGE in velocity.', points = 1 WHERE id = 'a5a319e6-8070-4fef-ab20-457834b85cd0';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '8ba3439e-0247-4a40-8f47-a5945e5c2968', curriculum_id = 'as', topic_code = '2.1', syllabus_cite = '9702 2.1 The meaning of acceleration', problem_number = 4, "order" = 4, question_text = 'What does "uniform acceleration" mean?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'The velocity changes by equal amounts in equal time intervals', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Uniform acceleration means the velocity changes at a constant RATE — equal changes in velocity occur in equal time intervals, throughout the motion. Common mistake: confusing "uniform acceleration" with "uniform velocity" (constant speed, zero acceleration) — these describe very different motions.', points = 1 WHERE id = '812498d3-56ad-43cb-bc34-288d5a1f5168';
UPDATE problem_options SET problem_id = '812498d3-56ad-43cb-bc34-288d5a1f5168', option_text = 'The velocity changes by equal amounts in equal time intervals', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = '23f01c7f-5cf4-4af3-ba71-1bfd4ab336ad';
UPDATE problem_options SET problem_id = '812498d3-56ad-43cb-bc34-288d5a1f5168', option_text = 'The velocity never changes', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = '1c4adc68-9c49-40de-ab39-f533250f8a68';
UPDATE problem_options SET problem_id = '812498d3-56ad-43cb-bc34-288d5a1f5168', option_text = 'The object moves in a straight line at constant speed', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '3e7edd09-fe79-4dd0-99d5-151991fe59fa';
UPDATE problem_options SET problem_id = '812498d3-56ad-43cb-bc34-288d5a1f5168', option_text = 'The acceleration is always zero', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '6eaaef3d-cae0-476b-9a36-4546610f2cf6';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '8ba3439e-0247-4a40-8f47-a5945e5c2968', curriculum_id = 'as', topic_code = '2.1', syllabus_cite = '9702 2.1 The meaning of acceleration', problem_number = 5, "order" = 5, question_text = 'An object moves at a constant velocity of 15 m/s in a straight line. State its acceleration.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '0', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Since velocity is not changing at all, Δv = 0, so acceleration = 0 m/s². Common mistake: assuming a moving object must have a nonzero acceleration simply because it is moving — acceleration depends on whether the velocity is CHANGING, not on whether it is zero.', points = 1 WHERE id = '32ec2c96-f49b-4ae6-9bdc-5c85563955f4';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '8ba3439e-0247-4a40-8f47-a5945e5c2968', curriculum_id = 'as', topic_code = '2.1', syllabus_cite = '9702 2.1 The meaning of acceleration', problem_number = 6, "order" = 6, question_text = 'A train''s velocity is 20 m/s at the start of a time interval, and still 20 m/s at the end of it. Calculate its acceleration over that interval.', question_image_url = 'diagram:kin-2.1-f6', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '0', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Since the velocity is unchanged (Δv = 20−20 = 0), the acceleration is 0 m/s², whatever the length of the time interval. Common mistake: assuming a nonzero time interval must automatically give a nonzero acceleration — acceleration depends on the CHANGE in velocity, not on how much time has passed.', points = 1 WHERE id = '01a1d81c-8f8e-4ff2-a482-4620314051c7';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '91cb1c54-423a-4525-a723-99c1e9e9bf6b', curriculum_id = 'as', topic_code = '2.2', syllabus_cite = '9702 2.2 Calculating acceleration', problem_number = 1, "order" = 1, question_text = 'A car accelerates uniformly from rest to 100 km/h in 10 s. Calculate its acceleration, in m/s².', question_image_url = 'diagram:kin-2.2-f1', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '2.778', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'First convert to m/s: 100 ÷ 3.6 = 27.8 m/s. acceleration = Δv ÷ Δt = (27.8 − 0) ÷ 10 = 2.78 m/s². Common mistake: substituting 100 (in km/h) directly into the formula without converting to m/s first, which gives an answer with the wrong units entirely.', points = 1 WHERE id = '43581613-ac55-41d6-8a6e-1336579b8b1c';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '91cb1c54-423a-4525-a723-99c1e9e9bf6b', curriculum_id = 'as', topic_code = '2.2', syllabus_cite = '9702 2.2 Calculating acceleration', problem_number = 2, "order" = 2, question_text = 'A bullet decelerates from 400 m/s to rest in 0.020 s as it embeds in a block of wood. Calculate the magnitude of its acceleration.', question_image_url = 'diagram:kin-2.2-f2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '20000', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'magnitude = Δv ÷ Δt = (400−0) ÷ 0.020 = 20000 m/s² — an enormous deceleration, typical of a rapid impact. Common mistake: mishandling the division by a very small time, e.g. multiplying by 0.020 instead of dividing by it.', points = 1 WHERE id = 'ef3121b1-b9b1-405a-8026-e9e3ecee76a0';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '91cb1c54-423a-4525-a723-99c1e9e9bf6b', curriculum_id = 'as', topic_code = '2.2', syllabus_cite = '9702 2.2 Calculating acceleration', problem_number = 3, "order" = 3, question_text = 'Rearranging a = Δv ÷ Δt to make Δv the subject gives which equation?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'Δv = aΔt', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Multiplying both sides of a = Δv ÷ Δt by Δt isolates Δv: Δv = a × Δt. Common mistake: dividing instead of multiplying when rearranging, which would give Δv = a ÷ Δt — the wrong operation entirely.', points = 1 WHERE id = 'fda7f4d0-f229-4a40-a08c-bd89639d485f';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '91cb1c54-423a-4525-a723-99c1e9e9bf6b', curriculum_id = 'as', topic_code = '2.2', syllabus_cite = '9702 2.2 Calculating acceleration', problem_number = 4, "order" = 4, question_text = 'An object has initial velocity 5.0 m/s and a constant acceleration of 3.0 m/s² for 4.0 s. Calculate its final velocity.', question_image_url = 'diagram:kin-2.2-f4', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '17', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'v = u + at = 5.0 + 3.0 × 4.0 = 17.0 m/s. Common mistake: forgetting to add the initial velocity (5.0 m/s), and giving just a × t = 12 m/s as the final velocity.', points = 1 WHERE id = 'bfd31cf4-a2f8-4a9a-9f75-0ae22167f009';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '91cb1c54-423a-4525-a723-99c1e9e9bf6b', curriculum_id = 'as', topic_code = '2.2', syllabus_cite = '9702 2.2 Calculating acceleration', problem_number = 5, "order" = 5, question_text = 'An object starts from rest and accelerates at 6.0 m/s². Calculate the time taken to reach 30 m/s.', question_image_url = 'diagram:kin-2.2-f5', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '5', answer_unit = 's', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 't = Δv ÷ a = (30−0) ÷ 6.0 = 5.00 s. Common mistake: multiplying 30 by 6.0 instead of dividing, which confuses the rearrangement of the acceleration formula.', points = 1 WHERE id = 'f0233df3-5933-476a-84c3-e258c2ccb9a5';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '91cb1c54-423a-4525-a723-99c1e9e9bf6b', curriculum_id = 'as', topic_code = '2.2', syllabus_cite = '9702 2.2 Calculating acceleration', problem_number = 6, "order" = 6, question_text = 'An object has a final velocity of 20 m/s after accelerating at −2.0 m/s² for 5.0 s. Calculate its initial velocity.', question_image_url = 'diagram:kin-2.2-f6', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '30', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'v = u + at, so u = v − at = 20 − ((−2.0) × 5.0) = 20 − (−10) = 30.0 m/s. Common mistake: computing 20 − (2.0 × 5.0) = 10 m/s, forgetting that the acceleration itself is negative, so subtracting it actually ADDS 10.', points = 1 WHERE id = '64d8d62e-ef09-4a0b-be9e-86f6c9c9fec8';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'cfa4c849-4465-4806-9a6e-29163a3db134', curriculum_id = 'as', topic_code = '2.3', syllabus_cite = '9702 2.3 Units of acceleration', problem_number = 1, "order" = 1, question_text = 'What is the SI base unit of acceleration?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'm s⁻² (metres per second squared)', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Acceleration = velocity ÷ time = (distance ÷ time) ÷ time = distance ÷ time², so its SI base unit is metres per second squared, written m s⁻². Common mistake: writing "m/s" (the unit of velocity) instead of "m/s²" for acceleration.', points = 1 WHERE id = '1919969a-98b7-4d4b-9e0c-66b80ebf00c4';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'cfa4c849-4465-4806-9a6e-29163a3db134', curriculum_id = 'as', topic_code = '2.3', syllabus_cite = '9702 2.3 Units of acceleration', problem_number = 2, "order" = 2, question_text = 'An acceleration of 5.0 m/s² can also be written as "5.0 metres per second, per second". Express this acceleration in km/h per second.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '18', answer_unit = 'km/h/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Since 1 m/s = 3.6 km/h, the same conversion factor applies directly to an acceleration expressed this way: 5.0 × 3.6 = 18.0 km/h per second — meaning the velocity increases by 18.0 km/h with every second that passes. Common mistake: trying to convert the "per second" part of the unit as well, when only the velocity part (m/s → km/h) needs converting here.', points = 1 WHERE id = '3bb619cc-db00-4911-9f50-29d6a37510ff';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'cfa4c849-4465-4806-9a6e-29163a3db134', curriculum_id = 'as', topic_code = '2.3', syllabus_cite = '9702 2.3 Units of acceleration', problem_number = 3, "order" = 3, question_text = 'A car''s acceleration is 20 m/s². Express this as a multiple of g (take g = 9.81 m/s²).', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '2.039', answer_unit = NULL, answer_unit_required = false, answer_tolerance = 0.05, answer_sign_sensitive = false, explanation = 'Number of g = acceleration ÷ g = 20 ÷ 9.81 = 2.04. Common mistake: multiplying by 9.81 instead of dividing, which would give a much larger (and wrong) number.', points = 1 WHERE id = 'e9f5387d-8e23-4eb0-bfd6-73f51af98e70';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'cfa4c849-4465-4806-9a6e-29163a3db134', curriculum_id = 'as', topic_code = '2.3', syllabus_cite = '9702 2.3 Units of acceleration', problem_number = 4, "order" = 4, question_text = 'What does the compound unit "m s⁻²" actually mean, physically?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'The velocity changes by that many m/s, for every second that passes', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'It means the velocity changes by that many metres per second, for every second that passes — "metres per second, per second". Common mistake: reading m s⁻² as simply "metres, very fast" without appreciating that it is a RATE of a rate: how quickly the velocity itself is changing.', points = 1 WHERE id = 'a3e5d9ca-067d-48aa-8cc5-f00e794d9155';
UPDATE problem_options SET problem_id = 'a3e5d9ca-067d-48aa-8cc5-f00e794d9155', option_text = 'The velocity changes by that many m/s, for every second that passes', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = 'b3ef7077-85b5-498f-98e5-116f08057fc6';
UPDATE problem_options SET problem_id = 'a3e5d9ca-067d-48aa-8cc5-f00e794d9155', option_text = 'The object travels that many metres every second', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = 'f0c7f311-1f74-4607-8c48-7537e596251a';
UPDATE problem_options SET problem_id = 'a3e5d9ca-067d-48aa-8cc5-f00e794d9155', option_text = 'The object’s distance doubles every second', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '024d4b25-d497-44e3-8172-cc938c54bb84';
UPDATE problem_options SET problem_id = 'a3e5d9ca-067d-48aa-8cc5-f00e794d9155', option_text = 'The object’s mass changes by that amount every second', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '91657e38-a5df-45b8-93de-9d1425c48967';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'cfa4c849-4465-4806-9a6e-29163a3db134', curriculum_id = 'as', topic_code = '2.3', syllabus_cite = '9702 2.3 Units of acceleration', problem_number = 5, "order" = 5, question_text = 'Express an acceleration of 0.50g in m/s² (take g = 9.81 m/s²).', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '4.905', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'acceleration = 0.50 × 9.81 = 4.91 m/s². Common mistake: dividing by 9.81 instead of multiplying, which is the reverse conversion.', points = 1 WHERE id = '40d141a1-556f-4754-b5a0-477b95325eb2';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'cfa4c849-4465-4806-9a6e-29163a3db134', curriculum_id = 'as', topic_code = '2.3', syllabus_cite = '9702 2.3 Units of acceleration', problem_number = 6, "order" = 6, question_text = 'Convert an acceleration of 7200 km/h² into m/s².', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '0.5556', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Convert km to m (×1000) and h² to s² (÷3600², since h² means the time unit is squared too): 7200 × 1000 ÷ 3600² = 0.556 m/s². Common mistake: dividing by 3600 only once, forgetting that BOTH factors of time in "per hour squared" need converting to seconds.', points = 1 WHERE id = '863b636b-3a5b-406b-b557-0a316b9383f9';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', curriculum_id = 'as', topic_code = '2.4', syllabus_cite = '9702 2.4 Deducing acceleration', problem_number = 1, "order" = 1, question_text = 'On a velocity-time graph, what does the gradient represent?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'acceleration', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Gradient = (change in velocity) ÷ (change in time), which is exactly the definition of acceleration. Common mistake: confusing this with a displacement-time graph’s gradient, which gives velocity, not acceleration.', points = 1 WHERE id = 'd82034d1-3bb8-48a9-88d8-9ee75df4fde4';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', curriculum_id = 'as', topic_code = '2.4', syllabus_cite = '9702 2.4 Deducing acceleration', problem_number = 2, "order" = 2, question_text = 'A velocity-time graph is a straight line from the origin to (5.0 s, 20 m/s). Calculate the acceleration it represents.', question_image_url = 'diagram:kin-2.4-q2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '4', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'acceleration = gradient = (20−0) ÷ (5.0−0) = 4.00 m/s². Common mistake: dividing time by velocity instead of velocity by time.', points = 1 WHERE id = 'c6e39ef3-228d-4447-aa37-dd97b065bf6e';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', curriculum_id = 'as', topic_code = '2.4', syllabus_cite = '9702 2.4 Deducing acceleration', problem_number = 3, "order" = 3, question_text = 'A velocity-time graph is a horizontal straight line. State the acceleration it represents.', question_image_url = 'diagram:kin-2.4-q3', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '0', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'A horizontal line has zero gradient, so the acceleration is 0 m/s² — the velocity is constant. Common mistake: confusing a horizontal line on a VELOCITY-time graph (constant velocity, zero acceleration) with a horizontal line on a DISPLACEMENT-time graph (object at rest).', points = 1 WHERE id = 'a4494a64-d084-4045-af49-046eaec66611';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', curriculum_id = 'as', topic_code = '2.4', syllabus_cite = '9702 2.4 Deducing acceleration', problem_number = 4, "order" = 4, question_text = 'Two velocity-time graphs are both straight lines from the origin. Line P is steeper than line Q. Which represents the LARGER acceleration?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'Line P', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'A steeper line on a velocity-time graph has a bigger gradient, and gradient = acceleration, so line P represents the larger acceleration. Common mistake: confusing this with the displacement-time case, where steepness instead compares velocities, not accelerations.', points = 1 WHERE id = '4b24d2bc-61bf-4b8f-83ab-fbba58cba325';
UPDATE problem_options SET problem_id = '4b24d2bc-61bf-4b8f-83ab-fbba58cba325', option_text = 'Line P', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = '71f6d5f0-7671-4442-867e-b3931a3d5b2c';
UPDATE problem_options SET problem_id = '4b24d2bc-61bf-4b8f-83ab-fbba58cba325', option_text = 'Line Q', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = '85938a77-8742-49db-b4a4-2d8cee824ac3';
UPDATE problem_options SET problem_id = '4b24d2bc-61bf-4b8f-83ab-fbba58cba325', option_text = 'They must be equal', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '46297baa-9ba7-4ba1-972d-dfd9f13cf232';
UPDATE problem_options SET problem_id = '4b24d2bc-61bf-4b8f-83ab-fbba58cba325', option_text = 'Cannot be determined from gradient alone', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '78fbdb5b-319f-448b-9e3b-5fe6e294c8ab';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', curriculum_id = 'as', topic_code = '2.4', syllabus_cite = '9702 2.4 Deducing acceleration', problem_number = 5, "order" = 5, question_text = 'A velocity-time graph is a straight line from (0 s, 15 m/s) to (3.0 s, 0 m/s). Calculate the acceleration.', question_image_url = 'diagram:kin-2.4-q5', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '-5', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'acceleration = (0−15) ÷ (3.0−0) = −5.00 m/s² — negative, since the object is decelerating. Common mistake: reporting the magnitude only (5.0 m/s²) without the negative sign that shows this is a deceleration.', points = 1 WHERE id = '1d308f51-9c74-4579-80d9-81c79e82326a';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', curriculum_id = 'as', topic_code = '2.4', syllabus_cite = '9702 2.4 Deducing acceleration', problem_number = 6, "order" = 6, question_text = 'A velocity-time graph is a straight line from (0 s, 5.0 m/s) to (10 s, 25 m/s). Calculate the acceleration.', question_image_url = 'diagram:kin-2.4-q6', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '2', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'acceleration = (25−5.0) ÷ (10−0) = 2.00 m/s². Common mistake: forgetting the non-zero starting velocity (5.0 m/s) is irrelevant to the GRADIENT calculation — only the CHANGE in velocity over the change in time matters for acceleration.', points = 1 WHERE id = '4cecb5c7-7c7d-4ace-9bb0-fc6c819bb337';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', curriculum_id = 'as', topic_code = '2.5', syllabus_cite = '9702 2.5 Deducing displacement', problem_number = 1, "order" = 1, question_text = 'What does the AREA under a velocity-time graph represent?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'displacement', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Area = velocity × time (for a simple rectangle), which has the units of displacement, and indeed represents exactly that: the displacement during that time interval. Common mistake: confusing this with the GRADIENT of a velocity-time graph, which instead gives acceleration.', points = 1 WHERE id = '613d3c8b-1f70-468f-a480-5123284e9f6a';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', curriculum_id = 'as', topic_code = '2.5', syllabus_cite = '9702 2.5 Deducing displacement', problem_number = 2, "order" = 2, question_text = 'A velocity-time graph shows a constant velocity of 10 m/s for 5.0 s. Calculate the displacement.', question_image_url = 'diagram:kin-2.5-q2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '50', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The area under the graph is a rectangle: displacement = velocity × time = 10 × 5.0 = 50.0 m. Common mistake: trying to use a SUVAT equation here instead of simply recognising this as the area of a rectangle.', points = 1 WHERE id = '03cfd3b7-326b-4b36-91a1-ab419cd8627a';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', curriculum_id = 'as', topic_code = '2.5', syllabus_cite = '9702 2.5 Deducing displacement', problem_number = 3, "order" = 3, question_text = 'A velocity-time graph shows velocity increasing uniformly from rest to 20 m/s over 4.0 s. Calculate the displacement.', question_image_url = 'diagram:kin-2.5-q3', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '40', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The area under the graph is a triangle: displacement = ½ × base × height = ½ × 4.0 × 20 = 40.0 m. Common mistake: using the FINAL velocity as if it acted for the whole time (20 × 4.0 = 80 m), rather than recognising the velocity builds up gradually from zero.', points = 1 WHERE id = 'dfe8ec40-b306-4e46-a3a8-6504c19e7989';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', curriculum_id = 'as', topic_code = '2.5', syllabus_cite = '9702 2.5 Deducing displacement', problem_number = 4, "order" = 4, question_text = 'A velocity-time graph is a trapezium shape (the velocity rises, then stays constant). What is the best way to find the total displacement?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'Split it into a triangle and a rectangle, and add their areas', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Split the trapezium into a triangle (the rising part) and a rectangle (the constant part), find the area of each separately, then add them together. Common mistake: trying to apply a single rectangle or triangle formula to the WHOLE shape at once, when it is actually a combination of two simpler shapes.', points = 1 WHERE id = 'b70c415e-2c72-4297-899b-e4b572a96f74';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', curriculum_id = 'as', topic_code = '2.5', syllabus_cite = '9702 2.5 Deducing displacement', problem_number = 5, "order" = 5, question_text = 'A velocity-time graph shows a constant velocity of 6.0 m/s for 8.0 s, after which the object stops instantly. Calculate the displacement during the 8.0 s.', question_image_url = 'diagram:kin-2.5-q5', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '48', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The shape is a rectangle: displacement = 6.0 × 8.0 = 48.0 m. Common mistake: trying to account for the sudden stop at the end, which happens AFTER this 8.0 s interval and so does not affect this calculation.', points = 1 WHERE id = 'bc8c400d-c9d9-4769-9ba1-63105740be26';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', curriculum_id = 'as', topic_code = '2.5', syllabus_cite = '9702 2.5 Deducing displacement', problem_number = 6, "order" = 6, question_text = 'A velocity-time graph shows a velocity of 12 m/s decreasing uniformly to zero over 6.0 s. Calculate the displacement.', question_image_url = 'diagram:kin-2.5-q6', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '36', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'This is a triangle: displacement = ½ × 6.0 × 12 = 36.0 m. Common mistake: using the INITIAL velocity as if it acted throughout (12 × 6.0 = 72 m), rather than accounting for the steady decrease to zero.', points = 1 WHERE id = 'd8a833e0-881a-4bb5-b3ca-c85a7a8d39c3';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '97c777dc-0adf-4df6-bd8f-9c659f0ef783', curriculum_id = 'as', topic_code = '2.6', syllabus_cite = '9702 2.6 Measuring velocity and acceleration', problem_number = 1, "order" = 1, question_text = 'A ticker-tape timer marks a dot on a paper tape at a fixed frequency, powered from a 50 Hz AC mains supply. Calculate the time between consecutive dots.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '0.02', answer_unit = 's', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'time between dots = 1 ÷ frequency = 1 ÷ 50 = 0.0200 s. Common mistake: using the frequency value (50) directly as if it were itself a time, rather than taking its reciprocal.', points = 1 WHERE id = 'c3df792a-d696-41a7-a9e5-4668df39b926';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '97c777dc-0adf-4df6-bd8f-9c659f0ef783', curriculum_id = 'as', topic_code = '2.6', syllabus_cite = '9702 2.6 Measuring velocity and acceleration', problem_number = 2, "order" = 2, question_text = 'A ticker tape (dot interval 1/50 s, from a 50 Hz timer) shows a constant spacing of 3.0 cm between consecutive dots. Calculate the velocity this represents.', question_image_url = 'diagram:kin-2.6-q2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '1.5', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'velocity = spacing ÷ time interval = 0.030 ÷ (1/50) = 1.50 m/s. Common mistake: forgetting to convert the spacing from cm to m before dividing.', points = 1 WHERE id = 'de23b3a0-5ea9-461c-9817-7eafe8aa9142';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '97c777dc-0adf-4df6-bd8f-9c659f0ef783', curriculum_id = 'as', topic_code = '2.6', syllabus_cite = '9702 2.6 Measuring velocity and acceleration', problem_number = 3, "order" = 3, question_text = 'A light gate times how long a card of known length takes to pass through the beam. Which calculation gives the speed of the card?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'card length ÷ blocking time', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'speed = (length of the card) ÷ (time the beam is blocked). Common mistake: dividing the time by the length instead of the length by the time.', points = 1 WHERE id = '9b03c1f2-ad4a-49ac-a977-95021394b7db';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '97c777dc-0adf-4df6-bd8f-9c659f0ef783', curriculum_id = 'as', topic_code = '2.6', syllabus_cite = '9702 2.6 Measuring velocity and acceleration', problem_number = 4, "order" = 4, question_text = 'A card of length 5.0 cm takes 0.040 s to pass through a light gate. Calculate its speed.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '1.25', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = 0.05, answer_sign_sensitive = false, explanation = 'speed = length ÷ time = 0.050 ÷ 0.040 = 1.25 m/s. Common mistake: using the card length in cm directly in the division without converting to metres first.', points = 1 WHERE id = '85a7f068-a5c3-487a-8e37-eca315a914db';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '97c777dc-0adf-4df6-bd8f-9c659f0ef783', curriculum_id = 'as', topic_code = '2.6', syllabus_cite = '9702 2.6 Measuring velocity and acceleration', problem_number = 5, "order" = 5, question_text = 'On a ticker tape, the spacing between successive dots gets progressively LARGER along the tape. What does this show about the object’s motion?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'The object is accelerating (speeding up)', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Since the dots are made at equal time intervals, a growing spacing means the object is covering more distance in each equal time interval — so it is accelerating (speeding up). Common mistake: assuming the dot spacing itself is a measure of speed without reference to the fact that the TIME between dots is always the same, which is what makes the spacing meaningful.', points = 1 WHERE id = '6c69c918-1bf0-4f3f-942f-9ee3c3019f10';
UPDATE problem_options SET problem_id = '6c69c918-1bf0-4f3f-942f-9ee3c3019f10', option_text = 'The object is accelerating (speeding up)', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = 'c34583a3-604d-42e6-9bd4-c8a826f25c0b';
UPDATE problem_options SET problem_id = '6c69c918-1bf0-4f3f-942f-9ee3c3019f10', option_text = 'The object is decelerating', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = 'fb0b50be-274e-4c06-9034-d115ae8c10f0';
UPDATE problem_options SET problem_id = '6c69c918-1bf0-4f3f-942f-9ee3c3019f10', option_text = 'The object is moving at constant velocity', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '76643602-cf2b-4242-9675-b76810c42c13';
UPDATE problem_options SET problem_id = '6c69c918-1bf0-4f3f-942f-9ee3c3019f10', option_text = 'The timer is malfunctioning', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = 'e5546f43-328c-46bb-ace0-eef2a270ffae';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '97c777dc-0adf-4df6-bd8f-9c659f0ef783', curriculum_id = 'as', topic_code = '2.6', syllabus_cite = '9702 2.6 Measuring velocity and acceleration', problem_number = 6, "order" = 6, question_text = 'A ticker tape (50 Hz timer) has a constant spacing of 4.5 cm between dots. Calculate the velocity.', question_image_url = 'diagram:kin-2.6-q6', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '2.25', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = 0.05, answer_sign_sensitive = false, explanation = 'velocity = 0.045 ÷ (1/50) = 2.25 m/s. Common mistake: using 50 directly as the time interval instead of its reciprocal, 1/50 s.', points = 1 WHERE id = '1c234c4f-5dda-41d6-8e31-3e426c9e4055';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'c16862d4-9430-4015-95fa-20d7cf89a45d', curriculum_id = 'as', topic_code = '2.7', syllabus_cite = '9702 2.7 Determining velocity and acceleration in the laboratory', problem_number = 1, "order" = 1, question_text = 'In a light-gate experiment, a card’s length is measured with a ruler marked in mm. What is the main source of uncertainty in this length measurement?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'The precision of the ruler used to measure the card’s length', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'It comes from the precision of the ruler itself (and how well its scale can be read) — typically taken as half the smallest division, or the smallest division itself, depending on how the reading is made. Common mistake: assuming the light gate’s electronic timing is the main source of uncertainty in the LENGTH measurement, when the two (length and time) are measured by entirely separate instruments.', points = 1 WHERE id = '866c62d4-fc3e-4220-b00b-3ab498bd46a8';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'c16862d4-9430-4015-95fa-20d7cf89a45d', curriculum_id = 'as', topic_code = '2.7', syllabus_cite = '9702 2.7 Determining velocity and acceleration in the laboratory', problem_number = 2, "order" = 2, question_text = 'A card’s length is measured as 2.00 ± 0.05 cm. Calculate the percentage uncertainty in this measurement.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '2.5', answer_unit = '%', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'percentage uncertainty = (absolute uncertainty ÷ measured value) × 100% = (0.05 ÷ 2.00) × 100% = 2.50%. Common mistake: forgetting to multiply by 100 to express the result as a percentage.', points = 1 WHERE id = 'f1dc993d-7cba-48b9-a31f-0fa18fdeec0d';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'c16862d4-9430-4015-95fa-20d7cf89a45d', curriculum_id = 'as', topic_code = '2.7', syllabus_cite = '9702 2.7 Determining velocity and acceleration in the laboratory', problem_number = 3, "order" = 3, question_text = 'A light gate’s timer reads 0.0200 ± 0.0005 s. Calculate the percentage uncertainty in this time.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '2.5', answer_unit = '%', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'percentage uncertainty = (0.0005 ÷ 0.0200) × 100% = 2.50%. Common mistake: mixing up which number is the measurement and which is the uncertainty when both are small decimals.', points = 1 WHERE id = '984dd30c-ea37-40db-8b7d-e6dc1e7b8747';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'c16862d4-9430-4015-95fa-20d7cf89a45d', curriculum_id = 'as', topic_code = '2.7', syllabus_cite = '9702 2.7 Determining velocity and acceleration in the laboratory', problem_number = 4, "order" = 4, question_text = 'A velocity is calculated as (card length) ÷ (blocking time), where the length has a 2.5% uncertainty and the time has a 2.5% uncertainty. How do these combine to give the percentage uncertainty in the velocity?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'They add: 2.5% + 2.5% = 5.0%', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'For a quantity found by MULTIPLYING or DIVIDING two measurements, the percentage uncertainties simply ADD: 2.5% + 2.5% = 5.0%. Common mistake: trying to add the absolute uncertainties of the length (in cm) and the time (in s) directly, which are in completely different units and cannot be combined that way — only the PERCENTAGE uncertainties can be added directly like this.', points = 1 WHERE id = '4ce17118-596b-49c0-aff6-6a402202cc2a';
UPDATE problem_options SET problem_id = '4ce17118-596b-49c0-aff6-6a402202cc2a', option_text = 'They add: 2.5% + 2.5% = 5.0%', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = 'a0610a58-508e-430f-9324-4900f283f740';
UPDATE problem_options SET problem_id = '4ce17118-596b-49c0-aff6-6a402202cc2a', option_text = 'They are averaged: 2.5%', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = '11c999df-200f-4d8d-ae6e-af854f652472';
UPDATE problem_options SET problem_id = '4ce17118-596b-49c0-aff6-6a402202cc2a', option_text = 'They multiply: 2.5% × 2.5% = 6.25%', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = 'b6bc17e1-7075-474e-855d-5b527bdaf7a0';
UPDATE problem_options SET problem_id = '4ce17118-596b-49c0-aff6-6a402202cc2a', option_text = 'Only the larger of the two counts', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '72eab30a-0159-42dd-93c8-e199bcf26c4c';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'c16862d4-9430-4015-95fa-20d7cf89a45d', curriculum_id = 'as', topic_code = '2.7', syllabus_cite = '9702 2.7 Determining velocity and acceleration in the laboratory', problem_number = 5, "order" = 5, question_text = 'A card of length 3.00 cm takes 0.0200 s to pass through a light gate. Calculate the velocity.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '1.5', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'velocity = 0.0300 ÷ 0.0200 = 1.50 m/s. Common mistake: using the length in cm (3.00) directly without converting to metres.', points = 1 WHERE id = '560a27ed-694d-42ca-9e77-fa53116b5c58';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'c16862d4-9430-4015-95fa-20d7cf89a45d', curriculum_id = 'as', topic_code = '2.7', syllabus_cite = '9702 2.7 Determining velocity and acceleration in the laboratory', problem_number = 6, "order" = 6, question_text = 'A velocity is calculated as 1.5 m/s, with a percentage uncertainty of 5.0%. Calculate the absolute uncertainty in this velocity.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '0.075', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'absolute uncertainty = percentage uncertainty × value = 0.050 × 1.5 = 0.0750 m/s, so the velocity should be quoted as 1.5 ± 0.0750 m/s. Common mistake: reporting the percentage (5.0%) as if it were itself the absolute uncertainty in m/s.', points = 1 WHERE id = '77ec6226-3305-446b-acf2-cbc3b393369a';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '69f49b38-4492-521c-be78-56effb528ad2', curriculum_id = 'as', topic_code = '2.8', syllabus_cite = '9702 2.8 The equations of motion', problem_number = 1, "order" = 1, question_text = 'Given initial velocity u, acceleration a and time t, which SUVAT equation directly gives the final velocity v?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'v = u + at', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'v = u + at is the equation that directly connects u, a, t and v, with no displacement s involved at all. Common mistake: reaching for an equation that includes s, even though s is neither given nor asked for here.', points = 1 WHERE id = 'f00ffd28-22a8-5f26-a19b-80fd37ab60aa';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '69f49b38-4492-521c-be78-56effb528ad2', curriculum_id = 'as', topic_code = '2.8', syllabus_cite = '9702 2.8 The equations of motion', problem_number = 2, "order" = 2, question_text = 'An object has u = 5.0 m/s, a = 2.0 m/s² and t = 4.0 s. Calculate v using v = u + at.', question_image_url = 'diagram:kin-2.8-f2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '13', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'v = u + at = 5.0 + 2.0 × 4.0 = 13.0 m/s. Common mistake: computing a × t and forgetting to then add u.', points = 1 WHERE id = '04910081-3798-576e-ab9b-6ad7f46d14d3';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '69f49b38-4492-521c-be78-56effb528ad2', curriculum_id = 'as', topic_code = '2.8', syllabus_cite = '9702 2.8 The equations of motion', problem_number = 3, "order" = 3, question_text = 'An object starts from rest (u = 0) with a = 3.0 m/s² for t = 5.0 s. Calculate the displacement using s = ut + ½at².', question_image_url = 'diagram:kin-2.8-f3', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '37.5', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 's = ut + ½at² = (0×5.0) + ½×3.0×5.0² = 0 + 37.5 = 37.5 m. Common mistake: forgetting to square the time before multiplying by ½a.', points = 1 WHERE id = 'b707a772-9c5a-54e0-b1e6-a99c56f54df4';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '69f49b38-4492-521c-be78-56effb528ad2', curriculum_id = 'as', topic_code = '2.8', syllabus_cite = '9702 2.8 The equations of motion', problem_number = 4, "order" = 4, question_text = 'An object has u = 0, a = 4.0 m/s², and travels a displacement s = 20 m. Calculate v using v² = u² + 2as.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '12.65', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = 0.05, answer_sign_sensitive = false, explanation = 'v² = 0² + 2×4.0×20 = 160, so v = √160 = 12.6 m/s. Common mistake: forgetting to take the square root at the end, and giving the value of v² instead of v.', points = 1 WHERE id = '59a912ef-ff21-51e6-8934-e9e918d980b2';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '69f49b38-4492-521c-be78-56effb528ad2', curriculum_id = 'as', topic_code = '2.8', syllabus_cite = '9702 2.8 The equations of motion', problem_number = 5, "order" = 5, question_text = 'An object has u = 10 m/s, v = 20 m/s, and travels for t = 6.0 s. Calculate the displacement using s = ((u+v)/2)t.', question_image_url = 'diagram:kin-2.8-f5', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '90', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 's = ((10+20)/2) × 6.0 = 15 × 6.0 = 90.0 m. Common mistake: forgetting to divide (u+v) by 2 before multiplying by t, which would double the answer.', points = 1 WHERE id = '01dfc716-8423-55e9-b867-832642d80633';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '69f49b38-4492-521c-be78-56effb528ad2', curriculum_id = 'as', topic_code = '2.8', syllabus_cite = '9702 2.8 The equations of motion', problem_number = 6, "order" = 6, question_text = 'A question gives u, a and s, and asks for v, but does NOT give (or ask for) the time t. Which SUVAT equation should be used?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'v² = u² + 2as', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'v² = u² + 2as is the only one of the four SUVAT equations that does not contain t at all, making it the natural choice whenever time is neither given nor needed. Common mistake: trying to first calculate t from another equation (needlessly) before using a DIFFERENT equation to find v, when the t-free equation can get there directly.', points = 1 WHERE id = '67a91bc1-0942-5528-b17f-939c75d75a84';
UPDATE problem_options SET problem_id = '67a91bc1-0942-5528-b17f-939c75d75a84', option_text = 'v² = u² + 2as', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = '232928db-7d2f-5799-8ea7-2c94eb33375f';
UPDATE problem_options SET problem_id = '67a91bc1-0942-5528-b17f-939c75d75a84', option_text = 'v = u + at', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = 'fa75a345-85d9-554d-bf0e-0760f48615be';
UPDATE problem_options SET problem_id = '67a91bc1-0942-5528-b17f-939c75d75a84', option_text = 's = ut + ½at²', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '566b0ba8-d3d6-5bae-ad6f-0a910d5ae086';
UPDATE problem_options SET problem_id = '67a91bc1-0942-5528-b17f-939c75d75a84', option_text = 's = ((u+v)/2)t', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '713bc647-3dd3-578f-909b-68bb308728bf';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '69bb568e-7993-444e-9ce8-19ebbd98c526', curriculum_id = 'as', topic_code = '2.9', syllabus_cite = '9702 2.9 Deriving the equations of motion', problem_number = 1, "order" = 1, question_text = 'Starting from the definition a = (v−u)/t, which rearrangement correctly isolates v?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'v = u + at', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Multiplying both sides by t gives at = v−u, and adding u to both sides gives v = u + at. Common mistake: rearranging to v = u − at by mishandling which side the −u term ends up on.', points = 1 WHERE id = '236d63f4-3e1f-483a-b484-8b9cb0aa3b69';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '69bb568e-7993-444e-9ce8-19ebbd98c526', curriculum_id = 'as', topic_code = '2.9', syllabus_cite = '9702 2.9 Deriving the equations of motion', problem_number = 2, "order" = 2, question_text = 'Using v = u + at (derived from the definition of acceleration), find v for u = 4.0 m/s, a = 2.0 m/s², t = 3.0 s.', question_image_url = 'diagram:kin-2.9-f2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '10', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'v = u + at = 4.0 + 2.0×3.0 = 10.0 m/s. Common mistake: multiplying u by a instead of a by t.', points = 1 WHERE id = 'e836e86e-5c3c-4d76-9dbb-26ddd0deccda';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '69bb568e-7993-444e-9ce8-19ebbd98c526', curriculum_id = 'as', topic_code = '2.9', syllabus_cite = '9702 2.9 Deriving the equations of motion', problem_number = 3, "order" = 3, question_text = 'On a velocity-time graph, what physical quantity does the AREA under the line represent? (This fact underlies the derivation of s = ((u+v)/2)t.)', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'Displacement', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The area under a velocity-time graph represents displacement — this is the geometric fact that the equation s = ((u+v)/2)t is simply restating algebraically (the area of a trapezium with parallel sides u and v, and "height" t). Common mistake: thinking the AREA gives acceleration (that is instead the GRADIENT of the line).', points = 1 WHERE id = '2839f5a6-db51-490d-b2a6-3d18ddb960fd';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '69bb568e-7993-444e-9ce8-19ebbd98c526', curriculum_id = 'as', topic_code = '2.9', syllabus_cite = '9702 2.9 Deriving the equations of motion', problem_number = 4, "order" = 4, question_text = 'Using s = ((u+v)/2)t (the area of the trapezium under a velocity-time graph), find s for u = 4.0 m/s, v = 10 m/s, t = 3.0 s.', question_image_url = 'diagram:kin-2.9-f4', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '21', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 's = ((4.0+10)/2) × 3.0 = 7.0 × 3.0 = 21.0 m. Common mistake: forgetting to divide (u+v) by 2 before multiplying by t.', points = 1 WHERE id = '9265473a-39e4-445d-8132-e171969e08f6';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '69bb568e-7993-444e-9ce8-19ebbd98c526', curriculum_id = 'as', topic_code = '2.9', syllabus_cite = '9702 2.9 Deriving the equations of motion', problem_number = 5, "order" = 5, question_text = 'When u is NOT zero, the trapezium area under a velocity-time graph can be split into two simpler shapes to derive s = ut + ½at². What are they?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'A rectangle (area ut) and a triangle on top of it (area ½at²)', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'A rectangle of height u and width t (giving area ut), plus a triangle on top with base t and height (v−u) = at (giving area ½ × t × at = ½at²). Adding these two areas gives s = ut + ½at². Common mistake: trying to treat the whole trapezium as a single triangle, which only works correctly when u = 0.', points = 1 WHERE id = '02d62f7e-1b76-477a-aec3-171586cfb989';
UPDATE problem_options SET problem_id = '02d62f7e-1b76-477a-aec3-171586cfb989', option_text = 'A rectangle (area ut) and a triangle on top of it (area ½at²)', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = '33dfab98-e2ae-43dd-8dac-37bd8d4d509f';
UPDATE problem_options SET problem_id = '02d62f7e-1b76-477a-aec3-171586cfb989', option_text = 'Two identical rectangles', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = 'f4f37fb7-cca7-4254-8c43-6ad275593cc3';
UPDATE problem_options SET problem_id = '02d62f7e-1b76-477a-aec3-171586cfb989', option_text = 'A single triangle with base t and height v', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '7bd166ac-b240-40bd-81ca-a9b91d93932d';
UPDATE problem_options SET problem_id = '02d62f7e-1b76-477a-aec3-171586cfb989', option_text = 'A circle and a square', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = 'f9d3db94-d6a3-4a6e-abf7-147745cbcd5f';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '69bb568e-7993-444e-9ce8-19ebbd98c526', curriculum_id = 'as', topic_code = '2.9', syllabus_cite = '9702 2.9 Deriving the equations of motion', problem_number = 6, "order" = 6, question_text = 'Using s = ut + ½at² (the rectangle-plus-triangle derivation), find s for u = 4.0 m/s, a = 2.0 m/s², t = 3.0 s. (This should match the previous question’s answer, found by a different method.)', question_image_url = 'diagram:kin-2.9-f6', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '21', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 's = ut + ½at² = (4.0×3.0) + ½×2.0×3.0² = 12 + 9.0 = 21.0 m — the same as before, confirming the two derivations describe the same physical displacement. Common mistake: forgetting to square t before multiplying by ½a, which would change the triangle’s area calculation.', points = 1 WHERE id = '69e9a4f8-b0ee-44a7-a68e-67488b313256';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '643b6cd1-3fbe-4618-9330-b9d737f06161', curriculum_id = 'as', topic_code = '2.10', syllabus_cite = '9702 2.10 Uniform and non-uniform acceleration', problem_number = 1, "order" = 1, question_text = 'How can you tell, from a velocity-time graph, whether an acceleration is uniform or non-uniform?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = ('Straight line = uniform acceleration' || chr(59) || ' curved line = non-uniform acceleration'), answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'A STRAIGHT line means a constant gradient, so the acceleration is uniform (constant). A CURVED line means the gradient is itself changing, so the acceleration is non-uniform. Common mistake: assuming any graph that keeps rising must represent uniform acceleration, regardless of whether it is straight or curved.', points = 1 WHERE id = '3ddf8bec-c90d-46f0-aa14-52fe0a914fb8';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '643b6cd1-3fbe-4618-9330-b9d737f06161', curriculum_id = 'as', topic_code = '2.10', syllabus_cite = '9702 2.10 Uniform and non-uniform acceleration', problem_number = 2, "order" = 2, question_text = 'Velocity readings at t = 0, 1, 2, 3 s are v = 0, 5, 10, 15 m/s. Calculate the acceleration, and state whether it is uniform.', question_image_url = 'diagram:kin-2.10-q2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '5', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The velocity increases by exactly 5 m/s in each 1 s interval (5, 5, 5) — equal changes in equal times, confirming UNIFORM acceleration. acceleration = (15−0) ÷ 3 = 5.00 m/s². Common mistake: only checking the first and last values without confirming that the increases between EVERY pair of consecutive readings are actually equal.', points = 1 WHERE id = '1ebd062a-7ef8-415f-a045-ca0819ba9450';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '643b6cd1-3fbe-4618-9330-b9d737f06161', curriculum_id = 'as', topic_code = '2.10', syllabus_cite = '9702 2.10 Uniform and non-uniform acceleration', problem_number = 3, "order" = 3, question_text = 'Velocity readings at t = 0, 1, 2, 3 s are v = 0, 3, 8, 15 m/s. Calculate the average acceleration over the whole 3 s, and state whether the acceleration is uniform.', question_image_url = 'diagram:kin-2.10-q3', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '5', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The velocity increases by 3, then 5, then 7 m/s in successive 1 s intervals — these are NOT equal, so the acceleration is NON-uniform (it is increasing). The overall average acceleration is still well-defined: (15−0) ÷ 3 = 5.00 m/s². Common mistake: assuming an "average" can only be calculated for UNIFORM acceleration — an average acceleration can always be found from Δv/Δt, whether or not the acceleration is actually constant throughout.', points = 1 WHERE id = '2f6b2cbf-c9ed-44c9-aac8-978d8d078294';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '643b6cd1-3fbe-4618-9330-b9d737f06161', curriculum_id = 'as', topic_code = '2.10', syllabus_cite = '9702 2.10 Uniform and non-uniform acceleration', problem_number = 4, "order" = 4, question_text = 'A displacement-time graph is a smooth curve whose gradient increases at a perfectly constant rate as time passes. What does this indicate about the acceleration?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'The acceleration is uniform (constant)', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'If the gradient (velocity) increases steadily, that is precisely the definition of a CONSTANT (uniform) acceleration — even though the displacement-time graph itself is curved (a parabola), the underlying acceleration is uniform. Common mistake: assuming any curved displacement-time graph must represent non-uniform acceleration — a smooth, evenly-curving parabola is exactly what UNIFORM acceleration looks like on a displacement-time graph.', points = 1 WHERE id = 'f67fca47-da95-40cf-b27e-d0d134a34124';
UPDATE problem_options SET problem_id = 'f67fca47-da95-40cf-b27e-d0d134a34124', option_text = 'The acceleration is uniform (constant)', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = '1abc1c33-b5eb-4e45-beef-9149527230f2';
UPDATE problem_options SET problem_id = 'f67fca47-da95-40cf-b27e-d0d134a34124', option_text = 'The acceleration is non-uniform', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = '6370ba47-545c-4b3c-ad8a-6f91975d4935';
UPDATE problem_options SET problem_id = 'f67fca47-da95-40cf-b27e-d0d134a34124', option_text = 'The velocity is constant', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '7d772c08-6f36-4cde-bf67-1213a015b222';
UPDATE problem_options SET problem_id = 'f67fca47-da95-40cf-b27e-d0d134a34124', option_text = 'The object is not accelerating at all', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '985293c3-6719-426f-9806-9e42b8bf587d';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '643b6cd1-3fbe-4618-9330-b9d737f06161', curriculum_id = 'as', topic_code = '2.10', syllabus_cite = '9702 2.10 Uniform and non-uniform acceleration', problem_number = 5, "order" = 5, question_text = 'Velocity readings at t = 0, 2, 4, 6 s are v = 0, 8, 16, 24 m/s. Calculate the acceleration, and confirm it is uniform.', question_image_url = 'diagram:kin-2.10-q5', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '4', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The velocity increases by exactly 8 m/s in each 2 s interval — equal changes in equal times, confirming uniform acceleration. acceleration = (24−0) ÷ 6 = 4.00 m/s². Common mistake: using the WRONG time interval (for example, treating each step as 1 s instead of the actual 2 s between readings).', points = 1 WHERE id = '01f44e03-0dc3-42b1-94c1-b66e69bcadb7';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '643b6cd1-3fbe-4618-9330-b9d737f06161', curriculum_id = 'as', topic_code = '2.10', syllabus_cite = '9702 2.10 Uniform and non-uniform acceleration', problem_number = 6, "order" = 6, question_text = 'Which of these real situations is LEAST likely to involve exactly uniform acceleration?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'A car driving through city traffic', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'A car navigating city traffic constantly speeds up and slows down in response to other vehicles and traffic lights, so its acceleration is almost never constant for any length of time. By contrast, an object falling under gravity with negligible air resistance experiences very nearly uniform acceleration (g) throughout its fall. Common mistake: assuming "acceleration" in physics problems is always uniform just because it is easier to analyse that way — real motion is very often non-uniform.', points = 1 WHERE id = '2d8691a7-14cb-41bf-b82e-31d1fa4dcdbe';
UPDATE problem_options SET problem_id = '2d8691a7-14cb-41bf-b82e-31d1fa4dcdbe', option_text = 'A car driving through city traffic', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = '34c859fc-4185-4f1f-8765-739659258124';
UPDATE problem_options SET problem_id = '2d8691a7-14cb-41bf-b82e-31d1fa4dcdbe', option_text = 'An object in free fall with negligible air resistance', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = 'b9bc0d9e-fcc2-4257-9efc-7f0433ebf3fb';
UPDATE problem_options SET problem_id = '2d8691a7-14cb-41bf-b82e-31d1fa4dcdbe', option_text = 'A ball rolling down a smooth, fixed-angle ramp', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '557502d6-60df-427b-b907-96b1922b7460';
UPDATE problem_options SET problem_id = '2d8691a7-14cb-41bf-b82e-31d1fa4dcdbe', option_text = 'A trolley pulled by a constant force on a frictionless track', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = 'b01e14fb-0363-4321-a76a-63edf2b5e774';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'e8c99a42-f3ca-45a2-9197-567cfffa1146', curriculum_id = 'as', topic_code = '2.11', syllabus_cite = '9702 2.11 Acceleration caused by gravity', problem_number = 1, "order" = 1, question_text = 'In the absence of air resistance, do a heavy object and a light object dropped from the same height reach the ground at the same time?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'Yes — both accelerate at the same rate, g, regardless of mass', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Yes — without air resistance, every object near Earth’s surface accelerates downward at the same rate, g ≈ 9.81 m/s², regardless of its mass. This is because gravitational force increases with mass in exactly the same proportion as the resistance to acceleration (inertia) does, so the two effects cancel. Common mistake: assuming heavier objects must fall faster, based on everyday experience with air resistance (which affects light, large-surface-area objects like feathers far more than dense ones like hammers).', points = 1 WHERE id = 'ed04becf-44b3-443d-9edc-a9ab94b83245';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'e8c99a42-f3ca-45a2-9197-567cfffa1146', curriculum_id = 'as', topic_code = '2.11', syllabus_cite = '9702 2.11 Acceleration caused by gravity', problem_number = 2, "order" = 2, question_text = 'An object is dropped from rest. Calculate its velocity after falling for 2.0 s (take g = 9.81 m/s²).', question_image_url = 'diagram:kin-2.11-f2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '19.62', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = 0.05, answer_sign_sensitive = false, explanation = 'v = u + at = 0 + 9.81×2.0 = 19.6 m/s. Common mistake: forgetting that "dropped from rest" means u = 0, and instead treating 2.0 as if it were a given initial velocity.', points = 1 WHERE id = '8d54514e-bfdd-4f30-8595-eaf288b0a547';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'e8c99a42-f3ca-45a2-9197-567cfffa1146', curriculum_id = 'as', topic_code = '2.11', syllabus_cite = '9702 2.11 Acceleration caused by gravity', problem_number = 3, "order" = 3, question_text = 'An object is dropped from rest. Calculate the distance it falls in 3.0 s (take g = 9.81 m/s²).', question_image_url = 'diagram:kin-2.11-f3', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '44.15', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 's = ut + ½at² = 0 + ½×9.81×3.0² = 44.1 m. Common mistake: forgetting to square the time before multiplying by ½g.', points = 1 WHERE id = '0a8cd17b-6c95-4dae-97fd-871060888bc0';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'e8c99a42-f3ca-45a2-9197-567cfffa1146', curriculum_id = 'as', topic_code = '2.11', syllabus_cite = '9702 2.11 Acceleration caused by gravity', problem_number = 4, "order" = 4, question_text = 'In which direction does the acceleration due to gravity, g, act near the Earth’s surface?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'Vertically downward, towards the centre of the Earth', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Vertically downward, towards the centre of the Earth, at every point near the surface. Common mistake: assuming g only "acts" while an object is actually falling — it acts on any object at all times (even one held stationary, or thrown upward), it is just that other forces can balance it in those cases.', points = 1 WHERE id = '36e2bfec-6c52-43dc-bc09-33daa1bd0ff0';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'e8c99a42-f3ca-45a2-9197-567cfffa1146', curriculum_id = 'as', topic_code = '2.11', syllabus_cite = '9702 2.11 Acceleration caused by gravity', problem_number = 5, "order" = 5, question_text = 'An object is dropped from rest. Calculate its velocity after 1.5 s (take g = 9.81 m/s²).', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '14.71', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = 0.05, answer_sign_sensitive = false, explanation = 'v = 0 + 9.81×1.5 = 14.7 m/s. Common mistake: rounding g to 10 m/s² when the question expects the more precise value (9.81 m/s²) to be used throughout.', points = 1 WHERE id = '313b1c8f-a30e-4976-9eeb-e2b460d23663';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'e8c99a42-f3ca-45a2-9197-567cfffa1146', curriculum_id = 'as', topic_code = '2.11', syllabus_cite = '9702 2.11 Acceleration caused by gravity', problem_number = 6, "order" = 6, question_text = 'Does the acceleration due to gravity, g, depend on the mass of the falling object (ignoring air resistance)?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'No — g is independent of mass', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'No — g is the same for every object near the Earth’s surface, regardless of its mass, as long as air resistance can be ignored. Common mistake: confusing the ACCELERATION (the same for all masses) with the FORCE of gravity (the object’s weight), which is different for different masses — a bigger mass needs a bigger force to give it the SAME acceleration.', points = 1 WHERE id = '8ee133a0-1e98-4fb1-a5c0-52d7844be517';
UPDATE problem_options SET problem_id = '8ee133a0-1e98-4fb1-a5c0-52d7844be517', option_text = 'No — g is independent of mass', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = '0b9adeb3-6728-4775-84d0-e84d42d16027';
UPDATE problem_options SET problem_id = '8ee133a0-1e98-4fb1-a5c0-52d7844be517', option_text = 'Yes — heavier objects have a larger g', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = '502bd954-fe40-45c8-937a-75a50acdb9ec';
UPDATE problem_options SET problem_id = '8ee133a0-1e98-4fb1-a5c0-52d7844be517', option_text = 'Yes — lighter objects have a larger g', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = '3131281e-c79d-49d2-8b04-94b0581a9ddc';
UPDATE problem_options SET problem_id = '8ee133a0-1e98-4fb1-a5c0-52d7844be517', option_text = 'g depends on an object’s colour, not its mass', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '0cde395a-a1ce-41b3-983e-84bf137292f9';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', curriculum_id = 'as', topic_code = '2.12', syllabus_cite = '9702 2.12 Determining g', problem_number = 1, "order" = 1, question_text = 'In the simplest laboratory method for determining g, an object is dropped from rest through a measured height s, and the time t is recorded. Which rearrangement of s = ½gt² gives g?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'g = 2s/t²', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Rearranging s = ½gt² for g: multiply both sides by 2 and divide by t², giving g = 2s/t². Common mistake: forgetting to square t in the rearranged formula, and using g = 2s/t instead.', points = 1 WHERE id = '97509044-a72b-4da6-9a47-fd3cdab5e0d3';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', curriculum_id = 'as', topic_code = '2.12', syllabus_cite = '9702 2.12 Determining g', problem_number = 2, "order" = 2, question_text = 'An object falls 2.00 m from rest in 0.639 s. Calculate g using g = 2s/t².', question_image_url = 'diagram:kin-2.12-f2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '9.796', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'g = 2×2.00 ÷ 0.639² = 4.00 ÷ 0.408 = 9.80 m/s², close to the accepted value of 9.81 m/s². Common mistake: forgetting to square 0.639 before dividing.', points = 1 WHERE id = 'caa57374-5b0b-4eb5-a08b-7e2c35f5be8d';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', curriculum_id = 'as', topic_code = '2.12', syllabus_cite = '9702 2.12 Determining g', problem_number = 3, "order" = 3, question_text = 'Why is a free-fall timing typically repeated several times, with the results averaged, when determining g?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'It reduces the effect of random timing variation, giving a more reliable mean time', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Repeating the timing and averaging reduces the effect of RANDOM variations (such as slight inconsistencies in exactly when the object is released or the timer started/stopped), giving a more reliable final value of g than any single timing alone. Common mistake: believing one single, carefully-taken reading is just as good as an average of several repeats.', points = 1 WHERE id = '2aa2b971-e406-4ace-904e-9b8e79734a40';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', curriculum_id = 'as', topic_code = '2.12', syllabus_cite = '9702 2.12 Determining g', problem_number = 4, "order" = 4, question_text = 'An object falls 1.50 m from rest in 0.555 s. Calculate g.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '9.739', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'g = 2×1.50 ÷ 0.555² = 3.00 ÷ 0.308 = 9.74 m/s². Common mistake: using the height in the wrong place in the formula (e.g. g = 2t²/s), which would give a completely different and meaningless number.', points = 1 WHERE id = '74499b02-723e-46c9-850e-9277fd7b1ab3';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', curriculum_id = 'as', topic_code = '2.12', syllabus_cite = '9702 2.12 Determining g', problem_number = 5, "order" = 5, question_text = 'In the graphical method for determining g, s (the height fallen) is plotted against t² (rather than against t). Why does this give a straight line, and what does its gradient represent?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'A straight line through the origin, with gradient ½g', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Since s = ½gt², plotting s against t² gives a straight line THROUGH THE ORIGIN (because s = ½g × (t²), which has the form y = mx with no constant term), whose gradient is ½g. Common mistake: plotting s against t directly, which gives a CURVE (a parabola), not a straight line, making the gradient much harder to measure accurately.', points = 1 WHERE id = '4697e9ae-896e-41f2-9a5d-e329eb2fd5bf';
UPDATE problem_options SET problem_id = '4697e9ae-896e-41f2-9a5d-e329eb2fd5bf', option_text = 'A straight line through the origin, with gradient ½g', option_letter = 'A', is_correct = true, "order" = 0 WHERE id = '67788b93-87f3-498e-b207-1439d79ee0c1';
UPDATE problem_options SET problem_id = '4697e9ae-896e-41f2-9a5d-e329eb2fd5bf', option_text = 'A straight line with gradient g, not through the origin', option_letter = 'B', is_correct = false, "order" = 1 WHERE id = 'aa0611e7-b56e-4e05-ae0a-ab82b45c59f6';
UPDATE problem_options SET problem_id = '4697e9ae-896e-41f2-9a5d-e329eb2fd5bf', option_text = 'A curve, since s and t² are unrelated', option_letter = 'C', is_correct = false, "order" = 2 WHERE id = 'ff3b540a-7f3c-4084-a5db-0b2175605b4f';
UPDATE problem_options SET problem_id = '4697e9ae-896e-41f2-9a5d-e329eb2fd5bf', option_text = 'A straight line with gradient 2g', option_letter = 'D', is_correct = false, "order" = 3 WHERE id = '94ecad61-8506-441d-87ff-7056c0bd1f63';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', curriculum_id = 'as', topic_code = '2.12', syllabus_cite = '9702 2.12 Determining g', problem_number = 6, "order" = 6, question_text = 'A graph of s against t² for a falling object has a gradient of 4.90 m/s². Calculate g.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '9.8', answer_unit = 'm/s²', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Since gradient = ½g, g = 2 × gradient = 2×4.90 = 9.80 m/s². Common mistake: quoting the gradient itself (4.90 m/s²) as g, forgetting the factor of ½ in s = ½gt².', points = 1 WHERE id = '42911929-c037-4679-8fb1-8d48507c8241';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '22a42568-867c-5245-91eb-c50c73e0ecb6', curriculum_id = 'as', topic_code = '2.13', syllabus_cite = '9702 2.13 Motion in two dimensions: projectiles', problem_number = 1, "order" = 1, question_text = 'In projectile motion with no air resistance, how are the horizontal and vertical components of the motion related?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'They are independent — horizontal velocity stays constant, vertical motion is simple free fall', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'They are completely INDEPENDENT of each other: the horizontal velocity stays constant throughout (no horizontal force acts), while the vertical motion accelerates downward at g, exactly as if it were simple free fall — neither component affects the other at all. Common mistake: assuming the vertical fall must somehow "use up" some of the horizontal motion, or that a faster horizontal launch makes an object fall more slowly.', points = 1 WHERE id = '85e6ac73-5f27-5879-aed0-17f5eb2a7918';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '22a42568-867c-5245-91eb-c50c73e0ecb6', curriculum_id = 'as', topic_code = '2.13', syllabus_cite = '9702 2.13 Motion in two dimensions: projectiles', problem_number = 2, "order" = 2, question_text = 'A ball is launched horizontally at 15 m/s from a table 1.0 m high. Calculate the time taken to reach the ground.', question_image_url = 'diagram:kin-2.13-f2', difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '0.4515', answer_unit = 's', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'The vertical motion is independent of the horizontal launch speed: it is simple free fall from rest (vertically), so 1.0 = ½×9.81×t², giving t = √(2×1.0 ÷ 9.81) = 0.452 s. Common mistake: trying to use the 15 m/s horizontal speed anywhere in this calculation — the time to fall depends ONLY on the height and g, not on how fast the ball is moving horizontally.', points = 1 WHERE id = 'ba9fea24-b648-55cf-8ab4-092fa5f7ae57';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '22a42568-867c-5245-91eb-c50c73e0ecb6', curriculum_id = 'as', topic_code = '2.13', syllabus_cite = '9702 2.13 Motion in two dimensions: projectiles', problem_number = 3, "order" = 3, question_text = 'Using the time found previously (0.4515 s) for the ball launched horizontally at 15 m/s from a 1.0 m table, calculate the horizontal range.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '6.773', answer_unit = 'm', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Horizontal motion has constant velocity (no horizontal acceleration): range = horizontal speed × time = 15 × 0.452 = 6.77 m. Common mistake: trying to apply a SUVAT acceleration equation to the horizontal motion, when the horizontal acceleration is exactly zero throughout the flight.', points = 1 WHERE id = 'fc81111c-7be0-5f0a-b424-3b1be78002d6';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '22a42568-867c-5245-91eb-c50c73e0ecb6', curriculum_id = 'as', topic_code = '2.13', syllabus_cite = '9702 2.13 Motion in two dimensions: projectiles', problem_number = 4, "order" = 4, question_text = 'During a projectile’s flight (no air resistance), what happens to the horizontal component of its velocity?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'It stays constant throughout the flight', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'It remains exactly constant throughout the whole flight, since no force acts horizontally (gravity acts only vertically). Common mistake: assuming the horizontal velocity must decrease as the object rises, or increase as it falls, confusing it with the VERTICAL component (which does change).', points = 1 WHERE id = 'f7550348-abc6-5b94-b64e-6a736b0ff0d5';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '22a42568-867c-5245-91eb-c50c73e0ecb6', curriculum_id = 'as', topic_code = '2.13', syllabus_cite = '9702 2.13 Motion in two dimensions: projectiles', problem_number = 5, "order" = 5, question_text = 'A ball undergoes projectile motion, launched horizontally. Calculate the magnitude of its vertical velocity component 2.0 s after launch.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '19.62', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = 0.05, answer_sign_sensitive = false, explanation = 'The vertical motion is simple free fall from vertical rest: v_y = gt = 9.81×2.0 = 19.6 m/s. Common mistake: including any horizontal speed in this calculation — the vertical component only ever depends on g and the time since launch (for a HORIZONTAL launch, where the initial vertical velocity is zero).', points = 1 WHERE id = '9e291f16-ea5b-5a55-b737-6d631a36712a';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', curriculum_id = 'as', topic_code = '2.14', syllabus_cite = '9702 2.14 Understanding projectiles', problem_number = 1, "order" = 1, question_text = 'What shape is the trajectory (path) of a projectile launched at an angle, with no air resistance?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'A parabola', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'It is a parabola — this follows directly from combining constant-velocity horizontal motion with constant-acceleration (free-fall) vertical motion. Common mistake: thinking the path is a simple straight line, or a circular arc, rather than the specific curve (a parabola) that this combination of motions actually produces.', points = 1 WHERE id = '177640c3-1783-45d3-90db-fa6111e09cda';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', curriculum_id = 'as', topic_code = '2.14', syllabus_cite = '9702 2.14 Understanding projectiles', problem_number = 2, "order" = 2, question_text = 'A projectile launched from and landing at the same height takes 1.2 s to reach its highest point. Using the symmetry of the trajectory, calculate the total time of flight.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '2.4', answer_unit = 's', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'By symmetry, the time to fall back down from the highest point to the original launch height equals the time taken to rise to it: total time = 2 × 1.2 = 2.4 s. Common mistake: forgetting to double the time to the highest point, and giving only 1.2 s as the total flight time.', points = 1 WHERE id = 'f4925bb2-fdf8-4c14-81bb-cffa39294a70';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', curriculum_id = 'as', topic_code = '2.14', syllabus_cite = '9702 2.14 Understanding projectiles', problem_number = 3, "order" = 3, question_text = 'For a given launch speed on level ground (no air resistance), which launch angle gives the maximum possible range?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = '45°', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Range = u²sin(2θ)/g is maximised when sin(2θ) = 1, which happens when 2θ = 90°, i.e. θ = 45°. Common mistake: assuming a very steep (e.g. nearly vertical) or very shallow (nearly horizontal) angle must give the greatest range — both of those actually give very SHORT ranges, with 45° being the balanced optimum.', points = 1 WHERE id = '1817e69b-fc0f-4a6d-9b2c-5ca05ad25dd6';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', curriculum_id = 'as', topic_code = '2.14', syllabus_cite = '9702 2.14 Understanding projectiles', problem_number = 4, "order" = 4, question_text = 'A projectile is launched at 22 m/s and lands back at exactly the same height from which it was launched (no air resistance). State its speed at the moment of landing.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '22', answer_unit = 'm/s', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'By the symmetry of projectile motion (and conservation of energy, since it returns to the same height), the landing speed exactly equals the launch speed: 22 m/s — though its DIRECTION is different (now angled downward rather than upward). Common mistake: assuming the ball must land more slowly because gravity has been "acting against it" throughout the flight.', points = 1 WHERE id = '7313908f-222d-4c37-92be-fd06dae7bdee';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', curriculum_id = 'as', topic_code = '2.14', syllabus_cite = '9702 2.14 Understanding projectiles', problem_number = 5, "order" = 5, question_text = 'Two projectiles are launched at the same speed, one at 30° and one at 60° above the horizontal. Which reaches the GREATER maximum height?', question_image_url = NULL, difficulty_level = 1, answer_type = 'multiple_choice'::answer_type, answer_correct = 'The one launched at 60°', answer_unit = NULL, answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Maximum height = u²sin²θ/(2g), which increases as θ increases towards 90° (since sinθ increases over this range). Since 60° has a larger sine than 30°, the 60° launch reaches the greater height. Common mistake: assuming a steeper angle must always mean a SHORTER flight overall, without separating out that it specifically increases height while (past 45°) decreasing range.', points = 1 WHERE id = 'be650e96-4830-4fe8-9378-46f1b6309457';
UPDATE problems SET chapter_id = 'ec015167-65fb-47df-b565-1055132ab4f3', topic_id = '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', curriculum_id = 'as', topic_code = '2.14', syllabus_cite = '9702 2.14 Understanding projectiles', problem_number = 6, "order" = 6, question_text = 'Time of flight is proportional to sinθ (for a given speed, on level ground). A projectile launched at 30° has a time of flight of 2.0 s. Estimate the time of flight for the same launch speed at 60°.', question_image_url = NULL, difficulty_level = 1, answer_type = 'numeric'::answer_type, answer_correct = '3.464', answer_unit = 's', answer_unit_required = false, answer_tolerance = NULL, answer_sign_sensitive = false, explanation = 'Since time of flight ∝ sinθ: ratio = sin60° ÷ sin30° = 0.866 ÷ 0.500 = 1.73. New time of flight = 2.0 × 1.73 = 3.46 s. Common mistake: assuming time of flight is proportional to the ANGLE itself (so 60° would simply be double the time for 30°) rather than to sinθ, which does not scale in the same simple way.', points = 1 WHERE id = 'fc29a213-81ff-491c-9b7b-7ff1345f5cd8';

COMMIT;
