INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('547f6fe9-3e4d-5833-b9af-f846dc5ccf52', 'ecf8e58b-e4d9-4ba0-a03a-a5a86e6f9a5c', 'distance travelled divided by the time taken', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('941f56c7-6b72-55c7-b849-4d3b64f2034c', 'ecf8e58b-e4d9-4ba0-a03a-a5a86e6f9a5c', 'displacement divided by the time taken', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('61c128d8-a8ca-5dca-afef-098ef7594980', 'ecf8e58b-e4d9-4ba0-a03a-a5a86e6f9a5c', 'the rate of change of velocity', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e99a0434-c12c-5809-8188-872c67c5ca9a', 'ecf8e58b-e4d9-4ba0-a03a-a5a86e6f9a5c', 'distance travelled multiplied by the time taken', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('894a9605-233b-5633-8c6b-e3657f92746c', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'as', '1.1', '9702 1.1 Speed', 10, 10, 'You shout towards a cliff and hear the echo 0.50 s later. Taking the speed of sound in air as 340 m/s, calculate your distance from the cliff.', 'diagram:kin-1.1-q10', 2, 'numeric'::answer_type, '85', 'm', false, NULL, false, 'The sound travels to the cliff and back in 0.50 s, so the total path length is 340 × 0.50 = 170 m. The distance to the cliff is half of this: 170 ÷ 2 = 85.0 m. Common mistake: forgetting the sound makes a round trip, and using the full 170 m as the distance to the cliff.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('31ec6cf0-9cc9-56a4-b3b7-73e56b92b028', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'as', '1.1', '9702 1.1 Speed', 11, 11, 'Usain Bolt''s 100 m world record is 9.58 s. Calculate his average speed over the race, in m/s, to 3 significant figures.', 'diagram:kin-1.1-q11', 2, 'numeric'::answer_type, '10.44', 'm/s', false, 0.05, false, 'speed = 100 ÷ 9.58 = 10.4 m/s. This is his AVERAGE speed over the whole race — his peak instantaneous speed partway through is higher, close to 12 m/s, because he is still accelerating during the first couple of seconds. Common mistake: rounding the time too early and losing a significant figure the question asks for.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('11893321-70f4-5155-b951-839a6e81a456', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'as', '1.1', '9702 1.1 Speed', 12, 12, 'A garden snail moves at a constant 0.014 m/s. Calculate the time, in minutes, for it to cross a 5.0 m path.', 'diagram:kin-1.1-q12', 2, 'numeric'::answer_type, '5.952', 'min', false, NULL, false, 't = distance ÷ speed = 5.0 ÷ 0.014 = 357 s. Converting to minutes: 357 ÷ 60 = 5.95 min. Common mistake: leaving the answer in seconds when the question asks for minutes.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('35cb75eb-6bdc-5583-88a1-9fcdf082f10c', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'as', '1.1', '9702 1.1 Speed', 13, 13, 'A spacecraft travels at a constant 1.2 × 10⁴ m/s. Calculate the time, in hours, for it to travel one astronomical unit (1 AU = 1.50 × 10¹¹ m).', NULL, 2, 'numeric'::answer_type, '3472', 'h', false, NULL, false, 't = distance ÷ speed = (1.50 × 10¹¹) ÷ (1.2 × 10⁴) = 1.25 × 10⁷ s. In hours: 1.25 × 10⁷ ÷ 3600 = 3470 h (about 140 days). Common mistake: mishandling the powers of ten when dividing two numbers in standard form.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0e290a5a-b6cb-5eab-9f9a-8279006a92cc', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'as', '1.1', '9702 1.1 Speed', 14, 14, 'A ferry crosses a 4.0 km wide channel. (a) Calculate the time for the outward crossing at an average speed of 8.0 km/h. (b) Calculate the time for the return crossing, along the same route, at an average speed of 12 km/h. (c) Calculate the average speed for the whole round trip. Give only the answer to (c).', 'diagram:kin-1.1-q14', 3, 'numeric'::answer_type, '9.6', 'km/h', false, NULL, false, ('(a) t₁ = 4.0 ÷ 8.0 = 0.500 h. (b) t₂ = 4.0 ÷ 12 = 0.333 h. (c) Average speed = total distance ÷ total time = 8.0 ÷ (0.500 + 0.333) = 8.0 ÷ 0.833 = 9.60 km/h. Common mistake: simply averaging 8.0 and 12 km/h to get 10 km/h — valid only if the two legs take equal TIME, not equal distance' || chr(59) || ' the slower leg here takes longer, pulling the true average below the simple mean.'), 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('bcd74601-560a-5355-8dd0-a48432d5ad5f', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'as', '1.1', '9702 1.1 Speed', 15, 15, 'A 45 km train journey is covered as follows: (a) the first 30 km at a constant 90 km/h, then (b) the remaining 15 km at a constant 30 km/h due to a speed restriction. (c) Calculate the average speed for the whole 45 km journey.', 'diagram:kin-1.1-q15', 3, 'numeric'::answer_type, '54', 'km/h', false, NULL, false, '(a) t₁ = 30 ÷ 90 = 0.333 h. (b) t₂ = 15 ÷ 30 = 0.500 h. (c) Average speed = total distance ÷ total time = 45 ÷ (0.333 + 0.500) = 45 ÷ 0.833 = 54.0 km/h. Common mistake: averaging 90 and 30 km/h to get 60 km/h — wrong, because the slow leg lasts longer (0.50 h vs 0.33 h) and so counts for more of the journey.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('cc040a22-f0fb-5ad4-90a5-faab48494992', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'as', '1.1', '9702 1.1 Speed', 16, 16, 'Concorde flew the 5560 km from London to New York, covering 560 km total during climb and descent at an average 306 m/s, and the remaining distance at a cruising speed of 680 m/s. Calculate the total flight time, in hours, to 3 significant figures.', 'diagram:kin-1.1-q16', 3, 'numeric'::answer_type, '2.551', 'h', false, 0.05, false, ('(a) Climb/descent: t₁ = 560 000 ÷ 306 = 1830 s. (b) Cruise distance = 5560 − 560 = 5000 km = 5.0 × 10⁶ m' || chr(59) || ' t₂ = (5.0 × 10⁶) ÷ 680 = 7350 s. (c) Total time = 1830 + 7350 = 9180 s = 2.55 h. Common mistake: forgetting to convert km to m before dividing by a speed given in m/s.'), 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f29d12bf-7337-5931-97e4-b510bc83fbb7', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'as', '1.1', '9702 1.1 Speed', 17, 17, 'In a 1000 m race: the hare runs the first 100 m at 8.0 m/s, then stops for a 1800 s nap, then sprints the final 900 m at 10 m/s. The tortoise walks the whole 1000 m at a steady 0.60 m/s. (a) Calculate the hare’s total time. (b) Calculate the tortoise’s total time. (c) By how many seconds does the tortoise win?', 'diagram:kin-1.1-q17', 3, 'numeric'::answer_type, '235.8', 's', false, NULL, false, '(a) Hare: t₁ = 100 ÷ 8.0 = 12.5 s running, plus the 1800 s nap, plus t₃ = 900 ÷ 10 = 90.0 s sprinting. Total = 12.5 + 1800 + 90.0 = 1900 s. (b) Tortoise: t = 1000 ÷ 0.60 = 1670 s. (c) The tortoise wins by 1900 − 1670 = 236 s. Common mistake: forgetting that the nap counts towards the hare’s total time even though no distance is covered during it.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('dc00b0ba-06ff-50ac-9943-a2b4cc453c9d', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'as', '1.1', '9702 1.1 Speed', 18, 18, ('A ship''s GPS log shows: in the first 24 minutes it covers 18.0 km on one heading' || chr(59) || ' it then changes course, and over the following 36 minutes it covers a further 14.0 km on the new heading. (a) Calculate the speed on the first leg, in km/h. (b) Calculate the speed on the second leg, in km/h. (c) Calculate the average speed for the whole hour.'), 'diagram:kin-1.1-q18', 3, 'numeric'::answer_type, '32', 'km/h', false, NULL, false, '(a) Leg 1: time = 24 min = 0.400 h, speed = 18.0 ÷ 0.400 = 45.0 km/h. (b) Leg 2: time = 36 min = 0.600 h, speed = 14.0 ÷ 0.600 = 23.3 km/h. (c) The two legs total exactly 60 minutes, so the average speed for the hour is simply the total distance covered in it: (18.0 + 14.0) ÷ 1.00 = 32.0 km/h. Common mistake: averaging the two leg speeds instead of using total distance ÷ total time — they only agree here because the legs happen to total exactly 60 minutes.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e7243be1-eae4-54c6-b951-35fa4246f2d0', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'as', '1.1', '9702 1.1 Speed', 19, 19, 'A journey is split into two equal DISTANCES d, travelled at constant speeds v₁ and v₂ respectively. Show that the average speed for the whole journey is 2v₁v₂/(v₁+v₂) — the harmonic mean, NOT the simple mean (v₁+v₂)/2. Then calculate this average speed for v₁ = 40 km/h and v₂ = 60 km/h.', 'diagram:kin-1.1-q19', 4, 'numeric'::answer_type, '48', 'km/h', false, NULL, false, 'Time for each leg: t₁ = d/v₁, t₂ = d/v₂. Total distance = 2d. Total time = d/v₁ + d/v₂ = d(v₁+v₂)/(v₁v₂). Average speed = total distance ÷ total time = 2d ÷ [d(v₁+v₂)/(v₁v₂)] = 2v₁v₂/(v₁+v₂) — the d cancels, so the result depends only on the two speeds. For v₁ = 40, v₂ = 60: average = (2 × 40 × 60) ÷ 100 = 48.0 km/h. Common mistake: quoting the simple mean (40+60)/2 = 50 km/h, which is only the correct average when the two legs take equal TIME, not equal distance — more time is spent at the slower speed when the distances match, which pulls the true average below 50.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('de2bb97a-0141-5ef9-8155-119ee0fff5cb', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'as', '1.1', '9702 1.1 Speed', 20, 20, 'Taking the speed of light as exactly 2.998 × 10⁸ m/s and one year as 365.25 days, calculate the distance represented by one light-year, in metres. Then estimate, to the nearest order of magnitude, how many Earth–Sun distances (1 AU = 1.496 × 10¹¹ m) this represents.', NULL, 4, 'numeric'::answer_type, '9.461e15', 'm', false, NULL, false, '1 year = 365.25 × 24 × 3600 = 3.16 × 10⁷ s. 1 light-year = c × t = (2.998 × 10⁸) × 3.16 × 10⁷ = 9.46 × 10¹⁵ m. Comparing to 1 AU: 9.46 × 10¹⁵ ÷ (1.496 × 10¹¹) = 63200 — of order 10⁵ AU. Common mistake: quoting the AU comparison as the final answer instead of the light-year distance the question actually asks for, or using 365 whole days (a small error here, but bad practice generally).', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('612fbf89-471e-5de7-a997-ce9d3e27b27c', '0bad663b-8bfe-41d3-ac46-902e868a3e04', ('Distance is a scalar' || chr(59) || ' displacement is a vector'), 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ecda34e8-afed-53bc-8d08-619bdab2abcf', '0bad663b-8bfe-41d3-ac46-902e868a3e04', 'Both are scalars', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('79b482ca-a750-5264-ad2a-1f31e09a7e7a', '0bad663b-8bfe-41d3-ac46-902e868a3e04', 'Both are vectors', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2b048a35-8f13-57bc-a098-5dbb50430a6c', '0bad663b-8bfe-41d3-ac46-902e868a3e04', ('Distance is a vector' || chr(59) || ' displacement is a scalar'), 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7feb4952-a016-5b31-b1b0-11797775e609', 'b121e968-668b-498f-897e-c5bc05905a21', 'displacement', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4acbb884-c2cd-50f2-976b-f722ec746626', 'b121e968-668b-498f-897e-c5bc05905a21', 'mass', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6a9b7d7c-3e1d-5211-90ad-675feeae357c', 'b121e968-668b-498f-897e-c5bc05905a21', 'distance', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9128b4cd-f305-5f02-8e99-57913cf7ffb5', 'b121e968-668b-498f-897e-c5bc05905a21', 'time', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a50bf1e3-866a-5fa9-b170-80bd1a644a17', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'as', '1.2', '9702 1.2 Distance and displacement, scalar and vector', 9, 9, 'A car travels 3.0 km east, then 4.0 km further east, then 2.0 km west. Calculate the magnitude of the final displacement from the start.', 'diagram:kin-1.2-q9', 2, 'numeric'::answer_type, '5 km', NULL, false, NULL, false, 'Taking east as positive: 3.0 + 4.0 − 2.0 = 5.00 km east. (The total distance travelled is larger, 3.0 + 4.0 + 2.0 = 9.0 km, because distance ignores the cancellation from reversing direction.) Common mistake: adding all three legs regardless of direction, which gives the distance (9.0 km) rather than the displacement.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e8a894fe-488d-52d8-bf44-54c5b275d248', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'as', '1.2', '9702 1.2 Distance and displacement, scalar and vector', 10, 10, 'Which of these statements about distance and displacement is FALSE?', NULL, 2, 'multiple_choice'::answer_type, 'The magnitude of displacement can be greater than the distance travelled', NULL, false, NULL, false, 'Distance can never be less than the magnitude of displacement, because displacement is the most direct (shortest) way between two points — any real path can only be the same length or longer. The false statement here is the one claiming displacement can exceed distance. Common mistake: picking a true statement by not reading "FALSE" carefully.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('468da513-37a6-56b9-84de-c130f8f29ee7', 'e8a894fe-488d-52d8-bf44-54c5b275d248', 'The magnitude of displacement can be greater than the distance travelled', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('efb3b66e-59c1-5d04-8ede-e7596526e200', 'e8a894fe-488d-52d8-bf44-54c5b275d248', 'Distance is always greater than or equal to the magnitude of displacement', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('82764b41-de7c-5189-984f-b1638fe85813', 'e8a894fe-488d-52d8-bf44-54c5b275d248', ('Displacement has a direction' || chr(59) || ' distance does not'), 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b3d5b887-df86-591a-8b28-778827df0e5d', 'e8a894fe-488d-52d8-bf44-54c5b275d248', 'If a journey has no change of direction, distance equals the magnitude of displacement', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('698d64f2-43bb-5137-97fa-dfb0c666aa0f', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'as', '1.2', '9702 1.2 Distance and displacement, scalar and vector', 11, 11, 'An ant walks from one corner of a square plot of side 8.0 m, along two adjacent sides, to the opposite corner. Calculate the magnitude of the ant''s displacement.', 'diagram:kin-1.2-q11', 2, 'numeric'::answer_type, '11.31', 'm', false, 0.05, false, 'The two sides are perpendicular, so the displacement is the diagonal of the square: √(8.0² + 8.0²) = √128 = 11.3 m. (The distance walked is 8.0 + 8.0 = 16 m, almost 1.4 times the displacement — this ratio, √2, appears whenever a right-angle path is cut by its own diagonal.) Common mistake: giving the distance (16 m) instead of the diagonal displacement.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('59e2e5c2-fb40-546d-9e82-608a21f29e41', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'as', '1.2', '9702 1.2 Distance and displacement, scalar and vector', 12, 12, 'A ship sails 40 km south, then 30 km west. Calculate the magnitude of the resultant displacement.', 'diagram:kin-1.2-q12', 2, 'numeric'::answer_type, '50 km', NULL, false, NULL, false, 'magnitude = √(40² + 30²) = √(1600 + 900) = √2500 = 50.0 m... careful with units: = 50.0 km. This is a 3–4–5 triangle scaled by 10. Common mistake: forgetting that south and west are perpendicular and simply adding 40 + 30 = 70 km.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('611f29ae-0c62-5057-b298-b6563036e412', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'as', '1.2', '9702 1.2 Distance and displacement, scalar and vector', 13, 13, 'Why can the magnitude of a displacement never be greater than the total distance travelled, but can be equal to it?', NULL, 2, 'multiple_choice'::answer_type, 'A straight line between two points is the shortest possible path, so distance (the actual path) is always at least as long as displacement (the straight-line separation)', NULL, false, NULL, false, 'The displacement is the length of the single straight line directly from the start to the finish — the shortest possible route between those two points. Any real path (the distance) can only match that straight line (if it never changes direction) or be longer (if it curves, loops back, or reverses at all). Common mistake: thinking a very winding path could somehow produce a displacement exceeding the ground actually covered.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b7f47aca-9f60-5b64-9560-1546be91ed95', '611f29ae-0c62-5057-b298-b6563036e412', 'A straight line between two points is the shortest possible path, so distance (the actual path) is always at least as long as displacement (the straight-line separation)', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('cc87ecfb-a348-5f57-84d4-165b5b3f6c35', '611f29ae-0c62-5057-b298-b6563036e412', 'Displacement always measures only half of the distance travelled', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('59d0f2b4-49f8-57a0-8791-ef766bcac464', '611f29ae-0c62-5057-b298-b6563036e412', 'Distance and displacement measure completely unrelated things with no general relationship', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2f700432-a72d-541b-a5fc-9265e2710957', '611f29ae-0c62-5057-b298-b6563036e412', 'Displacement is always exactly the distance divided by two', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4a39c3f6-edd6-591a-92c2-01d4555bb56a', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'as', '1.2', '9702 1.2 Distance and displacement, scalar and vector', 14, 14, 'A robot vacuum starts at a corner of a rectangular room 6.0 m by 8.0 m. It travels along one wall to the next corner (6.0 m), then along the adjacent wall to the far corner (8.0 m), then travels in a straight line directly back to its start. (a) Calculate the length of the straight diagonal return leg. (b) Calculate the total distance for the whole trip. Give only the answer to (b).', 'diagram:kin-1.2-q14', 3, 'numeric'::answer_type, '24', 'm', false, NULL, false, '(a) The two walls are perpendicular, so the diagonal is the hypotenuse: √(6.0² + 8.0²) = √(36+64) = √100 = 10.0 m (a 3-4-5 triangle scaled by 2). (b) Total distance = 6.0 + 8.0 + 10.0 = 24.0 m. Common mistake: using the diagonal as the room’s displacement from the START, forgetting the robot returns to its start, so its overall displacement for the whole trip is actually zero even though the distance is 24 m.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8ca70381-7b31-55bc-a209-cc39ae5f6f9d', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'as', '1.2', '9702 1.2 Distance and displacement, scalar and vector', 15, 15, 'A sailor travels 5.0 km due east, then a further distance X due north. The magnitude of the resulting displacement is measured as 13.0 km. (a) Use Pythagoras to find X. (b) Hence find the total distance sailed. (c) By how much does the total distance exceed the magnitude of the displacement? Give only the answer to (c).', 'diagram:kin-1.2-q15', 3, 'numeric'::answer_type, '4 km', NULL, false, NULL, false, '(a) The eastward leg, northward leg X and the 13.0 km displacement form a right triangle: 5.0² + X² = 13.0², so X² = 169 − 25 = 144 and X = 12.0 km (a 5-12-13 triangle). (b) Total distance = 5.0 + 12.0 = 17.0 km. (c) Excess = 17.0 − 13.0 = 4.00 km. Common mistake: adding 5.0 and 13.0 directly, or forgetting X is found from the DIFFERENCE of squares, not their sum.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3bf05efd-f3c3-54c3-aac5-9c7ebc650239', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'as', '1.2', '9702 1.2 Distance and displacement, scalar and vector', 16, 16, 'An orienteer runs 300 m north, then 400 m east, then 100 m south, then 100 m west. (a) Calculate the net north-south component of the displacement. (b) Calculate the net east-west component. (c) Calculate the magnitude of the resultant displacement. Give only the answer to (c), to 3 significant figures.', 'diagram:kin-1.2-q16', 3, 'numeric'::answer_type, '360.6', 'm', false, NULL, false, '(a) North-south: taking north as positive, 300 − 100 = 200 m north. (b) East-west: taking east as positive, 400 − 100 = 300 m east. (c) These two components are perpendicular, so the resultant magnitude is √(200² + 300²) = 361 m. Common mistake: adding all four leg lengths (300+400+100+100 = 900 m, the total distance) instead of first finding the net N-S and E-W components.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('924b1799-e60a-5cad-affd-de45ce2ce80f', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'as', '1.2', '9702 1.2 Distance and displacement, scalar and vector', 17, 17, 'A runner''s GPS watch records a total distance of 12.0 km for a looped route with a shortcut, covered at an average speed of 10.0 km/h. The runner''s displacement from start to finish is only 500 m, because the loop almost closes. (a) Calculate the time taken, in minutes. (b) Explain why the displacement is so much smaller than the distance. Give only the numerical answer to (a).', NULL, 3, 'numeric'::answer_type, '72', 'min', false, NULL, false, '(a) time = distance ÷ speed = 12.0 ÷ 10.0 = 1.20 h = 72.0 minutes. (b) The route loops around and nearly returns to the start, so most of the distance covered cancels out vectorially, leaving only a small net straight-line separation (500 m) between the start and finish points. Common mistake: using the displacement (500 m) instead of the distance (12.0 km) when finding the time from the average speed — average speed is always distance ÷ time, never displacement ÷ time (that combination defines average velocity instead).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('83a81f00-5da1-52cd-a88e-1f475026564c', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'as', '1.2', '9702 1.2 Distance and displacement, scalar and vector', 18, 18, 'A hiker walks 2.0 km on a bearing of 000° (due north), then 2.0 km on a bearing of 090° (due east), then 2.0 km on a bearing of 180° (due south). (a) Calculate the total distance walked. (b) Calculate the magnitude of the final displacement. (c) By what percentage does the distance exceed the displacement? Give only the answer to (c).', 'diagram:kin-1.2-q18', 3, 'numeric'::answer_type, '200', '%', false, NULL, false, '(a) Distance = 2.0 + 2.0 + 2.0 = 6.00 km. (b) The first and third legs are due north and due south — equal and opposite, so they cancel completely, leaving only the eastward leg: displacement = 2.00 km east. (c) Percentage excess = (6.00 − 2.00) ÷ 2.00 × 100% = 200%. Common mistake: forgetting that the north and south legs cancel exactly (they are equal in size and opposite in direction), and instead adding all three legs as if they all pointed the same way.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('69ee322b-9c1c-5be7-a592-ab7c0695f5d8', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'as', '1.2', '9702 1.2 Distance and displacement, scalar and vector', 19, 19, 'A robotic arm''s gripper traces a path described by four successive displacement vectors, in cm: (+40, 0), (0, +30), (−40, 0), (0, −10), where the first number is the horizontal (x) component and the second is the vertical (y) component. (a) Calculate the total distance travelled by the gripper. (b) Calculate the magnitude of the net displacement from its starting point. Give only the answer to (b).', 'diagram:kin-1.2-q19', 4, 'numeric'::answer_type, '20 cm', NULL, false, NULL, false, '(a) Distance sums the LENGTH of every leg regardless of sign: 40 + 30 + 40 + 10 = 120 cm. (b) Displacement sums each direction’s components algebraically: net x = 40 − 40 = 0 cm, net y = 30 − 10 = 20.0 cm. Since net x is zero, the net displacement is purely vertical: magnitude = 20.0 cm. Common mistake: treating the return leg of −40 cm in x as adding to the distance in the same direction as the first leg, rather than recognising it reverses that component (it still adds 40 cm to the DISTANCE, but subtracts 40 cm from the x-DISPLACEMENT).', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('89969c6c-caf3-5f3f-a888-0a21f9fec160', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'as', '1.2', '9702 1.2 Distance and displacement, scalar and vector', 20, 20, 'A point on a vibrating guitar string oscillates back and forth between two extreme positions a distance L apart, completing a whole number of full return trips so that it starts and finishes at the same point (zero overall displacement). Write an expression for the total distance travelled after n complete return trips, in terms of n and L, and evaluate it for n = 2500 and L = 0.015 m.', NULL, 4, 'numeric'::answer_type, '75', 'm', false, NULL, false, 'One complete return trip covers the gap twice (there and back), so it covers a distance of 2L. After n such trips, total distance = 2nL. For n = 2500 and L = 0.015 m: distance = 2 × 2500 × 0.015 = 75.0 m — a surprisingly large total distance for a string vibrating over a span of only 1.5 cm, even though the net displacement after a whole number of trips is exactly zero. Common mistake: writing nL instead of 2nL — each return trip is TWO crossings of the gap, not one.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0cb6a097-156d-5fb0-a003-aaf305a65caf', 'a16bb09d-949b-440e-ac9a-60d02379101b', ('Velocity has a direction and is the rate of change of displacement' || chr(59) || ' speed has no direction and is the rate of change of distance'), 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('da5b174f-49bf-5710-a831-7e5b140ca1c4', 'a16bb09d-949b-440e-ac9a-60d02379101b', 'Velocity and speed are always numerically different', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a7ad956c-391d-5daf-b408-af85531484ef', 'a16bb09d-949b-440e-ac9a-60d02379101b', 'Speed has a direction but velocity does not', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6340c790-2ef1-506e-8903-7c25139d63c8', 'a16bb09d-949b-440e-ac9a-60d02379101b', 'Velocity and speed are two names for exactly the same thing in every context', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('39210337-dba1-5307-81b2-9cbc9e7ba2ca', 'f0a139c9-9c17-4865-bbfd-1b50b116a00f', 'The car has reversed direction', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('66230402-9310-561d-afb0-4d1fbbd3de8d', 'f0a139c9-9c17-4865-bbfd-1b50b116a00f', 'The car has sped up in the same direction', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('67da8dcf-3362-5c66-bd44-bf9246492da6', 'f0a139c9-9c17-4865-bbfd-1b50b116a00f', 'The car''s direction is unaffected', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5fd0f080-0c2d-5397-bad0-88415e4233c7', 'f0a139c9-9c17-4865-bbfd-1b50b116a00f', 'The car has stopped', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2c22da13-95c6-54cc-bc22-441e95df71bd', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'as', '1.3', '9702 1.3 Speed and velocity', 9, 9, 'A swimmer swims 50 m along a straight pool, then swims back 50 m to the start, taking 40 s for each length. Calculate the average VELOCITY for the whole 80 s swim.', 'diagram:kin-1.3-q9', 2, 'numeric'::answer_type, '0', 'm/s', false, NULL, false, 'The swimmer finishes exactly where they started, so the total displacement is 0 m, and average velocity = 0 ÷ 80 = 0 m/s. (Their average SPEED is very different: total distance 100 m ÷ 80 s = 1.25 m/s — speed and velocity can disagree sharply for a there-and-back journey.) Common mistake: calculating the average speed (1.25 m/s) when the question specifically asks for average velocity.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1aaaf2c3-9c24-56e0-aedb-54654ffd21ff', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'as', '1.3', '9702 1.3 Speed and velocity', 10, 10, 'Taking the starting direction as positive, a particle''s displacement decreases uniformly from +12 m to −8 m over 5.0 s. Calculate its velocity.', 'diagram:kin-1.3-q10', 2, 'numeric'::answer_type, '-4', 'm/s', false, NULL, false, 'Because the change is uniform (a steady rate), the velocity is constant and equals the overall rate of change: velocity = ((−8) − (+12)) ÷ 5.0 = (−20) ÷ 5.0 = −4.00 m/s. The negative sign shows the particle moves in the negative direction throughout. Common mistake: computing (12 − (−8)) instead of ((−8) − 12), which flips the sign of the answer.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('81ab6dd4-32e7-534a-99b1-dbb42243269e', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'as', '1.3', '9702 1.3 Speed and velocity', 11, 11, 'Which of these could describe an object moving with truly constant velocity?', NULL, 2, 'multiple_choice'::answer_type, 'A car moving along a straight, flat road at a steady 60 km/h', NULL, false, NULL, false, 'Constant velocity needs BOTH constant speed AND constant direction — motion in a straight line at an unchanging speed. An object going around a circular track at constant speed is NOT at constant velocity, because its direction is continuously changing, even though its speed never does. Common mistake: picking the circular-track option because its speed is described as constant, overlooking the changing direction.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7ae8dce2-c47d-5552-bac9-759e11d84706', '81ab6dd4-32e7-534a-99b1-dbb42243269e', 'A car moving along a straight, flat road at a steady 60 km/h', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('22fe816b-3c5c-52e8-86c9-9f9ba8445cd2', '81ab6dd4-32e7-534a-99b1-dbb42243269e', 'A car moving at a steady 60 km/h around a circular track', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('23bc0b0c-4278-5f5b-816b-f33f062c4ec0', '81ab6dd4-32e7-534a-99b1-dbb42243269e', 'A ball thrown vertically upward and falling back down', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b230abdd-0630-5723-849d-e85ec40fd6ed', '81ab6dd4-32e7-534a-99b1-dbb42243269e', 'A pendulum swinging back and forth', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2ebf08eb-b610-5e4d-b18d-8cb50b4d0319', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'as', '1.3', '9702 1.3 Speed and velocity', 12, 12, 'Taking upward as positive, a lift descends 18 m in 9.0 s at a constant rate. Calculate its velocity.', 'diagram:kin-1.3-q12', 2, 'numeric'::answer_type, '-2', 'm/s', false, NULL, false, 'Since the lift moves downward, its displacement is negative: velocity = (−18) ÷ 9.0 = −2.00 m/s. Common mistake: giving +2.0 m/s by forgetting that "descends" means the displacement (and hence the velocity) is negative with upward taken as positive.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('29863651-25af-5bde-aaa7-8f905c0c365b', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'as', '1.3', '9702 1.3 Speed and velocity', 13, 13, 'Taking the outbound direction as positive, a train travels +300 m in 60 s, then reverses and travels −100 m in the next 40 s. Calculate its average velocity for the whole 100 s.', 'diagram:kin-1.3-q13', 2, 'numeric'::answer_type, '2', 'm/s', false, NULL, false, 'Total displacement = 300 + (−100) = 200 m over a total time of 60 + 40 = 100 s. Average velocity = 200 ÷ 100 = 2.00 m/s. Common mistake: using only one of the two phases, or adding the TIMES with the wrong sign instead of the displacements.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('dcfa5532-3a45-5aea-985c-71ad24331f91', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'as', '1.3', '9702 1.3 Speed and velocity', 14, 14, 'Taking upward as positive, a lift rises 15 m in 10 s, waits at that floor for 20 s, then descends 9.0 m in 6.0 s. (a) Calculate the net displacement for the whole trip. (b) Calculate the total time taken. (c) Calculate the average velocity for the whole trip. Give only the answer to (c).', 'diagram:kin-1.3-q14', 3, 'numeric'::answer_type, '0.1667', 'm/s', false, 0.05, false, '(a) Net displacement = 15 + (−9.0) = 6.00 m. (b) Total time = 10 + 20 + 6.0 = 36.0 s (the 20 s wait counts, even though no displacement happens during it). (c) Average velocity = 6.00 ÷ 36.0 = 0.167 m/s. Common mistake: leaving out the 20 s waiting time, which would badly overstate the average velocity.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0544720b-0f2c-5d68-862b-cdc86982c6e7', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'as', '1.3', '9702 1.3 Speed and velocity', 15, 15, 'Taking rightward as positive, a particle moves with velocity +8.0 m/s for the first 4.0 s of a journey, then with velocity −2.0 m/s for the next 6.0 s. (a) Calculate the displacement during the first part. (b) Calculate the displacement during the second part. (c) Calculate the average velocity for the whole 10 s. Give only the answer to (c).', 'diagram:kin-1.3-q15', 3, 'numeric'::answer_type, '2', 'm/s', false, NULL, false, '(a) Displacement 1 = 8.0 × 4.0 = 32.0 m. (b) Displacement 2 = (−2.0) × 6.0 = −12.0 m. (c) Total displacement = 32.0 + (−12.0) = 20.0 m over 10 s, so average velocity = 20.0 ÷ 10 = 2.00 m/s. Common mistake: averaging +8.0 and −2.0 to get +3.0 m/s, which ignores that the two phases last different amounts of time.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9086fa35-c3c5-5f4c-bc27-e3a4ee49ad7f', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'as', '1.3', '9702 1.3 Speed and velocity', 16, 16, 'A rocket sled''s displacement increases by +120 m during a 5.0 s launch phase, then by a further +30 m during a 3.0 s braking phase before it stops. (a) Calculate the velocity during the launch phase. (b) Calculate the velocity during the braking phase. (c) Calculate the average velocity for the whole 8.0 s. Give only the answer to (c).', 'diagram:kin-1.3-q16', 3, 'numeric'::answer_type, '18.75', 'm/s', false, NULL, false, '(a) Launch: velocity = 120 ÷ 5.0 = 24.0 m/s. (b) Braking: velocity = 30 ÷ 3.0 = 10.0 m/s. (c) Both displacements are in the same direction, so total displacement = 120 + 30 = 150 m over 8.0 s: average velocity = 150 ÷ 8.0 = 18.8 m/s. Common mistake: averaging the two phase velocities, (24.0+10.0)/2 = 17 m/s, instead of using total displacement ÷ total time (the phases last different lengths of time, so this simple mean is wrong).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e27921e1-ea77-5e3e-b9db-b5e28b64532b', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'as', '1.3', '9702 1.3 Speed and velocity', 17, 17, 'The table shows a cyclist’s displacement from a fixed point at various times. Calculate the average velocity between t = 0 s and t = 20 s.', 'diagram:kin-1.3-q17', 3, 'numeric'::answer_type, '1.8', 'm/s', false, NULL, false, 'Average velocity only needs the two end values, not what happens in between: average velocity = (displacement at 20 s − displacement at 0 s) ÷ (20 − 0) = (36 − 0) ÷ 20 = 1.80 m/s. (Between t = 10 s and t = 15 s the displacement does not change at all — the cyclist was stationary — but this does not affect the average over the full 20 s, since only the two endpoints matter.) Common mistake: trying to average the individual readings in the table (0, 8, 20, 20, 36) instead of using only the first and last values together with the total time.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6dc1cd89-bada-55a8-8bd1-f69cd5c83644', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'as', '1.3', '9702 1.3 Speed and velocity', 18, 18, 'A plane''s ground velocity is +250 m/s (due east) for 2.0 hours, then the wind shifts and its ground velocity becomes +180 m/s (still due east) for a further 1.5 hours. (a) Calculate the displacement during each phase, in km. (b) Calculate the average velocity for the whole 3.5 hour flight, in m/s. Give only the answer to (b).', 'diagram:kin-1.3-q18', 3, 'numeric'::answer_type, '220', 'm/s', false, NULL, false, '(a) Phase 1: displacement = 250 × (2.0 × 3600) = 1.80 × 10⁶ m = 1800 km. Phase 2: displacement = 180 × (1.5 × 3600) = 9.72 × 10⁵ m = 972 km. (b) Total displacement = 2.77 × 10⁶ m over a total time of 3.5 × 3600 = 12600 s: average velocity = 220 m/s. Common mistake: averaging 250 and 180 m/s to get 215 m/s — wrong here too, because the two phases last different lengths of time (2.0 h vs 1.5 h).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('355fd8ae-e007-54ee-a72e-0fbe4645698a', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'as', '1.3', '9702 1.3 Speed and velocity', 19, 19, 'Taking upward as positive, a ball’s displacement is +12.4 m at one instant, and +11.8 m exactly 0.10 s later. Estimate the ball’s instantaneous velocity at that first instant, and explain why this calculation only gives an ESTIMATE of the true instantaneous velocity.', 'diagram:kin-1.3-q19', 4, 'numeric'::answer_type, '-6', 'm/s', false, NULL, false, 'Estimated velocity ≈ change in displacement ÷ time interval = (11.8 − 12.4) ÷ 0.10 = −6.00 m/s. This is only an estimate because the ball’s velocity is actually changing continuously (it is accelerating under gravity), so the AVERAGE velocity over this short 0.10 s interval is close to, but not exactly equal to, the TRUE instantaneous velocity at the first instant — the shorter the time interval used, the better the estimate becomes, approaching the true instantaneous value as the interval shrinks towards zero (this is exactly the idea of a gradient at a single point on a graph). Common mistake: treating a calculation like this as giving an exact instantaneous value rather than an estimate, however small the time interval.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0621ef71-fe07-5572-8948-b2d4d6fb36ff', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'as', '1.3', '9702 1.3 Speed and velocity', 20, 20, 'Runner A starts from a start line and runs at a constant +5.0 m/s. Runner B starts from the same line, 2.0 s after A, and runs at a constant +6.0 m/s in the same direction. Measuring time t from the moment A starts, derive an expression for the time at which B catches up with A, and evaluate it.', NULL, 4, 'numeric'::answer_type, '12', 's', false, NULL, false, 'A''s position at time t is x_A = 5.0t. B starts 2.0 s later, so B''s position for t ≥ 2.0 s is x_B = 6.0(t − 2.0). B catches A when x_A = x_B: 5.0t = 6.0(t − 2.0) = 6.0t − 12.0, so 12.0 = 6.0t − 5.0t = t, giving t = 12.0 s after A started (which is 10.0 s after B started). Common mistake: measuring t from when B starts instead of from when A starts (or vice versa) and substituting into the wrong equation, which gives an answer with the wrong origin.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('98b24648-a805-58cf-936c-65ee5906f5cd', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 1, 1, 'On a displacement-time graph, what physical quantity does the gradient represent?', NULL, 1, 'multiple_choice'::answer_type, 'velocity', NULL, false, NULL, false, ('Gradient = (change in displacement) ÷ (change in time), which is exactly the definition of velocity. A steeper gradient means a larger velocity (faster motion)' || chr(59) || ' a negative gradient means velocity in the negative direction. Common mistake: thinking the gradient gives speed or acceleration instead of velocity.'), 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('63a7ec36-7828-59b2-bd47-bb932439ed3a', '98b24648-a805-58cf-936c-65ee5906f5cd', 'velocity', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('713dd752-2f27-599e-9991-2979d9c0490d', '98b24648-a805-58cf-936c-65ee5906f5cd', 'speed only, never direction', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('891baff1-1388-5ef2-8996-24a0db714dc4', '98b24648-a805-58cf-936c-65ee5906f5cd', 'acceleration', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3b5b377a-b4e7-5b03-9ee0-56401ac26e33', '98b24648-a805-58cf-936c-65ee5906f5cd', 'distance travelled', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9ceb4b92-b685-59e9-8065-54c9bb5fbced', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 2, 2, 'A displacement-time graph is a horizontal straight line. State the velocity of the object.', 'diagram:kin-1.4-q2', 1, 'numeric'::answer_type, '0', 'm/s', false, NULL, false, 'A horizontal line has zero gradient, and gradient = velocity, so the velocity is 0 m/s — the object is at rest (its displacement is not changing with time). Common mistake: confusing a horizontal line (at rest) with a line through the origin (moving at constant velocity, starting from zero displacement).', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('dd2912ee-df81-5055-9c98-7e67c9721c0a', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 3, 3, 'A displacement-time graph is a straight line from the origin to the point (5.0 s, 20 m). Calculate the velocity it represents.', 'diagram:kin-1.4-q3', 1, 'numeric'::answer_type, '4', 'm/s', false, NULL, false, 'velocity = gradient = change in displacement ÷ change in time = (20 − 0) ÷ (5.0 − 0) = 4.00 m/s. Common mistake: dividing time by displacement instead of displacement by time.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('72beca69-0b9e-5bab-9ec0-6e6b5f8641cc', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 4, 4, 'Two displacement-time graphs are both straight lines through the origin. Line P rises more steeply than line Q. Which object is moving faster?', NULL, 1, 'multiple_choice'::answer_type, 'The object represented by line P', NULL, false, NULL, false, 'A steeper straight line on a displacement-time graph means a larger gradient, and gradient = velocity, so line P represents the faster-moving object. Common mistake: assuming the LONGER line (reaching a larger displacement) must represent the faster object, rather than comparing gradients.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('81e277bb-1e72-586c-b20b-380ab4d3c033', '72beca69-0b9e-5bab-9ec0-6e6b5f8641cc', 'The object represented by line P', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5f36b4cf-2e69-5e01-a157-98c3fb9a754d', '72beca69-0b9e-5bab-9ec0-6e6b5f8641cc', 'The object represented by line Q', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('907895fa-16e5-5f93-b635-7b2ef5ba13fb', '72beca69-0b9e-5bab-9ec0-6e6b5f8641cc', 'They must be moving at the same speed', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e4ae86b9-31d9-5f42-a32d-dac6bfa63061', '72beca69-0b9e-5bab-9ec0-6e6b5f8641cc', 'There is not enough information', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3eb3c994-2ce7-51f5-8c78-7acbd5b643dd', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 5, 5, 'A displacement-time graph is a straight line from (0 s, +10 m) to (4.0 s, −6.0 m). Calculate the velocity it represents.', 'diagram:kin-1.4-q5', 1, 'numeric'::answer_type, '-4', 'm/s', false, NULL, false, 'velocity = gradient = ((−6.0) − (+10)) ÷ (4.0 − 0) = (−16) ÷ 4.0 = −4.00 m/s. The negative sign shows the object is moving in the negative direction throughout. Common mistake: subtracting in the wrong order, (10 − (−6))/4 = +4.0 m/s, which has the wrong sign.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('25b9f166-d5be-5ca0-95fd-b582b5df3154', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 6, 6, 'A displacement-time graph is a straight line through the origin, reaching (6.0 s, 24 m). Read off the displacement at t = 3.0 s.', 'diagram:kin-1.4-q6', 1, 'numeric'::answer_type, '12', 'm', false, NULL, false, 'The line passes through the origin with a constant gradient of 24 ÷ 6.0 = 4.0 m/s, so at t = 3.0 s the displacement is 4.0 × 3.0 = 12 m — exactly half of the displacement at t = 6.0 s, since the line is straight and 3.0 s is exactly halfway along it. Common mistake: trying to read this directly off a sketch without using the straight-line proportionality, and misjudging the halfway value.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0b61eea7-500e-509e-b9b3-990bd46bc1b0', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 7, 7, 'A displacement-time graph has three sections: rising from (0 s, 0 m) to (4 s, 8 m), then flat until (9 s, 8 m), then falling to (12 s, 2 m). Calculate the velocity during the final (falling) section.', 'diagram:kin-1.4-q7', 2, 'numeric'::answer_type, '-2', 'm/s', false, NULL, false, 'During the final section, gradient = (2 − 8) ÷ (12 − 9) = (−6) ÷ 3 = −2.00 m/s. The negative sign shows the object is moving back towards its starting point. Common mistake: using the overall start and end points of the WHOLE graph (0 to 12 s) instead of just the final section’s own two endpoints.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7313d3a6-571a-554f-a53d-db417152bc4f', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 8, 8, 'A displacement-time graph is a curve that becomes steeper and steeper as time increases. What does this indicate about the motion?', NULL, 2, 'multiple_choice'::answer_type, 'The velocity is increasing — the object is accelerating', NULL, false, NULL, false, 'A continuously increasing gradient means the velocity is continuously increasing — the object is accelerating (speeding up). Common mistake: describing this as ''constant speed'' because the curve looks smooth, without checking how the gradient itself is changing along the curve.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('08767383-6181-592d-8ece-c6875b8a8d76', '7313d3a6-571a-554f-a53d-db417152bc4f', 'The velocity is increasing — the object is accelerating', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d63c7858-d922-5ecb-845f-0511615ac859', '7313d3a6-571a-554f-a53d-db417152bc4f', 'The velocity is constant', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8705053b-e7d9-54fe-acad-5edf18e081cb', '7313d3a6-571a-554f-a53d-db417152bc4f', 'The velocity is decreasing', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c160336d-7541-5494-939a-42d61de7f7d6', '7313d3a6-571a-554f-a53d-db417152bc4f', 'The object is stationary', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('af5061ef-1332-5eed-a953-af00d9066a77', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 9, 9, 'A displacement-time graph is a straight line from (0 s, 5.0 m) to (10 s, 35 m). Read off the displacement at t = 4.0 s.', 'diagram:kin-1.4-q9', 2, 'numeric'::answer_type, '17', 'm', false, NULL, false, 'The line has gradient (35 − 5.0) ÷ 10 = 3.0 m/s and a starting value of 5.0 m, so displacement at any time t is 5.0 + 3.0t. At t = 4.0 s: 5.0 + 3.0 × 4.0 = 17.0 m. Common mistake: forgetting the non-zero starting displacement (5.0 m) and just computing 3.0 × 4.0 = 12 m.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('75b90827-d766-5093-878f-9fbb85c52ebb', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 10, 10, 'A displacement-time graph rises in a straight line from (0 s, 0 m) to (6 s, 18 m), stays flat until (10 s, 18 m), then falls in a straight line to (14 s, 2 m). Calculate the average velocity between t = 3.0 s and t = 12 s.', 'diagram:kin-1.4-q10', 2, 'numeric'::answer_type, '0.1111', 'm/s', false, NULL, false, 'Reading the graph: at t = 3.0 s (on the rising section, gradient 18/6 = 3.0 m/s) the displacement is 3.0 × 3.0 = 9.00 m. At t = 12 s (on the falling section, gradient (2−18)/(14−10) = −4.0 m/s) the displacement is 18 + (−4.0) × (12−10) = 10.0 m. Average velocity = (10.0 − 9.00) ÷ (12 − 3) = 0.111 m/s. Common mistake: using the gradient of either the rising or falling section as the average, instead of the two actual displacement VALUES at the two times asked about.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c9fe75e6-e6d7-522a-bc91-4b1f4faea9ae', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 11, 11, 'A displacement-time graph is a smooth curve that keeps rising but becomes LESS steep as time goes on. What does this indicate?', NULL, 2, 'multiple_choice'::answer_type, 'The object is moving forward but decelerating', NULL, false, NULL, false, 'A gradient that is positive but steadily decreasing means the velocity is positive but decreasing in magnitude — the object is still moving in the same direction, but slowing down (decelerating). Common mistake: concluding the object has stopped or reversed, when a decreasing-but-still-positive gradient only means it is slowing, not that it has stopped.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2675e051-b4c3-5f9d-ad89-7442a5297cb3', 'c9fe75e6-e6d7-522a-bc91-4b1f4faea9ae', 'The object is moving forward but decelerating', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('98288a4d-d54d-590b-9fda-49a6aedb2e00', 'c9fe75e6-e6d7-522a-bc91-4b1f4faea9ae', 'The object has stopped', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b5ef9ef8-f2fb-51c1-9059-1af06a9aea36', 'c9fe75e6-e6d7-522a-bc91-4b1f4faea9ae', 'The object has reversed direction', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f5a385ef-5524-5bc9-809d-025f23b5e229', 'c9fe75e6-e6d7-522a-bc91-4b1f4faea9ae', 'The object is accelerating', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('bb070f44-38fa-5ae2-98fb-34a9ee47bfe2', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 12, 12, 'A displacement-time graph is a curve starting at rest at the origin and reaching (10 s, 40 m), with a continuously increasing gradient. By drawing a tangent at t = 5.0 s, the gradient there is found to be consistent with a constant acceleration throughout. Calculate the gradient (instantaneous velocity) of that tangent.', 'diagram:kin-1.4-q12', 2, 'numeric'::answer_type, '4', 'm/s', false, NULL, false, 'Starting from rest with constant acceleration a, displacement follows x = ½at². Using the point (10 s, 40 m): 40 = ½ × a × 10², so a = 80/100 = 0.800 m/s². The instantaneous velocity (tangent gradient) at any time is v = at, so at t = 5.0 s: v = 0.800 × 5.0 = 4.00 m/s. Common mistake: using the AVERAGE gradient over the whole 10 s (40/10 = 4.0 m/s) instead of the gradient of the TANGENT at the one instant t = 5.0 s, which is different for a curved graph.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3b1cd32d-2109-5789-a500-b69487c75b17', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 13, 13, 'A displacement-time graph rises in a straight line from (0 s, 0 m) to (6 s, 18 m), then falls in a straight line back to (12 s, 0 m). Read off the time at which the object returns to its starting displacement.', 'diagram:kin-1.4-q13', 2, 'numeric'::answer_type, '12', 's', false, NULL, false, 'The graph shows the displacement reaching 0 m again exactly at t = 12 s, where the falling section meets the time axis. This is a direct graph-reading skill, not a calculation: the symmetric triangle shape shows the object moving away and then returning at the same average rate. Common mistake: reading off t = 6 s (the time of maximum displacement) instead of the time it returns to zero.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('241b4b8d-cc02-5053-bba5-ed677f669a93', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 14, 14, ('A displacement-time graph has three straight sections: (0 s, 0 m) to (4 s, 20 m)' || chr(59) || ' then flat to (7 s, 20 m)' || chr(59) || ' then (7 s, 20 m) to (10 s, −10 m). (a) Calculate the velocity during the first section. (b) Calculate the velocity during the third section. (c) Calculate the total DISTANCE travelled over the whole 10 s (not the displacement). Give only the answer to (c).'), 'diagram:kin-1.4-q14', 3, 'numeric'::answer_type, '50', 'm', false, NULL, false, '(a) Velocity 1 = (20−0)/(4−0) = 5.00 m/s. (b) Velocity 3 = (−10−20)/(10−7) = −10.0 m/s. (c) Distance adds the SIZE of the change in each section, ignoring sign: |20−0| + |20−20| + |−10−20| = 20 + 0 + 30 = 50.0 m. Common mistake: finding the final displacement instead (−10 m, or magnitude 10 m) rather than adding up the distance covered in each separate section.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('aef102c0-7dda-5656-b777-bde1eff6708f', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 15, 15, ('A delivery van''s displacement-time graph from its depot: (0 min, 0 km) to (10 min, 15 km) [drives to shop A]' || chr(59) || ' flat to (25 min, 15 km) [parked, delivering]' || chr(59) || ' then (25 min, 15 km) to (40 min, −5 km) [drives on to shop B, past the depot''s position]. (a) Calculate how long the van is parked. (b) Calculate the velocity while driving to shop B. (c) Calculate the total distance driven over the whole 40 minutes. Give only the answer to (c).'), 'diagram:kin-1.4-q15', 3, 'numeric'::answer_type, '35 km', NULL, false, NULL, false, '(a) Parked from t = 10 min to t = 25 min: duration = 15.0 min. (b) Velocity to shop B = (−5−15)/(40−25) = −1.33 km/min. (c) Distance = |15−0| + |15−15| + |−5−15| = 15 + 0 + 20 = 35.0 km. Common mistake: using the final displacement (−5 km from the depot) as the distance driven, instead of adding up the length of every leg actually covered.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d217d50d-b3ad-585d-a55f-936fa656e40b', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 16, 16, ('A particle’s displacement-time graph has straight sections: (0 s, 0 m) to (5 s, 10 m)' || chr(59) || ' then (5 s, 10 m) to (10 s, −10 m)' || chr(59) || ' then (10 s, −10 m) to (15 s, 0 m). (a) Calculate the velocity of the middle section. (b) Calculate the total distance travelled over the 15 s. (c) Calculate the average SPEED for the whole 15 s. Give only the answer to (c).'), 'diagram:kin-1.4-q16', 3, 'numeric'::answer_type, '2.667', 'm/s', false, NULL, false, '(a) Middle section velocity = (−10−10)/(10−5) = −4.00 m/s. (b) Distance = |10−0| + |−10−10| + |0−(−10)| = 10 + 20 + 10 = 40.0 m. (c) Average speed = total distance ÷ total time = 40.0 ÷ 15 = 2.67 m/s. Common mistake: using the final displacement (0 m, since the particle ends up back at the origin) and concluding the average speed must also be zero — average SPEED uses distance, which is 40 m here, not displacement.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b350fb52-3e02-504c-bd30-d50080cd9b07', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 17, 17, 'A displacement-time graph is plotted from readings accurate to only ±0.5 m at each point. The first reading is (0 s, 2.0 ± 0.5 m) and the last is (20 s, 42.0 ± 0.5 m). (a) Calculate the average velocity using these two readings. (b) The two reading errors combine by simple addition when you subtract the readings. Calculate the percentage uncertainty in this average velocity. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2.5', '%', false, NULL, false, '(a) Average velocity = (42.0 − 2.0) ÷ 20 = 2.00 m/s. (b) The absolute uncertainty in the DIFFERENCE of the two readings is the sum of their individual uncertainties: 0.5 + 0.5 = 1.0 m, out of a change of 40.0 m. Percentage uncertainty = 1.0 ÷ 40.0 × 100% = 2.50% (the time interval is normally taken as exact, so it contributes no extra uncertainty here). Common mistake: using only one reading’s ±0.5 m uncertainty instead of adding the uncertainties from BOTH readings used in the subtraction.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f743db4c-358a-5abf-ab84-67cd57c14399', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 18, 18, 'A displacement-time graph curves smoothly (starting from rest at the origin) up to (5.0 s, 25 m), and then continues as a STRAIGHT line to (9.0 s, 65 m). (a) State what feature of the graph after t = 5.0 s shows the object is moving at constant velocity. (b) Calculate that constant velocity. (c) State the displacement at t = 9.0 s. Give only the numerical answer to (b).', 'diagram:kin-1.4-q18', 3, 'numeric'::answer_type, '10', 'm/s', false, NULL, false, '(a) A STRAIGHT section of a displacement-time graph always means constant velocity, because a straight line has one unchanging gradient throughout. (b) velocity = (65−25)/(9.0−5.0) = 10.0 m/s. (c) The displacement at t = 9.0 s is read directly from the graph as 65 m. Common mistake: assuming a graph must be curved everywhere just because it started out curved, rather than checking each section’s shape separately.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('db66f178-fe54-5b63-a366-7184073a9b41', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 19, 19, 'A displacement-time graph curves smoothly from rest at the origin, consistent with a constant acceleration a. The gradient of the tangent at t = 2.0 s is found to be 3.0 m/s, and the gradient of the tangent at t = 6.0 s is found to be 9.0 m/s. Show that these two gradients are consistent with a constant acceleration, and calculate its value.', 'diagram:kin-1.4-q19', 4, 'numeric'::answer_type, '1.5', 'm/s²', false, NULL, false, ('For constant acceleration from rest, the instantaneous velocity (tangent gradient) at time t is v = at, so the gradient should be directly proportional to t. Check: at t = 2.0 s, v/t = 3.0/2.0 = 1.5' || chr(59) || ' at t = 6.0 s, v/t = 9.0/6.0 = 1.5 — the same value both times, confirming a constant acceleration. Calculating it directly from the change between the two tangents: a = Δv ÷ Δt = (9.0 − 3.0) ÷ (6.0 − 2.0) = 1.50 m/s². Common mistake: dividing a single gradient value by its own time (e.g. 3.0/2.0) and treating that as "the acceleration" directly, rather than using the CHANGE in velocity over the CHANGE in time between the two tangents (both methods agree here only because the object starts from rest).'), 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1861fcce-8fbc-571e-bfdd-b8e90dfeaf27', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'as', '1.4', '9702 1.4 Displacement–time graphs', 20, 20, 'A seismometer''s displacement-time trace during an aftershock is approximately two straight sections: the ground moves +0.024 m in 0.40 s, then snaps back −0.024 m (returning to zero) in the next 0.10 s. (a) Calculate the velocity during each phase. (b) Explain which phase is more likely to cause structural damage, given that engineers care about peak velocity (and acceleration) rather than the size of the displacement itself. Give only the magnitude of the larger velocity, in m/s.', 'diagram:kin-1.4-q20', 4, 'numeric'::answer_type, '0.24', 'm/s', false, NULL, false, '(a) Phase 1: velocity = 0.024 ÷ 0.40 = 0.0600 m/s. Phase 2: velocity = (−0.024) ÷ 0.10 = −0.240 m/s. (b) Even though both phases cover the SAME size of displacement (0.024 m), phase 2 happens four times faster, so its velocity (and the forces associated with such a rapid change of motion) are much larger in magnitude — this sudden "jolt back" is the more dangerous part of the motion for structures. Common mistake: assuming the two phases are equally severe because the displacement involved is the same size in each.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('640a8869-14cb-5931-9b05-c212c77b4759', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 1, 1, 'What is the standard method for finding the resultant of two displacement vectors?', NULL, 1, 'multiple_choice'::answer_type, ('Draw them tip-to-tail, to scale' || chr(59) || ' the resultant runs from the start of the first to the end of the second'), NULL, false, NULL, false, ('Draw the vectors tip-to-tail (the second vector starting where the first one ends), in order and to scale' || chr(59) || ' the resultant is the single straight-line vector from the very start to the very end. Common mistake: drawing both vectors from the SAME starting point and trying to read a resultant directly, rather than joining them tip-to-tail (or using components, which gives the same answer algebraically).'), 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('62b6d71d-7df9-5b27-ac3c-1a5fdecdbd24', '640a8869-14cb-5931-9b05-c212c77b4759', ('Draw them tip-to-tail, to scale' || chr(59) || ' the resultant runs from the start of the first to the end of the second'), 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e1267494-6370-5c2c-b95d-dbf75e4b330f', '640a8869-14cb-5931-9b05-c212c77b4759', 'Simply add their magnitudes, regardless of direction', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('17828188-0bd1-58e4-b56d-a6e90416d3c2', '640a8869-14cb-5931-9b05-c212c77b4759', 'Always use Pythagoras, whatever the angle between them', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e209ce55-b6db-5472-b3cc-28d1c8db0d95', '640a8869-14cb-5931-9b05-c212c77b4759', 'Multiply their magnitudes together', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a0fa651f-18a5-5da5-a0d1-c35a5e0c9e38', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 2, 2, 'Two displacements, 6.0 m and 4.0 m, act in the SAME direction. Calculate the magnitude of their resultant.', 'diagram:kin-1.5-q2', 1, 'numeric'::answer_type, '10', 'm', false, NULL, false, 'When two vectors point in exactly the same direction, they add directly like scalars: 6.0 + 4.0 = 10 m, still in that same direction. Common mistake: using Pythagoras here, which only applies when the two vectors are at an angle to each other, not when they are parallel.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('75a08b04-b757-545c-8329-f67f163679fe', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 3, 3, 'Two displacements, 6.0 m east and 8.0 m north, act at right angles to each other. Calculate the magnitude of their resultant.', 'diagram:kin-1.5-q3', 1, 'numeric'::answer_type, '10', 'm', false, NULL, false, 'Since the two vectors are perpendicular, Pythagoras applies directly: magnitude = √(6.0² + 8.0²) = √(36+64) = √100 = 10.0 m (a 3-4-5 triangle scaled by 2). Common mistake: simply adding 6.0 + 8.0 = 14 m, which ignores that the two vectors point in different directions.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4bc65cbd-d449-545c-8ddf-69acf12777ed', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 4, 4, 'A displacement of 10 m acts at 30° above the horizontal. Calculate the horizontal component of this displacement.', 'diagram:kin-1.5-q4', 1, 'numeric'::answer_type, '8.66', 'm', false, NULL, false, 'Horizontal component = magnitude × cos(angle from horizontal) = 10 × cos30° = 10 × 0.866 = 8.66 m. Common mistake: using sin30° instead of cos30° for the horizontal component — cos goes with the component ALONG the direction the angle is measured from.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d2ff9336-fb1c-5d95-9cff-b34c42eb7d49', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 5, 5, 'The same displacement of 10 m acts at 30° above the horizontal. Calculate the vertical component of this displacement.', 'diagram:kin-1.5-q5', 1, 'numeric'::answer_type, '5', 'm', false, NULL, false, 'Vertical component = magnitude × sin(angle from horizontal) = 10 × sin30° = 10 × 0.500 = 5.00 m. Common mistake: swapping sin and cos, which would give the vertical component as 8.66 m (the horizontal value) instead.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('49039c7b-e769-5947-bfd2-7e2c113f5811', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 6, 6, 'Two equal and opposite displacements, each of magnitude 12 m, act on an object. State the magnitude of their resultant.', NULL, 1, 'numeric'::answer_type, '0', 'm', false, NULL, false, 'Equal and opposite vectors cancel completely: the resultant is 0 m. Common mistake: adding the two magnitudes (12 + 12 = 24 m) without accounting for the fact that ''opposite'' means they point in opposite directions, so they subtract rather than add.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4feb4f0f-5684-5d1e-9752-476d542d604e', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 7, 7, 'Two displacements of 50 m each act with an angle of 60° between their directions. Calculate the magnitude of their resultant by resolving each into components along and perpendicular to the first vector.', 'diagram:kin-1.5-q7', 2, 'numeric'::answer_type, '86.6', 'm', false, NULL, false, 'Take the first vector along the x-axis: (50, 0). Resolve the second (50 m at 60°) into components: (25.0, 43.3). Adding component by component: x = 50 + 25.0 = 75.0, y = 0 + 43.3 = 43.3. Magnitude = √(75.0² + 43.3²) = 86.6 m. Common mistake: adding the two magnitudes directly (50+50=100 m), which would only be correct if the angle between them were 0°.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('39c25040-43aa-5b07-a84d-250f5861e890', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 8, 8, 'A displacement vector points into the second quadrant (up and to the left of the origin, between 90° and 180° measured from the positive x-axis). What are the signs of its x- and y-components?', NULL, 2, 'multiple_choice'::answer_type, 'x-component negative, y-component positive', NULL, false, NULL, false, 'In the second quadrant, the x-component is NEGATIVE (pointing left) and the y-component is POSITIVE (pointing up). This is why resolving a vector always needs the angle measured consistently from a fixed axis — cos and sin automatically produce the correct sign as long as the angle convention is applied consistently. Common mistake: assuming components are always positive and just reading off magnitudes without tracking which way each component actually points.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('cf8ad077-caae-544c-a290-9174c823786b', '39c25040-43aa-5b07-a84d-250f5861e890', 'x-component negative, y-component positive', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('52b30590-d939-5594-98f3-d8a7ec7fb0e2', '39c25040-43aa-5b07-a84d-250f5861e890', 'x-component positive, y-component positive', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('82bcd5e2-3519-5891-862d-54583677d980', '39c25040-43aa-5b07-a84d-250f5861e890', 'x-component negative, y-component negative', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9a53cb8e-457d-5d1c-b060-dda2752059d1', '39c25040-43aa-5b07-a84d-250f5861e890', 'x-component positive, y-component negative', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1108fa8e-ba7a-598f-8ea0-3bb2f62163f2', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 9, 9, 'A displacement of 25 m acts at 150°, measured anticlockwise from the positive x-axis. Calculate the x-component of this displacement.', 'diagram:kin-1.5-q9', 2, 'numeric'::answer_type, '-21.65', 'm', false, NULL, false, ('x-component = 25 × cos150° = 25 × (−0.866) = −21.7 m. The component is negative because 150° is past 90°, so the vector points partly in the negative x-direction. Common mistake: dropping the negative sign because "a length can’t be negative" — a COMPONENT can be negative' || chr(59) || ' only the overall magnitude of a vector cannot.'), 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('01549e76-bb30-51cf-ade4-fbb3ad69c8d5', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 10, 10, 'Three displacement vectors have components (in metres): (10, 0), (0, 15) and (−4, 3). Calculate the magnitude of their resultant.', 'diagram:kin-1.5-q10', 2, 'numeric'::answer_type, '18.97', 'm', false, NULL, false, ('Add the x-components together, and separately add the y-components: x = 10 + 0 + (−4) = 6.00 m' || chr(59) || ' y = 0 + 15 + 3 = 18.0 m. Resultant magnitude = √(6.00² + 18.0²) = 19.0 m. Common mistake: adding all six numbers together indiscriminately instead of keeping the x- and y-components separate until the final Pythagoras step.'), 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('10809e9b-0545-52c2-83df-c38a98530f77', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 11, 11, 'Two vectors of magnitude 5.0 and 3.0 are combined. Which of these values could NOT be the magnitude of their resultant?', NULL, 2, 'multiple_choice'::answer_type, '1.0', NULL, false, NULL, false, 'The resultant of two vectors can range from the difference of their magnitudes (when they point in exactly opposite directions, |5.0−3.0| = 2.0) up to their sum (when they point in exactly the same direction, 5.0+3.0 = 8.0), and anything in between depending on the angle. A resultant of 1.0 is smaller than this minimum of 2.0, so it is impossible. Common mistake: assuming any value could be a valid resultant, without checking it falls between the minimum and maximum possible magnitudes.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('fc210f83-e7d3-5f43-be71-7edc4bf23dc4', '10809e9b-0545-52c2-83df-c38a98530f77', '1.0', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('04b61068-4852-5d1f-9ccd-bda96b971ca5', '10809e9b-0545-52c2-83df-c38a98530f77', '2.0', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a0bcc224-6648-5544-9f88-ad210eaa8fc8', '10809e9b-0545-52c2-83df-c38a98530f77', '4.0', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a369efbc-4f04-5874-8dc2-03e31f0ca6ba', '10809e9b-0545-52c2-83df-c38a98530f77', '7.0', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c4deca11-a455-5108-9f48-20c0d909844a', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 12, 12, 'A resultant displacement has components (8.0 m, 6.0 m). Calculate the angle this resultant makes above the x-axis.', 'diagram:kin-1.5-q12', 2, 'numeric'::answer_type, '36.87', '°', false, NULL, false, 'angle = tan⁻¹(y-component ÷ x-component) = tan⁻¹(6.0 ÷ 8.0) = 36.9°. (This is a 3-4-5 triangle scaled by 2, so the magnitude is √(8.0²+6.0²) = 10 m.) Common mistake: computing tan⁻¹(8.0/6.0) instead — the ORDER matters: it is always y-component over x-component for the angle measured from the x-axis.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b4a901e8-2d87-58cf-8f66-88dff6a9d642', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 13, 13, 'A hiker''s displacement from camp has an eastward component of 120 m and a northward component of 50 m. Calculate the magnitude of the total displacement.', 'diagram:kin-1.5-q13', 2, 'numeric'::answer_type, '130', 'm', false, NULL, false, 'magnitude = √(120² + 50²) = √(14400+2500) = √16900 = 130 m. Common mistake: adding the two components directly (120+50=170 m) instead of combining them with Pythagoras, since they act at right angles to each other.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1eccf84b-3557-5f8a-baba-c99c5eb03533', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 14, 14, 'A ship sails 8.0 km on a bearing of 060°, then 5.0 km on a bearing of 150°. (a) Resolve the first leg into north and east components. (b) Resolve the second leg into north and east components. (c) Calculate the magnitude of the resultant displacement. Give only the answer to (c), to 3 significant figures.', 'diagram:kin-1.5-q14', 3, 'numeric'::answer_type, '9.434 km', NULL, false, NULL, false, ('(a) Leg 1: north = 8.0cos60° = 4.00 km, east = 8.0sin60° = 6.93 km. (b) Leg 2: north = 5.0cos150° = −4.33 km, east = 5.0sin150° = 2.50 km. (c) Net north = 4.00 + (−4.33) = −0.330 km' || chr(59) || ' net east = 6.93 + 2.50 = 9.43 km. Magnitude = √(−0.330² + 9.43²) = 9.43 km. Common mistake: using sin for the north (bearing) component and cos for east — for a BEARING (measured clockwise from north), it is north = cos and east = sin, the opposite convention to an angle measured from the x-axis.'), 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('14f0bdd4-b00f-5f4e-98f3-a6475855880d', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 15, 15, 'Vector A (15 m, along 0°) and an unknown vector B combine to give a resultant of 25 m at 36.9° above the x-axis. (a) Resolve the resultant into x- and y-components. (b) Hence find the components of vector B. (c) Calculate the magnitude of vector B. Give only the answer to (c).', 'diagram:kin-1.5-q15', 3, 'numeric'::answer_type, '15.81', 'm', false, NULL, false, '(a) Resultant components: x = 25cos36.9° = 20.0 m, y = 25sin36.9° = 15.0 m (a 3-4-5 triangle scaled by 5). (b) Since A + B = resultant, and A = (15, 0): B_x = 20.0 − 15 = 5.00 m, B_y = 15.0 − 0 = 15.0 m. (c) Magnitude of B = √(5.00² + 15.0²) = 15.8 m. Common mistake: adding A to the resultant instead of SUBTRACTING it to isolate B (since A + B = R means B = R − A).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4cf0916d-7810-5462-900f-0ec3a8a768a3', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 16, 16, 'An orienteering course has three legs: 300 m due east, then 400 m on a bearing of 030°, then 200 m due south. (a) Resolve each leg into north and east components. (b) Find the net north and east components of the overall displacement. (c) Calculate the magnitude of the resultant displacement, to 3 significant figures. Give only the answer to (c).', 'diagram:kin-1.5-q16', 3, 'numeric'::answer_type, '521', 'm', false, NULL, false, '(a) Leg 1 (due east): north = 0, east = 300 m. Leg 2 (bearing 030°): north = 400cos30° = 346 m, east = 400sin30° = 200 m. Leg 3 (due south): north = −200 m, east = 0. (b) Net north = 0 + 346 + (−200) = 146 m. Net east = 300 + 200 + 0 = 500 m. (c) Magnitude = √(146² + 500²) = 521 m. Common mistake: forgetting the negative sign on the southward leg’s north-component, which would overstate the net northward progress.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d4734e34-aab2-5ba9-9ea0-415049167726', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 17, 17, 'A surveyor''s traverse must close back exactly on its own starting point. Three legs have already been walked: 200 m due east, 150 m due north, and 100 m on a bearing of 200°. Calculate the length of the fourth leg needed to return exactly to the start.', 'diagram:kin-1.5-q17', 3, 'numeric'::answer_type, '175', 'm', false, 0.05, false, ('Running totals so far: north = 150 + 100cos200° = 56.0 m' || chr(59) || ' east = 200 + 100sin200° = 166 m. To close the traverse (return all totals to zero), the fourth leg must have components (−56.0 m north, −166 m east) — the exact negative of the running total. Its length is √(−56.0² + −166²) = 175 m. Common mistake: trying to close the traverse by adjusting only one of the three existing legs, instead of finding one single new leg whose components cancel the combined total of all three.'), 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9a9067ee-99a1-59f7-8d26-c086fec049d6', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 18, 18, 'A robot''s planned path is three legs of equal length, each 10 m: on bearings 000°, 120° and 240° — spaced exactly 120° apart. Calculate the magnitude of the resultant displacement.', 'diagram:kin-1.5-q18', 3, 'numeric'::answer_type, '0', 'm', false, NULL, false, 'Resolving each leg: leg 1 (10, 0), leg 2 10(cos120°, sin120°) = (−5.0, 8.66), leg 3 10(cos240°, sin240°) = (−5.0, −8.66) [components here taken from the x-axis for clarity]. Adding: x = 10−5.0−5.0 = 0, y = 0+8.66−8.66 = 0. The resultant is exactly ZERO — three equal vectors spaced evenly 120° apart always cancel completely, whatever their common magnitude. Common mistake: assuming three nonzero vectors can never sum to zero, and trying to force a nonzero numerical answer instead of checking the symmetry.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('aa8a7051-3f32-5fe3-af10-938b9aac2085', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 19, 19, 'Two displacement vectors of equal magnitude A have an angle θ between their directions (drawn tail-to-tail). Show, using components, that the magnitude of their resultant is R = 2A cos(θ/2). Then evaluate R for A = 10 m and θ = 80°.', 'diagram:kin-1.5-q19', 4, 'numeric'::answer_type, '15.32', 'm', false, 0.05, false, 'Place the two vectors symmetrically about the x-axis, each at θ/2 from it: vector 1 = (Acos(θ/2), Asin(θ/2)), vector 2 = (Acos(θ/2), −Asin(θ/2)). Adding: x = 2Acos(θ/2), y = Asin(θ/2) − Asin(θ/2) = 0 — the y-components cancel by the symmetry of the setup, leaving the resultant entirely along the bisector, with magnitude R = 2Acos(θ/2). For A = 10 m, θ = 80°: R = 2 × 10 × cos40° = 15.3 m. Common mistake: using the full angle θ instead of half of it (θ/2) inside the cosine — the formula only works because each vector is θ/2 away from the bisector, not θ away.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b5ef9103-2b7e-5327-8f1b-a1ee3def3d2c', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'as', '1.5', '9702 1.5 Combining displacements', 20, 20, 'A hiker''s GPS-tracked displacement from basecamp, in (east, north) km, updates each hour: Hour 1 (+1.2, +0.8), Hour 2 (+0.5, −1.5), Hour 3 (−0.9, +0.3). Their rescue beacon has a range of 2.0 km from basecamp. Calculate their distance from basecamp after these three hours, and state whether they remain in range.', 'diagram:kin-1.5-q20', 4, 'numeric'::answer_type, '0.8944 km', NULL, false, NULL, false, 'Net east component = 1.2 + 0.5 + (−0.9) = 0.800 km. Net north component = 0.8 + (−1.5) + 0.3 = −0.400 km. Distance from basecamp = √(0.800² + −0.400²) = 0.894 km, which is well within the 2.0 km beacon range. Common mistake: adding the magnitudes of the three hourly displacements directly (which would overestimate the distance, since several components partly cancel) instead of summing the east and north components separately first.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a2e2489e-2480-525f-a93d-d93a4e149d0a', 'd5d14e0a-5072-45b7-bec8-2e24ba2ee0b8', 'They are added as vectors (tip-to-tail, or by components)', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('46353c12-dde3-5d4f-9d07-750af90dae6d', 'd5d14e0a-5072-45b7-bec8-2e24ba2ee0b8', 'They are averaged', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('322666b5-2f9d-508b-8233-639a90c0acb9', 'd5d14e0a-5072-45b7-bec8-2e24ba2ee0b8', 'Only the larger of the two velocities matters', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0071756b-b576-5920-aa43-c47db4e3e193', 'd5d14e0a-5072-45b7-bec8-2e24ba2ee0b8', 'They are multiplied together', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2efb8a9a-9804-573f-b8a0-2b788669006e', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'as', '1.6', '9702 1.6 Combining velocities', 9, 9, 'A boat’s speed relative to the water is 5.0 m/s. It must be steered at an angle θ upstream from the straight-across direction to travel directly across a current flowing at 3.0 m/s. Calculate θ.', 'diagram:kin-1.6-q9', 2, 'numeric'::answer_type, '36.87', '°', false, NULL, false, 'The upstream component of the boat’s velocity must exactly cancel the current: 5.0sinθ = 3.0, so sinθ = 3.0/5.0 = 0.60 and θ = sin⁻¹(0.60) = 36.9° (this is a 3-4-5 triangle). Common mistake: using cos instead of sin, which would use the wrong side of the triangle for this angle.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1da8e068-b415-59f9-bb53-378da4542b13', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'as', '1.6', '9702 1.6 Combining velocities', 10, 10, 'A plane''s airspeed is 300 km/h due north, and a wind of 60 km/h blows due east. Calculate the magnitude of the plane''s ground speed.', 'diagram:kin-1.6-q10', 2, 'numeric'::answer_type, '305.9', 'km/h', false, NULL, false, 'ground speed = √(300² + 60²) = √(90000+3600) = √93600 = 306 km/h. Common mistake: adding 300 + 60 = 360 km/h, treating the perpendicular wind as if it were blowing along the plane’s own direction.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b879189a-c250-5e0e-afb3-f776e8f0edfb', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'as', '1.6', '9702 1.6 Combining velocities', 11, 11, 'In the previous scenario (airspeed 300 km/h due north, wind 60 km/h due east), is the plane''s actual track over the ground exactly due north?', NULL, 2, 'multiple_choice'::answer_type, 'No, the crosswind deflects the ground track east of due north', NULL, false, NULL, false, 'No — the eastward wind pushes the plane''s resultant track slightly east of due north. The plane''s NOSE points due north (that is its heading relative to the air), but its actual path over the ground (its track) is deflected towards the east by the crosswind, by an angle of tan⁻¹(60/300) ≈ 11° east of north. Common mistake: confusing the plane''s heading (where it points) with its track (the path it actually follows over the ground) — these are only the same when there is no crosswind.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7a286040-159c-517e-ba20-7dbbc02ebfe3', 'b879189a-c250-5e0e-afb3-f776e8f0edfb', 'No, the crosswind deflects the ground track east of due north', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('93609196-1089-5ace-8357-a45f850d50a6', 'b879189a-c250-5e0e-afb3-f776e8f0edfb', 'Yes, the track is always the same as the heading', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bea5226f-e100-54a7-8995-aad259202106', 'b879189a-c250-5e0e-afb3-f776e8f0edfb', 'No, the plane is blown due east instead', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4f4ec37b-4808-5a4c-8def-5f35234be35f', 'b879189a-c250-5e0e-afb3-f776e8f0edfb', 'Yes, because airspeed is larger than the wind speed', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5ed7d786-8954-5b85-80ea-4a93db835700', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'as', '1.6', '9702 1.6 Combining velocities', 12, 12, 'A swimmer''s velocity relative to the water is 1.2 m/s straight across a current flowing at 0.80 m/s. Calculate the magnitude of the swimmer''s resultant velocity.', 'diagram:kin-1.6-q12', 2, 'numeric'::answer_type, '1.442', 'm/s', false, 0.05, false, 'magnitude = √(1.2² + 0.80²) = √(1.44+0.64) = √2.08 = 1.44 m/s. Common mistake: rounding 1.2 and 0.80 too early and losing precision before combining them.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('51d6608a-ee91-517e-88d6-a3961ea9f625', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'as', '1.6', '9702 1.6 Combining velocities', 13, 13, 'A river is 50 m wide. A boat’s velocity component perpendicular to the banks (straight across) is 2.0 m/s, regardless of any current along the river. Calculate the time taken to cross.', NULL, 2, 'numeric'::answer_type, '25', 's', false, NULL, false, 'The time to cross depends ONLY on the component of velocity perpendicular to the banks: t = width ÷ perpendicular component = 50 ÷ 2.0 = 25.0 s. The along-river current affects where the boat lands, but not how long the crossing takes. Common mistake: trying to use the boat’s resultant speed (including the current) rather than just its cross-river component.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('42605cb2-8565-500a-af44-4aa31fcc5630', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'as', '1.6', '9702 1.6 Combining velocities', 14, 14, 'A river 120 m wide has a current of 1.5 m/s. A boat is steered straight across (relative to the water) at 2.0 m/s. (a) Calculate the time taken to cross. (b) Calculate how far downstream the boat drifts during the crossing. (c) Calculate the magnitude of the resultant speed over the ground. Give only the answer to (b).', 'diagram:kin-1.6-q14', 3, 'numeric'::answer_type, '90', 'm', false, NULL, false, '(a) Crossing time depends only on the cross-river component: t = 120 ÷ 2.0 = 60.0 s. (b) Downstream drift = current speed × crossing time = 1.5 × 60.0 = 90.0 m. (c) Resultant speed = √(2.0²+1.5²) = 2.50 m/s. Common mistake: using the resultant speed (2.5 m/s) instead of the current’s own speed (1.5 m/s) when finding the drift — the drift is caused by the current alone, over the time the crossing actually takes.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a0ef7ae7-0495-5876-aa58-1157f7823b7f', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'as', '1.6', '9702 1.6 Combining velocities', 15, 15, 'A boat’s speed relative to the water is 4.0 m/s, and the current flows at 2.4 m/s. (a) Calculate the angle upstream (from straight across) at which the boat must be steered to travel directly across. (b) Calculate the resultant cross-river speed in that case. (c) Calculate the time to cross a river 200 m wide. Give only the answer to (c).', 'diagram:kin-1.6-q15', 3, 'numeric'::answer_type, '62.5', 's', false, NULL, false, '(a) The upstream component must cancel the current: 4.0sinθ = 2.4, so sinθ = 0.60 and θ = 36.9°. (b) The cross-river component is then √(4.0² − 2.4²) = √(16−5.76) = √10.24 = 3.20 m/s (the remaining side of the same 3-4-5-style triangle). (c) Time = 200 ÷ 3.20 = 62.5 s. Common mistake: using the boat’s own speed relative to the water (4.0 m/s) to find the crossing time, instead of its smaller resultant cross-river component (3.2 m/s).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1ebf433b-ddc1-54b8-824f-d1d06d1e17fe', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'as', '1.6', '9702 1.6 Combining velocities', 16, 16, 'A plane needs to fly due north. Its airspeed is 250 km/h, and a wind of 40 km/h blows from the west (pushing due east). (a) Calculate the angle west of north at which the pilot must point the plane. (b) Calculate the resultant ground speed. Give only the answer to (b), to 3 significant figures.', 'diagram:kin-1.6-q16', 3, 'numeric'::answer_type, '246.8', 'km/h', false, NULL, false, '(a) The westward component of the airspeed must cancel the eastward wind: 250sinθ = 40, so sinθ = 0.16 and θ = 9.21° west of north. (b) The resulting northward ground speed is √(250² − 40²) = √(62500−1600) = √60900 = 247 km/h. Common mistake: adding the airspeed and wind speed directly (250+40=290 km/h) instead of recognising the pilot must angle into the wind, which reduces the forward ground speed below the airspeed.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4449c269-89c2-5596-aa8d-296bdb13714d', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'as', '1.6', '9702 1.6 Combining velocities', 17, 17, 'Car A travels at +25 m/s and car B travels at +18 m/s, both in the same direction on a straight road, with B exactly 500 m ahead of A. (a) Calculate the velocity of A relative to B. (b) Calculate the time taken for A to catch up with B, assuming both velocities stay constant. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '71.43', 's', false, NULL, false, '(a) Velocity of A relative to B = velocity of A − velocity of B = 25 − 18 = 7.00 m/s — this is how fast the 500 m gap closes. (b) Time to close the gap = 500 ÷ 7.00 = 71.4 s. Common mistake: using car A’s own velocity (25 m/s) instead of its velocity RELATIVE TO B (7 m/s) when finding how quickly the gap between them closes.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c396bb10-54a5-58a5-93a9-fb1edf50268b', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'as', '1.6', '9702 1.6 Combining velocities', 18, 18, 'Rain falls vertically at 8.0 m/s relative to the ground. A cyclist travels horizontally at 6.0 m/s. (a) Write the velocity of the rain relative to the ground as a vector, and the cyclist’s velocity as a vector, using the cyclist’s direction of travel as the horizontal axis and "up" as positive vertical. (b) Calculate the magnitude of the rain’s velocity relative to the cyclist. Give only the answer to (b).', 'diagram:kin-1.6-q18', 3, 'numeric'::answer_type, '10', 'm/s', false, NULL, false, '(a) Rain (relative to ground) = (0, −8.0) m/s [purely vertical, downward]. Cyclist (relative to ground) = (6.0, 0) m/s [purely horizontal]. (b) Velocity of rain relative to the cyclist = (rain’s velocity) − (cyclist’s velocity) = (0−6.0, −8.0−0) = (−6.00, −8.00) m/s. Magnitude = √(6.00² + 8.00²) = 10.0 m/s (a 3-4-5 triangle scaled by 2). Common mistake: adding the cyclist’s velocity to the rain’s instead of SUBTRACTING it — relative velocity of X with respect to Y is always (velocity of X) − (velocity of Y).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d4e7a8f4-5afa-57f4-a7aa-7638271417eb', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'as', '1.6', '9702 1.6 Combining velocities', 19, 19, 'A boat’s speed relative to the water is u, crossing a river of width w flowing at speed c (with c < u), steered at angle θ upstream from straight-across so that it lands exactly opposite its start. Derive expressions for θ and for the crossing time t, in terms of u, c and w. Evaluate t for u = 5.0 m/s, c = 3.0 m/s and w = 200 m.', NULL, 4, 'numeric'::answer_type, '50', 's', false, NULL, false, 'The upstream component of u must cancel the current: u sinθ = c, so θ = sin⁻¹(c/u). The remaining (cross-river) component is then √(u² − c²) by Pythagoras, so the crossing time is t = w ÷ √(u² − c²). Evaluating: θ = sin⁻¹(3.0/5.0) = 36.9°, cross-speed = √(5.0²−3.0²) = √16 = 4.00 m/s, and t = 200 ÷ 4.00 = 50.0 s. Common mistake: using u itself (5.0 m/s) in the time formula instead of the smaller cross-river component √(u²−c²) (4.0 m/s) — steering upstream to counter the current always costs some of the boat’s own forward progress.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f0f8bfe8-ef28-586e-a9b2-494947b24ee0', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'as', '1.6', '9702 1.6 Combining velocities', 20, 20, 'Ship B is 20 km due east of ship A. Ship A sails at 12 km/h on a course (bearing) of 045°, and ship B sails at 9.0 km/h on a course of 315°. Calculate the component of B’s velocity relative to A that lies along the original A–B line (due east–west), and hence state the rate at which the separation between the ships is changing.', NULL, 4, 'numeric'::answer_type, '14.85', 'km/h', false, NULL, false, 'Resolve each course into east/north components using east = speed × sin(bearing), north = speed × cos(bearing): A = (8.49, 8.49) km/h, B = (−6.36, 6.36) km/h. Velocity of B relative to A has east-component = −6.36 − 8.49 = −14.8 km/h. Since the ships’ initial separation lies purely east-west, this east-component alone tells us how the separation is changing: it is negative, meaning B is moving towards A (westward relative to A) at 14.8 km/h — the ships are getting closer. Common mistake: using the full magnitude of B’s relative velocity (which also has a north-south part) instead of only the component ALONG the line joining the two ships, which is the only part that affects their separation distance.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('71c4636f-67d4-52a6-afce-034f7f125571', 'cf6799e2-92a1-4300-971c-f530be613238', 'Reverse the direction of B, then add A + (−B)', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('54fd32ad-b0ae-5148-832e-b61a9c25e841', 'cf6799e2-92a1-4300-971c-f530be613238', 'Subtract the magnitude of B from the magnitude of A, ignoring direction', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8d7f7c8c-55ce-5a48-a65d-6be506e882fc', 'cf6799e2-92a1-4300-971c-f530be613238', 'Add A and B as normal, then halve the result', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9515a141-7bbb-5105-8ccb-1c2cd7bfd26f', 'cf6799e2-92a1-4300-971c-f530be613238', 'Rotate A by 90° and add B', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('dd04f9e1-b6e5-55fd-a42b-f3eb5358934f', '56866bb7-6c85-47b5-b325-81e7ca763d27', ('Keep the magnitude the same' || chr(59) || ' reverse the direction'), 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9c73b187-ed2c-5adb-a99c-89a42bab5aa1', '56866bb7-6c85-47b5-b325-81e7ca763d27', ('Double the magnitude' || chr(59) || ' keep the same direction'), 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e5377cc0-81b2-5bc9-a013-40293a9de95f', '56866bb7-6c85-47b5-b325-81e7ca763d27', ('Halve the magnitude' || chr(59) || ' keep the same direction'), 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bbab7a5b-b127-5382-a5d6-9adc48ef6590', '56866bb7-6c85-47b5-b325-81e7ca763d27', ('Keep the magnitude the same' || chr(59) || ' rotate it by 90°'), 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a438de23-0b45-5a5f-b97b-e8fc46cf0beb', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'as', '1.7', '9702 1.7 Subtracting vectors', 9, 9, 'An object moving in a circle at constant speed 8.0 m/s has velocity 8.0 m/s at 0° at one instant, and 8.0 m/s at 90° a quarter-revolution later. Calculate the magnitude of Δv between these two instants.', 'diagram:kin-1.7-q9', 2, 'numeric'::answer_type, '11.31', 'm/s', false, 0.05, false, ('Δv = v₂ − v₁ = 8.0(cos90°,sin90°) − 8.0(cos0°,sin0°) = (0,8.0) − (8.0,0) = (−8.00, 8.00) m/s. Magnitude = √(8.00²+8.00²) = 11.3 m/s. Common mistake: assuming Δv must be zero because the speed before and after is identical (8.0 m/s both times) — only the SPEED is unchanged' || chr(59) || ' the direction (and hence the velocity vector) is not.'), 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b7be025a-69d6-5670-b38f-5cb34c1f3958', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'as', '1.7', '9702 1.7 Subtracting vectors', 10, 10, 'Two velocity vectors have equal magnitude 20 m/s, with an angle of 60° between their directions. Using the fact that for equal magnitudes v, |Δv| = 2v sin(θ/2), calculate |Δv|.', NULL, 2, 'numeric'::answer_type, '20', 'm/s', false, NULL, false, '|Δv| = 2v sin(θ/2) = 2 × 20 × sin(30°) = 2 × 20 × 0.500 = 20.0 m/s. Common mistake: using the full angle θ = 60° inside the sine instead of half of it (30°) — the formula only works with half the angle between the two vectors.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1c36c728-5803-51b5-9e2e-091b392df043', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'as', '1.7', '9702 1.7 Subtracting vectors', 11, 11, 'For two velocity vectors of EQUAL magnitude v, with an angle θ between their directions, which expression correctly gives the magnitude of their difference, |Δv|?', NULL, 2, 'multiple_choice'::answer_type, '2v sin(θ/2)', NULL, false, NULL, false, ('For equal magnitudes, the two vectors and their difference form an isosceles triangle' || chr(59) || ' splitting it down the middle gives |Δv| = 2v sin(θ/2). Common mistake: picking 2v sinθ (using the full angle, not half of it) or vθ (confusing this with the ARC LENGTH formula from circular motion, which is a different quantity).'), 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('30677c5c-61d9-5f67-bca1-68cf5a5baf9e', '1c36c728-5803-51b5-9e2e-091b392df043', '2v sin(θ/2)', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1ca67d29-6005-59e5-bd03-42a982160b91', '1c36c728-5803-51b5-9e2e-091b392df043', '2v sinθ', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e1a23e61-8e82-5513-ab52-8caeaf3cb634', '1c36c728-5803-51b5-9e2e-091b392df043', 'vθ', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a94c8aec-2e2d-5f0d-8236-ed41783e3abf', '1c36c728-5803-51b5-9e2e-091b392df043', '2v cosθ', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('61f04299-f591-50dc-849b-b590efb02ddf', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'as', '1.7', '9702 1.7 Subtracting vectors', 12, 12, 'A velocity changes from (4.0, 3.0) m/s to (1.0, 7.0) m/s. Calculate the magnitude of Δv.', 'diagram:kin-1.7-q12', 2, 'numeric'::answer_type, '5', 'm/s', false, NULL, false, 'Δv = (1.0−4.0, 7.0−3.0) = (−3.00, 4.00) m/s. Magnitude = √(3.00² + 4.00²) = 5.00 m/s (a 3-4-5 triangle). Common mistake: subtracting the magnitudes of the two velocity vectors (|v₂|−|v₁|) instead of subtracting their COMPONENTS first and then finding the magnitude of the result.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b918df61-03c7-5bd3-a156-187455b384de', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'as', '1.7', '9702 1.7 Subtracting vectors', 13, 13, 'Taking the direction towards the wall as positive, a ball hits a wall at +6.0 m/s and bounces straight back at −6.0 m/s (an elastic, head-on bounce). Calculate Δv.', 'diagram:kin-1.7-q13', 2, 'numeric'::answer_type, '-12', 'm/s', false, NULL, false, 'Δv = final − initial = (−6.0) − (+6.0) = −12.0 m/s. Common mistake: giving +12 m/s (using initial − final) or 0 m/s (wrongly assuming the speed is "the same" before and after, so nothing has changed — the DIRECTION has fully reversed, so the velocity has changed a great deal).', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('88d142d0-9537-5db6-aa08-4e0e6416cd7e', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'as', '1.7', '9702 1.7 Subtracting vectors', 14, 14, 'A ball bounces off the corner of a wall: its velocity changes from 15 m/s at 0° to 15 m/s at 90° over a time of 0.50 s. (a) Calculate the components of Δv. (b) Calculate the magnitude of Δv. (c) Calculate the magnitude of the average acceleration during the bounce. Give only the answer to (c).', 'diagram:kin-1.7-q14', 3, 'numeric'::answer_type, '42.43', 'm/s²', false, NULL, false, '(a) Δv = 15(cos90°,sin90°) − 15(cos0°,sin0°) = (0,15) − (15,0) = (−15.0, 15.0) m/s. (b) |Δv| = √(15.0²+15.0²) = 21.2 m/s. (c) average acceleration = Δv ÷ Δt = 21.2 ÷ 0.50 = 42.4 m/s². Common mistake: using |v₂|−|v₁| = 0 for part (b), since the SPEED does not change in this bounce — only Δv, the vector difference, correctly captures the large change caused by the 90° redirection.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e25c166a-f78c-5ee2-9653-4500340d2a04', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'as', '1.7', '9702 1.7 Subtracting vectors', 15, 15, 'An object moves in a circle at constant speed v. (a) Using |Δv| = 2v sin(θ/2), write an expression for |Δv| after exactly a quarter revolution (θ = 90°), in terms of v. (b) Evaluate it for v = 12 m/s.', NULL, 3, 'numeric'::answer_type, '16.97', 'm/s', false, NULL, false, '(a) With θ = 90°: |Δv| = 2v sin(45°) = 2v × (√2/2) = v√2. (b) For v = 12 m/s: |Δv| = 12√2 = 17.0 m/s. Common mistake: assuming |Δv| should equal v itself after a quarter turn (since the two velocities look "equally spaced") — the correct factor is √2 ≈ 1.41, not 1.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('38fc256d-aee5-5847-b0dd-981f5bd426fc', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'as', '1.7', '9702 1.7 Subtracting vectors', 16, 16, 'A ball’s velocity just before bouncing off the ground is (8.0, −6.0) m/s, and just after is (8.0, +4.0) m/s (components in m/s, taking up as positive). (a) Calculate the components of Δv. (b) Calculate the magnitude of Δv. Give only the answer to (b).', 'diagram:kin-1.7-q16', 3, 'numeric'::answer_type, '10', 'm/s', false, NULL, false, '(a) Δv = (8.0−8.0, 4.0−(−6.0)) = (0, 10.0) m/s — the horizontal component is unchanged by the bounce (no horizontal force acts), while the vertical component reverses and loses some size (the bounce is not perfectly elastic). (b) |Δv| = √(0²+10.0²) = 10.0 m/s. Common mistake: including the unchanged horizontal component (8.0 m/s) as if it contributed to Δv — a component that does not change contributes exactly zero to the difference.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('bc8726d0-f2a7-595e-a624-ca808bf24199', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'as', '1.7', '9702 1.7 Subtracting vectors', 17, 17, 'The table shows a particle’s velocity components at two times. (a) Calculate the magnitude of Δv between t = 0 s and t = 4.0 s. (b) Calculate the magnitude of the average acceleration over this interval. Give only the answer to (b).', 'diagram:kin-1.7-q17', 3, 'numeric'::answer_type, '3', 'm/s²', false, NULL, false, '(a) Δv = (5.0−5.0, 12−0) = (0, 12) m/s, so |Δv| = 12.0 m/s. (b) average acceleration = |Δv| ÷ Δt = 12.0 ÷ 4.0 = 3.00 m/s². Common mistake: forgetting that the x-component (5.0 m/s) is unchanged here, and mistakenly including it in the magnitude of Δv, which would give the wrong (too large) value.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e9a313f1-2371-52fb-8bc6-fa23c474b16e', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'as', '1.7', '9702 1.7 Subtracting vectors', 18, 18, 'Car A''s velocity is (20, 0) m/s and car B''s velocity is (12, 16) m/s (components in m/s). Calculate the magnitude of the velocity of A relative to B, v_A − v_B.', 'diagram:kin-1.7-q18', 3, 'numeric'::answer_type, '17.89', 'm/s', false, NULL, false, 'v_A − v_B = (20−12, 0−16) = (8.00, −16.0) m/s. Magnitude = √(8.00² + 16.0²) = 17.9 m/s. Common mistake: computing v_B − v_A instead of v_A − v_B — the order matters, and reversing it would give a vector in exactly the opposite direction (the magnitude here happens to come out the same, but the direction would be wrong).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8a8a1c78-a5b1-50bd-90b1-2430a1fe7f5b', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'as', '1.7', '9702 1.7 Subtracting vectors', 19, 19, 'For two vectors of equal magnitude v with an angle θ between their directions, show (using the isosceles triangle formed by v₁, v₂ and Δv) that |Δv| = 2v sin(θ/2). Evaluate this for v = 15 m/s and θ = 50°.', NULL, 4, 'numeric'::answer_type, '12.68', 'm/s', false, 0.05, false, 'Place v₁ and v₂ tail-to-tail, each v₁ and v₂ making angle θ/2 with their common bisector (by symmetry, since |v₁|=|v₂|). Δv = v₂ − v₁ runs from the tip of v₁ to the tip of v₂, perpendicular to that bisector. Splitting the isosceles triangle along the bisector gives a right triangle with hypotenuse v and opposite side |Δv|/2, so sin(θ/2) = (|Δv|/2)/v, giving |Δv| = 2v sin(θ/2). For v = 15 m/s, θ = 50°: |Δv| = 2 × 15 × sin25° = 12.7 m/s. Common mistake: treating the triangle of v₁, v₂ and Δv as right-angled at the wrong vertex — the right angle only appears after bisecting the isosceles triangle, not in the original triangle itself.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('515917ca-1856-5b14-a478-4c3470bd261b', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'as', '1.7', '9702 1.7 Subtracting vectors', 20, 20, 'A spacecraft’s orbital velocity is (0, 7800) m/s just before a thruster burn, and (120, 7795) m/s just after (components in m/s). The burn lasts 2.5 s. (a) Calculate the components of Δv produced by the burn. (b) Calculate the magnitude of Δv. (c) Calculate the magnitude of the average acceleration produced by the thrusters. Give only the answer to (c).', NULL, 4, 'numeric'::answer_type, '48.04', 'm/s²', false, NULL, false, '(a) Δv = (120−0, 7795−7800) = (120, −5.00) m/s — the burn mostly changes the velocity sideways (120 m/s), while barely slowing the main orbital component (only 5 m/s). (b) |Δv| = √(120²+5.00²) = 120 m/s. (c) average acceleration = 120 ÷ 2.5 = 48.0 m/s². Common mistake: using only the large 7800-ish numbers to estimate Δv, which are nearly equal and mostly cancel — the SMALL sideways component (120 m/s) actually dominates the size of Δv here.', 6) ON CONFLICT (id) DO NOTHING;
