INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('946b198e-71d2-59fc-9f46-bc7b8429c8e5', '21af327e-b762-4ad1-b298-e2c7bbd8dc5f', 'temperature', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
