INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('dec35b40-b1a9-53ea-bead-7a809f6c9935', '747aff67-16c5-49af-8a41-23db12e65a2b', 'temperature', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7942fab9-9ebd-5f41-9675-6b70b83908f7', '747aff67-16c5-49af-8a41-23db12e65a2b', 'velocity', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('429d6218-c923-5520-a9cb-2d63035d1997', '747aff67-16c5-49af-8a41-23db12e65a2b', 'displacement', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0ad417ea-2b51-52bc-aaad-05a1629c0b0c', '747aff67-16c5-49af-8a41-23db12e65a2b', 'force', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f09c0367-849e-508c-9b04-aad01bc644f8', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'as', '1.8', '9702 1.8 Other examples of scalar and vector quantities', 9, 9, 'A 2.0 kg object moves at 6.0 m/s. Calculate the magnitude of its momentum.', 'diagram:kin-1.8-q9', 2, 'numeric'::answer_type, '12', 'kg m/s', false, NULL, false, 'momentum = mass × velocity = 2.0 × 6.0 = 12.0 kg m/s, directed the same way as the velocity (since mass, a positive scalar, never changes a vector’s direction, only scales its size). Common mistake: forgetting that momentum’s direction is simply inherited from the velocity’s direction — no separate calculation of direction is needed here.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('510b3de9-2f12-5a21-9690-3a57af204731', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'as', '1.8', '9702 1.8 Other examples of scalar and vector quantities', 10, 10, 'Two forces act on an object: 30 N due east and 40 N due north. Calculate the magnitude of the resultant force.', 'diagram:kin-1.8-q10', 2, 'numeric'::answer_type, '50', 'N', false, NULL, false, 'Forces combine exactly like any other vector: magnitude = √(30²+40²) = √(900+1600) = √2500 = 50.0 N (a 3-4-5 triangle scaled by 10). Common mistake: adding 30 + 40 = 70 N directly, forgetting the two forces act at right angles.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e4c3df8b-1d36-592e-89b0-c6e09c2e92dd', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'as', '1.8', '9702 1.8 Other examples of scalar and vector quantities', 11, 11, 'Identify the VECTOR quantity in this list.', NULL, 2, 'multiple_choice'::answer_type, 'acceleration', NULL, false, NULL, false, 'Acceleration (the rate of change of velocity) has both a size and a direction — the direction in which the velocity is changing — so it is a vector. Common mistake: thinking of acceleration only as "how quickly something speeds up", without considering it could also describe slowing down or changing direction, both of which need a direction to describe fully.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5e508cf6-d6ba-5447-8966-418109ea1e8a', 'e4c3df8b-1d36-592e-89b0-c6e09c2e92dd', 'acceleration', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('eba24e5c-07ae-5273-acde-4979d454148b', 'e4c3df8b-1d36-592e-89b0-c6e09c2e92dd', 'mass', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('27eb1cd0-864c-56fd-af0a-104a1df1558e', 'e4c3df8b-1d36-592e-89b0-c6e09c2e92dd', 'energy', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('91110814-2406-509c-9085-009e381b09c9', 'e4c3df8b-1d36-592e-89b0-c6e09c2e92dd', 'distance', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2093911d-b07a-50fb-b5f7-696f5585e800', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'as', '1.8', '9702 1.8 Other examples of scalar and vector quantities', 12, 12, 'An object’s weight is 20 N, acting vertically down. A rope pulls on it with tension 25 N, directed at 60° above the horizontal. Calculate the vertical component of the tension.', 'diagram:kin-1.8-q12', 2, 'numeric'::answer_type, '21.65', 'N', false, NULL, false, 'Vertical component = 25 × sin60° = 25 × 0.866 = 21.7 N. Common mistake: using cos60° instead of sin60° — the vertical component uses sin when the angle is measured FROM the horizontal.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('fb482231-f248-5686-a852-31101d69fc4f', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'as', '1.8', '9702 1.8 Other examples of scalar and vector quantities', 13, 13, 'Which of these statements about combining vector quantities is TRUE?', NULL, 2, 'multiple_choice'::answer_type, 'Two forces of 3 N and 4 N could combine to give a resultant anywhere from 1 N to 7 N, depending on the angle between them', NULL, false, NULL, false, 'Because vectors depend on direction as well as size, the resultant of two vectors of magnitude 3 N and 4 N could be anywhere from |4−3|=1 N (opposite directions) up to 4+3=7 N (same direction), depending on the angle between them — it is not simply fixed at one value. Common mistake: assuming two forces of given sizes must always combine to one fixed resultant, regardless of the angle between them.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('39cca423-3dcc-5265-9a7d-66db51529751', 'fb482231-f248-5686-a852-31101d69fc4f', 'Two forces of 3 N and 4 N could combine to give a resultant anywhere from 1 N to 7 N, depending on the angle between them', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3aa40391-9a90-551b-96f6-86ed6316be83', 'fb482231-f248-5686-a852-31101d69fc4f', 'Two forces of 3 N and 4 N must always combine to give exactly 7 N', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f97c4bb1-b237-568d-80d3-59c4430d5f95', 'fb482231-f248-5686-a852-31101d69fc4f', 'Two forces of 3 N and 4 N must always combine to give exactly 5 N', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('39c2befb-48ac-52ec-8990-85c6d7c15343', 'fb482231-f248-5686-a852-31101d69fc4f', 'The resultant of two vectors never depends on the angle between them', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('edc83621-c1a1-56bc-8e1a-d9c5c134aa0e', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'as', '1.8', '9702 1.8 Other examples of scalar and vector quantities', 14, 14, 'Two forces act on an object: 80 N at 0° and 60 N at 90°. (a) Calculate the magnitude of the resultant force. (b) Calculate the angle the resultant makes above the x-axis. Give only the answer to (a).', 'diagram:kin-1.8-q14', 3, 'numeric'::answer_type, '100', 'N', false, NULL, false, '(a) magnitude = √(80²+60²) = √(6400+3600) = √10000 = 100 N (a 3-4-5 triangle scaled by 20). (b) angle = tan⁻¹(60/80) = 36.9° above the x-axis. Common mistake: forgetting that the two given forces are already at right angles, and instead trying to use the general (and here unnecessary) component-resolution method for angled vectors.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f33f4888-bdc4-5b4e-861b-2a49c96acefd', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'as', '1.8', '9702 1.8 Other examples of scalar and vector quantities', 15, 15, 'A delivery drone’s weight is 30 N (vertically down). Its rotors provide a lift force of 45 N, directed 20° from the vertical. (a) Calculate the vertical component of the lift. (b) Calculate the horizontal component of the lift. (c) Calculate the net vertical force on the drone (lift’s vertical component minus weight). Give only the answer to (c).', 'diagram:kin-1.8-q15', 3, 'numeric'::answer_type, '12.29', 'N', false, 0.05, false, '(a) Vertical component of lift = 45cos20° = 42.3 N. (b) Horizontal component of lift = 45sin20° = 15.4 N. (c) Net vertical force = 42.3 − 30 = 12.3 N (upward, since it is positive), which is why the drone climbs. Common mistake: using the full 45 N lift (rather than just its vertical component) when finding the net vertical force, ignoring that the lift is tilted and so only part of it acts vertically.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('12e059d7-013d-5da7-ba0f-1f64df447320', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'as', '1.8', '9702 1.8 Other examples of scalar and vector quantities', 16, 16, 'State whether each of the following is a scalar or a vector: (i) kinetic energy, (ii) electric field strength, (iii) momentum, (iv) pressure. Then calculate the magnitude of the momentum of a 1500 kg car travelling at 20 m/s.', NULL, 3, 'numeric'::answer_type, '30000', 'kg m/s', false, NULL, false, '(i) Kinetic energy: scalar (no direction). (ii) Electric field strength: vector (has a direction, the direction a positive charge would be pushed). (iii) Momentum: vector (direction of motion). (iv) Pressure: scalar (force per unit area in all directions at a point, not one single direction). Momentum = mass × velocity = 1500 × 20 = 30000 kg m/s. Common mistake: classifying pressure as a vector because it comes from force (a vector) divided by area — the directional information is lost because pressure acts equally in every direction at a point.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('58853112-f967-51d2-a1aa-c8945fbdfac1', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'as', '1.8', '9702 1.8 Other examples of scalar and vector quantities', 17, 17, 'Taking the direction of approach to the wall as positive, a 0.50 kg ball has momentum +3.0 kg m/s just before hitting a wall, and −2.0 kg m/s just after bouncing back. (a) Calculate the change in momentum, Δp. (b) Explain why the fact that momentum is a VECTOR (not a scalar) matters for this calculation. Give only the numerical answer to (a).', 'diagram:kin-1.8-q17', 3, 'numeric'::answer_type, '-5', 'kg m/s', false, NULL, false, '(a) Δp = final − initial = (−2.0) − (+3.0) = −5.00 kg m/s. (b) Because momentum is a vector, the bounce (a reversal of direction) must be represented by a sign change, not just by comparing the SIZES of the momentum before and after (which would wrongly suggest only a 1.0 kg m/s decrease in "how much momentum" there is). Common mistake: calculating |p_after| − |p_before| = 2.0 − 3.0 = −1.0 kg m/s, which ignores the fact that the ball’s direction reversed.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('47cba9e9-e4e1-5b08-8656-3adb9ae5327e', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'as', '1.8', '9702 1.8 Other examples of scalar and vector quantities', 18, 18, 'State which of the following are vector quantities and which are scalar: mass, weight, electric field strength, charge, kinetic energy, momentum, time. Then two electric field strength vectors, of magnitude 500 N/C and 300 N/C, act at right angles to each other at a point. Calculate the magnitude of the resultant field strength.', 'diagram:kin-1.8-q18', 3, 'numeric'::answer_type, '583.1', 'N/C', false, NULL, false, 'Vectors: weight, electric field strength, momentum (each has a direction). Scalars: mass, charge, kinetic energy, time (each is fully described by a single number). The same combination rule that applies to displacement or velocity applies here too: magnitude = √(500²+300²) = √(250000+90000) = √340000 = 583 N/C. Common mistake: thinking electric field strength needs a completely different combination technique from "mechanical" vectors like displacement or force — the vector mathematics is identical for every vector quantity, whatever it physically represents.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8b0e77af-dab8-53d5-8054-3a5218575dce', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'as', '1.8', '9702 1.8 Other examples of scalar and vector quantities', 19, 19, 'A rod experiences a known force of 120 N at 0° and an unknown force F. The resultant of the two forces is 150 N, directed at 40° above the x-axis. (a) Resolve the resultant into x- and y-components. (b) Hence find the components of F. (c) Calculate the magnitude of F. Give only the answer to (c).', 'diagram:kin-1.8-q19', 4, 'numeric'::answer_type, '96.55', 'N', false, NULL, false, '(a) Resultant components: x = 150cos40° = 115 N, y = 150sin40° = 96.4 N. (b) Since the 120 N force + F = resultant: F_x = 115 − 120 = −5.09 N, F_y = 96.4 − 0 = 96.4 N. (c) Magnitude of F = √(−5.09² + 96.4²) = 96.6 N. Common mistake: adding the 120 N force to the resultant instead of SUBTRACTING it to isolate the unknown F (since 120 N + F = resultant means F = resultant − 120 N).', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8a850848-6d27-5a87-b797-dedc5412d18e', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'as', '1.8', '9702 1.8 Other examples of scalar and vector quantities', 20, 20, 'The method used to combine vectors (by components, or tip-to-tail) is identical no matter which physical quantity the vectors represent. Demonstrate this by finding the magnitude of the resultant of three momentum vectors, in kg m/s: (6, 0), (0, 8) and (−2, −1).', 'diagram:kin-1.8-q20', 4, 'numeric'::answer_type, '8.062', 'kg m/s', false, NULL, false, ('Exactly as with displacement or velocity, add the x-components together and the y-components together: x = 6 + 0 + (−2) = 4.00 kg m/s' || chr(59) || ' y = 0 + 8 + (−1) = 7.00 kg m/s. Magnitude = √(4.00² + 7.00²) = 8.06 kg m/s. This confirms the point of this topic: the mathematics of vectors does not care whether the quantity being combined is a displacement, a velocity, a force, or (as here) a momentum — only the type of quantity, which must match for a sum to make physical sense, changes. Common mistake: thinking a "new" rule is needed to combine momentum vectors specifically, rather than reusing the exact component method already learned for displacement and velocity.'), 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('be1de8e4-e3e0-53af-bcdd-609853fd2249', 'f8bf04cc-1ab1-4e5e-9aac-9f3c04cf62db', 'Acceleration is the rate of change of velocity', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('922c5da7-5d6c-598d-853a-90195e5bd0c3', 'f8bf04cc-1ab1-4e5e-9aac-9f3c04cf62db', 'Acceleration is the rate of change of distance', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6a00b8bc-7fc9-510a-aa0a-3f3a38e96fa5', 'f8bf04cc-1ab1-4e5e-9aac-9f3c04cf62db', 'Acceleration is velocity divided by mass', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('06e7c606-2b61-5468-81bd-ca4b82ed948a', 'f8bf04cc-1ab1-4e5e-9aac-9f3c04cf62db', 'Acceleration only occurs when an object speeds up', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ad9112ef-144e-5c1a-8b30-b2922400c9ce', '02e05a08-eaad-4e54-9837-81441faebbfc', 'Opposite to the direction of motion', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9d3250f9-cfbf-590f-afff-71c7984b510d', '02e05a08-eaad-4e54-9837-81441faebbfc', 'In the same direction as the motion', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('eae40543-7db1-52fd-884d-16b2c34ae38b', '02e05a08-eaad-4e54-9837-81441faebbfc', 'Perpendicular to the motion', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('17fc4769-01c8-5c30-9954-74e62645953a', '02e05a08-eaad-4e54-9837-81441faebbfc', 'Acceleration is undefined while slowing down', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5f78e54d-5ed1-5459-b43c-ca26a3caa2e1', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 7, 7, 'Taking the ball''s initial direction as positive, a ball''s velocity changes from +5.0 m/s to −3.0 m/s in 2.0 s (it bounces and reverses direction). Calculate its acceleration.', 'diagram:kin-2.1-q7', 2, 'numeric'::answer_type, '-4', 'm/s²', false, NULL, false, 'acceleration = Δv ÷ Δt = ((−3.0) − (+5.0)) ÷ 2.0 = (−8.0) ÷ 2.0 = −4.00 m/s². Common mistake: using the SPEEDS before and after (5.0 and 3.0 m/s) instead of the signed velocities, which would miss that the direction has reversed.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('48fda813-09b1-53a2-8121-751da4b09c9a', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 8, 8, 'A car moving in the negative direction (taking forward as positive) speeds up, becoming more negative. Is its acceleration positive or negative?', NULL, 2, 'multiple_choice'::answer_type, 'Negative — the acceleration points in the negative direction, in which the car is already moving and speeding up', NULL, false, NULL, false, 'The velocity is becoming MORE negative, so Δv is negative, meaning the acceleration itself is negative — even though the car is speeding up (not slowing down). Common mistake: assuming "negative acceleration" always means slowing down — it actually means the acceleration vector points in the negative direction, which can mean speeding up OR slowing down depending on which way the object is already moving.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3f0bffa7-06db-5715-9f83-f6c0154e83a2', '48fda813-09b1-53a2-8121-751da4b09c9a', 'Negative — the acceleration points in the negative direction, in which the car is already moving and speeding up', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5c488616-5110-5ff5-a67a-affac074bc3d', '48fda813-09b1-53a2-8121-751da4b09c9a', 'Positive, because speeding up is always a positive acceleration', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5e406025-2577-5f14-8ffc-6ebd5b094b3f', '48fda813-09b1-53a2-8121-751da4b09c9a', 'Zero, because the direction has not changed', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ed336fe9-1e9a-55a5-b854-da5fc971be36', '48fda813-09b1-53a2-8121-751da4b09c9a', 'It is impossible to have acceleration while moving in the negative direction', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('24b24a7e-2868-5cb9-9da0-5370f1653d15', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 9, 9, 'A train decelerates uniformly from 40 m/s to rest in 20 s. Calculate the magnitude of its deceleration.', 'diagram:kin-2.1-q9', 2, 'numeric'::answer_type, '2', 'm/s²', false, NULL, false, 'Deceleration is just the magnitude of a (negative) acceleration while slowing down: magnitude = Δv ÷ Δt = (40−0) ÷ 20 = 2.00 m/s². Common mistake: reporting this as "+2.0 m/s²" without recognising that, as an acceleration (not a deceleration magnitude), it would actually be −2.0 m/s² if forward is taken as positive.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('45705353-73a9-5e2a-bb55-b11b2496cbc2', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 10, 10, 'A ball is thrown straight up. At the very top of its path, its velocity is momentarily zero. Is its acceleration also zero at that instant?', NULL, 2, 'multiple_choice'::answer_type, 'No — its acceleration is still g, downward, even though its velocity is momentarily zero', NULL, false, NULL, false, 'No — gravity continues to act on the ball throughout its flight, giving it a constant downward acceleration of about 9.81 m/s² at every instant, including the top, even though its velocity happens to be zero there for just that one instant. This is a classic case where velocity and acceleration are zero at DIFFERENT times. Common mistake: assuming zero velocity must always mean zero acceleration — they are independent quantities.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('33cebf38-7fd0-54d6-bd8c-d3703f5ccfbf', '45705353-73a9-5e2a-bb55-b11b2496cbc2', 'No — its acceleration is still g, downward, even though its velocity is momentarily zero', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3892013d-b310-5cc4-a6d1-cce5571aa234', '45705353-73a9-5e2a-bb55-b11b2496cbc2', 'Yes — zero velocity always means zero acceleration', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f6cd3db6-56c9-530b-9cd2-166ed6f222ff', '45705353-73a9-5e2a-bb55-b11b2496cbc2', 'No — its acceleration briefly becomes infinite at the top', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('701db0cc-cccf-57a0-b436-f4ebe986338d', '45705353-73a9-5e2a-bb55-b11b2496cbc2', 'Yes, because the ball is not moving at that instant', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('dbe507e1-9548-598b-b68f-32cab1c9310c', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 11, 11, 'A lift accelerates uniformly upward from rest, reaching 3.0 m/s after 1.5 s. Calculate the magnitude of its acceleration.', 'diagram:kin-2.1-q11', 2, 'numeric'::answer_type, '2', 'm/s²', false, NULL, false, 'acceleration = Δv ÷ Δt = (3.0−0) ÷ 1.5 = 2.00 m/s². Common mistake: using the WRONG time (for example, confusing 1.5 s with a different stated time elsewhere in a multi-part problem).', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7ad756f6-8cf0-58cc-b0bc-6861122fc155', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 12, 12, 'Which statement correctly distinguishes "uniform acceleration" from "uniform velocity"?', NULL, 2, 'multiple_choice'::answer_type, ('Uniform velocity means velocity is constant (zero acceleration)' || chr(59) || ' uniform acceleration means acceleration is constant while velocity keeps changing steadily'), NULL, false, NULL, false, ('Uniform velocity means the velocity itself stays constant (so acceleration is zero)' || chr(59) || ' uniform acceleration means the ACCELERATION stays constant, while the velocity itself is continuously changing at a steady rate. Common mistake: treating the two phrases as describing the same kind of motion, when they describe opposite situations for the velocity (constant vs continuously changing).'), 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('41c4e3b7-8a40-5d55-8f5d-e0fe59fd60f6', '7ad756f6-8cf0-58cc-b0bc-6861122fc155', ('Uniform velocity means velocity is constant (zero acceleration)' || chr(59) || ' uniform acceleration means acceleration is constant while velocity keeps changing steadily'), 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('da6f7d3f-01d3-5c3d-9d53-17e3b0d4f2f9', '7ad756f6-8cf0-58cc-b0bc-6861122fc155', 'They both mean exactly the same thing', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7c3eeea1-1b8b-55ab-8274-284736af7a2f', '7ad756f6-8cf0-58cc-b0bc-6861122fc155', 'Uniform acceleration means the object is not moving', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('463d977d-ae59-57d0-8581-916e8b936d33', '7ad756f6-8cf0-58cc-b0bc-6861122fc155', 'Uniform velocity means the acceleration is increasing steadily', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b161977c-c32f-502c-a651-4ac18184d37a', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 13, 13, 'A cyclist''s velocity increases steadily from 4.0 m/s to 10 m/s over 12 s. Calculate the acceleration.', 'diagram:kin-2.1-q13', 2, 'numeric'::answer_type, '0.5', 'm/s²', false, NULL, false, 'acceleration = Δv ÷ Δt = (10−4.0) ÷ 12 = 0.500 m/s². Common mistake: dividing by the final velocity (10 m/s) rather than the time (12 s).', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3eb22f34-63cc-5105-9dc8-d3a4c1fa9704', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 14, 14, 'A sprinter''s velocity increases uniformly from 0 to 10 m/s in the first 2.0 s of a race, then stays constant at 10 m/s for the next 6.0 s. (a) Calculate the acceleration during the first 2.0 s. (b) State the acceleration during the next 6.0 s. (c) Explain why the acceleration in (b) is zero even though the sprinter is still moving quickly. Give only the numerical answer to (a).', 'diagram:kin-2.1-q14', 3, 'numeric'::answer_type, '5', 'm/s²', false, NULL, false, '(a) acceleration = (10−0) ÷ 2.0 = 5.00 m/s². (b) Since the velocity is no longer changing (it stays at exactly 10 m/s), acceleration = 0 m/s². (c) Acceleration depends on the RATE OF CHANGE of velocity, not on how fast the sprinter is actually moving — a high but unchanging velocity still gives zero acceleration. Common mistake: assuming a fast-moving object must also have a large acceleration — speed and acceleration are entirely separate quantities.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7e50170d-0bb0-509f-bd9d-b32417e903bc', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 15, 15, 'A ball is thrown vertically upward at 15 m/s and returns to the thrower’s hand 2 × 15/9.81 s later (taking up as positive, g = 9.81 m/s² throughout the flight). (a) Calculate the time taken to reach the highest point. (b) Calculate the velocity 0.50 s after being thrown. (c) State whether the ball is still rising or already falling at that time. Give only the numerical answer to (b).', 'diagram:kin-2.1-q15', 3, 'numeric'::answer_type, '10.09', 'm/s', false, NULL, false, '(a) At the highest point v = 0: 0 = 15 − 9.81t, so t = 15 ÷ 9.81 = 1.53 s. (b) At t = 0.50 s: v = 15 − 9.81 × 0.50 = 10.1 m/s. (c) Since this velocity is still positive (and 0.50 s is less than the 1.53 s found in (a)), the ball is still RISING at this time. Common mistake: using g = +9.81 (instead of −9.81, since gravity decelerates the rise when up is positive), which would wrongly make the ball appear to speed up as it rises.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('065d24aa-5523-5de0-b2dd-86b3b20b4f8c', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 16, 16, ('The table shows a trolley’s velocity at 1-second intervals: t = 0 s, 3.0 m/s' || chr(59) || ' t = 1 s, 6.0 m/s' || chr(59) || ' t = 2 s, 6.0 m/s' || chr(59) || ' wait — use this data: t (s): 0, 1, 2, 3, 4, 5' || chr(59) || ' v (m/s): 0, 3, 6, 9, 12, 16. Calculate the average acceleration between t = 2.0 s and t = 5.0 s.'), 'diagram:kin-2.1-q16', 3, 'numeric'::answer_type, '3.333', 'm/s²', false, NULL, false, 'Only the two endpoints matter for an average: acceleration = (16−6) ÷ (5−2) = 3.33 m/s². (Between t = 0 s and t = 4 s the trolley’s acceleration looks uniform at 3.0 m/s², but the final second shows a bigger jump of 4.0 m/s², so the motion is not perfectly uniform overall — this average blends both parts of the interval asked about.) Common mistake: using the acceleration from the earlier, uniform-looking part of the table (3.0 m/s²) instead of recalculating using the actual two times given in the question.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5322462f-d5b0-5d02-9c71-d5312f853f4e', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 17, 17, 'Velocity readings, each accurate to ±0.1 m/s, give 2.0 m/s at t = 0 and 6.4 m/s at t = 2.0 s (the time is measured precisely). (a) Calculate the acceleration. (b) Calculate the percentage uncertainty in this acceleration. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '4.545', '%', false, NULL, false, '(a) acceleration = (6.4−2.0) ÷ 2.0 = 2.20 m/s². (b) The two reading uncertainties combine by addition when the readings are subtracted: absolute uncertainty in Δv = 0.1 + 0.1 = 0.2 m/s, out of Δv = 4.40 m/s. Percentage uncertainty = 0.2 ÷ 4.40 × 100% = 4.55% (the precisely-measured time contributes no extra uncertainty). Common mistake: using only ONE reading’s ±0.1 m/s uncertainty, instead of adding the uncertainties from both readings used in the subtraction.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e32749e8-692d-52a2-8023-0d47851217dd', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 18, 18, 'A car starts from rest. Its acceleration is +2.0 m/s² for 4.0 s (speeding up), then 0 m/s² for 10 s (constant velocity), then −4.0 m/s² for 2.0 s (braking). (a) Calculate the velocity at the end of the first phase. (b) Calculate the velocity at the end of the second phase. (c) Calculate the velocity at the end of the third (braking) phase. Give only the answer to (c).', 'diagram:kin-2.1-q18', 3, 'numeric'::answer_type, '0', 'm/s', false, NULL, false, '(a) v = 0 + 2.0 × 4.0 = 8.00 m/s. (b) Unchanged during the constant-velocity phase: v = 8.00 m/s. (c) v = 8.00 + (−4.0) × 2.0 = 0 m/s — the braking phase exactly cancels the speeding-up phase, bringing the car back to rest. Common mistake: forgetting that the middle (zero-acceleration) phase leaves the velocity completely unchanged, and instead assuming it must also change the velocity because time has passed.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('60f1f8d3-5daa-5866-bf91-c62394ee600d', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 19, 19, 'Explain why an object can have zero velocity but nonzero acceleration at one instant, and why an object can have zero acceleration but nonzero velocity at another instant. Then, for a ball thrown vertically upward at 20 m/s (taking up as positive, g = 9.81 m/s²), calculate its acceleration at the exact instant it is at the highest point of its path (where v = 0).', NULL, 4, 'numeric'::answer_type, '-9.81', 'm/s²', false, NULL, false, 'Velocity and acceleration are independent quantities: velocity describes the CURRENT rate of change of displacement, while acceleration describes the rate of change of THAT velocity. A ball thrown upward has zero velocity at its highest point, but gravity is still acting on it at that exact instant, giving a nonzero (downward) acceleration — this is why it does not simply hover there, but immediately starts to fall. Conversely, an object moving at a constant velocity (e.g. a car cruising on a motorway) has a large, nonzero velocity but zero acceleration, since its velocity is not changing at all. For the ball: its acceleration is g = 9.81 m/s² directed downward AT EVERY INSTANT of its flight, including the top, so with up taken as positive, acceleration = −9.81 m/s². Common mistake: assuming the ball’s acceleration must also be zero at the top simply because its velocity is zero there.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('bf8be5d4-fbec-5286-85ac-cc4ee9460818', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'as', '2.1', '9702 2.1 The meaning of acceleration', 20, 20, 'A maglev train’s velocity doubles every 10 s while accelerating from rest: v = 5.0 m/s at t = 10 s, v = 10 m/s at t = 20 s, v = 20 m/s at t = 30 s. (a) Calculate the average acceleration between t = 10 s and t = 20 s. (b) Calculate the average acceleration between t = 20 s and t = 30 s. (c) Explain what this shows about whether the train’s acceleration is uniform. Give only the numerical answer to (b).', NULL, 4, 'numeric'::answer_type, '1', 'm/s²', false, NULL, false, '(a) Between t = 10 s and t = 20 s: average acceleration = (10−5.0) ÷ 10 = 0.500 m/s². (b) Between t = 20 s and t = 30 s: average acceleration = (20−10) ÷ 10 = 1.00 m/s². (c) The acceleration is NOT uniform — it is larger in the second 10 s interval (1.00 m/s²) than in the first (0.500 m/s²), which makes sense because a velocity that doubles every fixed time interval grows faster and faster in absolute terms as time goes on. Common mistake: assuming "doubling every 10 s" must describe uniform acceleration, just because the TIME intervals are equal — uniform acceleration needs equal CHANGES in velocity in equal times, not equal ratios.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3ece5a1f-3f62-52e9-8ec1-2187e0daff73', 'fda7f4d0-f229-4a40-a08c-bd89639d485f', 'Δv = aΔt', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('eb901646-9633-5dd3-b2ff-e43cdcafedb2', 'fda7f4d0-f229-4a40-a08c-bd89639d485f', 'Δv = a ÷ Δt', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9fd4f9cc-b000-5717-a405-f6379bdcdbbf', 'fda7f4d0-f229-4a40-a08c-bd89639d485f', 'Δv = Δt ÷ a', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ffe5e19e-aa06-507b-b329-d3bb9b07f06c', 'fda7f4d0-f229-4a40-a08c-bd89639d485f', 'Δv = a + Δt', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d4fe8618-4303-545d-ae6b-8742a129c044', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 7, 7, 'A cyclist starts from rest and accelerates at 0.80 m/s² for 15 s. Calculate the final velocity.', 'diagram:kin-2.2-q7', 2, 'numeric'::answer_type, '12', 'm/s', false, NULL, false, 'v = u + at = 0 + 0.80 × 15 = 12.0 m/s. Common mistake: forgetting that "starts from rest" means u = 0, and instead leaving u out of the formula entirely in a way that changes the structure of the calculation.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c9fd423f-432b-5b0a-bc31-11a25c7eb67c', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 8, 8, 'Can the acceleration of a real object ever be non-uniform, so that "average acceleration" over an interval differs from its instantaneous value at any one moment within it?', NULL, 2, 'multiple_choice'::answer_type, 'Yes, acceleration can be non-uniform, and an "average acceleration" calculation only gives the overall mean rate over the interval', NULL, false, NULL, false, 'Yes — just as with velocity, acceleration can vary moment to moment (for example, a car’s engine may provide more thrust at some speeds than others). "Average acceleration" calculated from Δv ÷ Δt over an interval is then only the overall mean rate over that whole interval, which can disagree with the acceleration at any single instant within it. Common mistake: assuming every acceleration calculation using Δv ÷ Δt automatically describes a truly constant (uniform) acceleration throughout the interval.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4c1306da-0afb-5b46-8301-b972f88a0da8', 'c9fd423f-432b-5b0a-bc31-11a25c7eb67c', 'Yes, acceleration can be non-uniform, and an "average acceleration" calculation only gives the overall mean rate over the interval', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f1554b01-1f92-5647-96d7-ae6d8805eba6', 'c9fd423f-432b-5b0a-bc31-11a25c7eb67c', 'No, acceleration is always uniform in any real situation', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5912d605-d449-5b09-8665-1945b72edd47', 'c9fd423f-432b-5b0a-bc31-11a25c7eb67c', 'No, average acceleration and instantaneous acceleration are mathematically identical by definition', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bbf04b22-69f5-5cda-b880-b17bb61280d4', 'c9fd423f-432b-5b0a-bc31-11a25c7eb67c', 'Yes, but only for objects moving in a circle', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d5f84868-ecf3-537e-b1cb-5374faed5110', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 9, 9, 'An object starts from rest, accelerates at +2.0 m/s² for 3.0 s, then decelerates at −1.0 m/s² for a further 4.0 s. Calculate its final velocity.', 'diagram:kin-2.2-q9', 2, 'numeric'::answer_type, '2', 'm/s', false, NULL, false, 'Phase 1: v₁ = 0 + 2.0×3.0 = 6.00 m/s. Phase 2: v₂ = 6.00 + (−1.0)×4.0 = 2.00 m/s. Common mistake: restarting from u = 0 for the second phase, instead of carrying forward the velocity reached at the end of the first phase as the new initial velocity.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ae22a82a-af65-5084-b413-a10ba0eeb036', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 10, 10, 'A car brakes from 100 km/h to rest in 2.5 s. Calculate its acceleration, in m/s².', 'diagram:kin-2.2-q10', 2, 'numeric'::answer_type, '-11.11', 'm/s²', false, NULL, false, 'Convert first: 100 ÷ 3.6 = 27.8 m/s. acceleration = (0 − 27.8) ÷ 2.5 = −11.1 m/s². Common mistake: forgetting the unit conversion, which would give a numerically very different (and wrong) result.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c1ba9fe4-caeb-5314-aede-4768b0cda68a', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 11, 11, 'Object A accelerates from 0 to 20 m/s in 4.0 s. Object B accelerates from 0 to 20 m/s in 8.0 s. Which has the greater acceleration?', NULL, 2, 'multiple_choice'::answer_type, 'Object A, because it reaches the same velocity change in less time', NULL, false, NULL, false, 'Both objects undergo the same change in velocity (20 m/s), but object A does it in a shorter time, so a = Δv ÷ Δt gives A a LARGER acceleration (5.0 m/s² vs 2.5 m/s² for B). Common mistake: assuming the one that reaches the higher velocity (here, they are equal) determines the greater acceleration, rather than considering the time taken too.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('86b47731-67d2-5b47-a008-2b8b79509cad', 'c1ba9fe4-caeb-5314-aede-4768b0cda68a', 'Object A, because it reaches the same velocity change in less time', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0acacec7-13d1-5d2a-95ae-a3d71ad00fa3', 'c1ba9fe4-caeb-5314-aede-4768b0cda68a', 'Object B, because it takes longer', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f1a4cb10-2be9-584d-b34b-a68bd3780ef3', 'c1ba9fe4-caeb-5314-aede-4768b0cda68a', 'They must have equal acceleration', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6a65d46c-7d66-5721-a5c5-f4bd98e7890a', 'c1ba9fe4-caeb-5314-aede-4768b0cda68a', 'Acceleration cannot be compared without knowing the mass', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2c46f655-80f8-5c36-b313-52460cee39db', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 12, 12, 'An object reaches a final velocity of 15 m/s after accelerating at 2.5 m/s² for 6.0 s. Calculate its initial velocity.', 'diagram:kin-2.2-q12', 2, 'numeric'::answer_type, '0', 'm/s', false, NULL, false, 'u = v − at = 15 − (2.5 × 6.0) = 15 − 15 = 0 m/s — it started from rest. Common mistake: adding at to v instead of subtracting it, which would give u = 30 m/s.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0ca57373-b977-5f5e-851f-39009b92c0b9', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 13, 13, 'A lift accelerates from rest at 1.2 m/s² for 2.0 s before reaching a constant speed. Calculate the velocity at the end of the accelerating phase.', 'diagram:kin-2.2-q13', 2, 'numeric'::answer_type, '2.4', 'm/s', false, NULL, false, 'v = u + at = 0 + 1.2 × 2.0 = 2.40 m/s. Common mistake: using the total trip time instead of just the 2.0 s accelerating phase stated in the question.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('fcec0bec-69d7-5692-86aa-b856a3e75655', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 14, 14, 'A rocket, starting from rest, accelerates at 20 m/s² for 5.0 s (stage 1), then at 10 m/s² for a further 10 s (stage 2), then at 5.0 m/s² for a further 20 s (stage 3). (a) Calculate the velocity at the end of stage 1. (b) Calculate the velocity at the end of stage 2. (c) Calculate the velocity at the end of stage 3. Give only the answer to (c).', 'diagram:kin-2.2-q14', 3, 'numeric'::answer_type, '300', 'm/s', false, NULL, false, '(a) v₁ = 0 + 20×5.0 = 100 m/s. (b) v₂ = 100 + 10×10 = 200 m/s. (c) v₃ = 200 + 5.0×20 = 300 m/s. Common mistake: using the acceleration of each stage with the TOTAL elapsed time rather than just that stage’s own duration (e.g. using t = 35 s for stage 3 instead of its own 20 s).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e3b5c529-2157-5e18-a90b-20ad27d94812', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 15, 15, 'A car decelerates from 30 m/s to 10 m/s in 4.0 s (phase 1), then continues decelerating from 10 m/s to rest in a further 5.0 s (phase 2). (a) Calculate the acceleration during phase 1. (b) Calculate the acceleration during phase 2. (c) State which phase has the greater MAGNITUDE of deceleration. Give only the magnitude for that phase.', 'diagram:kin-2.2-q15', 3, 'numeric'::answer_type, '5', 'm/s²', false, NULL, false, '(a) a₁ = (10−30) ÷ 4.0 = −5.00 m/s². (b) a₂ = (0−10) ÷ 5.0 = −2.00 m/s². (c) |a₁| = 5.00 m/s² is greater than |a₂| = 2.00 m/s², so phase 1 brakes more sharply. Common mistake: assuming the phase with the bigger velocity CHANGE (here, both are 20 m/s and 10 m/s respectively, so phase 1 has the bigger change) must automatically have the bigger acceleration — the TIME taken matters too.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('89b6f1e2-218c-585a-be97-8036c84c947f', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 16, 16, ('A dragster’s velocity is recorded as: t = 0 s, v = 0' || chr(59) || ' t = 2.2 s, v = 45 m/s' || chr(59) || ' t = 4.1 s, v = 89 m/s' || chr(59) || ' t = 6.0 s, v = 130 m/s. Calculate the average acceleration between t = 2.2 s and t = 6.0 s.'), 'diagram:kin-2.2-q16', 3, 'numeric'::answer_type, '22.37', 'm/s²', false, NULL, false, 'acceleration = (130−45) ÷ (6.0−2.2) = 85 ÷ 3.8 = 22.4 m/s². Common mistake: using the reading at t = 0 s, which is outside the interval the question actually asks about.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('93120859-c4a7-52ec-b025-3ba7a7ad6bf5', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 17, 17, 'A velocity increases from 12.0 ± 0.3 m/s to 18.0 ± 0.3 m/s over a time of 2.0 ± 0.05 s. (a) Calculate the acceleration. (b) Calculate the percentage uncertainty in this acceleration, given that the percentage uncertainties in Δv and in t simply add together. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '12.5', '%', false, 0.05, false, '(a) acceleration = (18.0−12.0) ÷ 2.0 = 3.00 m/s². (b) Percentage uncertainty in Δv: the two reading uncertainties add, giving 0.3+0.3 = 0.6 m/s out of 6.00 m/s, i.e. 10.0%. Percentage uncertainty in t: 0.05 ÷ 2.0 × 100% = 2.50%. Since a = Δv ÷ t is a DIVISION, the percentage uncertainties add: 10.0% + 2.50% = 12.5%. Common mistake: forgetting to include the time’s own percentage uncertainty, and reporting only the uncertainty from Δv.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3468ae17-af2d-52ab-a377-13bd3fb1f7da', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 18, 18, 'A roller coaster''s speed increases from 5.0 m/s to 25 m/s while climbing a hill in 8.0 s. (a) Calculate the acceleration. (b) If the same speed change instead took only 4.0 s, state whether the acceleration would be larger or smaller, and by what factor. (c) Calculate that alternative acceleration. Give only the answer to (c).', 'diagram:kin-2.2-q18', 3, 'numeric'::answer_type, '5', 'm/s²', false, NULL, false, '(a) acceleration = (25−5.0) ÷ 8.0 = 2.50 m/s². (b) Halving the time for the SAME change in velocity doubles the acceleration (acceleration is inversely proportional to time, for a fixed Δv). (c) acceleration = (25−5.0) ÷ 4.0 = 5.00 m/s², exactly double the value from (a), confirming the factor predicted in (b). Common mistake: assuming halving the time must also halve the acceleration, rather than recognising the inverse relationship (halving the time DOUBLES the acceleration, for the same Δv).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4d94da3a-2292-56b3-82a1-0b4ad1db4a6a', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 19, 19, 'Taking the car’s initial direction as positive, a car travelling at 12 m/s decelerates uniformly at 3.5 m/s². (a) Calculate the time taken for it to come to rest. (b) If the SAME constant acceleration continued to act after the car stops (for example, rolling backwards down a slope), calculate how much additional time it would take to reach a velocity of −7.0 m/s. Give only the answer to (b).', NULL, 4, 'numeric'::answer_type, '2', 's', false, NULL, false, '(a) Time to stop: 0 = 12 − 3.5t₁, so t₁ = 12 ÷ 3.5 = 3.43 s. (b) Time to reach −7.0 m/s from the start: −7.0 = 12 − 3.5t, so t = (12−(−7.0)) ÷ 3.5 = 19 ÷ 3.5 = 5.43 s in total. The ADDITIONAL time beyond stopping is 5.43 − 3.43 = 2.00 s — a clean, exact 2.0 s. Common mistake: computing the time to reach −7.0 m/s directly from the moment the car stops using only 7.0 ÷ 3.5, without checking this matches the difference between the two total-time calculations (it does here, since the acceleration is constant throughout).', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b6eaf6f8-997f-5df6-b434-f4e97cfe8f95', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'as', '2.2', '9702 2.2 Calculating acceleration', 20, 20, 'A particle’s acceleration itself increases uniformly with time, following a = kt for some constant k (so the acceleration is not constant). At t = 2.0 s the acceleration is 6.0 m/s², and at t = 5.0 s it is 15 m/s². (a) Find k. (b) Since a(t) is itself a straight line in t, its average value over an interval equals the mean of its endpoint values. Estimate the average acceleration between t = 2.0 s and t = 5.0 s. Give only the answer to (b).', NULL, 4, 'numeric'::answer_type, '10.5', 'm/s²', false, 0.05, false, '(a) k = a ÷ t = 6.0 ÷ 2.0 = 3.00 m/s³ (check: at t = 5.0 s, a = 3.00 × 5.0 = 15 m/s² ✔). (b) Since a(t) = kt is a straight line in t, its mean value over the interval is just the average of its two endpoint values: (6.00 + 15.0) ÷ 2 = 10.5 m/s². Common mistake: assuming "average acceleration" always means Δv ÷ Δt calculated from VELOCITY readings — here it is being estimated directly from the (linear) ACCELERATION function itself, a different route to a similar idea.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d257dbaf-edfd-577a-8ea2-37d7c1385133', '1919969a-98b7-4d4b-9e0c-66b80ebf00c4', 'm s⁻² (metres per second squared)', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('93caf053-3816-5fcb-899d-7aec93e61b3b', '1919969a-98b7-4d4b-9e0c-66b80ebf00c4', 'm s⁻¹ (metres per second)', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c7ae4478-099c-5bab-9da2-fb79240d18cb', '1919969a-98b7-4d4b-9e0c-66b80ebf00c4', 'kg m s⁻² (newtons)', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7cfdd45b-b015-583b-a744-5babe307e301', '1919969a-98b7-4d4b-9e0c-66b80ebf00c4', 's⁻¹ (per second)', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3d9fe7d4-27c6-5bba-b323-17642b15e37e', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 7, 7, 'A fighter pilot experiences an acceleration of 6.0g during a tight turn. Calculate this acceleration in m/s².', NULL, 2, 'numeric'::answer_type, '58.86', 'm/s²', false, NULL, false, 'acceleration = 6.0 × 9.81 = 58.9 m/s². Common mistake: using g = 10 m/s² for this kind of precise aerospace figure, which loses accuracy that the question (quoting g to 3 significant figures) expects to be kept.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('23cc2971-fed3-5400-97db-cbb74e5b88a1', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 8, 8, 'Why is the unit of acceleration "per second SQUARED" rather than just "per second"?', NULL, 2, 'multiple_choice'::answer_type, 'Because acceleration is a rate of change of velocity, which is itself already a rate (so time is divided by twice)', NULL, false, NULL, false, 'Velocity already has units of "distance per second" (m/s). Acceleration is the RATE OF CHANGE of velocity, so it is (m/s) per second — dividing by time a second time, which is where the second power of seconds (s⁻²) comes from. Common mistake: thinking "per second squared" means something is being squared physically, rather than recognising it as a consequence of dividing by time twice in a row.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('36875141-bf4d-5acf-8892-290c2646a9df', '23cc2971-fed3-5400-97db-cbb74e5b88a1', 'Because acceleration is a rate of change of velocity, which is itself already a rate (so time is divided by twice)', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('50cd65fa-bcdf-5951-bcbe-e071b324ef4f', '23cc2971-fed3-5400-97db-cbb74e5b88a1', 'Because distance is measured in square metres', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8a2aa912-d4c8-5d10-9926-de5b162649d6', '23cc2971-fed3-5400-97db-cbb74e5b88a1', 'It is simply a historical convention with no underlying reason', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3872240f-d5a2-5c1b-bfc6-f8c684153219', '23cc2971-fed3-5400-97db-cbb74e5b88a1', 'Because acceleration always involves circular motion', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c5822bdb-c94e-53ef-9bac-12cdd52b808d', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 9, 9, 'Convert an acceleration of 2.5 m/s² into cm/s².', NULL, 2, 'numeric'::answer_type, '250', 'cm/s²', false, NULL, false, ('1 m = 100 cm, so 2.5 × 100 = 250 cm/s² — only the DISTANCE part of the unit changes' || chr(59) || ' the "per second squared" time part is unaffected. Common mistake: also multiplying the time part by 100, which does not need converting here.'), 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('bb4791e9-9649-5cd1-93f2-83c4797e673c', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 10, 10, 'A roller coaster car briefly experiences a vertical acceleration of 3.5g. Calculate this in m/s².', NULL, 2, 'numeric'::answer_type, '34.34', 'm/s²', false, NULL, false, 'acceleration = 3.5 × 9.81 = 34.3 m/s². Common mistake: rounding g to 10 m/s² and losing precision the question’s 3-significant-figure multiplier (3.5g) expects to be kept.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('cad21ba3-33a1-5c1d-bff1-a49a577cb4d7', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 11, 11, 'Starting from a = Δv/Δt, with velocity v = Δs/Δt (distance over time), which combination of SI base units correctly gives the unit of acceleration?', NULL, 2, 'multiple_choice'::answer_type, 'm s⁻²', NULL, false, NULL, false, 'Substituting: a = (Δs/Δt)/Δt = Δs/Δt², so in SI base units this is metres divided by seconds squared, i.e. m s⁻². Common mistake: substituting velocity’s unit (m/s) directly for v without then dividing by time AGAIN for the outer a = Δv/Δt step, which would leave the units at m/s rather than m/s².', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1ca59e4f-a53b-52bb-bf35-e619667221ca', 'cad21ba3-33a1-5c1d-bff1-a49a577cb4d7', 'm s⁻²', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c547ebb4-131c-5f6b-b5a2-50c2c82f060f', 'cad21ba3-33a1-5c1d-bff1-a49a577cb4d7', 'm s⁻¹', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8c5e958e-13d6-58bb-8d63-260057767abc', 'cad21ba3-33a1-5c1d-bff1-a49a577cb4d7', 'm² s⁻¹', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('497db6b8-1268-58e7-ba25-4e964ac08adb', 'cad21ba3-33a1-5c1d-bff1-a49a577cb4d7', 's⁻²', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4e081b60-d10a-5b69-abe2-4fd6cc448a83', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 12, 12, 'Convert an acceleration of 15 000 mm/s² into m/s².', NULL, 2, 'numeric'::answer_type, '15', 'm/s²', false, NULL, false, '1 m = 1000 mm, so 15 000 ÷ 1000 = 15.0 m/s². Common mistake: dividing by 100 (confusing mm with cm) instead of by 1000.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('613db635-2a6b-57d2-bf47-5b84ef81b6c9', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 13, 13, 'A rocket sled’s acceleration is quoted as "gaining 45 km/h of speed every second". Convert this rate into m/s².', NULL, 2, 'numeric'::answer_type, '12.5', 'm/s²', false, 0.05, false, 'First convert the velocity part: 45 ÷ 3.6 = 12.5 m/s, gained every second, so the acceleration is 12.5 m/s². Common mistake: leaving the answer as "45 km/h per second" without converting it into the SI unit (m/s²) the question specifically asks for.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('dadaba8d-78e7-548c-9bb9-a68b7867fa96', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 14, 14, 'A fighter jet pilot can safely tolerate up to 9.0g before blacking out. (a) Convert 9.0g to m/s². (b) If the jet accelerated from rest at this maximum rate, calculate the time to reach 300 m/s. (c) Briefly comment on whether sustaining 9.0g for a full minute would be realistic. Give only the numerical answer to (b).', 'diagram:kin-2.3-q14', 3, 'numeric'::answer_type, '3.398', 's', false, NULL, false, '(a) acceleration = 9.0 × 9.81 = 88.3 m/s². (b) t = Δv ÷ a = (300−0) ÷ 88.3 = 3.40 s. (c) In reality, 9.0g can only be tolerated briefly (a few seconds) even by trained, g-suited pilots before blacking out — sustaining it for a full minute is not physiologically realistic. Common mistake: using g = 9.81 m/s² itself as the acceleration in part (b), forgetting that the jet’s actual acceleration is 9 TIMES bigger than g.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d000e7ed-aaea-5e26-8db0-839c5554986c', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 15, 15, 'A dragster''s acceleration is reported by two sources: 26.0 m/s² and 2.60g. (a) Convert 2.60g to m/s². (b) Calculate the percentage difference between the two reported values, relative to the 2.60g figure. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.937', '%', false, 0.05, false, '(a) 2.60 × 9.81 = 25.5 m/s². (b) Percentage difference = (26.0 − 25.5) ÷ 25.5 × 100% = 1.94%. Common mistake: dividing by 26.0 instead of by the 2.60g figure the question specifies as the reference value, which would give a slightly different percentage.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('01785e7a-4ac9-5a81-b39d-b465aed61dfe', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 16, 16, ('The table lists the same kind of acceleration in three different units: Row A, 3.5g' || chr(59) || ' Row B, 40 m/s²' || chr(59) || ' Row C, 3600 km/h². Calculate the value of Row A in m/s², so it can be fairly compared with the others.'), 'diagram:kin-2.3-q16', 3, 'numeric'::answer_type, '34.34', 'm/s²', false, NULL, false, 'Row A: 3.5 × 9.81 = 34.3 m/s². (For comparison: Row B is already 40 m/s², the largest of the three, and Row C converts to only 3600 × 1000 ÷ 3600² = 0.278 m/s², by far the smallest — all three "accelerations" look like comparable-sized numbers before conversion, but are wildly different once expressed in the same unit.) Common mistake: comparing the raw numbers in the table (3.5, 40, 3600) directly, without first converting them all into the same unit.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7e2988d6-f618-54da-8f5b-d68c0af71f09', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 17, 17, 'Starting from a = Δv/Δt with v = Δs/Δt, show that the SI base unit of acceleration is m s⁻². Then state how many m s⁻² there are in exactly 1 km h⁻¹ s⁻¹ (a velocity of 1 km/h, gained every second).', NULL, 3, 'numeric'::answer_type, '0.2778', 'm/s²', false, NULL, false, 'Substituting v = Δs/Δt into a = Δv/Δt gives a = Δs/Δt², so in SI base units acceleration is metres divided by seconds squared: m s⁻². For the conversion: 1 km/h = 1000 ÷ 3600 = 0.278 m/s, so 1 km h⁻¹ s⁻¹ = 0.278 m/s² (exactly 5/18). Common mistake: converting only the "km" to "m" and forgetting that "per hour" also needs converting to "per second" for the velocity part of this compound rate.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b4cd8228-6d1f-5a1a-8034-eb19a0a29011', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 18, 18, 'A Formula 1 car brakes from 300 km/h to rest in 2.9 s, reportedly sustaining close to 4.0g. (a) Convert 300 km/h to m/s. (b) Calculate the actual average deceleration achieved, in m/s². (c) Express this in units of g. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.929', NULL, false, NULL, false, '(a) 300 ÷ 3.6 = 83.3 m/s. (b) deceleration = 83.3 ÷ 2.9 = 28.7 m/s². (c) In units of g: 28.7 ÷ 9.81 = 2.93g — noticeably less than the quoted 4.0g, showing the "4.0g" figure likely refers to a brief peak during the stop rather than the AVERAGE deceleration over the whole 2.9 s. Common mistake: quoting the raw m/s² value from (b) as if it were already "in g" — the units g and m/s² are related by a factor of 9.81, not interchangeable.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d6e45dfb-6a40-5edc-9877-ca7e4abc73f7', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 19, 19, 'During a Soyuz capsule re-entry, astronauts can briefly experience up to 8.0g. (a) Express 8.0g in m/s². (b) Calculate how long it would theoretically take, accelerating from rest at this constant rate, to reach the speed of sound (343 m/s) — though in reality this acceleration does not act anywhere near that long. Give only the answer to (b).', NULL, 4, 'numeric'::answer_type, '4.371', 's', false, NULL, false, '(a) acceleration = 8.0 × 9.81 = 78.5 m/s². (b) t = Δv ÷ a = (343−0) ÷ 78.5 = 4.37 s. Common mistake: treating this calculated time as something that actually happens during re-entry — real re-entry decelerations last only a few seconds at their peak value, so this is a purely hypothetical "what if it lasted this long" calculation, used only to build a feel for the size of the acceleration.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9ea7fbbd-8d2d-5a86-a783-1ffaf58f16b2', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'as', '2.3', '9702 2.3 Units of acceleration', 20, 20, 'An engineer specifies the acceleration in a microchip shock test as "2.5 million g" (an extremely brief, violent mechanical shock). (a) Convert this to m/s². (b) Express your answer to 3 significant figures in standard form.', NULL, 4, 'numeric'::answer_type, '2.453e7', 'm/s²', false, 0.05, false, '(a)/(b) acceleration = 2.5 × 10⁶ × 9.81 = 2.45 × 10⁷ m/s². This is roughly two and a half million times the acceleration due to gravity — realistic for the violent, sub-millisecond impulse of a drop-shock test, even though it could never be sustained for any meaningful length of time. Common mistake: losing track of the powers of ten when multiplying 2.5 × 10⁶ by 9.81, and reporting an answer several orders of magnitude too large or too small.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('973e1136-26e0-5caa-ac11-84b469a6152f', 'd82034d1-3bb8-48a9-88d8-9ee75df4fde4', 'acceleration', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c9c38a45-6eed-5e56-b70d-38a3955f70d1', 'd82034d1-3bb8-48a9-88d8-9ee75df4fde4', 'velocity', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('67404771-c71d-5fcb-9b2b-197dee92c952', 'd82034d1-3bb8-48a9-88d8-9ee75df4fde4', 'distance travelled', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6b377d4a-2448-56c4-8e88-abff4fa52c89', 'd82034d1-3bb8-48a9-88d8-9ee75df4fde4', 'displacement', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('eaa787bd-804c-525e-b207-fae18f5926ad', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 7, 7, ('A velocity-time graph has three straight sections: (0 s, 0 m/s) to (4 s, 8 m/s)' || chr(59) || ' then flat to (9 s, 8 m/s)' || chr(59) || ' then falling to (12 s, 2 m/s). Calculate the acceleration during the final section.'), 'diagram:kin-2.4-q7', 2, 'numeric'::answer_type, '-2', 'm/s²', false, NULL, false, 'During the final section: gradient = (2−8) ÷ (12−9) = −2.00 m/s². Common mistake: using the overall start and end points of the WHOLE graph instead of just the final section’s own two endpoints.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('412c4fb3-ea51-5612-adaf-74d2195c1ddd', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 8, 8, 'A velocity-time graph is a curve that becomes steeper and steeper as time increases. What does this indicate?', NULL, 2, 'multiple_choice'::answer_type, 'The acceleration is increasing', NULL, false, NULL, false, 'A continuously increasing gradient on a velocity-time graph means the acceleration itself is continuously increasing — the object’s velocity is changing faster and faster as time goes on (this is NON-uniform acceleration). Common mistake: describing this as "constant acceleration" simply because the curve looks smooth and regular.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8156b81f-1d47-5078-9fbd-23e7ffa2d92a', '412c4fb3-ea51-5612-adaf-74d2195c1ddd', 'The acceleration is increasing', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a4dbe066-e35f-5521-8bb2-d512f729bf66', '412c4fb3-ea51-5612-adaf-74d2195c1ddd', 'The acceleration is constant', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('466781ee-82ca-5132-818e-316b46c39def', '412c4fb3-ea51-5612-adaf-74d2195c1ddd', 'The velocity is constant', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3065bb42-f031-54bf-b57c-e6dd9b755028', '412c4fb3-ea51-5612-adaf-74d2195c1ddd', 'The object is decelerating', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('bb89dd79-3299-5d6b-9dee-f0df6869a466', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 9, 9, 'A velocity-time graph is a straight line from (0 s, 10 m/s) to (6.0 s, 40 m/s). Calculate the acceleration.', 'diagram:kin-2.4-q9', 2, 'numeric'::answer_type, '5', 'm/s²', false, NULL, false, 'acceleration = (40−10) ÷ (6.0−0) = 5.00 m/s². Common mistake: using the final velocity alone (40 m/s) divided by the time, instead of the CHANGE in velocity.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('eebcae37-702d-5cc4-ac87-f81f6ffec508', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 10, 10, 'A velocity-time graph is a straight line from (0 s, 30 m/s) to (5.0 s, 0 m/s). Calculate the acceleration.', 'diagram:kin-2.4-q10', 2, 'numeric'::answer_type, '-6', 'm/s²', false, NULL, false, 'acceleration = (0−30) ÷ (5.0−0) = −6.00 m/s². Common mistake: giving +6.0 m/s², dropping the negative sign that correctly shows this is a deceleration.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e558b811-58ea-5661-9760-13309e820439', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 11, 11, 'Can the acceleration of an object be deduced directly from the GRADIENT of a displacement-time graph?', NULL, 2, 'multiple_choice'::answer_type, ('No — the gradient of a displacement-time graph gives velocity' || chr(59) || ' a velocity-time graph’s gradient is needed for acceleration'), NULL, false, NULL, false, 'No, not directly — the gradient of a displacement-time graph gives VELOCITY, not acceleration. To find acceleration, you would need to see how that gradient itself CHANGES along the curve (or better, convert the data into a velocity-time graph first and find ITS gradient). Common mistake: trying to read acceleration straight off a displacement-time graph’s steepness, when steepness there only ever represents velocity.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1f553924-306b-5a28-8669-34a82bbe67cc', 'e558b811-58ea-5661-9760-13309e820439', ('No — the gradient of a displacement-time graph gives velocity' || chr(59) || ' a velocity-time graph’s gradient is needed for acceleration'), 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f7b60931-ad5d-5ebe-bd20-24c1e3a4a4b9', 'e558b811-58ea-5661-9760-13309e820439', 'Yes — the gradient of any graph of motion always gives acceleration', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('744108d6-7ccb-5abd-aee3-ed6efb088e4b', 'e558b811-58ea-5661-9760-13309e820439', 'Yes — but only if the displacement-time graph is a straight line', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('58922ad5-dc28-5152-a01b-b2ca19687d6b', 'e558b811-58ea-5661-9760-13309e820439', 'No — acceleration can never be found from any graph', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('873e7a23-bdfd-5fb8-9243-4923c2388e63', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 12, 12, 'A velocity-time graph curves smoothly (non-uniform acceleration). Close readings near t = 6.0 s give v = 16.82 m/s at t = 5.8 s and v = 19.22 m/s at t = 6.2 s. Estimate the instantaneous acceleration at t = 6.0 s.', 'diagram:kin-2.4-q12', 2, 'numeric'::answer_type, '6', 'm/s²', false, NULL, false, 'Using the gradient of the short line joining these two close points as an estimate of the tangent (instantaneous) gradient at t = 6.0 s: a ≈ (19.2 − 16.8) ÷ (6.2−5.8) = 2.40 ÷ 0.40 = 6.00 m/s². Common mistake: using readings that are too far apart in time, which would estimate an AVERAGE acceleration over a wider interval rather than the instantaneous value at exactly t = 6.0 s.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7c0cc998-754d-506d-abc7-3ebfb536445f', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 13, 13, ('A train’s velocity-time data is: t = 0 s, v = 0' || chr(59) || ' t = 1 s, v = 4 m/s' || chr(59) || ' t = 2 s, v = 9 m/s' || chr(59) || ' t = 3 s, v = 16 m/s' || chr(59) || ' t = 4 s, v = 25 m/s. Calculate the average acceleration between t = 1 s and t = 3 s.'), 'diagram:kin-2.4-q13', 2, 'numeric'::answer_type, '6', 'm/s²', false, NULL, false, 'average acceleration = (16−4) ÷ (3−1) = 6.00 m/s². (This data follows v = t², so the acceleration is NOT uniform — it increases steadily with time, which is why different pairs of points in this table give different average accelerations.) Common mistake: assuming any table of increasing velocities must represent uniform acceleration, without checking whether equal time intervals really do give equal changes in velocity.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1b348144-c8b6-5d56-8f0f-6fb70ac32388', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 14, 14, ('A velocity-time graph has three straight sections: (0 s, 0 m/s) to (5 s, 20 m/s)' || chr(59) || ' then flat to (15 s, 20 m/s)' || chr(59) || ' then falling to (20 s, 0 m/s). (a) Calculate the acceleration during the rising section. (b) Calculate the acceleration during the falling section. (c) Explain the physical significance of the zero acceleration during the middle section. Give only the answer to (a).'), 'diagram:kin-2.4-q14', 3, 'numeric'::answer_type, '4', 'm/s²', false, NULL, false, '(a) a = (20−0) ÷ (5−0) = 4.00 m/s². (b) a = (0−20) ÷ (20−15) = −4.00 m/s². (c) Zero acceleration during the middle section means the velocity is not changing at all — the object is moving at a steady, constant 20 m/s throughout that part of the journey. Common mistake: assuming the middle, flat section of a velocity-time graph must mean the object is at REST, confusing it with the equivalent feature on a displacement-time graph.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2a65209b-ffe3-51d7-9f4d-6c609187ebec', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 15, 15, 'A velocity-time graph curves smoothly, with the velocity increasing faster and faster. Close readings give the acceleration near t = 2.0 s as approximately 2.0 m/s² (from readings at t = 1.8 s and t = 2.2 s), and near t = 6.0 s as approximately 6.0 m/s² (from readings at t = 5.8 s and t = 6.2 s). (a) State what this comparison shows about whether the acceleration is uniform. (b) If this pattern is consistent with acceleration increasing steadily with time (a = kt), estimate k. Give only the numerical answer to (b).', NULL, 3, 'numeric'::answer_type, '1', 'm/s³', false, 0.15, false, ('(a) The acceleration near t = 2.0 s (2.00 m/s²) is clearly smaller than near t = 6.0 s (6.00 m/s²), so the acceleration is NOT uniform — it is increasing with time. (b) If a = kt, then k = a ÷ t: near t = 2.0 s, k ≈ 2.00 ÷ 2.0 = 1.00' || chr(59) || ' near t = 6.0 s, k ≈ 6.00 ÷ 6.0 = 1.00 — both close to the same value, consistent with k ≈ 1.00 m/s³. Common mistake: assuming a smoothly curving velocity-time graph must represent SOME simple constant acceleration, rather than recognising the curve itself is the signature of a continuously changing (non-uniform) acceleration.'), 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5b072b5b-f6fa-5817-a48d-c46db86f5478', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 16, 16, 'Readings from a curved velocity-time graph give v = 1.62 m/s at t = 1.8 s and v = 16.82 m/s at t = 5.8 s. Calculate the average acceleration between these two readings.', NULL, 3, 'numeric'::answer_type, '3.8', 'm/s²', false, NULL, false, 'average acceleration = (16.82 − 1.62) ÷ (5.8 − 1.8) = 15.2 ÷ 4.0 = 3.80 m/s². Common mistake: treating this AVERAGE over a 4.0 s interval as if it were the instantaneous acceleration at either one of the two individual times — on a curved graph the two can be quite different.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('75ff89dd-cb13-59f0-a26f-7461e93cc846', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 17, 17, 'A student claims that for a displacement-time graph, ''the gradient at t = 4.0 s directly gives the acceleration at that time.'' Explain why this is incorrect, and state what the gradient of a displacement-time graph actually represents. The SAME motion, re-plotted as a velocity-time graph, is a straight line from (0 s, 2.0 m/s) to (10 s, 22 m/s). Calculate the actual acceleration.', 'diagram:kin-2.4-q17', 3, 'numeric'::answer_type, '2', 'm/s²', false, NULL, false, 'The gradient of a displacement-time graph always gives VELOCITY, not acceleration — to find acceleration, you need the gradient of a velocity-time graph instead. Using the velocity-time version of this motion: acceleration = (22−2.0) ÷ (10−0) = 2.00 m/s². Common mistake: trying to estimate acceleration by looking at how "curved" a displacement-time graph appears, rather than converting to a velocity-time graph (or examining how the GRADIENT of the displacement-time graph itself changes) first.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4b1efc38-6b24-5af1-879f-ec2ae2685b09', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 18, 18, 'A velocity-time graph is a single straight line from (0 s, +12 m/s) to (8.0 s, −4.0 m/s) (an object slowing, stopping, then speeding up in reverse under one constant deceleration). (a) Calculate the acceleration. (b) Calculate the time at which the velocity is zero. (c) State the object’s direction of motion just after that time. Give only the answer to (a).', 'diagram:kin-2.4-q18', 3, 'numeric'::answer_type, '-2', 'm/s²', false, NULL, false, '(a) acceleration = (−4.0−12) ÷ (8.0−0) = −2.00 m/s² — constant throughout, since the graph is one single straight line. (b) Setting v = 0: 0 = 12 + (−2.00)t, so t = 12 ÷ 2.00 = 6.00 s. (c) Just after this, v becomes negative, so the object moves in the reverse direction. Common mistake: assuming the acceleration must change sign or value at the instant the object is momentarily at rest (t = 6.00 s) — since the graph is one unbroken straight line, the SAME constant acceleration acts the whole time, through that instant and beyond.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('36209a7b-de06-51b2-81f6-709764f3fb12', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 19, 19, 'A velocity-time graph has two straight segments meeting at t = 3.0 s: acceleration a₁ = 2.0 m/s² from rest for the first 3.0 s, then a₂ = 6.0 m/s² for a further 2.0 s. Show that the OVERALL average acceleration from t = 0 to t = 5.0 s is NOT simply the mean of a₁ and a₂, and calculate its actual value.', NULL, 4, 'numeric'::answer_type, '3.6', 'm/s²', false, NULL, false, 'Velocity at t = 3.0 s: v = 0 + 2.0×3.0 = 6.00 m/s. Velocity at t = 5.0 s: v = 6.00 + 6.0×2.0 = 18.0 m/s. Overall average acceleration = (18.0−0) ÷ 5.0 = 3.60 m/s². This is NOT equal to the simple mean of the two accelerations, (2.0+6.0)/2 = 4.00 m/s² — the two values only agree when the two segments last EQUAL amounts of time (here, 3.0 s and 2.0 s are different). Common mistake: averaging a₁ and a₂ directly whenever two different accelerations are involved, without checking whether the two phases actually last the same length of time.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8896b517-0e87-52dd-905d-1402de702782', 'ec015167-65fb-47df-b565-1055132ab4f3', '5e4207c2-e358-4374-b5ab-92bbcb2b87e7', 'as', '2.4', '9702 2.4 Deducing acceleration', 20, 20, 'A crash-test dummy’s velocity drops from 15 m/s to 0 in just 0.12 s during a collision — brief enough to be treated as a single straight line on a velocity-time graph. Calculate the deceleration experienced, and express your answer in m/s².', NULL, 4, 'numeric'::answer_type, '125', 'm/s²', false, 0.05, false, 'Since the collision is so brief, the velocity-time graph is effectively one straight line, so: acceleration = (0−15) ÷ 0.12 = −125 m/s² (equivalent to about 12.7g) — an enormous deceleration typical of a real collision, which is exactly why cars have crumple zones and airbags: extending the collision TIME even slightly dramatically reduces this value. Common mistake: mishandling the very small time interval (0.12 s) in the division, giving an answer that is far too small rather than appropriately huge.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4a27efed-eb13-5200-9fbe-0a9fb1bd4d7c', '613d3c8b-1f70-468f-a480-5123284e9f6a', 'displacement', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a16b4c7b-97f6-5e8b-89be-c0961e56dc40', '613d3c8b-1f70-468f-a480-5123284e9f6a', 'acceleration', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('413255cf-da52-5bef-9298-76a20a4fbe4c', '613d3c8b-1f70-468f-a480-5123284e9f6a', 'average velocity only', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('49793770-e203-58f0-9f76-9cc921883d79', '613d3c8b-1f70-468f-a480-5123284e9f6a', 'nothing physically meaningful', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('45992ef4-e25f-5e8c-a9ea-23cab4fdeb1c', 'b70c415e-2c72-4297-899b-e4b572a96f74', 'Split it into a triangle and a rectangle, and add their areas', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e82ecd8b-b5ef-522a-be9b-2e4af42b30c0', 'b70c415e-2c72-4297-899b-e4b572a96f74', 'Multiply the final velocity by the total time', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8922b65b-a036-58c1-a1e0-364a1dec475c', 'b70c415e-2c72-4297-899b-e4b572a96f74', 'Use only the gradient of the final section', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('103652d8-661f-5363-ab8a-aadc1c47ba6b', 'b70c415e-2c72-4297-899b-e4b572a96f74', 'Average the initial and final velocities and ignore the time altogether', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7ac2e775-1da1-50a2-855e-af00c0b668a0', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 7, 7, 'A velocity-time graph is a straight line rising uniformly from 5.0 m/s at t = 0 to 15 m/s at t = 4.0 s. Calculate the displacement during this time.', 'diagram:kin-2.5-q7', 2, 'numeric'::answer_type, '40', 'm', false, NULL, false, 'This trapezium’s area = ½(a+b)h, using the two parallel velocity sides and the time as the "height": ½ × (5.0+15) × 4.0 = ½ × 20 × 4.0 = 40.0 m. (Equivalently, average velocity × time = ((5.0+15)/2) × 4.0, the same result.) Common mistake: using only the final velocity (15 × 4.0 = 60 m) and ignoring that the object started with a nonzero velocity of 5.0 m/s rather than from rest.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('96dd5048-ffc2-57f4-a57d-4e74d5c372ab', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 8, 8, 'A velocity-time graph rises uniformly from rest, then stays constant. Which combination of shapes makes up the total area?', NULL, 2, 'multiple_choice'::answer_type, 'A triangle, then a rectangle, added together', NULL, false, NULL, false, 'The rising part is a triangle (velocity building up from zero), and the constant part is a rectangle (velocity unchanging) — the total displacement is the SUM of the triangle’s area and the rectangle’s area. Common mistake: treating the whole shape as one single rectangle using only the final, constant velocity, which overestimates the displacement during the rising part.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('05d1c9c7-57fc-57f7-9f71-31d0c73d79e1', '96dd5048-ffc2-57f4-a57d-4e74d5c372ab', 'A triangle, then a rectangle, added together', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3b62c41e-334b-574e-97bb-b7c8203c78cf', '96dd5048-ffc2-57f4-a57d-4e74d5c372ab', 'Two separate rectangles', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('16e40867-047d-5401-8960-59741dd30d17', '96dd5048-ffc2-57f4-a57d-4e74d5c372ab', 'One single triangle for the whole motion', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c8673bb5-2e7f-5aae-be67-2f3d10d83f4d', '96dd5048-ffc2-57f4-a57d-4e74d5c372ab', 'A rectangle minus a triangle', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('abba4c1e-7e09-5420-a4af-22a6a0832cc3', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 9, 9, 'A velocity-time graph rises uniformly from rest to 10 m/s over 2.0 s, then stays constant at 10 m/s for a further 6.0 s. Calculate the total displacement.', 'diagram:kin-2.5-q9', 2, 'numeric'::answer_type, '70', 'm', false, NULL, false, 'Triangle (rising part): ½ × 2.0 × 10 = 10.0 m. Rectangle (constant part): 10 × 6.0 = 60.0 m. Total displacement = 10.0 + 60.0 = 70.0 m. Common mistake: forgetting to include the small triangular area from the rising phase, and only counting the constant-velocity rectangle.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('aa2d07d2-d76f-5943-a7dd-5aef37ae914f', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 10, 10, 'A velocity-time graph is a straight line falling from 20 m/s at t = 0 to 5.0 m/s at t = 3.0 s (the object is decelerating but never stops). Calculate the displacement.', 'diagram:kin-2.5-q10', 2, 'numeric'::answer_type, '37.5', 'm', false, NULL, false, 'Trapezium area: ½(20+5) × 3.0 = ½ × 25 × 3.0 = 37.5 m. Common mistake: treating this as a triangle (which would require the velocity to reach zero), rather than correctly identifying it as a trapezium since the velocity stays positive throughout.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('746a48e7-3d98-5eec-b86c-27c9dd8a69b7', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 11, 11, 'A velocity-time graph dips below the time axis (the velocity becomes negative) for part of a journey. What does the area BELOW the axis represent?', NULL, 2, 'multiple_choice'::answer_type, 'Negative displacement, which subtracts from the positive area elsewhere on the graph', NULL, false, NULL, false, 'It still represents displacement, but NEGATIVE displacement (in the opposite direction to the positive direction chosen) — this area should be subtracted from any positive area elsewhere on the graph to get the correct NET displacement for the whole journey. Common mistake: treating all area under a velocity-time graph as automatically positive, regardless of which side of the time axis it falls on.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d7e05a74-f350-57de-94ee-4abf531c5964', '746a48e7-3d98-5eec-b86c-27c9dd8a69b7', 'Negative displacement, which subtracts from the positive area elsewhere on the graph', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('03ccda10-f9f1-5a0f-bf65-3fa8bd6fbc76', '746a48e7-3d98-5eec-b86c-27c9dd8a69b7', 'The area below the axis is simply ignored', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6f60cd33-98fd-5243-80e9-38f539c7eb3f', '746a48e7-3d98-5eec-b86c-27c9dd8a69b7', 'It represents the object travelling at double speed', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c9bbdf34-76c1-5899-a602-6d0e4d5825a7', '746a48e7-3d98-5eec-b86c-27c9dd8a69b7', 'It represents an error in the graph, since area cannot be negative', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b428ac4a-c5f8-5dc7-a720-bf8e767cd0d1', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 12, 12, 'Taking the object’s intended forward direction as positive, a velocity-time graph shows a constant velocity of −4.0 m/s for 5.0 s. Calculate the displacement.', 'diagram:kin-2.5-q12', 2, 'numeric'::answer_type, '-20', 'm', false, NULL, false, 'displacement = velocity × time = (−4.0) × 5.0 = −20.0 m — the area lies entirely below the time axis, representing a negative (backward) displacement. Common mistake: reporting the magnitude of the area only (20 m) without the negative sign that shows the direction of travel.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1288e97f-622f-5d24-800d-0654250f3321', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 13, 13, 'A velocity-time graph is a straight line falling from +10 m/s at t = 0 to −5.0 m/s at t = 6.0 s. Calculate the NET displacement over the whole 6.0 s.', 'diagram:kin-2.5-q13', 2, 'numeric'::answer_type, '15', 'm', false, NULL, false, 'The line crosses zero at t = 4.00 s. Positive area (0 to 4.00 s): ½ × 4.00 × 10 = 20.0 m. Negative area (4.00 s to 6.0 s): ½ × 2.00 × 5.0 = 5.00 m, counted as negative. Net displacement = 20.0 − 5.00 = 15.0 m. Common mistake: adding the two triangle areas together as if both were positive, instead of subtracting the area that lies below the time axis.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('92b8af4d-c70d-5548-b871-02091ba7e2e9', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 14, 14, ('A velocity-time graph has three straight sections: (0 s, 0 m/s) to (5 s, 20 m/s)' || chr(59) || ' then flat to (15 s, 20 m/s)' || chr(59) || ' then falling to (20 s, 0 m/s). (a) Calculate the area (displacement) of the first (triangular) section. (b) Calculate the area of the middle (rectangular) section. (c) Calculate the TOTAL displacement for the whole 20 s. Give only the answer to (c).'), 'diagram:kin-2.5-q14', 3, 'numeric'::answer_type, '300', 'm', false, NULL, false, '(a) Triangle: ½ × 5 × 20 = 50.0 m. (b) Rectangle: 20 × 10 = 200 m. The final section is also a triangle: ½ × 5 × 20 = 50.0 m. (c) Total = 50.0 + 200 + 50.0 = 300 m. Common mistake: forgetting the final falling section also has a nonzero area, and leaving it out of the total.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('db274ad3-17ed-558c-9966-06cc4ae439e4', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 15, 15, 'A velocity-time graph is a straight line falling from +8.0 m/s at t = 0 to −4.0 m/s at t = 6.0 s (the object reverses direction partway through). (a) Calculate the net displacement for the whole 6.0 s. (b) Calculate the total distance travelled. Give only the answer to (a).', 'diagram:kin-2.5-q15', 3, 'numeric'::answer_type, '12', 'm', false, NULL, false, 'The line crosses zero at t = 4.00 s. Positive area: ½ × 4.00 × 8.0 = 16.0 m. Negative area: ½ × 2.00 × 4.0 = 4.00 m. (a) Net displacement = 16.0 − 4.00 = 12.0 m. (b) Total distance = 16.0 + 4.00 = 20.0 m — larger than the net displacement, because distance ADDS both areas regardless of sign. Common mistake: giving the same numerical answer for both (a) and (b) — they only agree when the object never reverses direction.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8c6f8c3c-dc68-585f-bef9-36cb6609a583', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 16, 16, 'Velocity readings are taken every 2.0 s: t = 0, 2, 4, 6, 8, 10 s give v = 0, 4, 7, 9, 10, 10 m/s. Using the trapezium rule (treating each 2.0 s interval as a trapezium), estimate the total displacement over the 10 s.', 'diagram:kin-2.5-q16', 3, 'numeric'::answer_type, '70', 'm', false, NULL, false, 'Each interval’s area = ½ × (vᵢ+vᵢ₊₁) × 2.0: 4.00, 11.0, 16.0, 19.0, 20.0 m. Summing all five intervals: 4.00 + 11.0 + 16.0 + 19.0 + 20.0 = 70.0 m. Common mistake: using only the velocity values directly (e.g. adding 0+4+7+9+10+10) instead of correctly pairing adjacent readings into trapeziums first.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1e76938e-8fad-586d-8f91-928ce1cd441c', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 17, 17, 'A velocity-time graph is a straight line falling from +15 m/s at t = 0 to −9.0 m/s at t = 12 s. (a) Calculate the net displacement for the whole 12 s. (b) Calculate the total distance travelled. Give only the answer to (a).', 'diagram:kin-2.5-q17', 3, 'numeric'::answer_type, '36', 'm', false, NULL, false, 'The line crosses zero at t = 7.50 s. Positive area: ½ × 7.50 × 15 = 56.2 m. Negative area: ½ × 4.50 × 9.0 = 20.2 m. (a) Net displacement = 56.2 − 20.2 = 36.0 m. (b) Total distance = 56.2 + 20.2 = 76.5 m. Common mistake: finding the zero-crossing time incorrectly by not setting up the straight-line equation v(t) properly, leading to the wrong split between the two triangular areas.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('76c268c1-17cd-517c-ac40-6d06b7f943e2', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 18, 18, 'A velocity of 10.0 ± 0.2 m/s is held constant for a time of 5.0 ± 0.1 s. (a) Calculate the displacement. (b) Calculate the percentage uncertainty in this displacement, given that percentage uncertainties ADD for a quantity found by multiplying two measurements. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '4', '%', false, NULL, false, '(a) displacement = 10.0 × 5.0 = 50.0 m. (b) Percentage uncertainty in v = 0.2 ÷ 10.0 × 100% = 2.00%. Percentage uncertainty in t = 0.1 ÷ 5.0 × 100% = 2.00%. Since displacement = v × t (a multiplication), these percentage uncertainties add: 2.00% + 2.00% = 4.00%. Common mistake: adding the ABSOLUTE uncertainties (0.2 and 0.1, in different units) rather than first converting each to a PERCENTAGE uncertainty before adding them.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4715a5f6-9c80-59b7-b22c-7c67d6aef78b', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 19, 19, 'Derive, by treating the trapezium area under a straight velocity-time line as ½(u+v)t, the familiar equation for displacement under constant acceleration: s = ((u+v)/2)t. Then evaluate it for u = 5.0 m/s, v = 25 m/s, t = 8.0 s.', NULL, 4, 'numeric'::answer_type, '120', 'm', false, NULL, false, 'A straight line on a velocity-time graph from u (at t=0) to v (at time t) traces a trapezium, with the two parallel sides of length u and v, and "height" t (along the time axis). Its area is ½(sum of parallel sides) × height = ½(u+v) × t — this IS the displacement, since area under a velocity-time graph always equals displacement. Rewriting slightly: s = ((u+v)/2) × t, i.e. displacement equals the AVERAGE velocity multiplied by time, exactly as expected for uniform acceleration. For u = 5.0, v = 25, t = 8.0: s = ((5.0+25)/2) × 8.0 = 120 m. Common mistake: thinking this "area" formula and the SUVAT equation s=((u+v)/2)t are two unrelated facts to memorise separately, rather than recognising the SUVAT equation is really just the trapezium area formula in disguise.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('49680e0e-da67-5660-86ba-6f877cb19546', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c47dfb2d-b9eb-482e-b89f-aecbc8e799cc', 'as', '2.5', '9702 2.5 Deducing displacement', 20, 20, 'A roller coaster’s velocity during a violent launch is sampled every 0.50 s: t = 0, 0.5, 1.0, 1.5, 2.0 s give v = 0, 8, 14, 18, 20 m/s. Using the trapezium rule, estimate the distance covered during the 2.0 s launch.', NULL, 4, 'numeric'::answer_type, '25', 'm', false, NULL, false, 'Each 0.50 s interval’s area: 2.00, 5.50, 8.00, 9.50 m. Total = 2.00 + 5.50 + 8.00 + 9.50 = 25.0 m. Common mistake: assuming the velocity increases uniformly between readings and using a single big triangle (½ × 2.0 × 20 = 20 m) instead of the more accurate trapezium-by-trapezium estimate, which correctly captures the DECREASING rate of increase visible in the actual readings (the gaps between successive velocities shrink: 8, 6, 4, 2).', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('55be4444-7687-59c9-b765-905df4b45c1d', '9b03c1f2-ad4a-49ac-a977-95021394b7db', 'card length ÷ blocking time', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9f6ef6d1-697e-5a3c-955c-0074f6eeab39', '9b03c1f2-ad4a-49ac-a977-95021394b7db', 'blocking time ÷ card length', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('263ca3e0-efaa-50b3-974f-a47836244a51', '9b03c1f2-ad4a-49ac-a977-95021394b7db', 'card length × blocking time', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('835622e2-7bd7-5b59-92ca-0ff6396783cd', '9b03c1f2-ad4a-49ac-a977-95021394b7db', 'card length only, ignoring the time', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('97846b4f-3498-5a47-88a9-bd3c84cb10f5', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 7, 7, 'A card of length 3.0 cm takes 0.024 s to pass through a light gate. Calculate its speed.', NULL, 2, 'numeric'::answer_type, '1.25', 'm/s', false, 0.05, false, 'speed = 0.030 ÷ 0.024 = 1.25 m/s. Common mistake: rounding the time too early, which can shift the final answer noticeably when the time is already small.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('32200312-2702-5c54-a600-e0d07702df26', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 8, 8, 'A light gate calculates speed from (card length) ÷ (blocking time). Is this the card’s speed at a single instant, or an average?', NULL, 2, 'multiple_choice'::answer_type, 'It is an average speed over the (short) transit time, approximating the instantaneous speed', NULL, false, NULL, false, 'It is an AVERAGE speed over the (very short) time the card takes to cross the beam — the calculation assumes the card’s speed barely changes during that brief transit, so this average is normally an excellent approximation to the instantaneous speed at that point. Common mistake: treating a light gate’s reading as a perfectly exact instantaneous value, rather than recognising it is still, strictly, an average over a short interval.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('00741e68-32fa-579c-95ee-a0cb5fbe7bc1', '32200312-2702-5c54-a600-e0d07702df26', 'It is an average speed over the (short) transit time, approximating the instantaneous speed', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('da258697-808f-50ae-8c8e-3a19d73adadc', '32200312-2702-5c54-a600-e0d07702df26', 'It is always exactly the instantaneous speed, with no approximation involved', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f95fddd8-51d2-50f6-941e-a0b48045249b', '32200312-2702-5c54-a600-e0d07702df26', 'It is the card’s maximum possible speed', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('60344069-b655-510f-a2b6-c7eed16d5dab', '32200312-2702-5c54-a600-e0d07702df26', 'It is unrelated to the card’s actual speed', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('98b7a1f3-b758-589f-9a88-eb98e40d6d24', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 9, 9, 'A trolley passes through two light gates 0.50 m apart, taking 0.25 s to travel between them. Calculate its average velocity between the gates.', 'diagram:kin-2.6-q9', 2, 'numeric'::answer_type, '2', 'm/s', false, NULL, false, 'velocity = distance ÷ time = 0.50 ÷ 0.25 = 2.00 m/s. Common mistake: using one gate’s own transit time (from its card length) instead of the time taken to travel the much larger distance BETWEEN the two gates.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3c590f7a-3ad6-549c-bf71-190e698174cc', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 10, 10, 'A ticker-tape timer is powered from a 50 Hz UK mains supply. What is the time interval between consecutive dots?', NULL, 2, 'multiple_choice'::answer_type, '0.020 s', NULL, false, NULL, false, 'time = 1 ÷ frequency = 1 ÷ 50 = 0.020 s between each dot. Common mistake: confusing the FREQUENCY (50 Hz, dots per second) with the TIME INTERVAL (0.020 s, seconds per dot) — they are reciprocals of each other, not the same number.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a27258ed-7676-52ec-8402-4b99329eed17', '3c590f7a-3ad6-549c-bf71-190e698174cc', '0.020 s', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8f4ebd87-0a84-54bf-b431-93fe2d803ed1', '3c590f7a-3ad6-549c-bf71-190e698174cc', '50 s', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('69bffe3a-9238-5dce-bc10-d35e46807576', '3c590f7a-3ad6-549c-bf71-190e698174cc', '0.50 s', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('93c08886-00a7-5586-95fa-2e8a44726c2b', '3c590f7a-3ad6-549c-bf71-190e698174cc', '5.0 s', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('cf3ea906-0afa-521f-8738-8a8f9af0bba2', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 11, 11, 'On a ticker tape (50 Hz timer), the distance from the 1st dot to the 6th dot (spanning 5 equal intervals) is 12.0 cm. Calculate the average velocity over this span.', NULL, 2, 'numeric'::answer_type, '1.2', 'm/s', false, NULL, false, 'Time for 5 intervals = 5 × 0.020 = 0.100 s. velocity = 0.120 ÷ 0.100 = 1.20 m/s. Common mistake: counting the number of DOTS (6) rather than the number of INTERVALS between them (5) — the 6th dot marks the end of the 5th interval, not a 6th one.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e820bc25-c28f-5f9d-a0e9-d6ca2be5618e', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 12, 12, 'A motion sensor records an object’s position 20 times every second. Calculate the time between consecutive readings.', NULL, 2, 'numeric'::answer_type, '0.05', 's', false, NULL, false, 'time = 1 ÷ 20 = 0.0500 s between readings. Common mistake: giving 20 s as the answer, confusing the sampling RATE (20 readings per second) with the time BETWEEN readings.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0f5a8806-9d4c-5290-8a89-c9623788a29c', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 13, 13, 'A motion sensor records position every 0.040 s. Two consecutive readings are 0.600 m apart. Calculate the velocity.', 'diagram:kin-2.6-q13', 2, 'numeric'::answer_type, '15', 'm/s', false, NULL, false, 'velocity = distance ÷ time = 0.600 ÷ 0.040 = 15.0 m/s. Common mistake: using the sampling RATE (1/0.040 = 25 readings per second) somewhere in the calculation instead of the actual time INTERVAL (0.040 s).', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f02a8ed5-7dae-5c87-b40d-deb5e4551235', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 14, 14, 'A card of length 4.0 cm passes through a single light gate twice during an experiment on a ramp: first giving a transit time of 0.080 s, then (after accelerating further down the ramp) a transit time of 0.032 s, exactly 0.60 s later. (a) Calculate the velocity at the first pass. (b) Calculate the velocity at the second pass. (c) Calculate the average acceleration between the two passes. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.25', 'm/s²', false, 0.05, false, '(a) v₁ = 0.040 ÷ 0.080 = 0.500 m/s. (b) v₂ = 0.040 ÷ 0.032 = 1.25 m/s. (c) acceleration = (1.25 − 0.500) ÷ 0.60 = 1.25 m/s². Common mistake: using the card’s transit times (0.080 s, 0.032 s) as the time interval in the acceleration formula, instead of the 0.60 s that actually separates the two PASSES through the gate.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8fed0f97-8265-5d0d-aecc-a80bf295d1f2', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 15, 15, 'A ticker tape (dot interval 0.020 s) shows four consecutive dot-to-dot spacings of 1.0 cm, 1.4 cm, 1.8 cm, 2.2 cm. (a) Calculate the velocity represented by the first interval. (b) Calculate the velocity represented by the last interval. (c) Calculate the average acceleration across the tape, using the time between the MIDPOINTS of the first and last intervals (3 intervals apart). Give only the answer to (c).', 'diagram:kin-2.6-q15', 3, 'numeric'::answer_type, '10', 'm/s²', false, NULL, false, '(a) v₁ = 0.010 ÷ 0.020 = 0.500 m/s. (b) v₄ = 0.022 ÷ 0.020 = 1.10 m/s. (c) The time between the MIDPOINTS of interval 1 and interval 4 spans 3 full intervals: 3 × 0.020 = 0.060 s. acceleration = (1.10 − 0.500) ÷ 0.060 = 10.0 m/s². Common mistake: using the time span of all 4 intervals (0.080 s) instead of the 3 intervals that actually separate the MIDPOINTS of the first and last intervals (where each interval’s velocity is best taken to apply).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b15e8255-2b48-57c2-bb28-15130bb9e8b6', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 16, 16, 'State one advantage and one disadvantage of using a light gate (compared with a ticker-tape timer) for measuring the velocity of a fast-moving trolley. Then calculate the velocity from a light gate reading: card length 1.5 cm, blocking time 0.0050 s.', NULL, 3, 'numeric'::answer_type, '3', 'm/s', false, NULL, false, 'Advantage of a light gate: it can accurately time very brief, fast events (a ticker tape is limited to the fixed 0.020 s interval of its timer and can struggle at high speed, since dots start to overlap or smear). Disadvantage: a light gate typically only gives a velocity at ONE point (where the gate is), whereas a ticker tape gives a continuous record of the ENTIRE motion on one tape. Calculation: velocity = 0.015 ÷ 0.0050 = 3.00 m/s. Common mistake: assuming one method is simply "better" in every situation, rather than recognising each has situations where it is more appropriate.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('89512a21-6390-5ed3-97ed-b402e2e6f7f9', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 17, 17, 'A datalogger records position readings every short interval: x = 0.200 m at t = 0.90 s, and x = 0.260 m at t = 1.10 s. Estimate the instantaneous velocity at t = 1.0 s using these two readings.', 'diagram:kin-2.6-q17', 3, 'numeric'::answer_type, '0.3', 'm/s', false, NULL, false, 'velocity ≈ (0.260−0.200) ÷ (1.10−0.90) = 0.060 ÷ 0.20 = 0.300 m/s — using two readings symmetrically placed around t = 1.0 s gives a good estimate of the gradient (and hence velocity) at that exact instant. Common mistake: using only ONE of the two readings together with t = 1.0 s (rather than the pair straddling it), which estimates an average velocity over a less well-centred interval.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('358f54b5-dba3-59d0-8bd8-0abe748be651', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 18, 18, 'A student wants to measure the acceleration of a falling object over a very short drop of only 0.30 m. (a) Explain why light gates connected to a data logger would be far more suitable than a hand-operated stopwatch for this measurement. (b) The fall is timed (by light gates) at 0.247 s from rest. Use s = ½at² to estimate the acceleration. Give only the answer to (b).', 'diagram:kin-2.6-q18', 3, 'numeric'::answer_type, '9.835', 'm/s²', false, NULL, false, '(a) The whole fall lasts well under half a second — far shorter than a typical human reaction time (around 0.2–0.3 s) — so a hand-started and hand-stopped stopwatch reading would be swamped by reaction-time error. A light gate, triggered automatically and electronically, removes human reaction time from the timing entirely. (b) From rest: 0.30 = ½ × a × 0.247², so a = (2 × 0.30) ÷ 0.247² = 9.83 m/s² (close to g, as expected for a falling object with only small air resistance). Common mistake: using a stopwatch-based time for an event this brief and treating the result as reliable, when reaction time alone could be comparable to the entire fall time.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('da05dd5a-58af-5fac-b832-b72ea0f5225e', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 19, 19, 'A ticker-tape timer running from stable 50 Hz mains has a negligible timing uncertainty, whereas a student using a stopwatch has a reaction-time uncertainty of about ±0.2 s on each press. For timing a short event lasting about 0.40 s, calculate the percentage uncertainty introduced by the stopwatch’s reaction time alone, and explain why a ticker tape or light gate would be enormously more precise for an event this brief.', NULL, 4, 'numeric'::answer_type, '50', '%', false, NULL, false, 'Percentage uncertainty = 0.2 ÷ 0.40 × 100% = 50.0% — an enormous uncertainty, essentially making a stopwatch reading of such a brief event almost meaningless on its own. A ticker tape or light gate times the event electronically (or marks it on a continuously-running tape), completely avoiding human reaction time, so its uncertainty is dramatically smaller for events on this timescale. Common mistake: assuming a stopwatch is "good enough" for any school experiment, without checking whether the TIMESCALE of the event being measured is comparable to typical human reaction times.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('017065c2-dab1-52bd-859d-aa9908900b8d', 'ec015167-65fb-47df-b565-1055132ab4f3', '97c777dc-0adf-4df6-bd8f-9c659f0ef783', 'as', '2.6', '9702 2.6 Measuring velocity and acceleration', 20, 20, 'A high-speed camera records 1000 frames per second (fps) to study a sprinter''s start. (a) Calculate the time between consecutive frames. (b) The sprinter''s hip moves 0.012 m between two consecutive frames. Calculate the corresponding velocity. Give only the answer to (b).', NULL, 4, 'numeric'::answer_type, '12', 'm/s', false, NULL, false, '(a) time between frames = 1 ÷ 1000 = 0.00100 s. (b) velocity = 0.012 ÷ 0.00100 = 12.0 m/s. Common mistake: using 1000 (the frame RATE) directly as a time in the velocity calculation, instead of its reciprocal.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('49784d75-2a28-5e46-8770-562444be6e98', '866c62d4-fc3e-4220-b00b-3ab498bd46a8', 'The precision of the ruler used to measure the card’s length', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('be6b8079-b2b7-5d6d-a63e-d319100f5b09', '866c62d4-fc3e-4220-b00b-3ab498bd46a8', 'The speed of light', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('10230d54-0396-5e82-b5d6-45d7bf4d7dce', '866c62d4-fc3e-4220-b00b-3ab498bd46a8', 'The frequency of the light gate’s own electronics', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('69323885-73fe-5d1e-9a1a-b88a37bedc69', '866c62d4-fc3e-4220-b00b-3ab498bd46a8', 'The card’s mass', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3bd24993-d6b7-5169-b85b-3418007cd192', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 7, 7, 'Five repeat timings of a trolley’s fall give: 0.42 s, 0.44 s, 0.41 s, 0.45 s, 0.43 s. Calculate the mean time.', 'diagram:kin-2.7-q7', 2, 'numeric'::answer_type, '0.43', 's', false, NULL, false, 'mean = (0.42+0.44+0.41+0.45+0.43) ÷ 5 = 2.15 ÷ 5 = 0.430 s. Common mistake: using only one of the five readings rather than averaging all of them, which throws away the benefit of repeating the measurement.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('bb8f5b38-37d1-5605-b953-9950abfa2183', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 8, 8, 'Using the same five timings (0.42, 0.44, 0.41, 0.45, 0.43 s), estimate the uncertainty in the mean time using half the range of the readings.', NULL, 2, 'numeric'::answer_type, '0.02', 's', false, NULL, false, 'half-range = (maximum − minimum) ÷ 2 = (0.45−0.41) ÷ 2 = 0.0200 s. Common mistake: using the full range (0.04 s) as the uncertainty, rather than HALF the range — the mean lies roughly in the middle of the spread, so it is only this far from either extreme.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('24a7f512-3e64-5800-b0d5-28038e525a67', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 9, 9, 'Why is a measurement normally repeated several times and a mean taken, rather than relying on a single reading?', NULL, 2, 'multiple_choice'::answer_type, 'It reduces the effect of random variation between readings, giving a more reliable mean', NULL, false, NULL, false, 'Repeating a measurement and averaging reduces the effect of RANDOM variations (such as slightly different reaction times, or small inconsistencies in how an experiment is set up each time) — the mean of several readings is normally a better estimate of the true value than any single one. Common mistake: believing that repeating a measurement removes a SYSTEMATIC error (one that affects every reading in the same way, such as a wrongly-zeroed instrument) — repeating readings cannot fix that kind of error.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('613a48c7-828e-5c63-8dc6-54f885de8980', '24a7f512-3e64-5800-b0d5-28038e525a67', 'It reduces the effect of random variation between readings, giving a more reliable mean', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('38618ceb-24c4-5e35-8b48-23391e7e74ca', '24a7f512-3e64-5800-b0d5-28038e525a67', 'It has no real benefit over a single reading', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2ec9cf2a-a19f-5fe6-8352-78d3f214c598', '24a7f512-3e64-5800-b0d5-28038e525a67', 'It removes any systematic error in the apparatus', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c5cfc717-a64c-506c-8441-f2622e3b5a12', '24a7f512-3e64-5800-b0d5-28038e525a67', 'It always doubles the precision of the final answer', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('bb38dfe1-fc25-5c69-af3e-e2da73956477', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 10, 10, 'Using the mean time (from the five readings 0.42, 0.44, 0.41, 0.45, 0.43 s) and the half-range uncertainty, calculate the percentage uncertainty in the mean time.', NULL, 2, 'numeric'::answer_type, '4.651', '%', false, NULL, false, 'percentage uncertainty = (0.0200 ÷ 0.430) × 100% = 4.65%. Common mistake: using one of the individual readings, rather than the calculated MEAN, as the denominator in this percentage calculation.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8e0ab3e3-8162-5b71-b387-dcee02f508cc', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 11, 11, 'A light gate is accidentally positioned 2 mm away from where the experimenter intended, affecting every single reading taken during the experiment in the same way. Is this a random or a systematic error?', NULL, 2, 'multiple_choice'::answer_type, 'Systematic — it affects every reading in the same way and is not reduced by repeating and averaging', NULL, false, NULL, false, 'This is a SYSTEMATIC error: it shifts every single result by the same fixed amount, in the same direction, so repeating the measurement and averaging will NOT reveal or reduce it. A random error, by contrast, varies unpredictably from reading to reading and CAN be reduced by repeating and averaging. Common mistake: assuming that taking more repeat readings will fix this kind of consistent positioning error — it will not, since every reading is affected identically.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('863ab568-71d3-5acc-b5ea-8631562f03eb', '8e0ab3e3-8162-5b71-b387-dcee02f508cc', 'Systematic — it affects every reading in the same way and is not reduced by repeating and averaging', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1d26f634-3ae1-5d47-a126-31dc8a07d5ef', '8e0ab3e3-8162-5b71-b387-dcee02f508cc', 'Random — because the gate was moved by a person', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8152aa8b-32b5-5bc6-bd38-dd3d2a9c7398', '8e0ab3e3-8162-5b71-b387-dcee02f508cc', 'Neither — positioning errors do not count as experimental errors', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4a371ec4-f950-5174-bb32-1a661bfae976', '8e0ab3e3-8162-5b71-b387-dcee02f508cc', 'Random, because 2 mm is a small distance', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('710cb889-f0d1-5caf-b163-fad0c4702982', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 12, 12, 'The distance between two light gates is measured as 60.0 ± 0.5 cm. Calculate the percentage uncertainty in this distance.', NULL, 2, 'numeric'::answer_type, '0.8333', '%', false, NULL, false, 'percentage uncertainty = (0.5 ÷ 60.0) × 100% = 0.833%. Common mistake: using the absolute uncertainty (0.5 cm) as if it were already a percentage.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e0411ef4-1665-52fb-b5c0-f4054d72ebba', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 13, 13, 'The time for a trolley to travel between two light gates is measured as 0.300 ± 0.010 s. Calculate the percentage uncertainty in this time.', NULL, 2, 'numeric'::answer_type, '3.333', '%', false, NULL, false, 'percentage uncertainty = (0.010 ÷ 0.300) × 100% = 3.33%. Common mistake: rounding 0.010/0.300 too aggressively and losing a significant figure the question needs kept.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a8a56a92-0816-5920-9b1d-933a3b2a679f', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 14, 14, 'A trolley’s velocity between two light gates is found from a distance of 60.0 ± 0.5 cm and a time of 0.300 ± 0.010 s. (a) Calculate the velocity. (b) Calculate the percentage uncertainty in the distance. (c) Calculate the percentage uncertainty in the time. (d) Calculate the percentage uncertainty in the velocity. Give only the answer to (d).', 'diagram:kin-2.7-q14', 3, 'numeric'::answer_type, '4.167', '%', false, NULL, false, '(a) velocity = 0.600 ÷ 0.300 = 2.00 m/s. (b) percentage uncertainty in distance = (0.5÷60.0)×100% = 0.833%. (c) percentage uncertainty in time = (0.010÷0.300)×100% = 3.33%. (d) Since velocity = distance ÷ time, the percentage uncertainties add: 0.833% + 3.33% = 4.17%. Common mistake: averaging the two percentage uncertainties from (b) and (c) instead of adding them.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d24aa7df-7053-52a5-bfa5-aef26e7dcbad', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 15, 15, 'Using the velocity of 2.00 m/s found in the previous question, and its overall percentage uncertainty of 4.17%, calculate the absolute uncertainty in the velocity.', NULL, 3, 'numeric'::answer_type, '0.0834', 'm/s', false, 0.1, false, 'absolute uncertainty = percentage uncertainty × value = 0.0417 × 2.00 = 0.0834 m/s, so the velocity should be quoted as 2.00 ± 0.0834 m/s. Common mistake: quoting the percentage (4.17%) itself as though it were already the absolute uncertainty, in m/s.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e7716a6c-2adf-50b7-9b73-a6538013b46c', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 16, 16, 'A trolley’s velocity is 0.80 ± 0.03 m/s at one light gate and 1.60 ± 0.04 m/s at a second, 0.50 ± 0.01 s later. (a) Calculate the acceleration. (b) Calculate the absolute uncertainty in Δv. (c) Calculate the percentage uncertainty in the acceleration. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '10.75', '%', false, 0.05, false, '(a) acceleration = (1.60−0.80) ÷ 0.50 = 1.60 m/s². (b) Since Δv is found by SUBTRACTING two measurements, their ABSOLUTE uncertainties add: 0.03 + 0.04 = 0.0700 m/s, out of Δv = 0.800 m/s, giving 8.75% uncertainty in Δv. (c) Percentage uncertainty in time = (0.01÷0.50)×100% = 2.00%. Since acceleration = Δv ÷ t (a division), the percentage uncertainties add: 8.75% + 2.00% = 10.8%. Common mistake: adding the PERCENTAGE uncertainties of the two velocities (for Δv) instead of their ABSOLUTE uncertainties — subtraction combines absolute uncertainties, not percentage ones.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ac39345d-9726-51ef-b8be-2c69cc75ad57', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 17, 17, 'A free-fall experiment gives h = 1.200 ± 0.002 m and t = 0.495 ± 0.008 s, used to find g from g = 2h/t². (a) Calculate the percentage uncertainty in h. (b) Calculate the percentage uncertainty in t. (c) Since t is SQUARED, its percentage uncertainty doubles when used in g’s formula. Calculate the overall percentage uncertainty in g. Give only the answer to (c).', 'diagram:kin-2.7-q17', 3, 'numeric'::answer_type, '3.399', '%', false, NULL, false, '(a) % uncertainty in h = (0.002÷1.200)×100% = 0.167%. (b) % uncertainty in t = (0.008÷0.495)×100% = 1.62%. (c) Since g ∝ 1/t², the percentage uncertainty from t DOUBLES: 2 × 1.62% = 3.23%. Total % uncertainty in g = 0.167% + 3.23% = 3.40%. Common mistake: forgetting to double the percentage uncertainty in t to account for it being SQUARED in the formula for g — a very common and important rule for combining uncertainties with powers.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('fdff246f-4954-5e1e-9171-c026ad784c9e', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 18, 18, 'Using g = 2h/t² with h = 1.200 m and t = 0.495 s (and the overall percentage uncertainty in g found previously, 3.40%), calculate (a) the value of g from this experiment, and (b) the absolute uncertainty in g. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.333', 'm/s²', false, 0.1, false, '(a) g = 2 × 1.200 ÷ 0.495² = 9.79 m/s². (b) absolute uncertainty = percentage uncertainty × value = 0.0340 × 9.79 = 0.333 m/s², so g = 9.79 ± 0.333 m/s². Common mistake: using the standard value of g (9.81 m/s²) instead of this experiment’s own calculated value when finding the absolute uncertainty.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('24527ba7-f57c-5673-86d3-9fb68a02792b', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 19, 19, ('A student investigates how a trolley’s acceleration a down a ramp depends on the ramp’s height h, expecting a ∝ h (approximately, for small angles). Two results: h = 0.050 m gives a = 0.48 m/s²' || chr(59) || ' h = 0.100 m gives a = 0.97 m/s². (a) Calculate a/h for each result. (b) Comment on whether the data supports a ∝ h. (c) Using the average of the two a/h values, predict a for h = 0.150 m. Give only the answer to (c).'), 'diagram:kin-2.7-q19', 4, 'numeric'::answer_type, '1.447', 'm/s²', false, 0.05, false, '(a) First: a/h = 0.48 ÷ 0.050 = 9.60. Second: a/h = 0.97 ÷ 0.100 = 9.70. (b) The two a/h values are very close (9.60 and 9.70), supporting a ∝ h over this range — if a were NOT proportional to h, a/h would differ noticeably between the two results rather than staying roughly constant. (c) Average a/h = (9.60+9.70)/2 = 9.65. Predicted a = 9.65 × 0.150 = 1.45 m/s². Common mistake: testing proportionality by comparing a values directly rather than checking whether a/h (or, equivalently, a plotted against h) stays constant.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('051c98f3-c092-5db4-a01b-7d503aec85de', 'ec015167-65fb-47df-b565-1055132ab4f3', 'c16862d4-9430-4015-95fa-20d7cf89a45d', 'as', '2.7', '9702 2.7 Determining velocity and acceleration in the laboratory', 20, 20, 'In a pendulum experiment to find g from T = 2π√(L/g), a student measures the time for 20 oscillations as 40.0 ± 0.4 s, for a pendulum of length L = 1.000 ± 0.005 m. (a) Calculate the period T of one oscillation. (b) Rearranging gives g = 4π²L/T². Calculate the overall percentage uncertainty in g (remembering T is squared). Give only the answer to (b).', NULL, 4, 'numeric'::answer_type, '2.5', '%', false, NULL, false, '(a) T = 40.0 ÷ 20 = 2.00 s (dividing by the exact count, 20, does not change the percentage uncertainty). (b) % uncertainty in the 20-oscillation time = (0.4÷40.0)×100% = 1.00%, so the same 1.00% applies to T itself. Since g ∝ 1/T², this doubles to 2.00%. % uncertainty in L = (0.005÷1.000)×100% = 0.500%. Total % uncertainty in g = 0.500% + 2.00% = 2.50%. Common mistake: recalculating the percentage uncertainty in T from scratch as if dividing by 20 (an exact number with no uncertainty of its own) somehow changed it — dividing by an exact constant leaves the PERCENTAGE uncertainty completely unchanged.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a55cdb35-691a-589b-86e6-2b78245e73ed', 'f00ffd28-22a8-5f26-a19b-80fd37ab60aa', 'v = u + at', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f6116477-be1d-53fd-a07e-e82340f8a34e', 'f00ffd28-22a8-5f26-a19b-80fd37ab60aa', 's = ut + ½at²', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f94ec0de-f566-5d6d-827c-9ea383fb6686', 'f00ffd28-22a8-5f26-a19b-80fd37ab60aa', 'v² = u² + 2as', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('cf8d7999-ee45-536e-a868-2cac89f35c2b', 'f00ffd28-22a8-5f26-a19b-80fd37ab60aa', 's = ((u+v)/2)t', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b74cdd3a-9c3b-57de-8227-b75f63175e0f', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 7, 7, 'An object has v = 25 m/s, a = 3.0 m/s² and t = 4.0 s. Calculate u.', 'diagram:kin-2.8-q7', 2, 'numeric'::answer_type, '13', 'm/s', false, NULL, false, 'Rearranging v = u + at: u = v − at = 25 − (3.0×4.0) = 25 − 12 = 13.0 m/s. Common mistake: adding at to v instead of subtracting it.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7e1729ff-58c4-5a48-a8fd-74d596e0c5b7', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 8, 8, 'An object has u = 10 m/s, v = 30 m/s and t = 5.0 s. Calculate a.', 'diagram:kin-2.8-q8', 2, 'numeric'::answer_type, '4', 'm/s²', false, NULL, false, 'Rearranging v = u + at: a = (v−u) ÷ t = (30−10) ÷ 5.0 = 4.00 m/s². Common mistake: dividing by u or v instead of by t.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b996b8d1-eb22-54da-bab5-d3626c80dd03', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 9, 9, 'An object has u = 6.0 m/s, v = 18 m/s and a = 3.0 m/s². Calculate t.', 'diagram:kin-2.8-q9', 2, 'numeric'::answer_type, '4', 's', false, NULL, false, 'Rearranging v = u + at: t = (v−u) ÷ a = (18−6.0) ÷ 3.0 = 4.00 s. Common mistake: dividing (v−u) by v instead of by a.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('dc7713c4-fa41-5b8c-9722-43757c8c4fb5', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 10, 10, 'An object has u = 0, v = 16 m/s and a = 2.0 m/s². Calculate the displacement s.', NULL, 2, 'numeric'::answer_type, '64', 'm', false, NULL, false, 'Rearranging v² = u² + 2as: s = (v²−u²) ÷ (2a) = (16²−0²) ÷ (2×2.0) = 256 ÷ 4.0 = 64.0 m. Common mistake: forgetting to square v and u before subtracting, and instead computing (v−u) ÷ (2a).', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f7c094d9-685c-5e93-8751-ef30607fc211', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 11, 11, 'A ball travelling in the positive direction is decelerating. In the SUVAT equations, with the positive direction as usual, what sign should its acceleration be given?', NULL, 2, 'multiple_choice'::answer_type, 'Negative, since the velocity is decreasing in the chosen positive direction', NULL, false, NULL, false, 'Since the ball is slowing down while moving in the positive direction, its velocity is decreasing, so the acceleration must be taken as NEGATIVE in all four SUVAT equations — using a positive value for a deceleration is one of the most common sources of sign errors in SUVAT problems. Common mistake: using a positive magnitude for "deceleration" directly in the equations, rather than converting it to the correctly-signed acceleration first.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ffd3ccc9-9477-5b0a-a050-6e6f5600c9ee', 'f7c094d9-685c-5e93-8751-ef30607fc211', 'Negative, since the velocity is decreasing in the chosen positive direction', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('fc428875-2049-5731-b80f-1831c26a1f7e', 'f7c094d9-685c-5e93-8751-ef30607fc211', 'Positive, since deceleration is itself always a positive quantity', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('49f04210-381c-5230-8e06-77cf06bbc69c', 'f7c094d9-685c-5e93-8751-ef30607fc211', 'Zero, since deceleration is not really an acceleration', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1dfd046e-c2cb-5d5f-bbac-8377e00d97aa', 'f7c094d9-685c-5e93-8751-ef30607fc211', 'It depends on the object’s mass', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f3c11737-dc98-5d48-a1b2-6fd11051fcf0', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 12, 12, 'A ball has u = 20 m/s and decelerates at 4.0 m/s² (so a = −4.0 m/s²) for 3.0 s. Calculate v.', 'diagram:kin-2.8-q12', 2, 'numeric'::answer_type, '8', 'm/s', false, NULL, false, 'v = u + at = 20 + (−4.0)×3.0 = 20 − 12 = 8.00 m/s. Common mistake: using a = +4.0 m/s², which would wrongly make the ball speed up instead of slow down.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('960599dd-a790-5006-8a7e-5b7b0028252e', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 13, 13, 'An object has u = 15 m/s and a = −3.0 m/s², for t = 2.0 s. Calculate the displacement s.', 'diagram:kin-2.8-q13', 2, 'numeric'::answer_type, '24', 'm', false, NULL, false, 's = ut + ½at² = (15×2.0) + ½×(−3.0)×2.0² = 30 + (−6.0) = 24.0 m. Common mistake: using a = +3.0 instead of −3.0, which would give a larger (and wrong) displacement of 36 m.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2507b3fe-a54e-5b90-ac57-4f065f915fc6', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 14, 14, 'A car has u = 5.0 m/s and accelerates at 2.0 m/s² for 6.0 s. (a) Calculate v using v = u + at. (b) Calculate the displacement using s = ((u+v)/2)t. (c) Verify your answer to (b) using s = ut + ½at². Give only the answer to (b).', 'diagram:kin-2.8-q14', 3, 'numeric'::answer_type, '66', 'm', false, NULL, false, '(a) v = 5.0 + 2.0×6.0 = 17.0 m/s. (b) s = ((5.0+17.0)/2) × 6.0 = 11.0 × 6.0 = 66.0 m. (c) Check: s = (5.0×6.0) + ½×2.0×6.0² = 30 + 36 = 66.0 m — matches, confirming the two equations are consistent for the same motion. Common mistake: trusting only one SUVAT equation without any way to check it — using a second, independent equation like this is a good habit for catching arithmetic slips.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('70b008fa-b461-57ff-812b-c514b42be000', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 15, 15, 'A car travelling at 25 m/s brakes with a deceleration of magnitude 5.0 m/s² until it stops. (a) Calculate the time taken to stop. (b) Calculate the braking distance, using v² = u² + 2as. Give only the answer to (b).', 'diagram:kin-2.8-q15', 3, 'numeric'::answer_type, '62.5', 'm', false, NULL, false, '(a) t = (v−u)÷a = (0−25)÷(−5.0) = 5.00 s. (b) Rearranging v²=u²+2as for s: 0 = 25² + 2×(−5.0)×s, so s = 25² ÷ (2×5.0) = 625÷10 = 62.5 m. Common mistake: using +5.0 m/s² for the deceleration in the equation, instead of −5.0 m/s², which would give a negative (meaningless) value under the square root logic of the rearrangement.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3c9d04e6-4f07-5ffe-ac37-d87299d91374', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 16, 16, 'An object starts from rest and accelerates at 3.0 m/s² for 4.0 s (phase 1), then moves at the resulting constant velocity for a further 5.0 s (phase 2). (a) Calculate the velocity reached at the end of phase 1. (b) Calculate the displacement during phase 1. (c) Calculate the TOTAL displacement for both phases combined. Give only the answer to (c).', 'diagram:kin-2.8-q16', 3, 'numeric'::answer_type, '84', 'm', false, NULL, false, '(a) v₁ = 0 + 3.0×4.0 = 12.0 m/s. (b) s₁ = (0×4.0) + ½×3.0×4.0² = 24.0 m. (c) Phase 2 (constant velocity): s₂ = 12.0×5.0 = 60.0 m. Total = 24.0 + 60.0 = 84.0 m. Common mistake: using the SUVAT acceleration equation for phase 2 as well, instead of recognising it is a SEPARATE, constant-velocity (zero acceleration) phase that just needs displacement = velocity × time.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d5cb5324-f549-59ce-b49b-2658a228973d', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 17, 17, 'A ball must decelerate from speed u to rest over a distance of exactly 40 m, under a deceleration of magnitude 2.0 m/s², in order to stop exactly at a wall. Calculate the maximum initial speed u for which this is possible.', NULL, 3, 'numeric'::answer_type, '12.65', 'm/s', false, 0.05, false, 'Using v² = u² + 2as with v = 0 and a = −2.0 m/s²: 0 = u² + 2×(−2.0)×40, so u² = 160 and u = √160 = 12.6 m/s. Common mistake: using a = +2.0 instead of −2.0 when rearranging, which would produce a negative value for u² (impossible) rather than a positive one.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6da2d519-62ec-58fd-954d-65fa9a332c94', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 18, 18, 'An object starts from rest and, under constant acceleration, covers 100 m in exactly 5.0 s. (a) Use s = ut + ½at² to find the acceleration. (b) Use v = u + at to find the velocity at t = 5.0 s. (c) Verify (b) using v² = u² + 2as. Give only the answer to (b).', 'diagram:kin-2.8-q18', 3, 'numeric'::answer_type, '40', 'm/s', false, NULL, false, '(a) 100 = (0×5.0) + ½×a×5.0², so a = (2×100) ÷ 25 = 8.00 m/s². (b) v = 0 + 8.00×5.0 = 40.0 m/s. (c) Check: v² = 0² + 2×8.00×100 = 1600, so v = √1600 = 40.0 m/s — matches (b). Common mistake: trusting a single calculation without any independent check — here, two different SUVAT routes both confirm v = 40 m/s.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('db0a0ae4-b164-57fc-8efa-1d283c5e0993', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 19, 19, 'Starting from v = u + at and s = ((u+v)/2)t, eliminate t algebraically to derive v² = u² + 2as. Then apply it: an object is dropped from rest and falls 45 m under gravity (g = 9.81 m/s², air resistance negligible). Calculate its speed after falling this distance.', NULL, 4, 'numeric'::answer_type, '29.71', 'm/s', false, NULL, false, 'From v = u+at: t = (v−u)/a. Substitute into s = ((u+v)/2)t: s = ((u+v)/2) × (v−u)/a = (v²−u²) ÷ (2a), using the difference-of-two-squares identity (u+v)(v−u) = v²−u². Rearranging gives 2as = v²−u², i.e. v² = u²+2as, with no t remaining. Applying it: v² = 0² + 2×9.81×45 = 883, so v = √883 = 29.7 m/s. Common mistake: trying to substitute t from a DIFFERENT equation (e.g. s = ut + ½at²) instead of from v = u+at, which does not cleanly eliminate t the same way.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2089a848-f4b6-5e5a-aa33-f349af9c8245', 'ec015167-65fb-47df-b565-1055132ab4f3', '69f49b38-4492-521c-be78-56effb528ad2', 'as', '2.8', '9702 2.8 The equations of motion', 20, 20, 'A particle decelerates uniformly from speed u to rest over a measured distance of 18 m in exactly 4.0 s. (a) Use s = ((u+v)/2)t (with v = 0) to find u. (b) Use v² = u² + 2as to find the acceleration a. (c) Check your value of a using v = u + at (which should also give v = 0). Give only the answer to (a).', NULL, 4, 'numeric'::answer_type, '9', 'm/s', false, NULL, false, '(a) s = ((u+0)/2) × t, so u = 2s/t = (2×18) ÷ 4.0 = 9.00 m/s. (b) 0 = 9.00² + 2×a×18, so a = −9.00² ÷ (2×18) = −2.25 m/s². (c) Check: v = 9.00 + (−2.25)×4.0 = 0 m/s — exactly 0, confirming the two independent equations agree. Common mistake: using s = ut + ½at² first (which has TWO unknowns, u and a, and cannot be solved alone) instead of the simpler s = ((u+v)/2)t, which has only one unknown once v = 0 is substituted.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c91d6ff3-4778-564e-a8f2-bd01f84b2273', '236d63f4-3e1f-483a-b484-8b9cb0aa3b69', 'v = u + at', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bfe90e32-a96a-5a53-bdcd-0e6bfedc6c29', '236d63f4-3e1f-483a-b484-8b9cb0aa3b69', 'v = u − at', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('54bffebb-ed28-577d-82dd-dd7c7b8e27ed', '236d63f4-3e1f-483a-b484-8b9cb0aa3b69', 'v = at − u', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('92610bf2-04e4-5259-988c-dc27bb60590e', '236d63f4-3e1f-483a-b484-8b9cb0aa3b69', 'v = a(t−u)', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9ca41830-341d-557a-b8cb-e9a9cff63719', '2839f5a6-db51-490d-b2a6-3d18ddb960fd', 'Displacement', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5f207fe9-cdc1-566d-a9c8-c14d5c58c43d', '2839f5a6-db51-490d-b2a6-3d18ddb960fd', 'Acceleration', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('82b14a43-06fc-516a-a055-a39c248f7375', '2839f5a6-db51-490d-b2a6-3d18ddb960fd', 'Average speed only', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4878cb60-d3b4-5699-9ea1-aa4fdcba017c', '2839f5a6-db51-490d-b2a6-3d18ddb960fd', 'Nothing physically meaningful', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('50ae0e97-148f-5f62-b93d-2254d09daed3', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 7, 7, 'By substituting t = (v−u)/a into s = ((u+v)/2)t, show that s = (v²−u²)/(2a). Apply this for u = 6.0 m/s, v = 14 m/s, a = 4.0 m/s².', 'diagram:kin-2.9-q7', 2, 'numeric'::answer_type, '20', 'm', false, NULL, false, 'Substituting: s = ((u+v)/2) × (v−u)/a = (u+v)(v−u) ÷ (2a) = (v²−u²) ÷ (2a), using the difference-of-two-squares identity. Applying it: s = (14²−6²) ÷ (2×4.0) = (196−36) ÷ 8.0 = 160 ÷ 8.0 = 20.0 m. Common mistake: expanding (u+v)(v−u) incorrectly, rather than recognising it directly as the difference-of-two-squares pattern v²−u².', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4d62c2d3-7b8c-5cfb-9db5-19635e0273c4', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 8, 8, 'Which algebraic identity is the key step in deriving v² = u² + 2as from v = u+at and s = ((u+v)/2)t?', NULL, 2, 'multiple_choice'::answer_type, '(v−u)(v+u) = v²−u²', NULL, false, NULL, false, 'The difference-of-two-squares identity, (v−u)(v+u) = v²−u², is what allows the two expressions (one from each original equation) to combine neatly into this form. Common mistake: trying to derive this result using a completely different approach (such as calculus), when at AS level the two original SUVAT equations and this one algebraic identity are all that is needed.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f7d25e71-b00d-571e-b7ec-6cc5b19c9176', '4d62c2d3-7b8c-5cfb-9db5-19635e0273c4', '(v−u)(v+u) = v²−u²', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8a2a1573-8abf-5c13-85ac-3816bf65b935', '4d62c2d3-7b8c-5cfb-9db5-19635e0273c4', '(v+u)² = v²+u²', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b1e39661-bd13-5c30-9227-17731efd752e', '4d62c2d3-7b8c-5cfb-9db5-19635e0273c4', 'v² ÷ u² = (v÷u)²', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('345fa45d-54d4-56b7-9b2c-a348ad7bb4fc', '4d62c2d3-7b8c-5cfb-9db5-19635e0273c4', 'a² + t² = (a+t)²', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('67ea0010-d104-59c3-bb6a-e85c1e2ba371', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 9, 9, 'Substitute v = u+at into s = ((u+v)/2)t to show this simplifies to s = ut + ½at². Verify this for u = 3.0 m/s, a = 5.0 m/s², t = 2.0 s, by calculating s both ways.', 'diagram:kin-2.9-q9', 2, 'numeric'::answer_type, '16', 'm', false, NULL, false, 'Substituting: s = ((u + (u+at))/2)t = ((2u+at)/2)t = ut + ½at². Direct substitution method: s = ut+½at² = (3.0×2.0) + ½×5.0×2.0² = 6.0+10 = 16.0 m. Using the original form with v = u+at = 3.0+5.0×2.0 = 13: s = ((3.0+13)/2)×2.0 = 16.0 m — the two methods agree. Common mistake: substituting incorrectly and ending up with an extra factor of 2 somewhere in the simplification.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('51022b75-f557-5d49-9e6b-5944061d5db5', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 10, 10, 'Of the four SUVAT equations, which one does NOT contain the time t at all?', NULL, 2, 'multiple_choice'::answer_type, 'v² = u² + 2as', NULL, false, NULL, false, 'v² = u² + 2as is the only one of the four equations with no t in it — it was specifically derived (by eliminating t between the other two) to be useful whenever time is neither known nor required. Common mistake: forgetting which of the equations is "the one without t", and wasting time calculating t unnecessarily.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('cb6ce194-667d-5fea-abac-a9f2258ebe12', '51022b75-f557-5d49-9e6b-5944061d5db5', 'v² = u² + 2as', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('450a2bcc-06c3-57e4-b41b-685a8c1b9ccf', '51022b75-f557-5d49-9e6b-5944061d5db5', 'v = u + at', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('81e4394e-97c3-5d22-9112-3e2b345427de', '51022b75-f557-5d49-9e6b-5944061d5db5', 's = ut + ½at²', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('dc1a2ab7-9e0c-5792-8d51-8f0e58282f10', '51022b75-f557-5d49-9e6b-5944061d5db5', 's = ((u+v)/2)t', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9b7bdd82-9107-5748-b25d-c363430509ec', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 11, 11, 'Using only the area-under-a-graph interpretation (without needing to recall a SUVAT formula from memory), find the displacement for u = 8.0 m/s decelerating uniformly to v = 2.0 m/s over t = 5.0 s.', 'diagram:kin-2.9-q11', 2, 'numeric'::answer_type, '25', 'm', false, NULL, false, 'The area of the trapezium is ½(sum of parallel sides) × height: s = ((8.0+2.0)/2) × 5.0 = 5.0 × 5.0 = 25.0 m. This is exactly s = ((u+v)/2)t, derived directly from first principles rather than recalled as a memorised formula. Common mistake: needing to look up a formula for this, rather than recognising the trapezium shape and computing its area directly.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('aff58f7a-563d-5f8c-9b0d-c66c97752ee9', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 12, 12, 'The SUVAT equations assume "uniform acceleration". What does this assumption mean, in terms of what it guarantees about equal time intervals?', NULL, 2, 'multiple_choice'::answer_type, 'Equal changes in velocity occur in equal time intervals, so the velocity-time graph is a straight line', NULL, false, NULL, false, 'Uniform acceleration means equal CHANGES in velocity occur over equal time intervals, throughout the motion — this is the key assumption that makes the velocity-time graph a single straight line, which is what allows all four SUVAT equations (each derived from that straight-line picture) to be valid. Common mistake: thinking "uniform acceleration" is just a vague description, rather than the precise mathematical condition (constant gradient on a v-t graph) that the whole derivation depends on.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('506f21ba-e0be-5939-b1a1-401795d05db2', 'aff58f7a-563d-5f8c-9b0d-c66c97752ee9', 'Equal changes in velocity occur in equal time intervals, so the velocity-time graph is a straight line', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0dc7ee0c-efa0-550f-9647-f6d769db75ea', 'aff58f7a-563d-5f8c-9b0d-c66c97752ee9', 'The velocity never changes', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('674f1faa-a42a-5511-81bd-7dfac77e1c0c', 'aff58f7a-563d-5f8c-9b0d-c66c97752ee9', 'The displacement is the same in every equal time interval', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5b5b1ce6-5525-58d9-a995-1668ca9e4e80', 'aff58f7a-563d-5f8c-9b0d-c66c97752ee9', 'The object never experiences any force', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('33566744-7604-5fe8-892a-00abf354a6d7', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 13, 13, 'Rearranging s = ut + ½at² to make a the subject gives a = 2(s−ut)/t². Apply this for s = 50 m, u = 5.0 m/s, t = 5.0 s.', NULL, 2, 'numeric'::answer_type, '2', 'm/s²', false, NULL, false, 'a = 2(s−ut) ÷ t² = 2×(50 − 5.0×5.0) ÷ 5.0² = 2×(50−25) ÷ 25 = 2×25 ÷ 25 = 2.00 m/s². Common mistake: forgetting to multiply by 2 before dividing by t², since the original ½ must be cleared when rearranging for a.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('80aa5835-c7f7-5602-8524-3e5b2702e3d7', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 14, 14, '(a) Starting from v = u+at, make t the subject. (b) Substitute your result into s = ((u+v)/2)t and simplify, showing it leads to v² = u² + 2as. (c) Apply the result to find s for u = 0, v = 30 m/s, a = 6.0 m/s². Give only the answer to (c).', 'diagram:kin-2.9-q14', 3, 'numeric'::answer_type, '75', 'm', false, NULL, false, ('(a) t = (v−u)/a. (b) Substituting: s = ((u+v)/2) × (v−u)/a = (u+v)(v−u)/(2a) = (v²−u²)/(2a), using the difference-of-two-squares identity' || chr(59) || ' rearranging gives v² = u² + 2as. (c) s = (30²−0²) ÷ (2×6.0) = 900 ÷ 12 = 75.0 m. Common mistake: substituting t into the WRONG equation (such as s=ut+½at², which does not simplify this cleanly) instead of into s=((u+v)/2)t.'), 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('100458dc-5c28-50fd-9600-ca3d12869411', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 15, 15, 'Derive s = ut+½at² using the area under a velocity-time graph, explaining what the rectangle part and the triangle part each represent physically. Apply it for u = 10 m/s, a = −2.0 m/s², t = 3.0 s. Give only the final numerical answer.', 'diagram:kin-2.9-q15', 3, 'numeric'::answer_type, '21', 'm', false, NULL, false, 'The rectangle (height u, width t) represents the displacement that WOULD occur if the velocity stayed at its initial value u the whole time: area = ut. The triangle on top (base t, height at) represents the EXTRA displacement caused by the velocity changing at a steady rate: area = ½×t×at = ½at². Adding them: s = ut+½at². Applying: rectangle = 10×3.0 = 30.0 m, triangle = ½×(−2.0)×3.0² = −9.00 m (negative, since the object is decelerating). s = 30.0 + (−9.00) = 21.0 m. Common mistake: treating the triangle’s area as always positive, when a negative acceleration makes it a genuinely negative contribution to the total.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0d920755-0015-58ca-a16f-10914fafc976', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 16, 16, 'When an object starts from rest (u = 0), show how each of the four SUVAT equations simplifies. Then use the simplified form of v² = u²+2as to find v for a free-fall object (a = g = 9.81 m/s²) after falling s = 10 m.', NULL, 3, 'numeric'::answer_type, '14.01', 'm/s', false, NULL, false, 'With u = 0: v = u+at becomes v = at. s = ut+½at² becomes s = ½at². s = ((u+v)/2)t becomes s = ½vt. v² = u²+2as becomes v² = 2as (each loses its "u" term, since u = 0). Applying v² = 2as: v² = 2×9.81×10 = 196, so v = √196 = 14.0 m/s. Common mistake: forgetting that u = 0 only removes the TERMS containing u, not necessarily simplifying every equation by the same amount (v=at loses an entire added term, while v²=2as loses a squared term).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3fa6ec4c-2344-5be6-b133-40c8cb33171e', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 17, 17, 'A motion has u = 7.0 m/s, a = 3.0 m/s², t = 4.0 s. (a) Calculate s using s = ut+½at². (b) Rearrange s = ((u+v)/2)t to find v from your value of s, WITHOUT using v = u+at directly. (c) Check your answer to (b) using v = u+at. Give only the answer to (b).', 'diagram:kin-2.9-q17', 3, 'numeric'::answer_type, '19', 'm/s', false, NULL, false, '(a) s = (7.0×4.0) + ½×3.0×4.0² = 28 + 24 = 52.0 m. (b) Rearranging s = ((u+v)/2)t for v: v = 2s/t − u = (2×52.0)/4.0 − 7.0 = 26.0 − 7.0 = 19.0 m/s. (c) Check: v = u+at = 7.0 + 3.0×4.0 = 19.0 m/s — matches (b), as it should since both equations describe the same uniformly accelerated motion. Common mistake: forgetting to subtract u at the end of the rearrangement in (b), leaving an answer that is too large by exactly u.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0c015dfe-b7f7-5007-a949-7307f7c84716', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 18, 18, 'The table gives u, a and t for three objects, A, B and C. For each, use s = ut+½at² to find the displacement, and state which object travels furthest. Give only the furthest distance travelled.', 'diagram:kin-2.9-q18', 3, 'numeric'::answer_type, '100', 'm', false, NULL, false, 'Object A: s = (0×10) + ½×2.0×10² = 100 m. Object B: s = (5.0×10) + ½×0.50×10² = 50+25 = 75.0 m. Object C: s = (10×10) + ½×(−1.0)×10² = 100−50 = 50.0 m. Object A travels furthest, at 100 m, even though it starts from rest — its larger acceleration more than compensates for its lower starting speed over this 10 s. Common mistake: assuming the object with the highest INITIAL velocity (C) must travel furthest, without actually calculating all three displacements.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e1b8e3c6-f7ed-55b1-bbc4-daee8ca705eb', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 19, 19, 'Derive, using the area under a velocity-time graph for uniformly accelerated motion starting from rest, an expression for the displacement during the Nth second (between t = N−1 and t = N), and show it equals a(N−½). Verify numerically for a = 4.0 m/s², N = 5 (compare with directly computing s(5)−s(4)).', NULL, 4, 'numeric'::answer_type, '18', 'm', false, NULL, false, 'For motion from rest, s(t) = ½at², so the displacement during the Nth second is s(N)−s(N−1) = ½a[N²−(N−1)²] = ½a[N²−N²+2N−1] = ½a(2N−1) = a(N−½). For a = 4.0, N = 5: formula gives 4.0×(5−0.5) = 18.0 m. Direct check: s(5) = ½×4.0×5² = 50.0 m, s(4) = ½×4.0×4² = 32.0 m, difference = 50.0−32.0 = 18.0 m — matches. Common mistake: expanding (N−1)² incorrectly as N²−1 instead of the correct N²−2N+1, which would give a completely wrong simplified formula.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5e6a5bcd-2131-538d-b974-930805c3c282', 'ec015167-65fb-47df-b565-1055132ab4f3', '69bb568e-7993-444e-9ce8-19ebbd98c526', 'as', '2.9', '9702 2.9 Deriving the equations of motion', 20, 20, 'Two particles, A and B, each start from rest and cover the SAME distance s under uniform accelerations aₐ and a_B respectively. Derive an expression for the ratio of their times, tₐ/t_B, in terms of aₐ and a_B. Evaluate it for aₐ = 3.0 m/s² and a_B = 12 m/s².', NULL, 4, 'numeric'::answer_type, '2', '', false, NULL, false, 'From rest, s = ½at², so t = √(2s/a). Since both cover the SAME s: tₐ/t_B = √(2s/aₐ) ÷ √(2s/a_B) = √(a_B/aₐ), as the 2s cancels completely. Evaluating: tₐ/t_B = √(12/3.0) = √4.0 = 2.00 — A, with the SMALLER acceleration, takes exactly twice as long as B to cover the same distance. Common mistake: writing the ratio upside down as √(aₐ/a_B), which would (incorrectly) suggest A takes LESS time than B despite its smaller acceleration.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0fa6f02a-0df9-5b5b-9108-bf4179566b6c', '3ddf8bec-c90d-46f0-aa14-52fe0a914fb8', ('Straight line = uniform acceleration' || chr(59) || ' curved line = non-uniform acceleration'), 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8eca6770-9023-5e0f-97a8-a11372b620c3', '3ddf8bec-c90d-46f0-aa14-52fe0a914fb8', ('Straight line = non-uniform' || chr(59) || ' curved line = uniform'), 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bc25e89a-e207-5c8f-91ad-603db4978345', '3ddf8bec-c90d-46f0-aa14-52fe0a914fb8', 'Both always represent uniform acceleration', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1d4b8a14-3a9a-554a-a2fc-19ca6132aac5', '3ddf8bec-c90d-46f0-aa14-52fe0a914fb8', 'Neither shape tells you anything about acceleration', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3fd7d924-1120-5a0d-badf-2a4bec82a007', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 7, 7, 'Velocity readings at t = 0, 1, 2, 3, 4 s are v = 0, 2.0, 4.5, 8.0, 13 m/s. (a) Show that the acceleration is not uniform. (b) Calculate the acceleration during the LAST 1 s interval only.', 'diagram:kin-2.10-q7', 2, 'numeric'::answer_type, '5', 'm/s²', false, NULL, false, '(a) Successive 1 s changes in velocity are 2.0, 2.5, 3.5, 5.0 m/s — these are increasing, not equal, so the acceleration is non-uniform. (b) During the last interval: acceleration = (13−8.0) ÷ 1.0 = 5.00 m/s². Common mistake: calculating the OVERALL average acceleration ((13−0)/4 = 3.25 m/s²) when the question specifically asks about just the last 1 s interval, which has a noticeably different (larger) value.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b75c5e0b-96b6-5609-a81a-555b33653ead', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 8, 8, 'Why do many real moving objects experience non-uniform acceleration, rather than perfectly uniform acceleration?', NULL, 2, 'multiple_choice'::answer_type, 'Resistive forces such as air resistance typically change (often increasing) as speed changes, altering the net force and hence the acceleration', NULL, false, NULL, false, 'In reality, the forces acting on an object often change as its speed changes — for example, air resistance (drag) increases as speed increases, which reduces the net force (and hence the acceleration) as an object speeds up. An engine or motor may also not provide a perfectly constant driving force at every speed. Common mistake: assuming any resistive force is automatically constant, when drag in particular typically increases with speed, making the resulting acceleration change over time.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('159aaa0f-164b-51fb-924f-c55d3b00c1c6', 'b75c5e0b-96b6-5609-a81a-555b33653ead', 'Resistive forces such as air resistance typically change (often increasing) as speed changes, altering the net force and hence the acceleration', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('720c41f6-01cf-5977-ae36-0f745719dac1', 'b75c5e0b-96b6-5609-a81a-555b33653ead', 'Non-uniform acceleration never actually occurs in reality', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('31d8aee2-9991-53ca-beb1-fdaae98d960a', 'b75c5e0b-96b6-5609-a81a-555b33653ead', 'All real accelerations are exactly uniform by definition', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('df650d81-e1d9-5340-8fc2-bdee92e69a24', 'b75c5e0b-96b6-5609-a81a-555b33653ead', 'Only electrically powered vehicles can have non-uniform acceleration', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0509fb29-587e-5337-ab0b-bb7c8693ec5d', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 9, 9, 'A ticker tape (0.10 s between dots) shows successive dot-to-dot distances of 2.0 cm, 5.0 cm, 8.0 cm, 11 cm. These distances increase by the same amount (3.0 cm) each time — a standard test for UNIFORM acceleration. Use Δ(Δs) = aT² (where T is the time between dots) to calculate the acceleration.', 'diagram:kin-2.10-q9', 2, 'numeric'::answer_type, '3', 'm/s²', false, NULL, false, 'The constant second difference (each distance is 3.0 cm more than the last) confirms uniform acceleration, since Δ(Δs) = aT² is constant only when a itself is constant. a = Δ(Δs) ÷ T² = 0.030 ÷ (0.10)² = 0.030 ÷ 0.010 = 3.00 m/s². Common mistake: forgetting to convert the second-difference distance from cm to m before dividing by T².', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0aae9e80-9c7e-528b-80c4-862c4b2800ee', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 10, 10, 'A ticker tape shows successive dot-to-dot distances of 2.0 cm, 4.0 cm, 7.0 cm, 11 cm (differences 2.0, 3.0, 4.0 cm — themselves increasing). What does this show about the acceleration?', NULL, 2, 'multiple_choice'::answer_type, 'The acceleration is uniform, because the second differences between the distances are constant', NULL, false, NULL, false, ('Since the SECOND differences (the differences between the differences: 1.0 cm, then 1.0 cm) are constant, the acceleration is actually UNIFORM — even though the raw dot-to-dot distances are clearly not in a simple equally-spaced pattern. Common mistake: concluding the acceleration is non-uniform just because the dot-to-dot distances themselves are not equally spaced' || chr(59) || ' uniform acceleration is confirmed by the SECOND differences being constant, not the first differences (which, for any nonzero acceleration, are never equal in the first place).'), 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('671c4a59-e7c2-53c1-a228-f7726613cab8', '0aae9e80-9c7e-528b-80c4-862c4b2800ee', 'The acceleration is uniform, because the second differences between the distances are constant', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9c653a4c-fd0a-53d7-a784-26e3a00544a6', '0aae9e80-9c7e-528b-80c4-862c4b2800ee', 'The acceleration is non-uniform, because the distances themselves are not equal', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6b4f0663-cd34-5fb6-b7d5-e254464bcca5', '0aae9e80-9c7e-528b-80c4-862c4b2800ee', 'The tape shows the object was stationary throughout', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5eda597b-b200-5eb4-b763-aa5c05eb5d26', '0aae9e80-9c7e-528b-80c4-862c4b2800ee', 'No conclusion can be drawn from dot spacings', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b7736b6b-5ab2-5dd3-8dd4-e45a5dbf9bab', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 11, 11, 'Velocity readings at t = 0, 1, 2, 3, 4 s are v = 0, 3, 7, 13, 21 m/s. Calculate the average acceleration over the whole 4 s.', 'diagram:kin-2.10-q11', 2, 'numeric'::answer_type, '5.25', 'm/s²', false, NULL, false, 'average acceleration = (21−0) ÷ 4 = 5.25 m/s² (the increasing gaps between readings — 3, 4, 6, 8 — show this motion is non-uniform, but an overall average can still be calculated from just the first and last readings and the total time). Common mistake: trying to average the four individual intervals’ accelerations (3, 4, 6, 8 m/s²) rather than simply using the total change in velocity over the total time.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8e2faadd-7729-5cd4-b8c6-3d70b1eb3bb7', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 12, 12, 'For an object with non-uniform acceleration, what can be said about its INSTANTANEOUS acceleration at different times?', NULL, 2, 'multiple_choice'::answer_type, 'It changes from moment to moment, rather than staying constant', NULL, false, NULL, false, 'Its instantaneous acceleration varies from moment to moment — it is not the same at every instant, which is exactly what "non-uniform" means for acceleration. Common mistake: thinking "non-uniform acceleration" means the acceleration is always zero at some moments and nonzero at others, rather than simply varying continuously in size (and/or direction).', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('44cc4172-299d-5e30-93e2-90c4ae82e654', '8e2faadd-7729-5cd4-b8c6-3d70b1eb3bb7', 'It changes from moment to moment, rather than staying constant', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7bbe2a43-0af1-568d-825c-4e2f2df30146', '8e2faadd-7729-5cd4-b8c6-3d70b1eb3bb7', 'It is always exactly zero', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('cd92b9e2-717f-5b62-93c3-9eb4adfc954e', '8e2faadd-7729-5cd4-b8c6-3d70b1eb3bb7', 'It is always exactly equal to the average acceleration', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4d61d14b-8c43-50ae-810e-1c11a2b8a496', '8e2faadd-7729-5cd4-b8c6-3d70b1eb3bb7', 'It cannot be defined at all for non-uniform motion', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6903bcc5-2049-550a-8ad4-f1a96ff64214', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 13, 13, 'A velocity-time graph curves smoothly (non-uniform acceleration). Close readings give v = 9.5 m/s at t = 2.9 s and v = 10.5 m/s at t = 3.1 s. Estimate the instantaneous acceleration at t = 3.0 s.', 'diagram:kin-2.10-q13', 2, 'numeric'::answer_type, '5', 'm/s²', false, NULL, false, 'a ≈ (10.5−9.5) ÷ (3.1−2.9) = 1.0 ÷ 0.20 = 5.00 m/s². Common mistake: using readings spaced too far apart in time, which would estimate an average rather than this specific instant’s acceleration.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2131b972-375f-53c8-8473-6aa03f289711', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 14, 14, 'A trolley’s velocity is recorded at t = 0, 1, 2, 3, 4, 5 s as v = 0, 2, 4, 6, 8, 10 m/s. (a) Determine, with a reason, whether the acceleration is uniform. (b) Calculate the acceleration. (c) Predict v at t = 8 s, assuming the same pattern continues. Give only the answer to (c).', 'diagram:kin-2.10-q14', 3, 'numeric'::answer_type, '16', 'm/s', false, NULL, false, '(a) Each 1 s interval increases v by exactly 2 m/s (equal changes in equal times), so the acceleration IS uniform. (b) a = 2.0 m/s². (c) Extending the same uniform pattern 3 more seconds: v(8) = 10 + 2.0×3 = 16.0 m/s. Common mistake: trying to predict beyond the data for a NON-uniform pattern by simple extrapolation — this only works reliably once uniformity has actually been confirmed, as it was here in part (a).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('cc53a796-d917-512f-92d1-f275b5d70140', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 15, 15, 'A ball’s velocity is recorded at t = 0, 1, 2, 3 s as v = 0, 4, 9, 16 m/s. (a) Show that the acceleration is non-uniform. (b) Calculate the average acceleration over the whole 3 s. (c) Calculate the acceleration during just the LAST 1 s interval. Give only the answer to (c).', 'diagram:kin-2.10-q15', 3, 'numeric'::answer_type, '7', 'm/s²', false, NULL, false, '(a) Successive 1 s velocity changes are 4, 5, 7 m/s — not equal, so non-uniform. (b) average acceleration = (16−0) ÷ 3 = 5.33 m/s². (c) Last interval: a = (16−9) ÷ 1.0 = 7.00 m/s², noticeably bigger than the overall average found in (b). Common mistake: using the overall average (5.33 m/s²) when the question specifically asks for the acceleration during only the final second.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f7bfe81f-49ab-5b2c-b58b-dc212a16d7c1', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 16, 16, ('An elevator''s measured acceleration is: 1.5 m/s² (uniform) for the first 2.0 s' || chr(59) || ' then non-uniform, falling from 1.5 to 0 m/s² over the next 0.5 s (not analysed in detail here)' || chr(59) || ' then exactly 0 m/s² (constant velocity) from then on. (a) State during which phase the SUVAT equations can be directly and exactly applied. (b) Using SUVAT for that phase (starting from rest), calculate the velocity at t = 2.0 s. Give only the answer to (b).'), 'diagram:kin-2.10-q16', 3, 'numeric'::answer_type, '3', 'm/s', false, NULL, false, '(a) SUVAT equations assume UNIFORM acceleration, so they can be applied directly and exactly only during the first phase (0 to 2.0 s), not during the middle (non-uniform) phase. (b) v = u+at = 0 + 1.5×2.0 = 3.00 m/s. Common mistake: applying a SUVAT equation across the whole elevator journey (including the non-uniform middle phase) as if it were uniformly accelerated throughout.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f24562ca-f84d-58b1-a536-eb95285793f7', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 17, 17, 'A ticker tape (0.10 s between dots) shows successive dot-to-dot distances: 1.0, 1.6, 2.2, 2.8, 3.4 cm. (a) Show that the acceleration is uniform. (b) Calculate its value. Give only the answer to (b).', 'diagram:kin-2.10-q17', 3, 'numeric'::answer_type, '0.6', 'm/s²', false, NULL, false, '(a) The differences between successive distances are 0.60, 0.60, 0.60 cm — constant, confirming uniform acceleration. (b) a = Δ(Δs) ÷ T² = 0.0060 ÷ (0.10)² = 0.600 m/s². Common mistake: using the FIRST differences (the distances themselves) in the formula, rather than the constant SECOND difference between them.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a84197cd-b24e-5386-90db-261466e8a428', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 18, 18, 'A ticker tape (0.10 s between dots) shows successive dot-to-dot distances: 1.0, 1.6, 2.5, 3.9 cm. (a) Show that the acceleration is NOT uniform. (b) Estimate the average velocity represented by the first interval, and by the last interval. (c) Hence estimate the average acceleration across the tape. Give only the answer to (c).', 'diagram:kin-2.10-q18', 3, 'numeric'::answer_type, '96.67', 'm/s²', false, NULL, false, '(a) Differences between successive distances: 0.60, 0.90, 1.4 cm — not constant (they are themselves increasing), so the acceleration is non-uniform. (b) First interval: v ≈ 0.010 ÷ 0.10 = 10.0 m/s. Last interval: v ≈ 0.039 ÷ 0.10 = 39.0 m/s. (c) These velocities apply roughly at the MIDPOINTS of the first and last intervals, which are 3 full intervals apart in time (0.30 s): a ≈ (39.0−10.0) ÷ 0.30 = 96.7 m/s². Common mistake: using the time span of all 4 intervals (0.40 s) instead of the 3 intervals that actually separate the midpoints of the first and last intervals.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8f99f5cf-fcdc-5f60-a87e-636920dfa321', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 19, 19, 'A particle starts from rest with an acceleration that increases linearly with time: a = 6.0t (in SI units, non-uniform). Since a(t) is linear, its average value over [0,T] equals the mean of its values at t=0 and t=T. Use this to derive an expression for the velocity gained by time T, and show it gives v = 3.0T². Verify for T = 4.0 s.', NULL, 4, 'numeric'::answer_type, '48', 'm/s', false, NULL, false, 'The average acceleration over [0,T] is (a(0)+a(T))/2 = (0+6.0T)/2 = 3.0T. Velocity gained = average acceleration × time = 3.0T × T = 3.0T². For T = 4.0 s: v = 3.0×4.0² = 3.0×16 = 48 m/s. Common mistake: using the FINAL value of the acceleration, 6.0T, as if it applied for the whole interval (which would overestimate v, since the acceleration started at zero and only reached 6.0T at the very end).', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('32e30fe2-3733-5d24-8f38-881ae5b0fb6b', 'ec015167-65fb-47df-b565-1055132ab4f3', '643b6cd1-3fbe-4618-9330-b9d737f06161', 'as', '2.10', '9702 2.10 Uniform and non-uniform acceleration', 20, 20, 'A cyclist''s velocity goes from 4.0 m/s to 7.0 m/s during one 1.0 s window, then (in a different training phase) from 7.0 m/s down to 5.0 m/s during the NEXT 1.0 s window. (a) Is the acceleration uniform over the combined 2.0 s? Justify your answer using the velocity change in each half. (b) Calculate the overall average acceleration over the full 2.0 s. Give only the answer to (b).', 'diagram:kin-2.10-q20', 4, 'numeric'::answer_type, '0.5', 'm/s²', false, NULL, false, '(a) The velocity change in the first window is +3.0 m/s, but in the second window it is −2.0 m/s — these are not equal, so the acceleration is NOT uniform over the combined 2.0 s (even if each half happened to be uniform within itself). (b) Overall average acceleration = (5.0−4.0) ÷ 2.0 = 0.500 m/s² — note how small this is compared to either individual phase, since the two phases partly cancel each other out. Common mistake: averaging the two PHASE accelerations ((+3.0 and −2.0 m/s² over each window) → (3.0+(−2.0))/2 = 0.50 m/s²) rather than correctly using only the overall first and last velocities with the TOTAL time — these happen to agree here only because the two windows are equal in length.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8aa9463d-c917-5b21-973e-88587154d280', 'ed04becf-44b3-443d-9edc-a9ab94b83245', 'Yes — both accelerate at the same rate, g, regardless of mass', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a8be9c77-0291-5c39-88ec-2c68218c8d13', 'ed04becf-44b3-443d-9edc-a9ab94b83245', 'No — the heavier object always falls faster', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('37b25413-771e-5a62-a74b-9fac58f7dc52', 'ed04becf-44b3-443d-9edc-a9ab94b83245', 'No — the lighter object always falls faster', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f75242d1-a7a9-5ff0-af72-498bda7f6891', 'ed04becf-44b3-443d-9edc-a9ab94b83245', 'It depends only on their colours', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7ac2b41f-f61b-5a40-9b39-cca626e9ab4f', '36e2bfec-6c52-43dc-bc09-33daa1bd0ff0', 'Vertically downward, towards the centre of the Earth', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e6be2b78-1d9a-556b-ad6d-1b02e00e8761', '36e2bfec-6c52-43dc-bc09-33daa1bd0ff0', 'Vertically upward', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d571e372-f61f-5ec4-8080-4440b04ef1d4', '36e2bfec-6c52-43dc-bc09-33daa1bd0ff0', 'Horizontally', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1e3111a6-bd5f-5104-a8ee-61cc801e1f16', '36e2bfec-6c52-43dc-bc09-33daa1bd0ff0', 'In the direction the object happens to be moving', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b959aa0c-5a88-5195-82f4-f2a258fbad31', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 7, 7, 'A ball is dropped from rest. Calculate the time it takes to fall 20 m (take g = 9.81 m/s²).', 'diagram:kin-2.11-q7', 2, 'numeric'::answer_type, '2.019', 's', false, NULL, false, 's = ½gt², so t = √(2s/g) = √(2×20 ÷ 9.81) = √4.08 = 2.02 s. Common mistake: forgetting to take the square root at the end, and giving t² as the final answer.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2d237393-58a7-561f-b3b0-4bd579893618', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 8, 8, 'A feather and a hammer are dropped together from the same height. In air, the hammer reaches the ground first, but in a vacuum chamber they land at exactly the same time. Explain this difference.', NULL, 2, 'multiple_choice'::answer_type, ('Air resistance affects the feather proportionally far more than the hammer' || chr(59) || ' in a vacuum there is no air resistance, so both fall at the same rate g'), NULL, false, NULL, false, 'In air, the feather experiences a much larger air resistance RELATIVE to its weight (because of its large surface area and small mass), which significantly slows its fall compared with the denser hammer. In a vacuum, there is no air resistance acting on either object, so both accelerate at exactly g and land together — this was famously demonstrated on the Moon, which has no atmosphere. Common mistake: concluding that gravity itself is "different" for the feather and the hammer, rather than recognising that it is air resistance (an entirely separate force) that causes the difference seen in air.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d70331a6-a271-5c1a-97dc-d1ef4f7fd678', '2d237393-58a7-561f-b3b0-4bd579893618', ('Air resistance affects the feather proportionally far more than the hammer' || chr(59) || ' in a vacuum there is no air resistance, so both fall at the same rate g'), 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('40a62d86-1a33-5a15-a52c-28d68934e3d4', '2d237393-58a7-561f-b3b0-4bd579893618', 'Gravity itself pulls harder on the hammer', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('5309399a-ecac-5064-a3ef-5ed2b50fa9ca', '2d237393-58a7-561f-b3b0-4bd579893618', 'The feather has a smaller value of g acting on it', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ddd13215-42f4-5a82-8bec-18355b84d7f1', '2d237393-58a7-561f-b3b0-4bd579893618', 'The hammer is magnetic and the floor attracts it', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8dac33e8-90e7-5233-bd2a-25644fb6288e', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 9, 9, 'An object is thrown straight down with an initial speed of 5.0 m/s. Calculate its speed after a further 2.0 s (take g = 9.81 m/s²).', 'diagram:kin-2.11-q9', 2, 'numeric'::answer_type, '24.62', 'm/s', false, NULL, false, 'Taking downward as positive: v = u + gt = 5.0 + 9.81×2.0 = 24.6 m/s. Common mistake: treating this as starting from rest (u = 0) and ignoring the given initial downward speed of 5.0 m/s.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('209ea335-fd03-5088-8a0e-40144cb32bea', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 10, 10, 'A ball is thrown vertically upward at 10 m/s. Calculate the time taken to reach its highest point (take g = 9.81 m/s², up positive).', 'diagram:kin-2.11-q10', 2, 'numeric'::answer_type, '1.019', 's', false, 0.05, false, 'At the highest point, v = 0: 0 = u − gt, so t = u/g = 10 ÷ 9.81 = 1.02 s. Common mistake: using g as +9.81 instead of recognising it decelerates the upward motion, which is equivalent to using a = −9.81 m/s² if up is taken as positive.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('8c1f0047-8758-577b-9cc4-3274e1bb1615', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 11, 11, 'At the very top of its flight, a ball thrown vertically upward has zero velocity. Is its acceleration also zero at that instant?', NULL, 2, 'multiple_choice'::answer_type, 'No — its acceleration is still g, downward, throughout the entire flight including the highest point', NULL, false, NULL, false, 'No — gravity acts continuously throughout the flight, so the ball’s acceleration is still g, directed downward, even at the single instant its velocity happens to be zero. This is exactly why the ball does not simply hover there, but immediately begins to fall. Common mistake: assuming the ball’s acceleration must also momentarily vanish simply because its velocity does.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6b2d32cf-187d-5a6c-8f09-3f7f6aed5a58', '8c1f0047-8758-577b-9cc4-3274e1bb1615', 'No — its acceleration is still g, downward, throughout the entire flight including the highest point', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6deb588c-bd6c-5d29-9784-15c1488179ad', '8c1f0047-8758-577b-9cc4-3274e1bb1615', 'Yes — zero velocity always means zero acceleration', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('96ec416c-9648-5882-be76-15f3f426744a', '8c1f0047-8758-577b-9cc4-3274e1bb1615', 'No — the acceleration briefly reverses to become upward', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('abf26ff8-17ea-5ea9-836a-2161fbfd5862', '8c1f0047-8758-577b-9cc4-3274e1bb1615', 'Yes, because gravity switches off at the highest point', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('004457bf-1016-5844-92c5-daa0c3ac3d9f', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 12, 12, 'A ball is thrown vertically upward at 10 m/s. Calculate the maximum height it reaches above the throwing point (take g = 9.81 m/s²).', 'diagram:kin-2.11-q12', 2, 'numeric'::answer_type, '5.097', 'm', false, NULL, false, 'Using v² = u² − 2gh (v = 0 at the top): 0 = 10² − 2×9.81×h, so h = 10² ÷ (2×9.81) = 5.10 m. Common mistake: using the WRONG equation (such as s = ut, which ignores the deceleration due to gravity entirely).', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('35054656-4b90-5388-a3fa-1324416c9621', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 13, 13, 'Taking upward as positive, a ball is thrown vertically upward at 12 m/s. Calculate its velocity at the moment it returns to the height from which it was thrown.', NULL, 2, 'numeric'::answer_type, '-12', 'm/s', false, NULL, false, 'By the symmetry of motion under constant acceleration, an object returning to its STARTING height has a velocity of exactly the same MAGNITUDE as its initial velocity, but in the OPPOSITE direction: −12 m/s. Common mistake: assuming the ball must arrive back more slowly because "it has used up energy against gravity" — with no air resistance, the speed on return exactly equals the speed it was thrown with.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('42498812-37c9-5818-af3c-923add853ebb', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 14, 14, 'A ball is dropped from rest from a 50 m cliff. (a) Calculate the time to reach the ground. (b) Calculate its impact speed. (c) If the ball were instead dropped from DOUBLE the height (100 m), would its impact speed also double? Calculate the actual impact speed from 100 m and compare. Give only the answer to (c).', 'diagram:kin-2.11-q14', 3, 'numeric'::answer_type, '44.29', 'm/s', false, NULL, false, ('(a) t = √(2×50 ÷ 9.81) = 3.19 s. (b) v = √(2×9.81×50) = 31.3 m/s. (c) From 100 m: v = √(2×9.81×100) = 44.3 m/s — this is NOT double 31.3 m/s (which would be 62.6 m/s)' || chr(59) || ' it is only larger by a factor of √2, since v ∝ √h, not v ∝ h. Common mistake: assuming impact speed is directly proportional to drop height, when the SUVAT relationship v² = 2gh actually makes speed proportional to the SQUARE ROOT of height.'), 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('cd28769c-97f0-5c8b-8cbe-2e07097bcd5d', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 15, 15, 'A ball is thrown upward at 15 m/s from the edge of a 20 m cliff, and falls all the way to the ground below. (a) Calculate the time to reach the highest point. (b) Calculate the maximum height above the throwing point. (c) Calculate the TOTAL time from being thrown until it hits the ground (20 m below the throwing point). Give only the answer to (c).', 'diagram:kin-2.11-q15', 3, 'numeric'::answer_type, '4.062', 's', false, NULL, false, '(a) t = u/g = 15 ÷ 9.81 = 1.53 s. (b) h = u² ÷ 2g = 15² ÷ (2×9.81) = 11.5 m. (c) Taking up as positive, the ground is at displacement −20 m: −20 = 15t − ½×9.81×t², a quadratic in t. Solving 4.905t²−15t−20 = 0 with the quadratic formula gives t = 4.06 s (taking the positive root). Common mistake: trying to use only s = ½gt² (which assumes the ball starts from rest) and ignoring the ball’s substantial initial upward velocity.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9c9d5943-9bf0-53c8-9b0a-285a7453dd58', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 16, 16, 'Ball A is dropped from rest from a tall tower. Exactly 0.50 s later, ball B is dropped from the SAME point. (a) Calculate ball A’s velocity at the moment B is dropped. (b) Calculate the separation between A and B at the moment 1.0 s after A was dropped (which is 0.50 s after B was dropped). Give only the answer to (b).', 'diagram:kin-2.11-q16', 3, 'numeric'::answer_type, '3.679', 'm', false, NULL, false, '(a) v_A = g×0.50 = 4.91 m/s. (b) At t = 1.0 s (measuring from when A was dropped): A has fallen s_A = ½×9.81×1.0² = 4.91 m. B, dropped 0.50 s later, has at this moment been falling for only 0.50 s: s_B = ½×9.81×0.50² = 1.23 m. Separation = 4.91 − 1.23 = 3.68 m. Common mistake: giving both balls the same 1.0 s of falling time, forgetting that B started 0.50 s later and so has only been falling for 0.50 s at this moment.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6ff9d6f9-07ca-510a-8598-a96b34ccad53', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 17, 17, ('A skydiver’s speed is recorded as: t = 0, 2, 4, 6, 8 s' || chr(59) || ' v = 0, 19.4, 36.9, 47.8, 53.0 m/s (the increases per 2 s interval are 19.4, 17.5, 10.9, 5.2 m/s — clearly shrinking). (a) Calculate the acceleration during the first 2 s. (b) Calculate the acceleration during the last 2 s. (c) Explain the physical reason for this decrease. Give only the answer to (b).'), 'diagram:kin-2.11-q17', 3, 'numeric'::answer_type, '2.6', 'm/s²', false, NULL, false, '(a) a = 19.4 ÷ 2.0 = 9.70 m/s² — very close to g, as expected before air resistance becomes significant at low speed. (b) a = 5.2 ÷ 2.0 = 2.60 m/s², much smaller. (c) As the skydiver’s speed increases, air resistance (drag) increases too, opposing gravity more and more and reducing the net downward force, and hence the acceleration — this is how a skydiver eventually approaches a constant terminal velocity. Common mistake: assuming g itself must be changing during the fall, rather than recognising that an ADDITIONAL force (air resistance) is increasingly opposing gravity.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('993e56cf-d57d-50cb-bd11-18de9f5f8fce', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 18, 18, 'A ball is thrown upward at 8.0 m/s from a window 15 m above the ground, and falls all the way to the ground. (a) Calculate the maximum height reached above the window. (b) Calculate the speed of impact with the ground, using v² = u² + 2gs with s = 15 m (the total distance fallen from the highest point back down past the window to the ground, consistent with v²=u²-2g(−15) measuring from the throw). Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '18.93', 'm/s', false, NULL, false, '(a) h = u² ÷ 2g = 8.0² ÷ (2×9.81) = 3.26 m above the window. (b) Using v² = u² + 2gs measured from the throw point down to the ground 15 m below (s = 15 m downward, same direction as g): v² = 8.0² + 2×9.81×15 = 64 + 294.3 = 358, so v = √358 = 18.9 m/s. Common mistake: trying to add the height risen (a) to the 15 m window height and using THAT total distance with u = 0, rather than correctly using the full displacement from the original throw point with the ball’s actual initial velocity of 8.0 m/s upward.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('eb2d2a9c-5848-5b6d-9d8e-5fa877b484ba', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 19, 19, 'Show that for an object thrown vertically upward at speed u, the time to return to its STARTING height is exactly 2u/g, and that its velocity on return has magnitude u but the opposite sign to the initial throw. Verify for u = 18 m/s.', NULL, 4, 'numeric'::answer_type, '3.67', 's', false, NULL, false, 'Taking up as positive and the throw point as s = 0: s = ut − ½gt². Setting s = 0 (other than the trivial t=0 solution): 0 = t(u−½gt), so the nonzero solution is t = 2u/g. Substituting into v = u−gt: v = u − g×(2u/g) = u−2u = −u, confirming the velocity on return is exactly reversed. For u = 18 m/s: t = 2×18 ÷ 9.81 = 3.67 s, and v = −18 m/s on return. Common mistake: solving 0 = ut−½gt² by dividing through by t too early, which discards the t = 0 solution but can also lead to sign errors if not handled carefully.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f07fdd10-3d59-5a60-adcc-2aff72f31421', 'ec015167-65fb-47df-b565-1055132ab4f3', 'e8c99a42-f3ca-45a2-9197-567cfffa1146', 'as', '2.11', '9702 2.11 Acceleration caused by gravity', 20, 20, 'On the Moon, g is about 1.62 m/s² (roughly 1/6 of Earth''s 9.81 m/s²). An astronaut drops a tool from a height of 2.0 m. (a) Calculate the time to fall on the Moon. (b) Calculate how much LONGER this takes compared with the same drop on Earth. Give only the answer to (b).', NULL, 4, 'numeric'::answer_type, '0.9328', 's', false, NULL, false, '(a) t_Moon = √(2×2.0 ÷ 1.62) = 1.57 s. (b) t_Earth = √(2×2.0 ÷ 9.81) = 0.639 s. Difference = 1.57 − 0.639 = 0.933 s. Common mistake: assuming the fall takes exactly 6 times as long on the Moon (matching the 6× smaller g) — because t ∝ 1/√g, not 1/g, the time only increases by a factor of √6 ≈ 2.45, not 6.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1f3a34df-e1c8-5b5d-a26c-42fef061c2fc', '97509044-a72b-4da6-9a47-fd3cdab5e0d3', 'g = 2s/t²', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('739e47d2-133c-53a4-90a1-294040272ecb', '97509044-a72b-4da6-9a47-fd3cdab5e0d3', 'g = s/(2t²)', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('89f46b7c-12c5-5375-b270-b641b324439a', '97509044-a72b-4da6-9a47-fd3cdab5e0d3', 'g = 2s/t', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f49ab38e-8067-5779-b4e1-053c421dd4ed', '97509044-a72b-4da6-9a47-fd3cdab5e0d3', 'g = s²/(2t)', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0b375a3a-b108-56b2-8e57-29c723956d19', '2aa2b971-e406-4ace-904e-9b8e79734a40', 'It reduces the effect of random timing variation, giving a more reliable mean time', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('7d3a7e57-a56f-5f94-8228-5a494dc070bb', '2aa2b971-e406-4ace-904e-9b8e79734a40', 'It has no effect on the reliability of the result', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1171976c-2b8d-5c86-abb8-daa52b41d096', '2aa2b971-e406-4ace-904e-9b8e79734a40', 'It removes any systematic error in the measured height', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('15fccb9c-de1a-504d-bdbc-4cf1072e08b7', '2aa2b971-e406-4ace-904e-9b8e79734a40', 'Repeating always doubles the precision exactly', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d5671c42-1990-5752-8e07-b4fd5a4ba7a9', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 7, 7, 'Two points on an s against t² graph are (t² = 0.50 s², s = 2.3 m) and (t² = 1.0 s², s = 4.9 m). Calculate the gradient between these points, and hence estimate g.', NULL, 2, 'numeric'::answer_type, '10.4', 'm/s²', false, 0.1, false, 'gradient = (4.9−2.3) ÷ (1.0−0.50) = 2.6 ÷ 0.50 = 5.20 m/s². g = 2 × gradient = 2×5.20 = 10.4 m/s² (a bit above the accepted value, reflecting the inevitable scatter in real experimental data from just two points). Common mistake: using t (not t²) as the horizontal axis value in the gradient calculation.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3ac09785-3502-5cd2-9608-82cda78f9774', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 8, 8, 'A simple free-fall experiment to determine g tends to give a value slightly LOWER than the accepted 9.81 m/s². What is the most likely cause?', NULL, 2, 'multiple_choice'::answer_type, 'Air resistance opposes the fall, systematically reducing the measured acceleration below true g', NULL, false, NULL, false, 'Air resistance acts on the falling object throughout its drop, opposing its motion and slightly reducing its acceleration below the true value of g — this is a systematic effect that always acts in the same direction (reducing the measured value), however carefully the experiment is repeated. Common mistake: assuming repeating the experiment more times and taking a better average would fix this — a SYSTEMATIC effect like air resistance is not reduced by averaging repeated readings.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3d4d7794-f8e5-5737-b942-a1db01ada2e0', '3ac09785-3502-5cd2-9608-82cda78f9774', 'Air resistance opposes the fall, systematically reducing the measured acceleration below true g', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a7def693-c34a-530c-a2e7-2c216be1db36', '3ac09785-3502-5cd2-9608-82cda78f9774', 'The timer runs systematically too fast', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c2857259-84c2-5c76-abde-99fbeccb0914', '3ac09785-3502-5cd2-9608-82cda78f9774', 'Gravity is weaker in a laboratory than elsewhere', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('02fa04bf-1478-56c9-a416-17a93ca784a7', '3ac09785-3502-5cd2-9608-82cda78f9774', 'The object’s mass systematically increases as it falls', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e57f9a5d-1f34-5856-a118-313442369767', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 9, 9, 'In a trolley-on-a-ramp method, a trolley’s acceleration down a ramp inclined at 15° to the horizontal is measured as 2.45 m/s². Using a = g sinθ (the component of g acting along the slope), estimate g.', NULL, 2, 'numeric'::answer_type, '9.466', 'm/s²', false, NULL, false, 'g = a ÷ sinθ = 2.45 ÷ sin15° = 2.45 ÷ 0.259 = 9.47 m/s². This ramp method deliberately slows the "effective" acceleration down to something easier to time accurately, at the cost of needing an accurate angle measurement too. Common mistake: using cosθ instead of sinθ — the component of gravity ALONG a slope uses sin of the angle from the horizontal.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('43c1a348-1492-5117-a199-13ce2ad4d748', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 10, 10, 'Why would light gates connected to an electronic timer give a more accurate value of g than a hand-operated stopwatch, in a free-fall experiment?', NULL, 2, 'multiple_choice'::answer_type, 'Light gates remove human reaction-time error, which would otherwise be comparable to the whole fall time', NULL, false, NULL, false, 'A typical free fall over a metre or so lasts well under half a second — comparable to, or shorter than, typical human reaction time (around 0.2–0.3 s). Light gates trigger and stop the timing electronically, with no human reaction-time delay at all, making the measured time (and hence g) far more accurate. Common mistake: assuming a stopwatch is "accurate enough" for any timing task, without considering whether the EVENT being timed is itself comparable in length to typical reaction times.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('fdd03734-3a26-51a1-bdf7-6a32ecf1c0cc', '43c1a348-1492-5117-a199-13ce2ad4d748', 'Light gates remove human reaction-time error, which would otherwise be comparable to the whole fall time', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ad416739-61f0-5b91-b481-5a88f367b75a', '43c1a348-1492-5117-a199-13ce2ad4d748', 'Light gates measure a completely different physical quantity from a stopwatch', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('1d51d04f-1a18-5f63-9e5f-8e3a620caf7f', '43c1a348-1492-5117-a199-13ce2ad4d748', 'Stopwatches are always more accurate for very short events', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('da117e04-28f7-5a62-a98a-4439bedd0ab8', '43c1a348-1492-5117-a199-13ce2ad4d748', 'There is no real difference between the two methods', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('45a6692a-50d7-5be3-985b-d3b64ecb0249', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 11, 11, 'Five repeated timings for the same fall give: 0.640, 0.638, 0.642, 0.639, 0.641 s. Calculate the mean time.', 'diagram:kin-2.12-q11', 2, 'numeric'::answer_type, '0.64', 's', false, NULL, false, 'mean = (0.64+0.638+0.642+0.639+0.641) ÷ 5 = 3.20 ÷ 5 = 0.640 s. Common mistake: using the median or a single "typical-looking" value instead of properly averaging all five readings.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('75b704b0-ddfb-5a17-b031-040b9b710a3b', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 12, 12, 'Using the mean time found previously (0.640 s) for a fall of height 2.00 m, calculate g.', NULL, 2, 'numeric'::answer_type, '9.766', 'm/s²', false, NULL, false, 'g = 2×2.00 ÷ 0.640² = 4.00 ÷ 0.4096 = 9.77 m/s². Common mistake: using one of the INDIVIDUAL raw timings instead of the properly-calculated mean of all five readings.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f2f47c78-11c6-5bb3-8015-89f5eb9d68a7', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 13, 13, 'Why is the graphical method (plotting several s against t² points and finding the gradient of a best-fit line) generally more reliable than calculating g from just ONE height-and-time measurement?', NULL, 2, 'multiple_choice'::answer_type, 'A best-fit line through several points averages out random scatter, and reveals anomalous points', NULL, false, NULL, false, 'A single measurement is fully exposed to whatever random error affected that one particular reading. A graph uses MANY data points, and a best-fit line effectively averages out the scatter from random errors across all of them — and a clearly anomalous point also becomes visible and can be investigated, which is impossible with only one reading. Common mistake: assuming more data points automatically guarantees a more accurate result REGARDLESS of how they are analysed — the benefit specifically comes from fitting a line through the scatter, not simply from having "more numbers".', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c7e7b192-da67-5873-9833-1608ef085f7c', 'f2f47c78-11c6-5bb3-8015-89f5eb9d68a7', 'A best-fit line through several points averages out random scatter, and reveals anomalous points', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('45e12600-ee72-5c2b-9830-a2b94fd3bf5c', 'f2f47c78-11c6-5bb3-8015-89f5eb9d68a7', ('There is no real advantage' || chr(59) || ' a single measurement is just as reliable'), 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2c259714-b6b2-5975-855f-0c54a028f94d', 'f2f47c78-11c6-5bb3-8015-89f5eb9d68a7', 'It completely removes all systematic errors automatically', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('41ec4ca9-7f7f-5270-aae0-5effc8e54bf0', 'f2f47c78-11c6-5bb3-8015-89f5eb9d68a7', 'It only works if every single point lies exactly on the line', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('27aef0d7-2878-5a4f-b52e-89e6529d300b', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 14, 14, ('An s against t² graph has data points: t² = 0.10, 0.20, 0.30, 0.40, 0.50 s²' || chr(59) || ' s = 0.49, 0.98, 1.47, 1.96, 2.45 m. (a) Calculate the gradient, using the first and last points. (b) Calculate g. (c) Compare your value of g with the accepted value, 9.81 m/s². Give only the answer to (b).'), 'diagram:kin-2.12-q14', 3, 'numeric'::answer_type, '9.8', 'm/s²', false, NULL, false, '(a) gradient = (2.45−0.49) ÷ (0.5−0.1) = 1.96 ÷ 0.400 = 4.90 m/s². (b) g = 2 × gradient = 2×4.90 = 9.80 m/s². (c) This matches the accepted value of 9.81 m/s² almost exactly — this data set is perfectly consistent with s = ½gt² (each point lies exactly on the line through the origin). Common mistake: using only ONE of the five data points (together with the origin) instead of the full line’s gradient, which throws away the benefit of having multiple readings.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d400c44c-05f7-5ef8-a370-8231954712cf', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 15, 15, 'A graph of s against t² has a best-fit gradient of 4.85 ± 0.08 m/s². (a) Calculate g. (b) Calculate the absolute uncertainty in g. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.16', 'm/s²', false, NULL, false, '(a) g = 2 × 4.85 = 9.70 m/s². (b) Since g is exactly DOUBLE the gradient, the absolute uncertainty also doubles: uncertainty in g = 2 × 0.08 = 0.160 m/s², so g = 9.70 ± 0.160 m/s². Common mistake: quoting the gradient’s own uncertainty (0.08 m/s²) as if it were already the uncertainty in g, forgetting the factor of 2 relating gradient to g.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6ad704f4-d0f2-5ef7-a4d8-3375ae9fc43a', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 16, 16, 'Method A gives g = 9.75 ± 0.15 m/s². Method B gives g = 9.95 ± 0.10 m/s². (a) Write out the range of values each method is consistent with. (b) Determine whether the two results agree with each other, and calculate the width of the range over which both results overlap.', NULL, 3, 'numeric'::answer_type, '0.05', 'm/s²', false, NULL, false, '(a) Method A is consistent with 9.60 to 9.90 m/s². Method B is consistent with 9.85 to 10.0 m/s². (b) These two ranges DO overlap, between 9.85 and 9.90 m/s², a width of 0.0500 m/s² — so the two methods are consistent with each other within their stated uncertainties, even though their single "best" values (9.75 and 9.95) are different. Common mistake: concluding the two results disagree simply because their quoted central values are different, without checking whether their UNCERTAINTY RANGES actually overlap.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4a8e5c4b-94ed-574b-9b4b-7f653e14e13e', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 17, 17, 'A student determines g three times by timing a 2.000 m fall: 0.640 s, 0.637 s, 0.643 s. (a) Calculate g for each timing. (b) Calculate the mean g. (c) Calculate the percentage difference between the mean and the accepted value, 9.81 m/s². Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.448', '%', false, NULL, false, '(a) g values: 2×2.000÷0.640²=9.77, 2×2.000÷0.637²=9.86, 2×2.000÷0.643²=9.67 m/s². (b) mean = (9.77+9.86+9.67) ÷ 3 = 9.77 m/s². (c) percentage difference = (9.81−9.77) ÷ 9.81 × 100% = 0.448%. Common mistake: averaging the three TIMES first and calculating g only once from that single mean time, rather than calculating g separately for each timing and THEN averaging the resulting g values (both approaches are common in practice, but this question specifically asks for the latter).', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4c9ac069-5d6e-5a08-ad0e-dfd42005883a', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 18, 18, ('A student’s ruler is worn, causing every height measurement to read 1.0 cm too SHORT. A true height of 2.00 m is recorded (wrongly) as 1.99 m' || chr(59) || ' the timing, 0.639 s, is unaffected by this error. (a) Calculate the g value obtained using the WRONG (recorded) height. (b) Calculate the g value using the TRUE height. (c) Comment on the direction of the resulting error in (a). Give only the answer to (b).'), 'diagram:kin-2.12-q18', 3, 'numeric'::answer_type, '9.796', 'm/s²', false, NULL, false, '(a) Using the recorded (too-short) height: g = 2×1.99 ÷ 0.639² = 9.75 m/s². (b) Using the true height: g = 2×2.00 ÷ 0.639² = 9.80 m/s². (c) The recorded (wrong) height gives a SMALLER value of g than the true height does — a systematic error that shortens the measured distance will always systematically UNDERESTIMATE g, since g is directly proportional to the (wrongly too-small) height used. Common mistake: assuming a small 1.0 cm measurement error in a 2 m height is too small to matter — it still introduces a small but entirely systematic (one-directional) shift in every result calculated from it.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('71b6c458-ad4c-5210-b0e6-a8cf77a7501b', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 19, 19, 'In the s against t² method, explain why the gradient of the graph equals ½g, not g itself. A best-fit line through a data set has gradient 4.88 m/s², while the steepest acceptable line through the error bars (the "worst-fit" line) has gradient 4.95 m/s². Estimate the percentage uncertainty in g from this comparison.', NULL, 4, 'numeric'::answer_type, '1.434', '%', false, 0.05, false, 'Since s = ½gt² has the form (quantity plotted on y) = (constant) × (quantity plotted on x), with the constant being ½g, the gradient of a straight-line s-against-t² graph is exactly ½g — this is why the calculated g must always be DOUBLE the measured gradient. The spread between the best-fit and worst-fit gradients gives an estimate of the uncertainty in the gradient (and hence, since doubling a quantity does not change its PERCENTAGE uncertainty, in g too): percentage uncertainty ≈ (4.95−4.88) ÷ 4.88 × 100% = 1.43%. Common mistake: assuming the gradient itself IS g, rather than half of it, which would give a final g value exactly double the correct one.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('77408b04-4792-5356-a7ef-de800dc1780d', 'ec015167-65fb-47df-b565-1055132ab4f3', 'f2b48a0f-392d-4e95-bbe4-c2ee1de168d9', 'as', '2.12', '9702 2.12 Determining g', 20, 20, 'A pendulum method gives g = 9.76 ± 0.12 m/s², and a free-fall method on the same day gives 9.85 ± 0.08 m/s². A more precise laboratory result elsewhere quotes g = 9.812 m/s² (with negligible uncertainty). (a) State which student method agrees better with the precise value, and why. (b) Calculate how many of the pendulum method''s own uncertainty-widths (0.12 m/s²) the precise value sits away from the pendulum''s own measured value. Give only the answer to (b).', NULL, 4, 'numeric'::answer_type, '0.4333', '', false, 0.1, false, ('(a) The free-fall result (9.85 ± 0.08) is closer in absolute terms to 9.812, and 9.812 actually falls WITHIN its uncertainty range (9.77 to 9.93)' || chr(59) || ' the pendulum result (9.76 ± 0.12) also brackets 9.812 within its range (9.64 to 9.88), so both are arguably consistent, but the free-fall result pins the value down more tightly (smaller uncertainty). (b) Difference from the pendulum’s own value: 9.812 − 9.76 = 0.0520 m/s². In units of the pendulum’s own uncertainty (0.12 m/s²): 0.0520 ÷ 0.12 = 0.433 — well under 1, confirming good agreement. Common mistake: judging agreement between an experimental result and an accepted value using only the raw numerical difference, without expressing that difference relative to the experiment’s own stated uncertainty.'), 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ceeb2f92-83a9-505a-9520-6838203e794a', '85e6ac73-5f27-5879-aed0-17f5eb2a7918', 'They are independent — horizontal velocity stays constant, vertical motion is simple free fall', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a579533b-b013-54ed-af72-003173b03fb0', '85e6ac73-5f27-5879-aed0-17f5eb2a7918', 'The vertical motion slows down the horizontal motion', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('82812368-d631-57e7-8c47-8740fe140ca5', '85e6ac73-5f27-5879-aed0-17f5eb2a7918', 'The horizontal motion slows down the vertical motion', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('19967b56-86f0-5d5a-bb0e-57f7decc1e65', '85e6ac73-5f27-5879-aed0-17f5eb2a7918', 'They must always be numerically equal', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8b7f743f-1f1e-5293-9a4c-46887d543cce', 'f7550348-abc6-5b94-b64e-6a736b0ff0d5', 'It stays constant throughout the flight', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('07683634-14d7-5f80-a156-8e5989d5747a', 'f7550348-abc6-5b94-b64e-6a736b0ff0d5', 'It decreases steadily to zero', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('28c09fba-c92b-52a3-9c4b-1c697079687a', 'f7550348-abc6-5b94-b64e-6a736b0ff0d5', 'It increases as the object falls', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('cfd02d18-efaf-52ed-b6d6-061f49da8acb', 'f7550348-abc6-5b94-b64e-6a736b0ff0d5', 'It becomes zero at the highest point', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('32f975ae-581f-5853-a7c2-e411e2743206', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 6, 6, 'A ball is launched horizontally at 8.0 m/s and is in the air for 0.50 s before landing. Calculate the horizontal distance travelled.', 'diagram:kin-2.13-f6', 1, 'numeric'::answer_type, '4', 'm', false, NULL, false, 'range = horizontal speed × time = 8.0 × 0.50 = 4.00 m. Common mistake: trying to adjust this calculation for the vertical fall, when the horizontal distance depends only on the (constant) horizontal speed and the time of flight.', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a38f0ff6-6ad4-5c3e-8d8b-d68b968b8905', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 7, 7, 'A projectile is launched at 20 m/s, at 30° above the horizontal. Calculate the horizontal component of its initial velocity.', 'diagram:kin-2.13-q7', 2, 'numeric'::answer_type, '17.32', 'm/s', false, 0.05, false, 'u_x = u cosθ = 20×cos30° = 20×0.866 = 17.3 m/s. Common mistake: using sin30° instead of cos30° for the horizontal component.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('52ba5f3e-d858-5e55-885b-9c12fe09ce4b', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 8, 8, 'For the same projectile (20 m/s at 30° above the horizontal), calculate the vertical component of its initial velocity.', NULL, 2, 'numeric'::answer_type, '10', 'm/s', false, NULL, false, 'u_y = u sinθ = 20×sin30° = 20×0.500 = 10.0 m/s. Common mistake: swapping sin and cos, which would give the vertical component as 17.3 m/s (the horizontal value) instead.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d9ac3007-e7de-5a71-be33-84c7fef2ab20', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 9, 9, 'The projectile (u_y = 10.0 m/s) is launched from and lands at the same height. Calculate the total time of flight, using the fact that the flight is symmetric about the highest point.', NULL, 2, 'numeric'::answer_type, '2.039', 's', false, 0.05, false, 'Time to the highest point (where v_y = 0): t_up = u_y/g = 10.0÷9.81 = 1.02 s. By symmetry, the fall back down takes the same time, so total time of flight = 2 × t_up = 2u_y/g = 2×10.0÷9.81 = 2.04 s. Common mistake: calculating only the time to the TOP of the flight and forgetting to double it for the full time of flight.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('087aed82-f7a1-5c7d-bcc6-a1088ee17d2c', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 10, 10, 'Why does a projectile launched with no air resistance follow a parabolic path?', NULL, 2, 'multiple_choice'::answer_type, 'Because combining constant-velocity horizontal motion with constant-acceleration vertical motion mathematically produces a parabola when y is plotted against x', NULL, false, NULL, false, 'The horizontal position increases at a constant rate (constant horizontal velocity, so x = u_x t, which is linear in t), while the vertical position follows y = u_y t − ½gt² (quadratic in t, from the constant downward acceleration). Combining these (eliminating t) gives y as a quadratic function of x — exactly the equation of a parabola. Common mistake: thinking the parabolic SHAPE is some separate, additional physical assumption, rather than something that falls directly out of combining the two already-known types of motion (constant velocity, and constant acceleration).', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bd56b190-8d41-5460-aa51-e0046fa5bdfc', '087aed82-f7a1-5c7d-bcc6-a1088ee17d2c', 'Because combining constant-velocity horizontal motion with constant-acceleration vertical motion mathematically produces a parabola when y is plotted against x', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f01dbddc-baf1-5ab8-ad81-aac4d5fbd145', '087aed82-f7a1-5c7d-bcc6-a1088ee17d2c', 'Because air resistance curves the path into a parabola', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('33070ddf-9240-5da6-ac5e-144146af1711', '087aed82-f7a1-5c7d-bcc6-a1088ee17d2c', 'Because gravity itself has a parabolic shape', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('28fcf291-b746-5e47-9e1a-62472d4f915b', '087aed82-f7a1-5c7d-bcc6-a1088ee17d2c', 'Parabolic motion is simply assumed, with no underlying reason', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2c41c361-d8c6-5816-ab20-2c3da5df858b', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 11, 11, 'For the same projectile (u_x = 17.3 m/s, time of flight 2.04 s), calculate the horizontal range.', 'diagram:kin-2.13-q11', 2, 'numeric'::answer_type, '35.31', 'm', false, NULL, false, 'range = u_x × t = 17.3 × 2.04 = 35.3 m. Common mistake: using the vertical component, or the original launch speed (20 m/s) instead of its horizontal component, in this calculation.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c6f77d4e-a12d-5f01-abe0-ee5fbb811752', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 12, 12, 'For the same projectile (u_y = 10.0 m/s), calculate the maximum height reached.', NULL, 2, 'numeric'::answer_type, '5.097', 'm', false, NULL, false, 'Using v² = u_y² − 2gh with v = 0 at the top: h = u_y² ÷ (2g) = 10.0² ÷ (2×9.81) = 5.10 m. Common mistake: using the ORIGINAL launch speed (20 m/s) instead of only its vertical component in this height calculation.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('96f98e55-8bb8-5f70-94ce-19f959061cfd', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 13, 13, 'At the highest point of a projectile’s trajectory (launched at an angle, not straight up), is its velocity exactly zero?', NULL, 2, 'multiple_choice'::answer_type, ('No — only the vertical component is zero' || chr(59) || ' the horizontal component is still the original launch value'), NULL, false, NULL, false, ('No — only the VERTICAL component of velocity is zero at the highest point' || chr(59) || ' the horizontal component is unaffected by gravity and continues at its original, constant value throughout the flight. So the projectile’s overall velocity at the top is horizontal, not zero. Common mistake: confusing this with a ball thrown STRAIGHT up (with no horizontal motion at all), where the velocity genuinely is zero at the top — that is a special case, not the general rule for an angled launch.'), 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('f4a8910f-382f-5b4e-91a8-550f84806ee6', '96f98e55-8bb8-5f70-94ce-19f959061cfd', ('No — only the vertical component is zero' || chr(59) || ' the horizontal component is still the original launch value'), 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e33a1706-a5fa-5ee8-8f5a-b87892973050', '96f98e55-8bb8-5f70-94ce-19f959061cfd', 'Yes — the velocity is always exactly zero at the highest point', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4625a8e3-a0f4-5d3f-b1a0-21e85f39ace2', '96f98e55-8bb8-5f70-94ce-19f959061cfd', 'No — the velocity is at its maximum at the highest point', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('c96d3750-7173-57dd-b6ca-469ae1f7773f', '96f98e55-8bb8-5f70-94ce-19f959061cfd', 'Yes, but only if the projectile is heavier than air', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('6c5b16e5-158b-5eea-a024-fce145f16a7a', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 14, 14, 'A ball rolls off a table 0.90 m high at 4.0 m/s (horizontal launch). (a) Calculate the time to reach the ground. (b) Calculate the horizontal range. (c) Calculate the speed at which it lands. Give only the answer to (c).', 'diagram:kin-2.13-q14', 3, 'numeric'::answer_type, '5.802', 'm/s', false, NULL, false, ('(a) t = √(2×0.90 ÷ 9.81) = 0.428 s. (b) range = 4.0×0.428 = 1.71 m. (c) At landing: v_x = 4.0 m/s (unchanged)' || chr(59) || ' v_y = g×0.428 = 4.20 m/s. Combining as vectors: v = √(4.0²+4.20²) = 5.80 m/s. Common mistake: simply adding the horizontal and vertical speeds (4.0+4.20) instead of combining them as perpendicular vector components using Pythagoras.'), 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d2d7a7e2-371b-5451-9b8d-e8738e40ce5f', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 15, 15, 'A golf ball is launched at 25 m/s at 40° above the horizontal from a cliff edge, landing 15 m below the launch point. Calculate the horizontal range. (Hint: set up the vertical motion with the landing point at −15 m and solve the resulting quadratic for t, then use the horizontal component.)', 'diagram:kin-2.13-q15', 3, 'numeric'::answer_type, '77.26', 'm', false, NULL, false, 'Components: u_x = 25cos40° = 19.2 m/s, u_y = 25sin40° = 16.1 m/s. Vertically (up positive): −15 = 16.1t − 4.905t², i.e. 4.905t² − 16.1t − 15 = 0. Solving with the quadratic formula gives t = 4.03 s (taking the positive root). Horizontal range = 19.2 × 4.03 = 77.3 m. Common mistake: using the time of flight formula for level ground (2u_y/g), which only applies when the landing height equals the launch height — here it is 15 m lower, so a full quadratic solution is needed.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a57bdd62-c9e6-5af8-9974-2607de00c54b', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 16, 16, 'A ball is kicked at 35° above the horizontal on level ground and must travel exactly 40 m horizontally before landing. Using range = u²sin(2θ)/g (derived from the independence of horizontal and vertical motion), calculate the launch speed needed.', 'diagram:kin-2.13-q16', 3, 'numeric'::answer_type, '20.43', 'm/s', false, 0.05, false, 'Rearranging R = u²sin(2θ)/g for u: u = √(Rg ÷ sin(2θ)) = √(40×9.81 ÷ sin70°) = √(392.4 ÷ 0.940) = √418 = 20.4 m/s. Common mistake: using sinθ (35°) instead of sin(2θ) = sin70° in the range formula — the angle inside the sine is DOUBLE the launch angle.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('42019c3b-cee9-5665-bbab-f3ecca00fa29', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 17, 17, 'A strobe photograph of a projectile records its horizontal position x at two times: x = 2.0 m at t = 0.10 s, and x = 6.0 m at t = 0.30 s. Calculate the horizontal component of the launch velocity.', 'diagram:kin-2.13-q17', 3, 'numeric'::answer_type, '20', 'm/s', false, NULL, false, 'Since horizontal velocity is constant throughout the flight, it can be found from any two readings: u_x = (6.0−2.0) ÷ (0.30−0.10) = 4.0 ÷ 0.20 = 20.0 m/s. This works because x increases LINEARLY with time for the horizontal component — exactly the behaviour of constant velocity. Common mistake: trying to use the readings’ absolute times (0.10 s, 0.30 s) directly as if x were proportional to t from t = 0, rather than correctly using the CHANGE in x over the CHANGE in t between the two readings.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('e88dbef8-f32f-5fa5-aef6-886a671fd4aa', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 18, 18, 'A stone is thrown horizontally from a cliff and lands 2.5 s later, 45 m from the base of the cliff. (a) Calculate the launch speed. (b) Calculate the height of the cliff. Give only the answer to (a).', 'diagram:kin-2.13-q18', 3, 'numeric'::answer_type, '18', 'm/s', false, NULL, false, '(a) The horizontal motion has constant velocity: u = range ÷ time = 45 ÷ 2.5 = 18.0 m/s. (b) height = ½gt² = ½×9.81×2.5² = 30.7 m. Common mistake: trying to use the cliff height (which is not yet known) to find the launch speed, rather than recognising the horizontal motion is self-contained and only needs the range and time.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d677a2fe-ead1-5a2c-904d-d3866b2d6f1b', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 19, 19, 'A ball is thrown from ground level at speed u = 18 m/s and lands back at the same level after a horizontal range of exactly 25 m. Using R = u²sin(2θ)/g, find the SMALLER of the two possible launch angles that give this range (noting that sin(2θ) has two solutions between 0° and 180°).', NULL, 4, 'numeric'::answer_type, '24.6', '°', false, NULL, false, 'Rearranging: sin(2θ) = Rg/u² = (25×9.81) ÷ 18.0² = 245.25 ÷ 324 = 0.757. This gives 2θ = 49.2° OR 2θ = 180°−49.2° = 131° (since sinX = sin(180−X)). So θ = 24.6° or θ = 65.4° — TWO different launch angles give exactly the same range, a low, flat trajectory and a high, lobbed one. The smaller angle is 24.6°. Common mistake: taking the inverse sine and reporting only ONE angle, missing that there are generally two different launch angles (which sum to 90°) giving the same range.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7b178615-07a2-5f0a-96ae-258d92331fd1', 'ec015167-65fb-47df-b565-1055132ab4f3', '22a42568-867c-5245-91eb-c50c73e0ecb6', 'as', '2.13', '9702 2.13 Motion in two dimensions: projectiles', 20, 20, 'A fire-fighting aircraft flying horizontally at 60 m/s and at a height of 80 m must release water so that it lands exactly on a target directly below a point it will fly over LATER (since the water keeps moving horizontally as it falls). Calculate how far BEFORE the target (measured horizontally) the water must be released.', 'diagram:kin-2.13-q20', 4, 'numeric'::answer_type, '242.3', 'm', false, NULL, false, 'Time to fall: t = √(2×80 ÷ 9.81) = 4.04 s. During this time, the water (and the plane) continue moving horizontally at 60 m/s: horizontal distance covered while falling = 60 × 4.04 = 242 m. The water must therefore be released this far BEFORE the target. Common mistake: releasing the water directly above the target, forgetting that it retains the aircraft’s horizontal velocity and will carry on moving forward throughout the whole fall.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d4a9c404-da67-5cb5-8c3c-2a4be35ce51c', '177640c3-1783-45d3-90db-fa6111e09cda', 'A parabola', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e99d4d57-09eb-58af-854b-1d78389ec864', '177640c3-1783-45d3-90db-fa6111e09cda', 'A straight line', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('cb8e3a76-7f61-5c90-bf86-8ca995592e0b', '177640c3-1783-45d3-90db-fa6111e09cda', 'A circle', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ed2aaa56-9e8e-50c7-b42d-5843a9797154', '177640c3-1783-45d3-90db-fa6111e09cda', 'An ellipse', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('78c53931-cf31-570e-838e-deea243689f9', '1817e69b-fc0f-4a6d-9b2c-5ca05ad25dd6', '45°', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4fd477f7-1657-5106-8461-a90ed90ff37b', '1817e69b-fc0f-4a6d-9b2c-5ca05ad25dd6', '90°', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('561d1ca5-1aa0-5413-8e74-f77a6454b9eb', '1817e69b-fc0f-4a6d-9b2c-5ca05ad25dd6', '0°', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('dd375a38-c286-5429-a948-8eb94968d59b', '1817e69b-fc0f-4a6d-9b2c-5ca05ad25dd6', '60°', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e0ac18ae-fa36-5d44-99be-55ddc61cfd78', 'be650e96-4830-4fe8-9378-46f1b6309457', 'The one launched at 60°', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('53a27e65-ec30-54bb-8d98-30a315000267', 'be650e96-4830-4fe8-9378-46f1b6309457', 'The one launched at 30°', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e7a57e40-6c42-5442-87cf-2d05d74f269a', 'be650e96-4830-4fe8-9378-46f1b6309457', 'They reach exactly the same height', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e7b1ac16-7b5c-5163-8e22-a297c4c45da3', 'be650e96-4830-4fe8-9378-46f1b6309457', 'Height cannot be compared without knowing the mass', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('0a597410-8cc1-559c-a02f-2b421dfd5cdc', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 7, 7, 'A projectile is launched at 30 m/s at 25° above the horizontal. Using h = u²sin²θ/(2g), calculate its maximum height.', 'diagram:kin-2.14-q7', 2, 'numeric'::answer_type, '8.193', 'm', false, NULL, false, 'h = 30.0² × sin²25° ÷ (2×9.81) = 900 × 0.179 ÷ 19.62 = 161 ÷ 19.62 = 8.19 m. Common mistake: forgetting to SQUARE sinθ in this formula (it comes from squaring the vertical velocity component in v²=u²−2gh).', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('80291dae-b644-5db1-a44a-9e73f15bff66', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 8, 8, 'Two projectiles are launched at the same speed, at complementary angles (e.g. 20° and 70°, which add to 90°). What can be said about their ranges?', NULL, 2, 'multiple_choice'::answer_type, 'Their ranges are exactly equal, though their times of flight and maximum heights differ', NULL, false, NULL, false, 'Range = u²sin(2θ)/g. For complementary angles θ and (90°−θ), the doubled angles are 2θ and (180°−2θ), and since sinX = sin(180°−X), these give EXACTLY THE SAME range — even though their times of flight and maximum heights are quite different (the steeper angle goes higher and takes longer, but covers the same horizontal distance). Common mistake: assuming the steeper of two complementary-angle launches must also travel further, when in fact their ranges are identical.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ce808327-ca52-5069-a835-562a37516da5', '80291dae-b644-5db1-a44a-9e73f15bff66', 'Their ranges are exactly equal, though their times of flight and maximum heights differ', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('18454e85-26f6-53f4-8efd-1ddc0d6698e0', '80291dae-b644-5db1-a44a-9e73f15bff66', 'The steeper angle always has the greater range', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('95d0f2e7-b439-50b7-be22-7ec9c13a1d3d', '80291dae-b644-5db1-a44a-9e73f15bff66', 'The shallower angle always has the greater range', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4a27295c-58d8-5691-95bc-7f7053e8b083', '80291dae-b644-5db1-a44a-9e73f15bff66', 'Complementary angles always give zero range', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('70d6400c-3a3d-5876-b72d-dd890ae05244', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 9, 9, 'A projectile is launched at 20 m/s at 20°, and another at 20 m/s at 70° (complementary angles). Calculate the range of EACH, confirming they are equal.', NULL, 2, 'numeric'::answer_type, '26.21', 'm', false, 0.05, false, 'For 20°: R = 20.0² × sin40° ÷ 9.81 = 400 × 0.643 ÷ 9.81 = 26.2 m. For 70°: R = 20.0² × sin140° ÷ 9.81 = 400 × 0.643 ÷ 9.81 = 26.2 m — the same, since sin40° = sin140° exactly. Common mistake: expecting sin(2×70°) = sin140° to be a DIFFERENT value from sin40°, rather than recognising the sin(180−X)=sinX identity that makes them equal.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('204b2547-5870-591b-8e8d-a40c911967dc', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 10, 10, 'At what angle is the range of a projectile launched at 18 m/s maximised (on level ground), and what is that maximum range?', NULL, 2, 'numeric'::answer_type, '33.03', 'm', false, NULL, false, 'The maximum range always occurs at θ = 45° (where sin2θ = sin90° = 1), giving R_max = u²/g = 18.0² ÷ 9.81 = 33.0 m. Common mistake: still including the sin(2θ) factor in the final calculation even after substituting 2θ=90°, when sin90° = 1 exactly, so it simply disappears from the formula.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2c845d08-b84d-52c3-865c-1492a69b17c8', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 11, 11, 'In reality, with air resistance present, is 45° still exactly the optimum launch angle for maximum range?', NULL, 2, 'multiple_choice'::answer_type, 'No — with air resistance, the optimum angle for range is typically somewhat less than 45°', NULL, false, NULL, false, 'No — with significant air resistance, the optimum angle for maximum range is typically somewhat LESS than 45° (often considerably less for fast, light projectiles). This is because a lower, flatter trajectory spends less time in the air at high speed fighting drag, compared with a higher trajectory at the idealised 45°. Common mistake: assuming the clean theoretical result (45° for no air resistance) must still apply exactly in every real situation, however significant drag is.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9cd48e0d-b2e6-531f-8263-9644555bf860', '2c845d08-b84d-52c3-865c-1492a69b17c8', 'No — with air resistance, the optimum angle for range is typically somewhat less than 45°', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('19092e62-91cd-5bdd-a4e6-1b072bf6eb65', '2c845d08-b84d-52c3-865c-1492a69b17c8', 'Yes — 45° is always optimal, with or without air resistance', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ff1c46e0-e4a9-56eb-a41f-ba816ef11513', '2c845d08-b84d-52c3-865c-1492a69b17c8', 'No — with air resistance, the optimum angle becomes greater than 45°', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('21691780-95aa-5f38-a076-91192e3537ff', '2c845d08-b84d-52c3-865c-1492a69b17c8', 'Air resistance has no effect on the optimum launch angle at all', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('d4f3b073-ab9d-5732-9532-8c6b642b39ed', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 12, 12, 'A projectile is launched at 16 m/s at 50° above the horizontal. Calculate its maximum height.', NULL, 2, 'numeric'::answer_type, '7.657', 'm', false, NULL, false, 'h = 16.0² × sin²50° ÷ (2×9.81) = 256 × 0.587 ÷ 19.62 = 7.66 m. Common mistake: using sin50° alone (not squared), which would give a substantially different (and wrong) height.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('713de6ef-9220-5670-bb7b-c74038bd559f', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 13, 13, 'For a FIXED launch angle, if the launch speed u is doubled, by what factor does the range increase (on level ground, no air resistance)?', NULL, 2, 'multiple_choice'::answer_type, '4 times (since range ∝ u²)', NULL, false, NULL, false, 'Range = u²sin(2θ)/g, so range is proportional to u². Doubling u increases range by a factor of 2² = 4, not simply by a factor of 2. Common mistake: assuming range scales directly (linearly) with speed, rather than with speed SQUARED — a common and important source of error whenever a formula contains u² rather than u.', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8994cb47-fb26-5242-9f94-a51ae5dad5bf', '713de6ef-9220-5670-bb7b-c74038bd559f', '4 times (since range ∝ u²)', 'A', true, 0) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3138a78f-73e0-58d3-8e97-773abee74d1e', '713de6ef-9220-5670-bb7b-c74038bd559f', '2 times', 'B', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('573ae6cf-34f2-5381-9220-8bad3d154950', '713de6ef-9220-5670-bb7b-c74038bd559f', '8 times', 'C', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('3da1214a-144f-5911-9038-2bed6e8107ea', '713de6ef-9220-5670-bb7b-c74038bd559f', 'The range is unaffected by speed', 'D', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1545a062-e191-5bde-96b7-99ad23d6e621', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 14, 14, 'Starting from x = (u cosθ)t and y = (u sinθ)t − ½gt², eliminate t to show that y = x tanθ − gx²/(2u²cos²θ), the equation of the parabolic trajectory. Then, for u = 20 m/s, θ = 35°, calculate y when x = 15 m.', 'diagram:kin-2.14-q14', 3, 'numeric'::answer_type, '6.391', 'm', false, NULL, false, 'From the x equation: t = x/(u cosθ). Substituting into y: y = (u sinθ) × x/(u cosθ) − ½g × [x/(u cosθ)]² = x tanθ − gx²/(2u²cos²θ), since (sinθ/cosθ) = tanθ. Applying with x = 15, θ = 35°, u = 20: y = 15×tan35° − (9.81×15²) ÷ (2×20.0²×cos²35°) = 10.5 − 4.11 = 6.39 m. Common mistake: forgetting to square u and cosθ in the second term, since both were already squared individually before being combined in the original substitution.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('96d3ce89-a917-5d7a-936c-976e15de8b20', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 15, 15, 'Two balls are launched from the same point at the same speed, 25 m/s, but at complementary angles: 40° and 50°. (a) Calculate the range for the 40° launch. (b) Calculate the range for the 50° launch. (c) Explain why they are equal. Give only the answer to (a).', 'diagram:kin-2.14-q15', 3, 'numeric'::answer_type, '62.74', 'm', false, NULL, false, ('(a)/(b) Both use R = u²sin(2θ)/g with the SAME value of sin(2θ): for 40°, 2θ=80°' || chr(59) || ' for 50°, 2θ=100°, and sin100°=sin80°. R = 25.0² × sin80° ÷ 9.81 = 625 × 0.985 ÷ 9.81 = 62.7 m for BOTH. (c) 40° and 50° are complementary (they add to 90°), so their doubled angles (80° and 100°) are supplementary, giving equal sines and hence equal ranges. Common mistake: computing sin(2×50°) = sin100° as if it were a different, smaller value from sin80°, rather than recognising they are exactly equal.'), 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('56eb4c5d-b00b-5c5c-816e-5c2d5c459a87', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 16, 16, 'A projectile’s maximum height is measured as 12.0 m for a launch angle of 50°. (a) Using h = u²sin²θ/(2g), calculate the launch speed u. (b) Hence calculate the range. Give only the answer to (b).', 'diagram:kin-2.14-q16', 3, 'numeric'::answer_type, '40.28', 'm', false, NULL, false, '(a) Rearranging: u² = 2gh ÷ sin²θ = (2×9.81×12.0) ÷ sin²50° = 235.4 ÷ 0.587 = 401, so u = 20.0 m/s. (b) Range = u²sin(2×50°)/g = 401 × sin100° ÷ 9.81 = 40.3 m. Common mistake: forgetting to take the square root at the end of part (a), and carrying u² (rather than u) forward into later work — though in THIS case, since (b) itself needs u² again, it is important to keep track of which quantity is which.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c36afcec-5f95-594c-9284-1e859ab850e9', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 17, 17, 'For a fixed launch speed of 15 m/s, the table shows the range at three launch angles: 20°, 45° and 70°. Calculate the range for each, and identify which angle gives the maximum range. Give only that maximum range.', 'diagram:kin-2.14-q17', 3, 'numeric'::answer_type, '22.94', 'm', false, NULL, false, '20°: R = 225×sin40°÷9.81 = 14.7 m. 45°: R = 225×sin90°÷9.81 = 22.9 m. 70°: R = 225×sin140°÷9.81 = 14.7 m. The 20° and 70° results are equal (complementary angles), while 45° gives the clear maximum, 22.9 m. Common mistake: assuming the maximum range must occur at the LARGEST of the given angles (70°), rather than checking all three and recognising 45° as the true optimum.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b9374821-3cdd-5fb1-9225-caefaf32b62c', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 18, 18, 'A javelin is released at 28° above the horizontal at 24 m/s, from a height of 1.8 m above the (level) ground. Calculate the range, accounting for the launch height (the simple level-ground range formula does not directly apply here).', 'diagram:kin-2.14-q18', 3, 'numeric'::answer_type, '51.86', 'm', false, NULL, false, 'Components: u_x = 24cos28° = 21.2 m/s, u_y = 24sin28° = 11.3 m/s. Vertically, taking up as positive, the ground is at −1.8 m: −1.8 = 11.3t − 4.905t², giving 4.905t²−11.3t−1.8 = 0. Solving: t = 2.45 s. Range = 21.2 × 2.45 = 51.9 m. Common mistake: using R = u²sin(2θ)/g directly, which assumes the launch and landing heights are EQUAL — here the javelin is released above the ground it lands on, so the full quadratic approach is needed instead.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('371c5a05-6f4d-5530-8fe7-af22da636e49', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 19, 19, 'Show that R = u²sin(2θ)/g is maximised when θ = 45°, and that the resulting maximum range equals exactly u²/g. Verify for u = 22 m/s.', NULL, 4, 'numeric'::answer_type, '49.34', 'm', false, NULL, false, 'sin(2θ) reaches its largest possible value, 1, exactly when 2θ = 90°, i.e. θ = 45° (since sin(2θ) ≤ 1 for all θ, with equality only there). Substituting sin(2θ)=1 into the range formula gives simply R_max = u² ÷ g (the sine factor disappears entirely). For u = 22 m/s: R_max = 22.0² ÷ 9.81 = 49.3 m. Common mistake: trying to use calculus (differentiating R with respect to θ) when at AS level it is far simpler to note directly that sin(2θ) is bounded above by 1, and that this bound is reached at θ = 45°.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c084c7b4-7742-55ba-b240-184e6adf2e0a', 'ec015167-65fb-47df-b565-1055132ab4f3', '71e8bd3f-97fc-4cc7-9864-8ce994d6e5b6', 'as', '2.14', '9702 2.14 Understanding projectiles', 20, 20, 'A javelin is launched at 30 m/s at 40° above the horizontal. (a) Calculate the range if launched from ground level (height 0). (b) Calculate the range if instead released from a height of 2.0 m above the (otherwise identical) landing level. (c) Calculate the percentage increase in range caused by the extra launch height. Give only the answer to (c).', 'diagram:kin-2.14-q20', 4, 'numeric'::answer_type, '2.572', '%', false, NULL, false, ('(a) Ground-level range: R₀ = 30.0²×sin80°÷9.81 = 900×0.985÷9.81 = 90.3 m. (b) With launch height 2.0 m: u_x=23.0 m/s, u_y=19.3 m/s' || chr(59) || ' solving −2.0=19.3t−4.905t² gives t=4.03 s, so R_h = 23.0×4.03 = 92.7 m. (c) Percentage increase = (92.7−90.3) ÷ 90.3 × 100% = 2.57%. Common mistake: assuming launch height has no effect on range, when in fact ANY positive launch height always slightly increases the flight time (and hence the range), compared with an otherwise identical ground-level launch.'), 6) ON CONFLICT (id) DO NOTHING;
